INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('automagik-dev/omni/omni-executor', 'omni-executor', 'automagik-dev', 'omni', 'community', 'omni-executor automagik-dev omni community ai-agents bun discord event-driven messaging nats omnichannel typescript whatsapp The omni-executor skill enables AI agents to communicate universally across any messaging platform, leveraging event-driven architecture. It benefits developers working with AI agents and messaging platforms. omni-executor是一个通用事件驱动的AI代理平台，支持跨多个消息平台的通信 omni-executorは、AIエージェントのためのイベント駆動型オムニチャネルプラットフォームです omni-executor는 유니버설 이벤트 驱动의 AI 에이전트 플랫폼으로, 여러 메시징 플랫폼에서의 통신을 지원 omni-executor es una plataforma de eventos universales para la comunicación entre agentes de IA en cualquier plataforma de mensajería. omni-executor est une plateforme événementielle universelle pour la communication entre les agents IA sur n''importe quelle plateforme de messagerie. omni-executor ist eine universelle ereignisgesteuerte Plattform für die Kommunikation zwischen AI-Agents auf beliebigen Messaging-Plattformen. O Omni-Executor é uma plataforma de comunicação entre agentes de IA que permite a troca de mensagens em diferentes canais Omni-Executor — это платформа для обмена данными между ИИ Агентами, поддерживающая различные мессенджеры Omni-Executor هو منصة للاتصال بين أدوات الذكاء الاصطناعي التي تمكن من تبادل الرسائل على قنوات متعددة how to use omni-executor omni-executor alternative omni-executor setup guide what is omni-executor omni-executor vs bun omni-executor install event-driven messaging platform omni-executor whatsapp integration omni-executor discord setup omni-executor AI代理 事件驱动 omni CLI NATS Bun TypeScript 消息平台 AI工具 omni-executor集成 Utilizes the omni CLI for installation and authentication Employs jq for JSON processing and manipulation Supports sending messages via the omni send command Integrates with NATS for event-driven communication Written in TypeScript for robust and maintainable code Replaced by atomic skills in plugins/omni/skills/ for improved functionality omni-executor is a universal event-driven omnichannel platform for AI agents to communicate across various messaging platforms, including Discord and WhatsApp.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ViktorBarzin/infra/setup-project', 'community', 'ViktorBarzin', 'infra', 'ViktorBarzin/infra', 'setup-project', 4, 0, 47, '2026-02-26T21:21:50Z', '2026-03-06T06:57:51.781Z', 'f5eb776d58567646f34dda6c4961fa0cdccd2d84d3b55e9ac8b48639f3a69da8', '{"id":"ViktorBarzin/infra/setup-project","name":"setup-project","description":{"en":"The setup-project skill deploys new self-hosted services to Kubernetes clusters from GitHub repositories, benefiting developers who need to automate deployment workflows.","zh":"Setup Project技能用于将GitHub仓库中的自托管服务部署到Kubernetes集群，支持Docker镜像和docker-compose.yml文件","ja":"Setup Projectスキルは、GitHubリポジトリのセルフホスティングサービスをKubernetesクラスターにデプロイするために使用されます","ko":"Setup Project 스킬은 GitHub 리포지토리의 자가 호스팅 서비스를 Kubernetes 클러스터에 배포하는 데 사용됩니다","es":"El skill setup-project despliega un nuevo servicio autohospedado en un clúster de Kubernetes desde un repositorio de GitHub.","fr":"Le skill setup-project déploie un nouveau service auto-hébergé dans un cluster Kubernetes à partir d''un référentiel GitHub.","de":"Der Skill setup-project bereitstellt einen neuen selbstgehosteten Dienst in einem Kubernetes-Cluster aus einem GitHub-Repository.","pt":"O setup-project é uma habilidade que permite configurar um projeto e deployá-lo em um cluster Kubernetes a partir de um repositório GitHub.","ru":"Настройка проекта - это навык, который позволяет настроить проект и развернуть его на кластере Kubernetes из репозитория GitHub.","ar":"إعداد المشروع هو مهارة تمكنك من إعداد وتحسين مشروع وتثبيته على مجموعة Kubernetes من مستودع GitHub."},"seo":{"title":{"en":"setup-project: Kubernetes Deployment Guide | AI Agent Skill","zh":"Setup Project Setup Guide - 基于Kubernetes的自托管服务部署","ja":"Setup Project ベストプラクティス - GitHubリポジトリからのKubernetesクラスターへの...","ko":"Setup Project 설정 가이드 - Kubernetes 클러스터에 GitHub 리포지토리 배포","es":"Guía de configuración de proyecto con Kubernetes","fr":"Guide de configuration de projet avec Kubernetes","de":"Einrichtungsleitfaden für Projekt mit Kubernetes","pt":"Guia de Configuração de Projeto com Kubernetes","ru":"Настройка Проекта: ИИ Агенты для Развертывания на Kubernetes","ar":"إعداد مشروع مع Kubernetes: أداة ذكاء اصطناعي لتحسين التطوير"},"description":{"en":"Learn how to deploy self-hosted services to Kubernetes clusters using GitHub repositories with setup-project. Get started now!","zh":"使用Setup Project技能，轻松部署GitHub仓库中的自托管服务到Kubernetes集群，实现容器化应用的自动化部署","ja":"Setup Projectスキルを使用して、GitHubリポジトリのセルフホスティングサービスをKubernetesクラスターにデプロイします","ko":"Setup Project 스킬을 사용하여 GitHub 리포지토리의 자가 호스팅 서비스를 Kubernetes 클러스터에 배포합니다","es":"Descubre cómo configurar un proyecto de Kubernetes desde un repositorio de GitHub con nuestra guía paso a paso","fr":"Découvrez comment configurer un projet Kubernetes à partir d''un référentiel GitHub avec notre guide étape par étape","de":"Erfahren Sie, wie Sie ein Kubernetes-Projekt aus einem GitHub-Repository mit unserer Schritt-für-Schritt-Anleitung einrichten","pt":"Aprenda a configurar um projeto com o setup-project, incluindo deploy em cluster Kubernetes e integração com repositórios GitHub","ru":"Используйте ИИ Агенты для настройки проекта и развертывания его на Kubernetes, с поддержкой GitHub и Docker","ar":"استخدم أداة ذكاء اصطناعي لإعداد مشروع وتحسين التطوير مع Kubernetes و GitHub"},"definition":{"en":"setup-project is a skill that automates the deployment of self-hosted services to Kubernetes clusters using GitHub repository URLs or project names.","zh":"Setup Project是一种AI技能，用于自动化部署GitHub仓库中的自托管服务到Kubernetes集群","ja":"Setup Projectは、GitHubリポジトリのセルフホスティングサービスをKubernetesクラスターにデプロイするためのAIエージェントです","ko":"Setup Project는 GitHub 리포지토리의 자가 호스팅 서비스를 Kubernetes 클러스터에 배포하는 데 사용되는 AI 도구입니다","es":"Un setup-project es una habilidad que despliega servicios autohospedados en Kubernetes","fr":"Un setup-project est une compétence qui déploie des services auto-hébergés dans Kubernetes","de":"Ein setup-project ist eine Fähigkeit, die selbstgehostete Dienste in Kubernetes bereitstellt","pt":"O que é setup-project? É uma habilidade que automatiza a configuração de projetos em clusters Kubernetes.","ru":"Что такое настройка проекта? Это навык, который автоматизирует настройку проектов в кластерах Kubernetes.","ar":"ما هو إعداد المشروع؟ إنه مهارة تتيح لك توفير الوقت والجهد في إعداد وتثبيت المشاريع على مجموعات Kubernetes."},"features":{"en":["Visits GitHub repositories to gather deployment information","Checks README files for official Docker images and docker-compose.yml files","Supports deployment from GitHub repositories using Kubernetes","Automates self-hosting documentation retrieval","Requires GitHub repository URL or project name as input"],"zh":["支持GitHub仓库URL或项目名称输入","自动检查README文件中的官方Docker镜像和docker-compose.yml文件","支持自托管文档和所需依赖项的检查","基于Kubernetes的容器化应用部署"],"ja":["GitHubリポジトリURLまたはプロジェクト名の入力に対応","READMEファイル内の公式Dockerイメージとdocker-compose.ymlファイルの自動チェック","セルフホスティングドキュメントと必要な依存関係のチェックをサポート","Kubernetesベースのコンテナ化アプリケーションのデプロイ"],"ko":["GitHub 리포지토리 URL 또는 프로젝트 이름 입력 지원","README 파일 내의 공식 Docker 이미지 및 docker-compose.yml 파일 자동 체크","자가 호스팅 문서 및 필요한 의존성 체크 지원","Kubernetes 기반 컨테이너화된 애플리케이션 배포"],"es":["Despliegue de servicios autohospedados en Kubernetes","Soporte para repositorios de GitHub","Búsqueda de imágenes oficiales de Docker","Uso de docker-compose.yml para la configuración","Búsqueda de documentación de autohospedaje","Compatibilidad con ghcr.io y Docker Hub"],"fr":["Déploiement de services auto-hébergés dans Kubernetes","Prise en charge des référentiels GitHub","Recherche d''images Docker officielles","Utilisation de docker-compose.yml pour la configuration","Recherche de documentation d''auto-hébergement","Compatibilité avec ghcr.io et Docker Hub"],"de":["Bereitstellung selbstgehosteter Dienste in Kubernetes","Unterstützung für GitHub-Repositorys","Suche nach offiziellen Docker-Images","Verwendung von docker-compose.yml für die Konfiguration","Suche nach Selbsthosting-Dokumentation","Kompatibilität mit ghcr.io und Docker Hub"],"pt":["Deploy de projetos em clusters Kubernetes","Integração com repositórios GitHub","Suporte a imagens Docker oficiais","Leitura de arquivos docker-compose.yml","Verificação de documentação de auto-hospedagem"],"ru":["Развертывание проектов на кластерах Kubernetes","Интеграция с репозиториями GitHub","Поддержка официальных образов Docker","Чтение файлов docker-compose.yml","Проверка документации по само-хостингу"],"ar":["تثبيت المشاريع على مجموعات Kubernetes","التكامل مع مستودعات GitHub","دعم الصور الرسمية ل Docker","قراءة ملفات docker-compose.yml","التحقق من توثيق الاستضافة الذاتية"]},"keywords":{"en":["how to use setup-project","setup-project kubernetes deployment","github repository deployment","setup-project install guide","setup-project vs kubectl","setup-project tutorial","kubernetes self-hosted services","github to kubernetes deployment"],"zh":["Setup Project","Kubernetes部署","GitHub仓库","自托管服务","Docker镜像","docker-compose.yml","AI技能","容器化应用","自动化部署"],"ja":["Setup Project","Kubernetesデプロイ","GitHubリポジトリ","セルフホスティングサービス","Dockerイメージ","docker-compose.yml","AIエージェント","コンテナ化アプリケーション","自動化デプロイ"],"ko":["Setup Project","Kubernetes 배포","GitHub 리포지토리","자가 호스팅 서비스","Docker 이미지","docker-compose.yml","AI 도구","컨테이너화된 애플리케이션","자동화 배포"],"es":["setup-project","Kubernetes","GitHub","Docker","docker-compose","autohospedaje","despliegue de servicios","configuración de proyecto"],"fr":["setup-project","Kubernetes","GitHub","Docker","docker-compose","auto-hébergement","déploiement de services","configuration de projet"],"de":["setup-project","Kubernetes","GitHub","Docker","docker-compose","Selbsthosting","Bereitstellung von Diensten","Projekt-Konfiguration"],"pt":["setup-project","Kubernetes","GitHub","Docker","deploy de projetos","integração contínua","desenvolvimento de software","automatização de tarefas"],"ru":["настройка проекта","Kubernetes","GitHub","Docker","развертывание проектов","непрерывная интеграция","разработка программного обеспечения","автоматизация задач","ИИ Агенты"],"ar":["إعداد المشروع","Kubernetes","GitHub","Docker","تثبيت المشاريع","التكامل المستمر","تطوير البرمجيات","آداة ذكاء اصطناعي","تحسين التطوير"]}},"owner":"ViktorBarzin","repo":"infra","repoPath":"ViktorBarzin/infra","stars":4,"forks":0,"updatedAt":"2026-02-26T21:21:50Z","topics":[],"category":"community","skillMd":{"name":"setup-project","description":"|","version":"1.0.0","bodyPreview":"# Setup Project Skill\n\n**Purpose**: Deploy a new self-hosted service to the Kubernetes cluster from a GitHub repository.\n\n**When to use**: User provides a GitHub URL or project name and wants to deploy it to the cluster.\n\n## Workflow\n\n### 1. Research Phase\n\n**Input**: GitHub repository URL or project name\n\n**Actions**:\n- Visit the GitHub repository\n- Check the README for:\n  - Official Docker image (Docker Hub, ghcr.io, etc.)\n  - docker-compose.yml file\n  - Self-hosting documentation\n  - Required","body":"# Setup Project Skill\n\n**Purpose**: Deploy a new self-hosted service to the Kubernetes cluster from a GitHub repository.\n\n**When to use**: User provides a GitHub URL or project name and wants to deploy it to the cluster.\n\n## Workflow\n\n### 1. Research Phase\n\n**Input**: GitHub repository URL or project name\n\n**Actions**:\n- Visit the GitHub repository\n- Check the README for:\n  - Official Docker image (Docker Hub, ghcr.io, etc.)\n  - docker-compose.yml file\n  - Self-hosting documentation\n  - Required dependencies (PostgreSQL, MySQL, Redis, etc.)\n  - Environment variables needed\n  - Default ports\n  - Storage requirements\n\n**Find Docker Image Priority**:\n1. Check official documentation for recommended image\n2. Look in docker-compose.yml for `image:` directive\n3. Check GitHub Container Registry: `ghcr.io/<org>/<repo>`\n4. Check Docker Hub: `<org>/<repo>`\n5. Check releases page for container images\n6. Last resort: Build from Dockerfile (avoid if possible)\n\n**Extract Configuration**:\n- Container port (default port the app listens on)\n- Environment variables (DATABASE_URL, REDIS_HOST, SMTP, etc.)\n- Volume mounts (what data needs persistence)\n- Dependencies (database type, cache, etc.)\n\n### 2. Database Setup (if needed)\n\n**If project requires PostgreSQL**:\n- User provides database credentials or use pattern: `<service>` user with secure password\n- Database will be created in shared `postgresql.dbaas.svc.cluster.local`\n- Connection string format: `postgresql://<user>:<password>@postgresql.dbaas.svc.cluster.local:5432/<dbname>`\n\n**If project requires MySQL**:\n- User provides database credentials\n- Database in shared `mysql.dbaas.svc.cluster.local`\n- Connection string format: `mysql://<user>:<password>@mysql.dbaas.svc.cluster.local:3306/<dbname>`\n\n**If project requires Redis**:\n- Use shared Redis: `redis.redis.svc.cluster.local:6379`\n- No password required\n\n**IMPORTANT**: Never create databases yourself - always ask user for credentials to use.\n\n### 3. NFS Storage Setup (if service needs persistent data)\n\n**IMPORTANT**: NFS directories must exist and be exported on the NFS server BEFORE deploying the service. If the directory doesn''t exist, the pod will fail to mount the volume and get stuck in `ContainerCreating`.\n\n**Steps**:\n\n1. **Create the directory on the NFS server**:\n```bash\nssh root@10.0.10.15 ''mkdir -p /mnt/main/<service> && chmod 777 /mnt/main/<service>''\n```\n\n2. **Export the directory via TrueNAS**:\n   - The NFS export must be configured in TrueNAS so Kubernetes nodes can mount it\n   - Create the export via TrueNAS WebUI or API, allowing access from the Kubernetes network (10.0.20.0/24)\n   - Verify the export is accessible:\n```bash\n# From a k8s node or the dev VM\nshowmount -e 10.0.10.15 | grep <service>\n```\n\n3. **Verify the mount works before proceeding**:\n```bash\n# Quick test from a k8s node\nssh root@10.0.20.100 ''mount -t nfs 10.0.10.15:/mnt/main/<service> /tmp/test-mount && ls /tmp/test-mount && umount /tmp/test-mount''\n```\n\n**Only proceed to Terraform module creation after confirming the NFS export is accessible.**\n\n### 4. Terraform Module Creation\n\n**Create module directory**:\n```bash\nmkdir -p modules/kubernetes/<service-name>/\n```\n\n**Create `modules/kubernetes/<service-name>/main.tf`**:\n\n```hcl\nvariable \"tls_secret_name\" {}\nvariable \"tier\" { type = string }\nvariable \"postgresql_password\" {}  # Only if needed\n# Add other variables as needed (smtp_password, api_keys, etc.)\n\nresource \"kubernetes_namespace\" \"<service>\" {\n  metadata {\n    name = \"<service>\"\n  }\n}\n\nmodule \"tls_secret\" {\n  source          = \"../setup_tls_secret\"\n  namespace       = kubernetes_namespace.<service>.metadata[0].name\n  tls_secret_name = var.tls_secret_name\n}\n\n# If database migrations needed, add init_container\nresource \"kubernetes_deployment\" \"<service>\" {\n  metadata {\n    name      = \"<service>\"\n    namespace = kubernetes_namespace.<service>.metadata[0].name\n    labels = {\n      app  = \"<service>\"\n      tier = var.tier\n    }\n  }\n  spec {\n    replicas = 1\n    selector {\n      match_labels = {\n        app = \"<service>\"\n      }\n    }\n    template {\n      metadata {\n        labels = {\n          app = \"<service>\"\n        }\n      }\n      spec {\n        # Init container for migrations (if needed)\n        # init_container { ... }\n\n        container {\n          name  = \"<service>\"\n          image = \"<docker-image>:<tag>\"\n\n          port {\n            container_port = <port>\n          }\n\n          # Environment variables\n          env {\n            name  = \"DATABASE_URL\"\n            value = \"postgresql://<service>:${var.postgresql_password}@postgresql.dbaas.svc.cluster.local:5432/<service>\"\n          }\n          # Add other env vars as needed\n\n          # Volume mounts for persistent data\n          volume_mount {\n            name       = \"data\"\n            mount_path = \"<mount-path>\"\n            sub_path   = \"<optional-subpath>\"\n          }\n\n          resources {\n            requests = {\n              memory = \"256Mi\"\n              cpu    = \"100m\"\n            }\n            limits = {\n              memory = \"2Gi\"\n              cpu    = \"1\"\n            }\n          }\n\n          # Health checks (if endpoints exist)\n          liveness_probe {\n            http_get {\n              path = \"/health\"  # or /healthz, /, etc.\n              port = <port>\n            }\n            initial_delay_seconds = 60\n            period_seconds        = 30\n          }\n        }\n\n        # NFS volume for persistence\n        volume {\n          name = \"data\"\n          nfs {\n            server = \"10.0.10.15\"\n            path   = \"/mnt/main/<service>\"\n          }\n        }\n      }\n    }\n  }\n}\n\nresource \"kubernetes_service\" \"<service>\" {\n  metadata {\n    name      = \"<service>\"\n    namespace = kubernetes_namespace.<service>.metadata[0].name\n    labels = {\n      app = \"<service>\"\n    }\n  }\n\n  spec {\n    selector = {\n      app = \"<service>\"\n    }\n    port {\n      name        = \"http\"\n      port        = 80\n      target_port = <container-port>\n    }\n  }\n}\n\nmodule \"ingress\" {\n  source          = \"../ingress_factory\"\n  namespace       = kubernetes_namespace.<service>.metadata[0].name\n  name            = \"<service>\"\n  tls_secret_name = var.tls_secret_name\n  # Add extra_annotations if needed (proxy-body-size, timeouts, etc.)\n}\n```\n\n### 5. Update Main Terraform Files\n\n**Add to `modules/kubernetes/main.tf`**:\n\n1. Add variable declarations at top:\n```hcl\nvariable \"<service>_postgresql_password\" { type = string }\n```\n\n2. Add to appropriate DEFCON level (ask user which level, default to 5):\n```hcl\n5 : [\n  ...,\n  \"<service>\"\n]\n```\n\n3. Add module block at bottom:\n```hcl\nmodule \"<service>\" {\n  source              = \"./<service>\"\n  for_each            = contains(local.active_modules, \"<service>\") ? { <service> = true } : {}\n  tls_secret_name     = var.tls_secret_name\n  postgresql_password = var.<service>_postgresql_password\n  tier                = local.tiers.aux  # or appropriate tier\n\n  depends_on = [null_resource.core_services]\n}\n```\n\n**Add to `main.tf`**:\n\n1. Add variable:\n```hcl\nvariable \"<service>_postgresql_password\" { type = string }\n```\n\n2. Pass to kubernetes_cluster module:\n```hcl\nmodule \"kubernetes_cluster\" {\n  ...\n  <service>_postgresql_password = var.<service>_postgresql_password\n}\n```\n\n**Update `terraform.tfvars`**:\n\n1. Add password/credentials:\n```hcl\n<service>_postgresql_password = \"<secure-password>\"\n```\n\n2. Add to Cloudflare DNS (ask user if proxied or non-proxied):\n```hcl\ncloudflare_non_proxied_names = [\n  ...,\n  \"<service>\"\n]\n```\n\n### 6. Email/SMTP Configuration (if needed)\n\nIf service needs to send emails:\n```hcl\nenv {\n  name  = \"MAILER_HOST\"\n  value = \"mailserver.viktorbarzin.me\"  # Public hostname for TLS\n}\nenv {\n  name  = \"MAILER_PORT\"\n  value = \"587\"\n}\nenv {\n  name  = \"MAILER_USER\"\n  value = \"info@viktorbarzin.me\"\n}\nenv {\n  name  = \"MAILER_PASSWORD\"\n  value = var.mailserver_accounts[\"info@viktorbarzin.me\"]  # Pass from module\n}\n```\n\nAdd to module call:\n```hcl\nsmtp_password = var.mailserver_accounts[\"info@viktorbarzin.me\"]\n```\n\n### 7. Apply Terraform\n\n```bash\nterraform init\nterraform apply -target=module.kubernetes_cluster.module.<service> -var=\"kube_config_path=$(pwd)/config\" -auto-approve\n```\n\n**IMPORTANT: Also apply the cloudflared module to create the Cloudflare DNS record:**\n```bash\nterraform apply -target=module.kubernetes_cluster.module.cloudflared -var=\"kube_config_path=$(pwd)/config\" -auto-approve\n```\nWithout this step, the DNS record won''t be created even though it''s defined in `terraform.tfvars`.\n\n### 8. Verification\n\n```bash\nkubectl get pods -n <service>\nkubectl logs -n <service> -l app=<service> --tail=50\n```\n\nTest URL: `https://<service>.viktorbarzin.me`\n\n### 9. Commit Changes\n\n```bash\ngit add modules/kubernetes/<service>/ main.tf modules/kubernetes/main.tf terraform.tfvars\ngit commit -m \"Add <service> deployment\n\n- Deploy <service> as <description>\n- Uses <dependencies>\n- Ingress at <service>.viktorbarzin.me\n\n[ci skip]\"\n```\n\n## Common Patterns\n\n### Init Container for Migrations\n```hcl\ninit_container {\n  name    = \"migration\"\n  image   = \"<same-image>\"\n  command = [\"sh\", \"-c\", \"<migration-command>\"]\n\n  # Same env vars and volumes as main container\n}\n```\n\n### Dynamic Environment Variables\n```hcl\nlocals {\n  common_env = [\n    { name = \"VAR1\", value = \"value1\" },\n    { name = \"VAR2\", value = \"value2\" },\n  ]\n}\n\ndynamic \"env\" {\n  for_each = local.common_env\n  content {\n    name  = env.value.name\n    value = env.value.value\n  }\n}\n```\n\n### External URL Configuration\nMany apps need their public URL configured:\n```hcl\nenv {\n  name  = \"APP_URL\"  # or PUBLIC_URL, EXTERNAL_URL, etc.\n  value = \"https://<service>.viktorbarzin.me\"\n}\nenv {\n  name  = \"HTTPS\"  # or ENABLE_HTTPS, etc.\n  value = \"true\"\n}\n```\n\n## Checklist\n\n- [ ] Find official Docker image or docker-compose\n- [ ] Identify dependencies (DB, Redis, etc.)\n- [ ] Ask user for database credentials (never create yourself)\n- [ ] Create NFS directory and export on TrueNAS (if persistent storage needed)\n- [ ] Verify NFS mount is accessible from k8s nodes\n- [ ] Create `modules/kubernetes/<service>/main.tf`\n- [ ] Update `modules/kubernetes/main.tf` (variables, DEFCON level, module block)\n- [ ] Update `main.tf` (variable, pass to module)\n- [ ] Update `terraform.tfvars` (password, Cloudflare DNS)\n- [ ] Run `terraform init` and `terraform apply`\n- [ ] Verify pods are running\n- [ ] Test the URL\n- [ ] Commit changes with `[ci skip]`\n\n## Questions to Ask User\n\n1. What DEFCON level should this service be in? (Default: 5)\n2. Should Cloudflare proxy this domain? (Default: no, add to non_proxied_names)\n3. Does this need email/SMTP? (Configure if yes)\n4. What database credentials should I use? (Never create yourself)\n5. What tier? (core/cluster/gpu/edge/aux - default: aux)\n\n## Notes\n\n- **Always create NFS directories and exports BEFORE deploying** - pods will get stuck in `ContainerCreating` if the NFS path doesn''t exist or isn''t exported\n- **Always use official documentation** as the source of truth\n- **Prefer stable/latest tags** over specific versions for self-hosted\n- **Use shared infrastructure**: PostgreSQL at `postgresql.dbaas.svc.cluster.local`, Redis at `redis.redis.svc.cluster.local`\n- **NFS storage**: Always at `10.0.10.15:/mnt/main/<service>`\n- **Email**: Use `mailserver.viktorbarzin.me` (public hostname) not internal service name\n- **Resource limits**: Start conservative, can increase if needed\n- **Health checks**: Only add if the app has health endpoints\n"},"lastSynced":"2026-03-06T06:57:51.781Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated Kubernetes deployment workflows from GitHub repositories.","zh":"适用于需要从 GitHub 仓库自动化 Kubernetes 部署工作流的 DevOps Agents。","ja":"GitHub リポジトリからの自動化された Kubernetes デプロイ ワークフローを必要とする DevOps エージェントに適しています。","ko":"GitHub 리포지토리로부터 자동화된 Kubernetes 배포 워크플ロー가 필요한 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren flujos de trabajo de implementación de Kubernetes automatizados desde repositorios de GitHub.","fr":"Idéal pour les agents DevOps nécessitant des flux de travail de déploiement Kubernetes automatisés à partir de référentiels GitHub.","de":"Ideal für DevOps-Agents, die automatisierte Kubernetes-Bereitstellungsworkflows aus GitHub-Repositorys benötigen.","pt":"Ideal para Agentes DevOps que requerem fluxos de trabalho de implantação automatizados do Kubernetes a partir de repositórios do GitHub.","ru":"Идеально для агентов DevOps, требующих автоматизированных рабочих процессов развертывания Kubernetes из репозиториев GitHub.","ar":"مثالي للموكلين DevOps الذين يحتاجون إلى سير عمل تثبيت自动ي لـ Kubernetes من مستودعات GitHub."},"recommendation":{"en":"Empowers agents to deploy self-hosted services to Kubernetes clusters using GitHub repository URLs or project names, leveraging Docker images and docker-compose.yml files for streamlined deployment.","zh":"赋予代理部署到 Kubernetes 集群的自托管服务的能力，使用 GitHub 仓库 URL 或项目名称，利用 Docker 镜像和 docker-compose.yml 文件以实现简化的部署。","ja":"GitHub リポジトリの URL またはプロジェクト名を使用して、Kubernetes クラスターにセルフホスト サービスをデプロイするエージェントの能力を提供し、Docker イメージと docker-compose.yml ファイルを使用してデプロイを簡素化します。","ko":"GitHub 리포지토리 URL 또는 프로젝트 이름을 사용하여 Kubernetes 클러스터에 자체 호스팅 서비스를 배포하는 에이전트의 능력을 제공하며, Docker 이미지를 사용하고 docker-compose.yml 파일을 사용하여 배포를 간소화합니다.","es":"Habilita a los agentes para implementar servicios autoalojados en clusters de Kubernetes utilizando URLs de repositorios de GitHub o nombres de proyectos, aprovechando imágenes de Docker y archivos docker-compose.yml para una implementación optimizada.","fr":"Permet aux agents de déployer des services auto-hébergés sur des clusters Kubernetes en utilisant des URL de référentiels GitHub ou des noms de projets, en exploitant les images Docker et les fichiers docker-compose.yml pour un déploiement optimisé.","de":"Ermächtigt Agents, selbstgehostete Dienste in Kubernetes-Clustern bereitzustellen, indem sie GitHub-Repository-URLs oder Projektnamen verwenden und Docker-Images sowie docker-compose.yml-Dateien für eine optimierte Bereitstellung nutzen.","pt":"Habilita os agentes a implantar serviços autohospedados em clusters do Kubernetes usando URLs de repositórios do GitHub ou nomes de projetos, aproveitando imagens do Docker e arquivos docker-compose.yml para implantação simplificada.","ru":"Наделяет агентов возможностью развертывать самообслуживаемые услуги в кластерах Kubernetes, используя URL-адреса репозиториев GitHub или имена проектов, используя образы Docker и файлы docker-compose.yml для упрощенного развертывания.","ar":"تمكين الوكلاء من نشر الخدمات المضيفة المضمنة في مجموعات Kubernetes باستخدام عناوين URL لمستودعات GitHub أو أسماء المشاريع، واستخدام صور Docker وملفات docker-compose.yml لنشر مبسط."},"useCases":{"en":["Automating deployment workflows for new services","Deploying self-hosted applications from GitHub repositories","Streamlining Kubernetes cluster management"],"zh":["自动化新服务的部署工作流","从 GitHub 仓库部署自托管应用程序","简化 Kubernetes 集群管理"],"ja":["新しいサービスのデプロイ ワークフローを自動化する","GitHub リポジトリからセルフホスト アプリケーションをデプロイする","Kubernetes クラスターの管理を簡素化する"],"ko":["새로운 서비스의 배포 워크플ロー 자동화","GitHub 리포지토리로부터 자체 호스팅 애플리케이션을 배포","Kubernetes 클러스터 관리를 간소화"],"es":["Automatizar flujos de trabajo de implementación para nuevos servicios","Implementar aplicaciones autoalojadas desde repositorios de GitHub","Optimizar la administración de clusters de Kubernetes"],"fr":["Automatiser les flux de travail de déploiement pour de nouveaux services","Déployer des applications auto-hébergées à partir de référentiels GitHub","Optimiser la gestion de clusters Kubernetes"],"de":["Automatisierung von Bereitstellungsworkflows für neue Dienste","Bereitstellung von selbstgehosteten Anwendungen aus GitHub-Repositorys","Optimierung der Kubernetes-Cluster-Verwaltung"],"pt":["Automatizar fluxos de trabalho de implantação para novos serviços","Implantar aplicações autohospedadas a partir de repositórios do GitHub","Simplificar a gestão de clusters do Kubernetes"],"ru":["Автоматизировать рабочие процессы развертывания для новых услуг","Развертывать самообслуживаемые приложения из репозиториев GitHub","Упрощать управление кластерами Kubernetes"],"ar":["توفير سير عمل تثبيت自动ي للخدمات الجديدة","نشر التطبيقات المضيفة المضمنة من مستودعات GitHub","تبسيط إدارة مجموعات Kubernetes"]},"limitations":{"en":["Requires GitHub repository access","Kubernetes cluster setup necessary","Docker image or docker-compose.yml file required in repository"],"zh":["需要 GitHub 仓库访问权限","Kubernetes 集群设置是必要的","仓库中需要 Docker 镜像或 docker-compose.yml 文件"],"ja":["GitHub リポジトリへのアクセスが必要","Kubernetes クラスターの設定が必要","リポジトリ内に Docker イメージまたは docker-compose.yml ファイルが必要"],"ko":["GitHub 리포지토리에 대한 액세스 권한이 필요","Kubernetes 클러스터 설정이 필요","리포지토리 내에 Docker 이미지 또는 docker-compose.yml 파일이 필요"],"es":["Se requiere acceso al repositorio de GitHub","Se requiere configuración del cluster de Kubernetes","Se requiere una imagen de Docker o un archivo docker-compose.yml en el repositorio"],"fr":["L''accès au référentiel GitHub est requis","La configuration du cluster Kubernetes est nécessaire","Une image Docker ou un fichier docker-compose.yml est requis dans le référentiel"],"de":["Zugriff auf das GitHub-Repository ist erforderlich","Kubernetes-Cluster-Einrichtung ist notwendig","Docker-Image oder docker-compose.yml-Datei ist im Repository erforderlich"],"pt":["Requer acesso ao repositório do GitHub","Configuração do cluster do Kubernetes necessária","Imagem do Docker ou arquivo docker-compose.yml necessário no repositório"],"ru":["Требуется доступ к репозиторию GitHub","Необходимо настроить кластер Kubernetes","Образ Docker или файл docker-compose.yml необходим в репозитории"],"ar":["يتطلب الوصول إلى مستودع GitHub","يجب إعداد كلاستر Kubernetes","يتطلب صورة Docker أو ملف docker-compose.yml في المستودع"]},"version":4},"contentHash":"f5eb776d58567646f34dda6c4961fa0cdccd2d84d3b55e9ac8b48639f3a69da8","qualityScore":47}');
