INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ViktorBarzin/infra/setup-project', 'setup-project', 'ViktorBarzin', 'infra', 'community', 'setup-project ViktorBarzin infra community The setup-project skill deploys new self-hosted services to Kubernetes clusters from GitHub repositories, benefiting developers who need to automate deployment workflows. Setup Project技能用于将GitHub仓库中的自托管服务部署到Kubernetes集群，支持Docker镜像和docker-compose.yml文件 Setup Projectスキルは、GitHubリポジトリのセルフホスティングサービスをKubernetesクラスターにデプロイするために使用されます Setup Project 스킬은 GitHub 리포지토리의 자가 호스팅 서비스를 Kubernetes 클러스터에 배포하는 데 사용됩니다 El skill setup-project despliega un nuevo servicio autohospedado en un clúster de Kubernetes desde un repositorio de GitHub. Le skill setup-project déploie un nouveau service auto-hébergé dans un cluster Kubernetes à partir d''un référentiel GitHub. Der Skill setup-project bereitstellt einen neuen selbstgehosteten Dienst in einem Kubernetes-Cluster aus einem GitHub-Repository. O setup-project é uma habilidade que permite configurar um projeto e deployá-lo em um cluster Kubernetes a partir de um repositório GitHub. Настройка проекта - это навык, который позволяет настроить проект и развернуть его на кластере Kubernetes из репозитория GitHub. إعداد المشروع هو مهارة تمكنك من إعداد وتحسين مشروع وتثبيته على مجموعة Kubernetes من مستودع GitHub. how to use setup-project setup-project kubernetes deployment github repository deployment setup-project install guide setup-project vs kubectl setup-project tutorial kubernetes self-hosted services github to kubernetes deployment Setup Project Kubernetes部署 GitHub仓库 自托管服务 Docker镜像 docker-compose.yml AI技能 容器化应用 自动化部署 Visits GitHub repositories to gather deployment information Checks README files for official Docker images and docker-compose.yml files Supports deployment from GitHub repositories using Kubernetes Automates self-hosting documentation retrieval Requires GitHub repository URL or project name as input setup-project is a skill that automates the deployment of self-hosted services to Kubernetes clusters using GitHub repository URLs or project names.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('T-rav/hydraflow/continuous-learning-v2', 'community', 'T-rav', 'hydraflow', 'T-rav/hydraflow', 'continuous-learning-v2', 3, 0, 47, '2026-03-05T08:36:26Z', '2026-03-06T07:04:01.323Z', '727bdebde88d3f921ee6cbd95eaacb76162292b0dce80360ff3ba4c955d04e54', '{"id":"T-rav/hydraflow/continuous-learning-v2","name":"continuous-learning-v2","description":{"en":"Continuous-Learning-V2 is an advanced learning system that turns Claude Code sessions into reusable knowledge. It benefits developers by providing atomic ''instincts'' with confidence scoring.","zh":"continuous-learning-v2是一种高级的学习系统，通过atomic \"instincts\"实现智能编程和自动化学习","ja":"continuous-learning-v2は、atomic \"instincts\"を使用してAIエージェントベースの学習システムを実現する高度な学習システムです","ko":"continuous-learning-v2는 atomic \"instincts\"를 사용하여 지속적 학습을 위한 AI 에이전트를 구축하는 고급 학습 시스템입니다","es":"Continuous Learning v2 es un sistema de aprendizaje avanzado que convierte sesiones de Claude Code en conocimiento reutilizable a través de ''instintos'' atómicos con puntuación de confianza.","fr":"Continuous Learning v2 est un système d''apprentissage avancé qui transforme les sessions Claude Code en connaissances réutilisables via des ''instincts'' atomiques avec notation de confiance.","de":"Continuous Learning v2 ist ein fortschrittliches Lernsystem, das Claude-Code-Sitzungen in wiederverwendbares Wissen durch atomare ''Instinkte'' mit Vertrauensbewertung umwandelt.","pt":"O Continuous Learning v2 é um sistema de aprendizado avançado que transforma suas sessões de Claude Code em conhecimento reutilizável por meio de ''instintos'' atômicos","ru":"Continuous Learning v2 - это продвинутая система обучения, которая превращает ваши сессии Claude Code в многоразовое знание через атомарные ''инстинкты''","ar":"Continuous Learning v2 هو نظام تعلم متقدم يتحول جلساتك من Claude Code إلى معرفة قابلة لإعادة الاستخدام من خلال ''الانفعالات'' الذرية"},"seo":{"title":{"en":"Continuous-Learning-V2: Setup Guide for AI Agents","zh":"continuous-learning-v2 Setup Guide - AIエージェント 智能编程","ja":"continuous-learning-v2 Setup Guide - AIエージェントベースの学習システム","ko":"continuous-learning-v2 Setup Guide - AI 에이전트를 위한 지속적 학습","es":"Guía de configuración de Continuous Learning v2 para agen...","fr":"Guide de mise en place de Continuous Learning v2 pour les...","de":"Einrichtungsleitfaden für Continuous Learning v2 - KI-Tools","pt":"Guia de Configuração do Continuous Learning v2 para Desen...","ru":"ИИ Агенты: Руководство по Настройке Continuous Learning v2","ar":"دليل إعداد Continuous Learning v2 للبرمجة الذكية"},"description":{"en":"Unlock the full potential of HydraFlow with Continuous-Learning-V2. Learn how to activate instinct-based architecture and tune confidence thresholds for lear...","zh":"了解continuous-learning-v2的功能和特点，实现智能编程和自动化学习","ja":"continuous-learning-v2の機能と特徴を紹介します。AIエージェントベースの学習システムを構築しましょう","ko":"continuous-learning-v2의 기능과 특징을 살펴보고 지속적 학습을 위한 AI 에이전트를 구축하세요","es":"Aprende a configurar Continuous Learning v2 para mejorar la capacidad de aprendizaje de tus agentes de inteligencia artificial con tecnologías como Claude Code","fr":"Découvrez comment configurer Continuous Learning v2 pour améliorer la capacité d''apprentissage de vos outils d''IA avec des technologies comme Claude Code","de":"Erfahren Sie, wie Sie Continuous Learning v2 konfigurieren, um die Lernfähigkeit Ihrer KI-Tools mit Technologien wie Claude Code zu verbessern","pt":"Aprenda a configurar o Continuous Learning v2 para melhorar a eficiência do seu workflow de desenvolvimento com tecnologias de aprendizado de máquina","ru":"Узнайте, как настроить Continuous Learning v2 для повышения эффективности вашего рабочего процесса разработки с помощью технологий машинного обучения","ar":"تعرف على كيفية إعداد Continuous Learning v2 لتحسين كفاءة سير عمل البرمجة الخاص بك باستخدام تقنيات التعلم الآلي"},"definition":{"en":"Continuous-Learning-V2 is an advanced learning system that enables instinct-based architecture for reusable knowledge extraction from Claude Code sessions.","zh":"continuous-learning-v2是一种AIエージェント，用于实现智能编程和自动化学习","ja":"continuous-learning-v2は、AIエージェントベースの学習システムを構築するための高度な学習システムです","ko":"continuous-learning-v2는 지속적 학습을 위한 AI 에이전트를 구축하는 고급 학습 시스템입니다","es":"Continuous Learning v2 es un sistema de aprendizaje que permite a los agentes de inteligencia artificial aprender de sesiones de Claude Code","fr":"Continuous Learning v2 est un système d''apprentissage qui permet aux outils d''IA d''apprendre à partir de sessions Claude Code","de":"Continuous Learning v2 ist ein Lernsystem, das es KI-Tools ermöglicht, aus Claude-Code-Sitzungen zu lernen","pt":"O que é Continuous Learning v2? É um sistema de aprendizado que cria conhecimento reutilizável a partir de sessões de Claude Code","ru":"Что такое Continuous Learning v2? Это система обучения, создающая многоразовое знание из сессий Claude Code","ar":"ما هو Continuous Learning v2؟ هو نظام تعلم يخلق معرفة قابلة لإعادة الاستخدام من جلسات Claude Code"},"features":{"en":["Activates automatic learning from Claude Code sessions","Configures instinct-based behavior extraction via hooks","Tunes confidence thresholds for learned behaviors","Supports reviewing, exporting, or importing instinct libraries","Evolve instincts into full-fledged behaviors"],"zh":["atomic \"instincts\"を使用した智能编程","自动化学习和confidence scoring","Claude Code sessionsからの学習","instinct librariesのレビューとエクスポート","confidence thresholdsの調整"],"ja":["atomic \"instincts\"を使用したAIエージェントベースの学習","自動化学習とconfidence scoring","Claude Code sessionsからの学習","instinct librariesのレビューとエクスポート","confidence thresholdsの調整"],"ko":["atomic \"instincts\"를 사용한 지속적 학습","자동화 학습과 confidence scoring","Claude Code sessionsからの 학습","instinct libraries의 리뷰와 익스ポート","confidence thresholds의 조정"],"es":["Aprendizaje automático desde sesiones de Claude Code","Extracción de comportamientos basados en instintos a través de hooks","Ajuste de umbrales de confianza para comportamientos aprendidos","Revisión, exportación e importación de bibliotecas de instintos","Evolución de instintos en funciones completas"],"fr":["Apprentissage automatique à partir de sessions Claude Code","Extraction de comportements basés sur les instincts via des hooks","Réglage des seuils de confiance pour les comportements appris","Révision, exportation et importation de bibliothèques d''instincts","Évolution des instincts en fonctions complètes"],"de":["Automatisches Lernen aus Claude-Code-Sitzungen","Extraktion von instinktbasiertem Verhalten über Hooks","Anpassung von Vertrauensschwellen für gelerntes Verhalten","Überprüfung, Export und Import von Instinktbibliotheken","Weiterentwicklung von Instinkten in vollständige Funktionen"],"pt":["Aprendizado de máquina baseado em ''instintos'' atômicos","Extração de comportamento baseado em hooks","Ajuste de limiares de confiança para comportamentos aprendidos","Revisão, exportação e importação de bibliotecas de instintos","Evolução de instintos em comportamentos completos"],"ru":["Машинное обучение на основе атомарных ''инстинктов''","Извлечение поведения на основе хуков","Настройка порогов доверия для изученных поведений","Просмотр, экспорт и импорт библиотек инстинктов","Эволюция инстинктов в полные поведения"],"ar":["التعلم الآلي القائم على ''الانفعالات'' الذرية","استخراج السلوك القائم على المشابك","ضبط عتبات الثقة للسلوكيات المكتسبة","مراجعة وتصدير واستيراد مكتبات الانفعالات","تطور الانفعالات إلى سلوكيات كاملة"]},"keywords":{"en":["how to use continuous-learning-v2","what is continuous-learning-v2","continuous-learning-v2 setup guide","continuous-learning-v2 alternative","continuous-learning-v2 vs agentic-development","installing continuous-learning-v2 for HydraFlow","continuous-learning-v2 tutorial for AI agents","agentic-workflow with continuous-learning-v2","wishful-programming with continuous-learning-v2"],"zh":["continuous-learning-v2","AIエージェント","智能编程","自动化学习","atomic instincts","Claude Code","confidence scoring","instinct libraries"],"ja":["continuous-learning-v2","AIエージェント","AIエージェントベースの学習","自動化学習","atomic instincts","Claude Code","confidence scoring","instinct libraries"],"ko":["continuous-learning-v2","AI 에이전트","지속적 학습","자동화 학습","atomic instincts","Claude Code","confidence scoring","instinct libraries"],"es":["agentes de inteligencia artificial","Continuous Learning v2","Claude Code","aprendizaje automático","instintos atómicos","puntuación de confianza","desarrollo de software","herramientas de IA"],"fr":["outils d''IA","Continuous Learning v2","Claude Code","apprentissage automatique","instincts atomiques","notation de confiance","développement de logiciels","intelligence artificielle"],"de":["KI-Tools","Continuous Learning v2","Claude Code","automatisches Lernen","atomare Instinkte","Vertrauensbewertung","Software-Entwicklung","künstliche Intelligenz"],"pt":["Continuous Learning v2","aprendizado de máquina","desenvolvimento de software","Claude Code","instintos atômicos","hooks","limiares de confiança","bibliotecas de instintos"],"ru":["Continuous Learning v2","машинное обучение","разработка программного обеспечения","Claude Code","атомарные инстинкты","хуки","пороги доверия","библиотеки инстинктов"],"ar":["Continuous Learning v2","التعلم الآلي","برمجة البرمجيات","Claude Code","الانفعالات الذرية","المشابك","عتبات الثقة","مكتبات الانفعالات"]}},"owner":"T-rav","repo":"hydraflow","repoPath":"T-rav/hydraflow","stars":3,"forks":0,"updatedAt":"2026-03-05T08:36:26Z","topics":["agentic-development","agentic-workflow","wishful-programming"],"category":"community","skillMd":{"name":"continuous-learning-v2","description":"Instinct-based learning system that observes sessions via hooks, creates atomic instincts with confidence scoring, and evolves them into skills/commands/agents.","version":"2.0.0","bodyPreview":"# Continuous Learning v2 - Instinct-Based Architecture\n\nAn advanced learning system that turns your Claude Code sessions into reusable knowledge through atomic \"instincts\" - small learned behaviors with confidence scoring.\n\n## When to Activate\n\n- Setting up automatic learning from Claude Code sessions\n- Configuring instinct-based behavior extraction via hooks\n- Tuning confidence thresholds for learned behaviors\n- Reviewing, exporting, or importing instinct libraries\n- Evolving instincts into ful","body":"# Continuous Learning v2 - Instinct-Based Architecture\n\nAn advanced learning system that turns your Claude Code sessions into reusable knowledge through atomic \"instincts\" - small learned behaviors with confidence scoring.\n\n## When to Activate\n\n- Setting up automatic learning from Claude Code sessions\n- Configuring instinct-based behavior extraction via hooks\n- Tuning confidence thresholds for learned behaviors\n- Reviewing, exporting, or importing instinct libraries\n- Evolving instincts into full skills, commands, or agents\n\n## What''s New in v2\n\n| Feature | v1 | v2 |\n|---------|----|----|\n| Observation | Stop hook (session end) | PreToolUse/PostToolUse (100% reliable) |\n| Analysis | Main context | Background agent (Haiku) |\n| Granularity | Full skills | Atomic \"instincts\" |\n| Confidence | None | 0.3-0.9 weighted |\n| Evolution | Direct to skill | Instincts → cluster → skill/command/agent |\n| Sharing | None | Export/import instincts |\n\n## The Instinct Model\n\nAn instinct is a small learned behavior:\n\n```yaml\n---\nid: prefer-functional-style\ntrigger: \"when writing new functions\"\nconfidence: 0.7\ndomain: \"code-style\"\nsource: \"session-observation\"\n---\n\n# Prefer Functional Style\n\n## Action\nUse functional patterns over classes when appropriate.\n\n## Evidence\n- Observed 5 instances of functional pattern preference\n- User corrected class-based approach to functional on 2025-01-15\n```\n\n**Properties:**\n- **Atomic** — one trigger, one action\n- **Confidence-weighted** — 0.3 = tentative, 0.9 = near certain\n- **Domain-tagged** — code-style, testing, git, debugging, workflow, etc.\n- **Evidence-backed** — tracks what observations created it\n\n## How It Works\n\n```\nSession Activity\n      │\n      │ Hooks capture prompts + tool use (100% reliable)\n      ▼\n┌─────────────────────────────────────────┐\n│         observations.jsonl              │\n│   (prompts, tool calls, outcomes)       │\n└─────────────────────────────────────────┘\n      │\n      │ Observer agent reads (background, Haiku)\n      ▼\n┌─────────────────────────────────────────┐\n│          PATTERN DETECTION              │\n│   • User corrections → instinct         │\n│   • Error resolutions → instinct        │\n│   • Repeated workflows → instinct       │\n└─────────────────────────────────────────┘\n      │\n      │ Creates/updates\n      ▼\n┌─────────────────────────────────────────┐\n│         instincts/personal/             │\n│   • prefer-functional.md (0.7)          │\n│   • always-test-first.md (0.9)          │\n│   • use-zod-validation.md (0.6)         │\n└─────────────────────────────────────────┘\n      │\n      │ /evolve clusters\n      ▼\n┌─────────────────────────────────────────┐\n│              evolved/                   │\n│   • commands/new-feature.md             │\n│   • skills/testing-workflow.md          │\n│   • agents/refactor-specialist.md       │\n└─────────────────────────────────────────┘\n```\n\n## Quick Start\n\n### 1. Enable Observation Hooks\n\nAdd to your `~/.claude/settings.json`.\n\n**If installed as a plugin** (recommended):\n\n```json\n{\n  \"hooks\": {\n    \"PreToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"${CLAUDE_PLUGIN_ROOT}/skills/continuous-learning-v2/hooks/observe.sh pre\"\n      }]\n    }],\n    \"PostToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"${CLAUDE_PLUGIN_ROOT}/skills/continuous-learning-v2/hooks/observe.sh post\"\n      }]\n    }]\n  }\n}\n```\n\n**If installed manually** to `~/.claude/skills`:\n\n```json\n{\n  \"hooks\": {\n    \"PreToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"~/.claude/skills/continuous-learning-v2/hooks/observe.sh pre\"\n      }]\n    }],\n    \"PostToolUse\": [{\n      \"matcher\": \"*\",\n      \"hooks\": [{\n        \"type\": \"command\",\n        \"command\": \"~/.claude/skills/continuous-learning-v2/hooks/observe.sh post\"\n      }]\n    }]\n  }\n}\n```\n\n### 2. Initialize Directory Structure\n\nThe Python CLI will create these automatically, but you can also create them manually:\n\n```bash\nmkdir -p ~/.claude/homunculus/{instincts/{personal,inherited},evolved/{agents,skills,commands}}\ntouch ~/.claude/homunculus/observations.jsonl\n```\n\n### 3. Use the Instinct Commands\n\n```bash\n/instinct-status     # Show learned instincts with confidence scores\n/evolve              # Cluster related instincts into skills/commands\n/instinct-export     # Export instincts for sharing\n/instinct-import     # Import instincts from others\n```\n\n## Commands\n\n| Command | Description |\n|---------|-------------|\n| `/instinct-status` | Show all learned instincts with confidence |\n| `/evolve` | Cluster related instincts into skills/commands |\n| `/instinct-export` | Export instincts for sharing |\n| `/instinct-import <file>` | Import instincts from others |\n\n## Configuration\n\nEdit `config.json`:\n\n```json\n{\n  \"version\": \"2.0\",\n  \"observation\": {\n    \"enabled\": true,\n    \"store_path\": \"~/.claude/homunculus/observations.jsonl\",\n    \"max_file_size_mb\": 10,\n    \"archive_after_days\": 7\n  },\n  \"instincts\": {\n    \"personal_path\": \"~/.claude/homunculus/instincts/personal/\",\n    \"inherited_path\": \"~/.claude/homunculus/instincts/inherited/\",\n    \"min_confidence\": 0.3,\n    \"auto_approve_threshold\": 0.7,\n    \"confidence_decay_rate\": 0.05\n  },\n  \"observer\": {\n    \"enabled\": true,\n    \"model\": \"haiku\",\n    \"run_interval_minutes\": 5,\n    \"patterns_to_detect\": [\n      \"user_corrections\",\n      \"error_resolutions\",\n      \"repeated_workflows\",\n      \"tool_preferences\"\n    ]\n  },\n  \"evolution\": {\n    \"cluster_threshold\": 3,\n    \"evolved_path\": \"~/.claude/homunculus/evolved/\"\n  }\n}\n```\n\n## File Structure\n\n```\n~/.claude/homunculus/\n├── identity.json           # Your profile, technical level\n├── observations.jsonl      # Current session observations\n├── observations.archive/   # Processed observations\n├── instincts/\n│   ├── personal/           # Auto-learned instincts\n│   └── inherited/          # Imported from others\n└── evolved/\n    ├── agents/             # Generated specialist agents\n    ├── skills/             # Generated skills\n    └── commands/           # Generated commands\n```\n\n## Integration with Skill Creator\n\nWhen you use the [Skill Creator GitHub App](https://skill-creator.app), it now generates **both**:\n- Traditional SKILL.md files (for backward compatibility)\n- Instinct collections (for v2 learning system)\n\nInstincts from repo analysis have `source: \"repo-analysis\"` and include the source repository URL.\n\n## Confidence Scoring\n\nConfidence evolves over time:\n\n| Score | Meaning | Behavior |\n|-------|---------|----------|\n| 0.3 | Tentative | Suggested but not enforced |\n| 0.5 | Moderate | Applied when relevant |\n| 0.7 | Strong | Auto-approved for application |\n| 0.9 | Near-certain | Core behavior |\n\n**Confidence increases** when:\n- Pattern is repeatedly observed\n- User doesn''t correct the suggested behavior\n- Similar instincts from other sources agree\n\n**Confidence decreases** when:\n- User explicitly corrects the behavior\n- Pattern isn''t observed for extended periods\n- Contradicting evidence appears\n\n## Why Hooks vs Skills for Observation?\n\n> \"v1 relied on skills to observe. Skills are probabilistic—they fire ~50-80% of the time based on Claude''s judgment.\"\n\nHooks fire **100% of the time**, deterministically. This means:\n- Every tool call is observed\n- No patterns are missed\n- Learning is comprehensive\n\n## Backward Compatibility\n\nv2 is fully compatible with v1:\n- Existing `~/.claude/skills/learned/` skills still work\n- Stop hook still runs (but now also feeds into v2)\n- Gradual migration path: run both in parallel\n\n## Privacy\n\n- Observations stay **local** on your machine\n- Only **instincts** (patterns) can be exported\n- No actual code or conversation content is shared\n- You control what gets exported\n\n## Related\n\n- [Skill Creator](https://skill-creator.app) - Generate instincts from repo history\n- Homunculus - Community project that inspired the v2 instinct-based architecture (atomic observations, confidence scoring, instinct evolution pipeline)\n- [The Longform Guide](https://x.com/affaanmustafa/status/2014040193557471352) - Continuous learning section\n\n---\n\n*Instinct-based learning: teaching Claude your patterns, one observation at a time.*\n"},"lastSynced":"2026-03-06T07:04:01.323Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code needing advanced instinct-based learning capabilities with confidence scoring","zh":"适用于需要高级基于本能的学习能力和置信度评分的AI代理，如Claude Code","ja":"Claude Codeのような、高度な直感ベースの学習機能と信頼性スコアリングが必要なAIエージェントに適しています","ko":"클로드 코드와 같은 고급 본능 기반 학습 능력 및 신뢰도评分이 필요한 AI 에이전트에 적합합니다","es":"Ideal para agentes de IA como Claude Code que necesitan capacidades de aprendizaje avanzadas basadas en instintos con puntuación de confianza","fr":"Idéal pour les agents IA comme Claude Code ayant besoin de capacités d''apprentissage avancées basées sur l''instinct avec notation de confiance","de":"Ideal für KI-Agenten wie Claude Code, die erweiterte, instinktbasierende Lernfähigkeiten mit Vertrauensbewertung benötigen","pt":"Ideal para Agentes de IA como Claude Code que necessitam de capacidades de aprendizado baseado em instintos avançadas com pontuação de confiança","ru":"Идеально для агентов ИИ, таких как Claude Code, требующих продвинутых возможностей обучения на основе инстинкта с оценкой уверенности","ar":"مثالي لعميل الذكاء الاصطناعي مثل Claude Code الذي يحتاج إلى قابليات تعلم متقدمة قائم على الحدس مع تسجيل درجات الثقة"},"recommendation":{"en":"Empowers agents to turn Claude Code sessions into reusable knowledge through atomic ''instincts'' with confidence scoring, utilizing instinct-based behavior extraction via hooks and tuning confidence thresholds for learned behaviors","zh":"赋予代理将Claude Code会话转化为可重用知识的能力，通过原子化的''本能''和置信度评分，利用hook实现基于本能的行为提取，并调整学习行为的置信度阈值","ja":"Claude Codeのセッションを再利用可能な知識に変換する機能をエージェントに与え、原子的な''直感''と信頼性スコアリングを利用し、フックを介して直感ベースの動作抽出を行い、学習した動作の信頼性しきい値を調整します","ko":"클라우드 코드 세션을 재사용 가능한 지식으로 변환할 수 있는 기능을 에이전트에 부여하고, 원자적인 ''본능''과 신뢰도 평가를 사용하여 후크를 통해 본능 기반 행동 추출을 수행하고, 학습된 행동의 신뢰도 임계값을 조정합니다","es":"Permite a los agentes convertir sesiones de Claude Code en conocimiento reutilizable a través de ''instintos'' atómicos con puntuación de confianza, utilizando la extracción de comportamiento basada en instintos a través de hooks y ajustando los umbrales de confianza para comportamientos aprendidos","fr":"Permet aux agents de transformer des sessions Claude Code en connaissances réutilisables à travers des ''instincts'' atomiques avec notation de confiance, en utilisant l''extraction de comportement basée sur l''instinct via des hooks et en réglant les seuils de confiance pour les comportements appris","de":"Ermöglicht es Agenten, Claude Code-Sitzungen in wiederverwendbares Wissen durch atomare ''Instinkte'' mit Vertrauensbewertung umzuwandeln, indem sie die Extraktion von instinktbasiertem Verhalten über Hooks nutzen und die Vertrauensschwellen für gelerntes Verhalten anpassen","pt":"Habilita os agentes a transformar sessões do Claude Code em conhecimento reutilizável por meio de ''instintos'' atômicos com pontuação de confiança, utilizando extração de comportamento baseado em instintos via hooks e ajuste de limiares de confiança para comportamentos aprendidos","ru":"Наделяет агентов возможностью превратить сессии Claude Code в многократно используемые знания посредством атомарных ''инстинктов'' с оценкой уверенности, используя извлечение поведения на основе инстинкта через хуки и настройку порогов уверенности для выученных поведений","ar":"تمكّن الوكيل من تحويل جلسات Claude Code إلى معرفة قابلة لإعادة الاستخدام من خلال ''الحدس'' الذري مع تسجيل درجات الثقة، باستخدام استخراج السلوك القائم على الحدس عبر hooks وضبط عتبات الثقة للتصرفات المكتسبة"},"useCases":{"en":["Automating learning from Claude Code sessions","Configuring instinct-based behavior extraction via hooks","Evolving instincts into full-fledged knowledge libraries"],"zh":["从Claude Code会话中自动学习","通过hook配置基于本能的行为提取","将本能演化为完整的知识库"],"ja":["Claude Codeのセッションから自動的に学習する","フックを介して直感ベースの動作抽出を構成する","直感を完全な知識ライブラリに進化させる"],"ko":["클라우드 코드 세션에서 자동으로 학습하기","후크를 통해 본능 기반 행동 추출을 구성하기","본능을 완전한 지식 라이브러리로 진화시키기"],"es":["Automatizar el aprendizaje de sesiones de Claude Code","Configurar la extracción de comportamiento basada en instintos a través de hooks","Evolutionar instintos en bibliotecas de conocimiento completas"],"fr":["Automatiser l''apprentissage à partir de sessions Claude Code","Configurer l''extraction de comportement basée sur l''instinct via des hooks","Évoluer les instincts en bibliothèques de connaissances à part entière"],"de":["Das Lernen aus Claude Code-Sitzungen automatisieren","Die Extraktion von instinktbasiertem Verhalten über Hooks konfigurieren","Instinkte in vollständige Wissensbibliotheken weiterentwickeln"],"pt":["Automatizar o aprendizado a partir de sessões do Claude Code","Configurar a extração de comportamento baseado em instintos via hooks","Evoluir os instintos em bibliotecas de conhecimento completas"],"ru":["Автоматизировать обучение из сессий Claude Code","Настроить извлечение поведения на основе инстинкта через хуки","Развивать инстинкты в полноценные знания"],"ar":["تحويل جلسات Claude Code إلى تعلم آلي","تكوين استخراج السلوك القائم على الحدس عبر hooks","تطوير الحدس إلى مكتبات معرفة كاملة"]},"limitations":{"en":["Requires Claude Code sessions for knowledge generation","Needs configuration of instinct-based behavior extraction via hooks","Dependent on confidence threshold tuning for effective learning"],"zh":["需要Claude Code会话来生成知识","需要通过hook配置基于本能的行为提取","依赖于置信度阈值调节以实现有效学习"],"ja":["知識の生成にはClaude Codeのセッションが必要","直感ベースの動作抽出をフックを介して構成する必要がある","効果的な学習には信頼性しきい値の調整に依存する"],"ko":["지식 생성을 위해 클라우드 코드 세션이 필요합니다","본능 기반 행동 추출을 후크를 통해 구성해야 합니다","유효한 학습을 위해 신뢰도 임계값 조정에 의존합니다"],"es":["Requiere sesiones de Claude Code para la generación de conocimiento","Necesita configuración de la extracción de comportamiento basada en instintos a través de hooks","Dependiente del ajuste del umbral de confianza para un aprendizaje efectivo"],"fr":["Nécessite des sessions Claude Code pour la génération de connaissances","Nécessite une configuration de l''extraction de comportement basée sur l''instinct via des hooks","Dépend de la réglage du seuil de confiance pour un apprentissage efficace"],"de":["Benötigt Claude Code-Sitzungen für die Wissensgenerierung","Benötigt die Konfiguration der Extraktion von instinktbasiertem Verhalten über Hooks","Ist abhängig von der Anpassung der Vertrauensschwelle für ein effektives Lernen"],"pt":["Requer sessões do Claude Code para geração de conhecimento","Necessita de configuração da extração de comportamento baseado em instintos via hooks","Depende do ajuste do limiar de confiança para aprendizado eficaz"],"ru":["Требует сессий Claude Code для генерации знаний","Требует настройки извлечения поведения на основе инстинкта через хуки","Зависит от настройки порога уверенности для эффективного обучения"],"ar":["يتطلب جلسات Claude Code لتوليد المعرفة","يحتاج إلى تكوين استخراج السلوك القائم على الحدس عبر hooks","يعتمد على ضبط عتبات الثقة للتعلم الفعال"]},"version":4},"contentHash":"727bdebde88d3f921ee6cbd95eaacb76162292b0dce80360ff3ba4c955d04e54","qualityScore":47}');
