INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('T-rav/hydraflow/continuous-learning-v2', 'continuous-learning-v2', 'T-rav', 'hydraflow', 'community', 'continuous-learning-v2 T-rav hydraflow community agentic-development agentic-workflow wishful-programming Continuous-Learning-V2 is an advanced learning system that turns Claude Code sessions into reusable knowledge. It benefits developers by providing atomic ''instincts'' with confidence scoring. continuous-learning-v2是一种高级的学习系统，通过atomic "instincts"实现智能编程和自动化学习 continuous-learning-v2は、atomic "instincts"を使用してAIエージェントベースの学習システムを実現する高度な学習システムです continuous-learning-v2는 atomic "instincts"를 사용하여 지속적 학습을 위한 AI 에이전트를 구축하는 고급 학습 시스템입니다 Continuous Learning v2 es un sistema de aprendizaje avanzado que convierte sesiones de Claude Code en conocimiento reutilizable a través de ''instintos'' atómicos con puntuación de confianza. Continuous Learning v2 est un système d''apprentissage avancé qui transforme les sessions Claude Code en connaissances réutilisables via des ''instincts'' atomiques avec notation de confiance. Continuous Learning v2 ist ein fortschrittliches Lernsystem, das Claude-Code-Sitzungen in wiederverwendbares Wissen durch atomare ''Instinkte'' mit Vertrauensbewertung umwandelt. O Continuous Learning v2 é um sistema de aprendizado avançado que transforma suas sessões de Claude Code em conhecimento reutilizável por meio de ''instintos'' atômicos Continuous Learning v2 - это продвинутая система обучения, которая превращает ваши сессии Claude Code в многоразовое знание через атомарные ''инстинкты'' Continuous Learning v2 هو نظام تعلم متقدم يتحول جلساتك من Claude Code إلى معرفة قابلة لإعادة الاستخدام من خلال ''الانفعالات'' الذرية how to use continuous-learning-v2 what is continuous-learning-v2 continuous-learning-v2 setup guide continuous-learning-v2 alternative continuous-learning-v2 vs agentic-development installing continuous-learning-v2 for HydraFlow continuous-learning-v2 tutorial for AI agents agentic-workflow with continuous-learning-v2 wishful-programming with continuous-learning-v2 continuous-learning-v2 AIエージェント 智能编程 自动化学习 atomic instincts Claude Code confidence scoring instinct libraries Activates automatic learning from Claude Code sessions Configures instinct-based behavior extraction via hooks Tunes confidence thresholds for learned behaviors Supports reviewing, exporting, or importing instinct libraries Evolve instincts into full-fledged behaviors Continuous-Learning-V2 is an advanced learning system that enables instinct-based architecture for reusable knowledge extraction from Claude Code sessions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('evildarkarchon/FormID-Database-Manager/openspec-explore', 'community', 'evildarkarchon', 'FormID-Database-Manager', 'evildarkarchon/FormID-Database-Manager', 'openspec-explore', 2, 0, 47, '2026-02-28T13:02:33Z', '2026-03-07T01:53:38.055Z', '64ded43c11f45d9be10670202659bbbb81bb70e4fd67d3579ae31f1a1f693911', '{"id":"evildarkarchon/FormID-Database-Manager/openspec-explore","name":"openspec-explore","description":{"en":"The openspec-explore skill enables developers to enter exploration mode, allowing them to think deeply and visualize freely without writing code. This skill benefits developers who need to investigate codebases and create OpenSpec proposals, designs, and specs.","zh":"openspec-explore 是一种探索模式，允许开发者自由思考和创建 OpenSpec 文档","ja":"openspec-explore は探索モードで思考し、OpenSpec アーティファクトを作成する AI エージェントです","ko":"openspec-explore는 탐색 모드에서 생각하고 OpenSpec 아티팩트를 생성할 수 있는 개발 도구입니다","es":"Openspec-explore es un modo de exploración que permite a los desarrolladores investigar y diseñar sin implementar código, creando artefactos OpenSpec como propuestas y especificaciones","fr":"Openspec-explore est un mode d''exploration qui permet aux développeurs d''investiguer et de concevoir sans implémenter de code, en créant des artefacts OpenSpec tels que des propositions et des spécifications","de":"Openspec-explore ist ein Explorationsmodus, der es Entwicklern ermöglicht, zu untersuchen und zu entwerfen, ohne Code zu implementieren, und OpenSpec-Artefakte wie Vorschläge und Spezifikationen zu erstellen","pt":"O openspec-explore é um modo de exploração que permite pensar e visualizar livremente, sem implementar recursos","ru":"openspec-explore - это режим изучения, который позволяет глубоко подумать и визуализировать без реализации функций с помощью ИИ Агентов","ar":"openspec-explore هو وضع استكشاف يسمح بالتفكير والتصور بحرية بدون تنفيذ الميزات باستخدام الأدوات الذكية"},"seo":{"title":{"en":"openspec-explore: Exploration Mode Setup Guide | AI Agent...","zh":"openspec-explore 设置指南：探索模式和 OpenSpec 文档","ja":"openspec-explore のベストプラクティス：AIエージェントと探索モード","ko":"openspec-explore 사용법: 탐색 모드와 OpenSpec 아티팩트 생성","es":"Guía de configuración de openspec-explore para desarrolla...","fr":"Mode d''exploration openspec-explore : Guide de démarrage","de":"Openspec-Explore-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração do openspec-explore: Modo de Explora...","ru":"Настройка openspec-explore: Режим Изучения и Исследования...","ar":"دليل إعداد openspec-explore: وضع الاستكشاف المتقدم للأدوا..."},"description":{"en":"Unlock the full potential of openspec-explore and discover how to think deeply, visualize freely, and create OpenSpec artifacts without implementing code. Le...","zh":"了解 openspec-explore 的探索模式，创建 OpenSpec 文档，提高开发效率","ja":"openspec-explore を使用して探索モードで思考し、OpenSpec アーティファクトを作成する","ko":"openspec-explore를 사용하여 탐색 모드에서 생각하고 OpenSpec 아티팩트를 생성하여 개발 효율성을 높이세요","es":"Descubre cómo utilizar openspec-explore para investigar y diseñar sin implementar código, y crea artefactos OpenSpec con facilidad","fr":"Découvrez comment utiliser openspec-explore pour investiguer et concevoir sans implémenter de code, et créez des artefacts OpenSpec avec facilité","de":"Erfahren Sie, wie Sie openspec-explore verwenden, um zu untersuchen und zu entwerfen, ohne Code zu implementieren, und erstellen Sie OpenSpec-Artefakte mit L...","pt":"Aprenda a usar o openspec-explore para explorar códigos e criar artefatos OpenSpec sem implementar recursos","ru":"Узнайте, как использовать openspec-explore для изучения кода и создания артефактов OpenSpec без реализации функций с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام openspec-explore لاستكشاف الأكواد وإنشاء مكونات OpenSpec بدون تنفيذ الميزات باستخدام الأدوات الذكية"},"definition":{"en":"openspec-explore is a skill that enables exploration mode for thinking and visualizing, allowing developers to read files, search code, and investigate codebases without implementing features.","zh":"openspec-explore 是一种探索模式，用于思考和创建 OpenSpec 文档","ja":"openspec-explore は思考と OpenSpec アーティファクトの作成のための探索モードです","ko":"openspec-explore는思考과 OpenSpec 아티팩트 생성을 위한 탐색 모드입니다","es":"Openspec-explore es un modo de exploración que permite investigar y diseñar sin implementar código","fr":"Openspec-explore est un mode d''exploration qui permet d''investiguer et de concevoir sans implémenter de code","de":"Openspec-explore ist ein Explorationsmodus, der es ermöglicht, zu untersuchen und zu entwerfen, ohne Code zu implementieren","pt":"O que é openspec-explore? Um modo de exploração para pensar e visualizar códigos sem implementar recursos","ru":"Что такое openspec-explore? Режим изучения для глубокого размышления и визуализации кода без реализации функций","ar":"ما هو openspec-explore? وضع استكشاف للتفكير والتصور الأكواد بدون تنفيذ الميزات"},"features":{"en":["Enters exploration mode for thinking and visualizing","Allows reading files and searching code","Enables investigation of codebases without implementing features","Supports creation of OpenSpec artifacts, such as proposals, designs, and specs","Reminds users to exit explore mode before implementing code changes","Integrates with commands like /opsx:new and /opsx:ff for seamless workflow"],"zh":["探索模式：自由思考和创建 OpenSpec 文档","创建 OpenSpec 文档：提案、设计、规格","不允许写代码或实现功能","可以读取文件、搜索代码和调查代码库","支持 OpenSpec 文档的创建"],"ja":["探索モード：自由に思考し OpenSpec アーティファクトを作成する","OpenSpec アーティファクトの作成：提案、設計、仕様","コードの書き込みや機能の実装は不可能","ファイルの読み取り、コードの検索、コードベースの調査が可能","OpenSpec アーティファクトの作成をサポートする"],"ko":["탐색 모드: 자유롭게 생각하고 OpenSpec 아티팩트를 생성","OpenSpec 아티팩트 생성: 제안, 설계, 사양","코드 작성이나 기능 구현은 불가능","파일 읽기, 코드 검색, 코드베이스 조사 가능","OpenSpec 아티팩트 생성을 지원"],"es":["Investigación de código sin implementación","Creación de artefactos OpenSpec como propuestas y especificaciones","Diseño y exploración de la base de código","Compatibilidad con la lectura de archivos y búsqueda de código","No requiere implementación de características"],"fr":["Investigation de code sans implémentation","Création d''artefacts OpenSpec tels que des propositions et des spécifications","Conception et exploration de la base de code","Compatibilité avec la lecture de fichiers et la recherche de code","Nécessite pas l''implémentation de fonctionnalités"],"de":["Untersuchung von Code ohne Implementierung","Erstellung von OpenSpec-Artefakten wie Vorschlägen und Spezifikationen","Entwurf und Exploration der Codebasis","Kompatibilität mit der Dateilesung und der Code-Suche","Erfordert keine Implementierung von Funktionen"],"pt":["Exploração de códigos sem implementar recursos","Criação de artefatos OpenSpec","Leitura de arquivos e busca de código","Investigação do codebase","Suporte à visualização livre"],"ru":["Изучение кода без реализации функций","Создание артефактов OpenSpec","Чтение файлов и поиск кода","Изучение кодовой базы","Поддержка свободной визуализации с помощью ИИ Агентов"],"ar":["استكشاف الأكواد بدون تنفيذ الميزات","إنشاء مكونات OpenSpec","قراءة الملفات و البحث عن الأكواد","التحقيق في قاعدة الأكواد","دعم التصور الحر باستخدام الأدوات الذكية"]},"keywords":{"en":["how to use openspec-explore","openspec-explore alternative","openspec-explore setup guide","what is openspec-explore","openspec-explore vs other AI skills","openspec-explore install","openspec-explore exploration mode","openspec-explore OpenSpec artifacts","openspec-explore code investigation","openspec-explore workflow integration"],"zh":["openspec-explore","探索模式","OpenSpec 文档","AI 工具","开发效率","代码库管理","OpenSpec 文档创建"],"ja":["openspec-explore","探索モード","OpenSpec アーティファクト","AI エージェント","開発効率","コードベース管理","OpenSpec アーティファクトの作成"],"ko":["openspec-explore","탐색 모드","OpenSpec 아티팩트","AI 도구","개발 효율성","코드베이스 관리","OpenSpec 아티팩트 생성"],"es":["openspec-explore","herramientas de AI para desarrolladores","modos de exploración de código","diseño de software sin implementación","creación de artefactos OpenSpec","investigación de código","lectura de archivos","búsqueda de código"],"fr":["openspec-explore","outils d''IA pour développeurs","modes d''exploration de code","conception de logiciels sans implémentation","création d''artefacts OpenSpec","investigation de code","lecture de fichiers","recherche de code"],"de":["openspec-explore","AI-Tools für Entwickler","Code-Explorationsmodi","Software-Design ohne Implementierung","Erstellung von OpenSpec-Artefakten","Code-Untersuchung","Dateilesung","Code-Suche"],"pt":["openspec-explore","modo de exploração","visualização de código","artefatos OpenSpec","leitura de arquivos","busca de código","investigação de codebase","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["openspec-explore","режим изучения","визуализация кода","артефакты OpenSpec","чтение файлов","поиск кода","изучение кодовой базы","разработка программного обеспечения","инструменты разработки","ИИ Агенты"],"ar":["openspec-explore","وضع الاستكشاف","تصور الأكواد","مكونات OpenSpec","قراءة الملفات","البحث عن الأكواد","التحقيق في قاعدة الأكواد","تطوير البرمجيات","أدوات التطوير","الأدوات الذكية"]}},"owner":"evildarkarchon","repo":"FormID-Database-Manager","repoPath":"evildarkarchon/FormID-Database-Manager","stars":2,"forks":0,"updatedAt":"2026-02-28T13:02:33Z","topics":[],"category":"community","skillMd":{"name":"openspec-explore","description":"Enter explore mode - a thinking partner for exploring ideas, investigating problems, and clarifying requirements. Use when the user wants to think through something before or during a change.","version":"1.0","bodyPreview":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s c","body":"Enter explore mode. Think deeply. Visualize freely. Follow the conversation wherever it goes.\n\n**IMPORTANT: Explore mode is for thinking, not implementing.** You may read files, search code, and investigate the codebase, but you must NEVER write code or implement features. If the user asks you to implement something, remind them to exit explore mode first (e.g., start a change with `/opsx:new` or `/opsx:ff`). You MAY create OpenSpec artifacts (proposals, designs, specs) if the user asks—that''s capturing thinking, not implementing.\n\n**This is a stance, not a workflow.** There are no fixed steps, no required sequence, no mandatory outputs. You''re a thinking partner helping the user explore.\n\n---\n\n## The Stance\n\n- **Curious, not prescriptive** - Ask questions that emerge naturally, don''t follow a script\n- **Open threads, not interrogations** - Surface multiple interesting directions and let the user follow what resonates. Don''t funnel them through a single path of questions.\n- **Visual** - Use ASCII diagrams liberally when they''d help clarify thinking\n- **Adaptive** - Follow interesting threads, pivot when new information emerges\n- **Patient** - Don''t rush to conclusions, let the shape of the problem emerge\n- **Grounded** - Explore the actual codebase when relevant, don''t just theorize\n\n---\n\n## What You Might Do\n\nDepending on what the user brings, you might:\n\n**Explore the problem space**\n- Ask clarifying questions that emerge from what they said\n- Challenge assumptions\n- Reframe the problem\n- Find analogies\n\n**Investigate the codebase**\n- Map existing architecture relevant to the discussion\n- Find integration points\n- Identify patterns already in use\n- Surface hidden complexity\n\n**Compare options**\n- Brainstorm multiple approaches\n- Build comparison tables\n- Sketch tradeoffs\n- Recommend a path (if asked)\n\n**Visualize**\n```\n┌─────────────────────────────────────────┐\n│     Use ASCII diagrams liberally        │\n├─────────────────────────────────────────┤\n│                                         │\n│   ┌────────┐         ┌────────┐        │\n│   │ State  │────────▶│ State  │        │\n│   │   A    │         │   B    │        │\n│   └────────┘         └────────┘        │\n│                                         │\n│   System diagrams, state machines,      │\n│   data flows, architecture sketches,    │\n│   dependency graphs, comparison tables  │\n│                                         │\n└─────────────────────────────────────────┘\n```\n\n**Surface risks and unknowns**\n- Identify what could go wrong\n- Find gaps in understanding\n- Suggest spikes or investigations\n\n---\n\n## OpenSpec Awareness\n\nYou have full context of the OpenSpec system. Use it naturally, don''t force it.\n\n### Check for context\n\nAt the start, quickly check what exists:\n```bash\nopenspec list --json\n```\n\nThis tells you:\n- If there are active changes\n- Their names, schemas, and status\n- What the user might be working on\n\n### When no change exists\n\nThink freely. When insights crystallize, you might offer:\n\n- \"This feels solid enough to start a change. Want me to create one?\"\n  → Can transition to `/opsx:new` or `/opsx:ff`\n- Or keep exploring - no pressure to formalize\n\n### When a change exists\n\nIf the user mentions a change or you detect one is relevant:\n\n1. **Read existing artifacts for context**\n   - `openspec/changes/<name>/proposal.md`\n   - `openspec/changes/<name>/design.md`\n   - `openspec/changes/<name>/tasks.md`\n   - etc.\n\n2. **Reference them naturally in conversation**\n   - \"Your design mentions using Redis, but we just realized SQLite fits better...\"\n   - \"The proposal scopes this to premium users, but we''re now thinking everyone...\"\n\n3. **Offer to capture when decisions are made**\n\n   | Insight Type | Where to Capture |\n   |--------------|------------------|\n   | New requirement discovered | `specs/<capability>/spec.md` |\n   | Requirement changed | `specs/<capability>/spec.md` |\n   | Design decision made | `design.md` |\n   | Scope changed | `proposal.md` |\n   | New work identified | `tasks.md` |\n   | Assumption invalidated | Relevant artifact |\n\n   Example offers:\n   - \"That''s a design decision. Capture it in design.md?\"\n   - \"This is a new requirement. Add it to specs?\"\n   - \"This changes scope. Update the proposal?\"\n\n4. **The user decides** - Offer and move on. Don''t pressure. Don''t auto-capture.\n\n---\n\n## What You Don''t Have To Do\n\n- Follow a script\n- Ask the same questions every time\n- Produce a specific artifact\n- Reach a conclusion\n- Stay on topic if a tangent is valuable\n- Be brief (this is thinking time)\n\n---\n\n## Handling Different Entry Points\n\n**User brings a vague idea:**\n```\nUser: I''m thinking about adding real-time collaboration\n\nYou: Real-time collab is a big space. Let me think about this...\n\n      COLLABORATION SPECTRUM\n      ════════════════════════════════════════════\n\n      Awareness          Coordination         Sync\n          │                   │                 │\n          ▼                   ▼                 ▼\n      ┌────────┐         ┌────────┐        ┌────────┐\n      │Presence│         │Cursors │        │  CRDT  │\n      │  \"3    │         │ Multi  │        │Conflict│\n      │online\" │         │ select │        │  free  │\n      └────────┘         └────────┘        └────────┘\n          │                   │                 │\n       trivial            moderate           complex\n\n      Where''s your head at?\n```\n\n**User brings a specific problem:**\n```\nUser: The auth system is a mess\n\nYou: [reads codebase]\n\n     ┌─────────────────────────────────────────────┐\n     │              CURRENT AUTH FLOW              │\n     └─────────────────────────────────────────────┘\n                        │\n          ┌─────────────┼─────────────┐\n          ▼             ▼             ▼\n     ┌─────────┐  ┌─────────┐  ┌─────────┐\n     │ Google  │  │  GitHub │  │  Email  │\n     │  OAuth  │  │  OAuth  │  │  Magic  │\n     └────┬────┘  └────┬────┘  └────┬────┘\n          │             │             │\n          └─────────────┼─────────────┘\n                        ▼\n                  ┌───────────┐\n                  │  Session  │\n                  └─────┬─────┘\n                        │\n                        ▼\n                  ┌───────────┐\n                  │   Perms   │\n                  └───────────┘\n\n     I see three tangles. Which one''s burning?\n```\n\n**User is stuck mid-implementation:**\n```\nUser: /opsx:explore add-auth-system\n      The OAuth integration is more complex than expected\n\nYou: [reads change artifacts]\n\n     You''re on task 4: \"Implement OAuth flow\"\n\n     Let me trace what''s involved...\n\n     [draws diagram, explores options, suggests paths]\n\n     Want to update the design to reflect this?\n     Or add a spike task to investigate?\n```\n\n**User wants to compare options:**\n```\nUser: Should we use Postgres or SQLite?\n\nYou: Generic answer is boring. What''s the context?\n\nUser: A CLI tool that tracks local dev environments\n\nYou: That changes everything.\n\n     ┌─────────────────────────────────────────────────┐\n     │         CLI TOOL DATA STORAGE                  │\n     └─────────────────────────────────────────────────┘\n\n     Key constraints:\n     • No daemon running\n     • Must work offline\n     • Single user\n\n                  SQLite          Postgres\n     Deployment   embedded ✓      needs server ✗\n     Offline      yes ✓           no ✗\n     Single file  yes ✓           no ✗\n\n     SQLite. Not even close.\n\n     Unless... is there a sync component?\n```\n\n---\n\n## Ending Discovery\n\nThere''s no required ending. Discovery might:\n\n- **Flow into action**: \"Ready to start? /opsx:new or /opsx:ff\"\n- **Result in artifact updates**: \"Updated design.md with these decisions\"\n- **Just provide clarity**: User has what they need, moves on\n- **Continue later**: \"We can pick this up anytime\"\n\nWhen it feels like things are crystallizing, you might summarize:\n\n```\n## What We Figured Out\n\n**The problem**: [crystallized understanding]\n\n**The approach**: [if one emerged]\n\n**Open questions**: [if any remain]\n\n**Next steps** (if ready):\n- Create a change: /opsx:new <name>\n- Fast-forward to tasks: /opsx:ff <name>\n- Keep exploring: just keep talking\n```\n\nBut this summary is optional. Sometimes the thinking IS the value.\n\n---\n\n## Guardrails\n\n- **Don''t implement** - Never write code or implement features. Creating OpenSpec artifacts is fine, writing application code is not.\n- **Don''t fake understanding** - If something is unclear, dig deeper\n- **Don''t rush** - Discovery is thinking time, not task time\n- **Don''t force structure** - Let patterns emerge naturally\n- **Don''t auto-capture** - Offer to save insights, don''t just do it\n- **Do visualize** - A good diagram is worth many paragraphs\n- **Do explore the codebase** - Ground discussions in reality\n- **Do question assumptions** - Including the user''s and your own\n"},"lastSynced":"2026-03-07T01:53:38.055Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing deep exploration and OpenSpec proposal generation capabilities.","zh":"适合需要深入探索和 OpenSpec 提案生成能力的代码分析代理。","ja":"コード分析エージェントが深い探索と OpenSpec 提案生成機能を必要とする場合に最適です。","ko":"코드 분석 에이전트가 깊은 탐색과 OpenSpec 제안 생성 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan una exploración profunda y capacidades de generación de propuestas de OpenSpec.","fr":"Parfait pour les Agents d''Analyse de Code nécessitant une exploration approfondie et des capacités de génération de propositions OpenSpec.","de":"Perfekt für Code-Analyse-Agents, die eine tiefe Exploration und OpenSpec-Proposals-Generierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de exploração profunda e capacidades de geração de propostas OpenSpec.","ru":"Идеально подходит для агентов анализа кода, которым необходимы глубокое исследование и возможности генерации предложений OpenSpec.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى استكشاف عميق وقدرات توليد مقترحات OpenSpec."},"recommendation":{"en":"Empowers agents to thoroughly investigate codebases, create OpenSpec artifacts like proposals, designs, and specs, and engage in unrestricted conversation using OpenSpec protocols, all while avoiding premature implementation.","zh":"赋予代理彻底调查代码库、创建 OpenSpec 文档，如提案、设计和规范，并使用 OpenSpec 协议进行无限制的对话，同时避免过早实现。","ja":"エージェントがコードベースを徹底的に調査し、OpenSpec アーティファクト such as 提案、設計、仕様を作成し、OpenSpec プロトコルを使用して制限のない会話を交わしながら、過早な実装を回避することを可能にします。","ko":"에이전트가 코드베이스를 철저하게 조사하고 OpenSpec 아티팩트(예: 제안, 설계, 사양)를 생성하며 OpenSpec 프로토콜을 사용하여 제한 없는 대화를 나누，同时過早な実装을 피하는 것을 가능하게 합니다.","es":"Habilita a los agentes a investigar exhaustivamente las bases de código, crear artefactos OpenSpec como propuestas, diseños y especificaciones, y participar en conversaciones ilimitadas utilizando protocolos OpenSpec, todo esto mientras evita la implementación prematura.","fr":"Permet aux agents d''enquêter de manière approfondie sur les bases de code, de créer des artefacts OpenSpec tels que des propositions, des conceptions et des spécifications, et de s''engager dans des conversations sans restriction en utilisant les protocoles OpenSpec, le tout en évitant une mise en œuvre prématurée.","de":"Ermöglicht es Agenten, Codebasen gründlich zu untersuchen, OpenSpec-Artefakte wie Vorschläge, Entwürfe und Spezifikationen zu erstellen und an unbeschränkten Gesprächen unter Verwendung von OpenSpec-Protokollen teilzunehmen, all dies, während eine vorzeitige Implementierung vermieden wird.","pt":"Habilita os agentes a investigar completamente as bases de código, criar artefatos OpenSpec, como propostas, projetos e especificações, e engajar-se em conversas sem restrições usando protocolos OpenSpec, tudo isso sem implementação prematura.","ru":"Наделяет агентов возможностью тщательно исследовать кодовые базы, создавать артефакты OpenSpec, такие как предложения, проекты и спецификации, и участвовать в неограниченных разговорах с использованием протоколов OpenSpec, все это без преждевременной реализации.","ar":"يمنح الوكلاء القدرة على التحقيق الشامل في قواعد البيانات ، وإنشاء مكونات OpenSpec مثل المقترحات والتصاميم والمواصفات ، والمشاركة في محادثات غير مقيدة باستخدام بروتوكولات OpenSpec ، كل ذلك بدون تنفيذ مسبق."},"useCases":{"en":["Investigating large codebases for optimization opportunities","Generating OpenSpec proposals for new features","Creating detailed design specs without writing code"],"zh":["探索大型代码库以查找优化机会","为新功能生成 OpenSpec 提案","创建详细的设计规范而无需编写代码"],"ja":["大規模なコードベースを最適化の機会を探すために調査する","新しい機能のための OpenSpec 提案を生成する","コードを書かずに詳細な設計仕様を作成する"],"ko":["최적화 기회를 찾기 위해 대규모 코드베이스를 조사하는 것","새로운 기능을 위한 OpenSpec 제안을 생성하는 것","코드를 작성하지 않고 자세한 디자인 사양을 생성하는 것"],"es":["Investigar grandes bases de código en busca de oportunidades de optimización","Generar propuestas OpenSpec para nuevas características","Crear especificaciones de diseño detalladas sin escribir código"],"fr":["Enquêter sur de grandes bases de code pour trouver des opportunités d''optimisation","Générer des propositions OpenSpec pour de nouvelles fonctionnalités","Créer des spécifications de conception détaillées sans écrire de code"],"de":["Große Codebasen auf Optimierungsmöglichkeiten untersuchen","OpenSpec-Vorschläge für neue Funktionen generieren","Detaillierte Entwurfspezifikationen erstellen, ohne Code zu schreiben"],"pt":["Investigar grandes bases de código para oportunidades de otimização","Gerar propostas OpenSpec para recursos novos","Criar especificações de projeto detalhadas sem escrever código"],"ru":["Изучение больших кодовых баз для поиска возможностей оптимизации","Генерация предложений OpenSpec для новых функций","Создание подробных технических спецификаций без написания кода"],"ar":["التحقيق في قواعد بيانات كبيرة للفرص التى تتيح تحسين الأداء","توليد مقترحات OpenSpec للميزات الجديدة","إنشاء مواصفات تصميم مفصلة بدون كتابة التعليمات البرمجية"]},"limitations":{"en":["Must not write code or implement features in explore mode","Requires exit from explore mode to start implementation with /opsx:new or /opsx:ff"],"zh":["探索模式下不能编写代码或实现功能","需要退出探索模式以使用 /opsx:new 或 /opsx:ff 开始实现"],"ja":["探索モードではコードを書いたり機能を実装したりできない","実装を開始するために /opsx:new または /opsx:ff を使用して探索モードを終了する必要がある"],"ko":["탐색 모드에서 코드를 작성하거나 기능을 구현할 수 없음","/opsx:new 또는 /opsx:ff를 사용하여 구현을 시작하기 위해 탐색 모드를 종료해야 함"],"es":["No debe escribir código ni implementar características en modo de exploración","Requiere la salida del modo de exploración para comenzar la implementación con /opsx:new o /opsx:ff"],"fr":["Ne doit pas écrire de code ou implémenter des fonctionnalités en mode d''exploration","Nécessite la sortie du mode d''exploration pour commencer l''implémentation avec /opsx:new ou /opsx:ff"],"de":["Darf in Explorationsmodus keinen Code schreiben oder Funktionen implementieren","Erfordert den Ausgang aus dem Explorationsmodus, um die Implementierung mit /opsx:new oder /opsx:ff zu starten"],"pt":["Não deve escrever código ou implementar recursos no modo de exploração","Exige saída do modo de exploração para iniciar a implementação com /opsx:new ou /opsx:ff"],"ru":["Не должно писать код или реализовывать функции в режиме исследования","Требует выхода из режима исследования для начала реализации с помощью /opsx:new или /opsx:ff"],"ar":["لا يجب كتابه الشفرة أو تنفيذ الميزات في وضع الاستكشاف","يتطلب الخروج من وضع الاستكشاف لبدء التنفيذ باستخدام /opsx:new أو /opsx:ff"]},"version":4},"contentHash":"64ded43c11f45d9be10670202659bbbb81bb70e4fd67d3579ae31f1a1f693911","qualityScore":47}');
