INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('evildarkarchon/FormID-Database-Manager/openspec-explore', 'openspec-explore', 'evildarkarchon', 'FormID-Database-Manager', 'community', 'openspec-explore evildarkarchon FormID-Database-Manager community The openspec-explore skill enables developers to enter exploration mode, allowing them to think deeply and visualize freely without writing code. This skill benefits developers who need to investigate codebases and create OpenSpec proposals, designs, and specs. openspec-explore 是一种探索模式，允许开发者自由思考和创建 OpenSpec 文档 openspec-explore は探索モードで思考し、OpenSpec アーティファクトを作成する AI エージェントです openspec-explore는 탐색 모드에서 생각하고 OpenSpec 아티팩트를 생성할 수 있는 개발 도구입니다 Openspec-explore es un modo de exploración que permite a los desarrolladores investigar y diseñar sin implementar código, creando artefactos OpenSpec como propuestas y especificaciones Openspec-explore est un mode d''exploration qui permet aux développeurs d''investiguer et de concevoir sans implémenter de code, en créant des artefacts OpenSpec tels que des propositions et des spécifications Openspec-explore ist ein Explorationsmodus, der es Entwicklern ermöglicht, zu untersuchen und zu entwerfen, ohne Code zu implementieren, und OpenSpec-Artefakte wie Vorschläge und Spezifikationen zu erstellen O openspec-explore é um modo de exploração que permite pensar e visualizar livremente, sem implementar recursos openspec-explore - это режим изучения, который позволяет глубоко подумать и визуализировать без реализации функций с помощью ИИ Агентов openspec-explore هو وضع استكشاف يسمح بالتفكير والتصور بحرية بدون تنفيذ الميزات باستخدام الأدوات الذكية how to use openspec-explore openspec-explore alternative openspec-explore setup guide what is openspec-explore openspec-explore vs other AI skills openspec-explore install openspec-explore exploration mode openspec-explore OpenSpec artifacts openspec-explore code investigation openspec-explore workflow integration openspec-explore 探索模式 OpenSpec 文档 AI 工具 开发效率 代码库管理 OpenSpec 文档创建 Enters exploration mode for thinking and visualizing Allows reading files and searching code Enables investigation of codebases without implementing features Supports creation of OpenSpec artifacts, such as proposals, designs, and specs Reminds users to exit explore mode before implementing code changes Integrates with commands like /opsx:new and /opsx:ff for seamless workflow openspec-explore is a skill that enables exploration mode for thinking and visualizing, allowing developers to read files, search code, and investigate codebases without implementing features.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nroze22/TalosixSkills/marketing-content', 'community', 'nroze22', 'TalosixSkills', 'nroze22/TalosixSkills', 'marketing-content', 1, 1, 47, '2026-03-03T17:36:46Z', '2026-03-06T07:18:53.030Z', '76d9f4c72cb0bdd9753c278c3fa83d4b8599e722e21876101a84b8d07133009c', '{"id":"nroze22/TalosixSkills/marketing-content","name":"marketing-content","description":{"en":"The marketing-content skill creates marketing content for Talosix EDC, positioning it as a leader in clinical trial technology for clinical operations directors, data managers, and trial sponsors.","zh":"Talosix EDC 营销内容生成技能，创建针对临床运营专业人员、数据经理和试验赞助商的有效营销内容","ja":"Talosix EDC マーケティングコンテンツ生成スキル、臨床運用専門家、データマネージャー、試験スポンサー向けの効果的なマーケティングコンテンツを作成","ko":"Talosix EDC 마케팅 콘텐츠 생성 스킬, 임상 운영 전문가, 데이터 관리자, 시술 후원자를 위한 효과적인 마케팅 콘텐츠 생성","es":"Genera contenido de marketing efectivo para Talosix EDC, enfocado en profesionales de operaciones clínicas y gestores de datos","fr":"Créez du contenu marketing efficace pour Talosix EDC, axé sur les professionnels des opérations cliniques et les gestionnaires de données","de":"Erstellen Sie effektive Marketinginhalte für Talosix EDC, ausgerichtet auf klinische Operations- und Datenmanagement-Professionals","pt":"O skill de marketing-content gera conteúdo de marketing para diretores de operações clínicas e gestores de dados clínicos, destacando a liderança da Talosix em tecnologia EDC","ru":"ИИ Агент для генерации маркетингового контента создает убедительный контент для клинических операций и спонсоров испытаний","ar":"أداة الذكاء الاصطناعي لإنشاء محتوى تسويقي تهدف إلى تعزيز vị trí شركة Talosix في تقنيات الأبحاث السريرية"},"seo":{"title":{"en":"Marketing-Content: Regulatory-Aware Content Generation fo...","zh":"Talosix EDC 营销内容生成设置指南","ja":"Talosix EDC マーケティングコンテンツ生成ベストプラクティス","ko":"Talosix EDC 마케팅 콘텐츠 생성 가이드","es":"Guía de configuració