INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nroze22/TalosixSkills/marketing-content', 'marketing-content', 'nroze22', 'TalosixSkills', 'community', 'marketing-content nroze22 TalosixSkills community The marketing-content skill creates marketing content for Talosix EDC, positioning it as a leader in clinical trial technology for clinical operations directors, data managers, and trial sponsors. Talosix EDC 营销内容生成技能，创建针对临床运营专业人员、数据经理和试验赞助商的有效营销内容 Talosix EDC マーケティングコンテンツ生成スキル、臨床運用専門家、データマネージャー、試験スポンサー向けの効果的なマーケティングコンテンツを作成 Talosix EDC 마케팅 콘텐츠 생성 스킬, 임상 운영 전문가, 데이터 관리자, 시술 후원자를 위한 효과적인 마케팅 콘텐츠 생성 Genera contenido de marketing efectivo para Talosix EDC, enfocado en profesionales de operaciones clínicas y gestores de datos Créez du contenu marketing efficace pour Talosix EDC, axé sur les professionnels des opérations cliniques et les gestionnaires de données Erstellen Sie effektive Marketinginhalte für Talosix EDC, ausgerichtet auf klinische Operations- und Datenmanagement-Professionals O skill de marketing-content gera conteúdo de marketing para diretores de operações clínicas e gestores de dados clínicos, destacando a liderança da Talosix em tecnologia EDC ИИ Агент для генерации маркетингового контента создает убедительный контент для клинических операций и спонсоров испытаний أداة الذكاء الاصطناعي لإنشاء محتوى تسويقي تهدف إلى تعزيز vị trí شركة Talosix في تقنيات الأبحاث السريرية how to use marketing-content for clinical trials what is marketing-content in EDC technology marketing-content alternative for clinical operations marketing-content vs traditional marketing methods marketing-content setup guide for AI agents marketing-content install for clinical trial EDC Talosix EDC 营销内容生成 临床运营专业人员营销 数据管理员营销 试验赞助商营销 AIエージェント营销 营销内容生成工具 临床试验 EDC 技术 Creates content for Clinical Operations Directors concerned with study timelines and budget control Generates marketing materials for Clinical Data Managers focused on data quality and integrity Maintains regulatory awareness and evidence-based credibility in all marketing content Positions Talosix as a leader in clinical trial EDC technology Resonates with trial sponsors and clinical operations professionals Marketing-content is a skill that generates compelling marketing content for clinical trial EDC technology, resonating with clinical operations professionals and maintaining regulatory awareness.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mgnfy-view/morpho-vault-v2-adapters/safe-refactor', 'community', 'mgnfy-view', 'morpho-vault-v2-adapters', 'mgnfy-view/morpho-vault-v2-adapters', 'safe-refactor', 1, 0, 47, '2026-01-28T12:25:58Z', '2026-03-06T13:11:46.817Z', '324ae74446e0986cf72330a8fc714d5f55fd01ba23d7ff92ec6d459c8f69417f', '{"id":"mgnfy-view/morpho-vault-v2-adapters/safe-refactor","name":"safe-refactor","description":{"en":"The safe-refactor skill refactors non-upgradeable Solidity contracts for DeFi protocols, improving code clarity and maintainability without altering semantics. It benefits developers working with Ethereum, Morpho, and Foundry.","zh":"safe-refactor 技术用于重构非升级的 Solidity 合约，提高代码清晰度、可维护性和内部结构，适用于 DeFi 协议和 Ethereum 开发","ja":"safe-refactor 技術は、非アップグレード可能な Solidity コントラクトをリファクタリングして、コードの明確性、保守性、内部構造を向上させます。DeFi プロトコルと Ethereum 開発に適しています","ko":"safe-refactor 기술은 비업그레이드 가능한 Solidity 계약을 리팩토링하여 코드의 명확성, 유지 보수성 및 내부 구조를 향상시키는 데 사용됩니다. DeFi 프로토콜 및 이더리움 개발에 적합합니다","es":"Safe-refactor es una herramienta de refactorización segura para contratos Solidity que mejora la claridad y mantenibilidad sin alterar la semántica","fr":"Safe-refactor est un outil de refactorisation sûr pour les contrats Solidity qui améliore la clarté et la maintenabilité sans altérer la sémantique","de":"Safe-refactor ist ein Werkzeug für sichere Refaktorierung von Solidity-Verträgen, das die Klarheit und Wartbarkeit verbessert, ohne die Semantik zu ändern","pt":"O safe-refactor é uma habilidade que refatora contratos Solidity para melhorar a clareza e manutenção, sem alterar o comportamento observable.","ru":"Safe-refactor - это навык, который рефакторит контракты Solidity для улучшения ясности и поддерживаемости, не изменяя наблюдаемое поведение.","ar":"safe-refactor هو مهارة تقوم بإعادة هيكلة العقود الصلبة لتحسين الوضوح والصيانة، دون تغيير السلوك المرئي."},"seo":{"title":{"en":"safe-refactor: Solidity Contract Refactoring Setup Guide ...","zh":"safe-refactor Setup Guide: Solidity 合约重构最佳实践","ja":"safe-refactor セットアップガイド: Solidity コントラクトのリファクタリング","ko":"safe-refactor 설정 가이드: Solidity 계약 리팩토링","es":"Guía de configuración de safe-refactor para refactorizaci...","fr":"Guide de mise en place de safe-refactor pour la refactori...","de":"Einrichtungsanleitung für safe-refactor zur sicheren Refa...","pt":"Guia de Configuração do safe-refactor para DeFi","ru":"Настройка safe-refactor для ИИ Агентов DeFi","ar":"دليل إعداد safe-refactor لتقنيات الـDeFi"},"description":{"en":"Unlock the full potential of your DeFi protocols with safe-refactor. Learn how to refactor non-upgradeable Solidity contracts for improved clarity and mainta...","zh":"了解 safe-refactor 技术，优化 Solidity 合约结构，提高代码可维护性和可读性，适用于 DeFi 协议和 Ethereum 开发","ja":"safe-refactor 技術を使用して Solidity コントラクトの構造を最適化し、コードの保守性と可読性を向上させます。DeFi プロトコルと Ethereum 開発に適しています","ko":"safe-refactor 기술을 사용하여 Solidity 계약 구조를 최적화하고 코드 유지 보수성과 가독성을 향상시키는 방법을 알아보세요. DeFi 프로토콜 및 이더리움 개발에 적합합니다","es":"Mejora la claridad y mantenibilidad de tus contratos Solidity con safe-refactor, una herramienta de refactorización segura para DeFi","fr":"Améliorez la clarté et la maintenabilité de vos contrats Solidity avec safe-refactor, un outil de refactorisation sûr pour DeFi","de":"Verbessern Sie die Klarheit und Wartbarkeit Ihrer Solidity-Verträge mit safe-refactor, einem Werkzeug für sichere Refaktorierung für DeFi","pt":"Aprenda a refactorar contratos Solidity com o safe-refactor, melhorando a clareza e manutenção sem alterar o comportamento","ru":"Узнайте, как рефакторить контракты Solidity с помощью safe-refactor, улучшая ясность и поддерживаемость без изменения поведения","ar":"تعرف على كيفية إعادة هيكلة العقود الصلبة باستخدام safe-refactor، مع تحسين الوضوح والصيانة دون تغيير السلوك"},"definition":{"en":"safe-refactor is a skill that refactors non-upgradeable Solidity contracts to improve internal structure and maintainability without changing observable behavior.","zh":"safe-refactor 是一种用于重构 Solidity 合约的技术，提高代码可维护性和可读性","ja":"safe-refactor は、Solidity コントラクトの構造を最適化するための技術です","ko":"safe-refactor는 Solidity 계약을 리팩토링하여 코드의 유지 보수성과 가독성을 향상시키는 기술입니다","es":"Safe-refactor es una herramienta de refactorización que mejora la estructura interna de contratos Solidity sin cambiar el comportamiento observable","fr":"Safe-refactor est un outil de refactorisation qui améliore la structure interne des contrats Solidity sans changer le comportement observable","de":"Safe-refactor ist ein Werkzeug für die Refaktorierung, das die interne Struktur von Solidity-Verträgen verbessert, ohne das beobachtbare Verhalten zu ändern","pt":"O que é safe-refactor? Uma habilidade que refatora contratos Solidity para melhorar a clareza e manutenção.","ru":"Что такое safe-refactor? Навык, который рефакторит контракты Solidity для улучшения ясности и поддерживаемости.","ar":"ما هو safe-refactor؟ مهارة تقوم بإعادة هيكلة العقود الصلبة لتحسين الوضوح والصيانة."},"features":{"en":["Refactors non-upgradeable Solidity contracts for improved clarity and maintainability","Supports Morpho vault v2 adapters for popular DeFi protocols","Ensures no changes to semantics, interfaces, or externally visible effects","Improves code readability and simplifies logic after behavior has been locked by tests","Prepares code for audit or review","Removes duplication and improves code organization"],"zh":["重构非升级的 Solidity 合约","提高代码清晰度和可维护性","优化内部结构","适用于 DeFi 协议和 Ethereum 开发","支持 Morpho vault v2 适配器","提高代码可读性"],"ja":["非アップグレード可能な Solidity コントラクトのリファクタリング","コードの明確性と保守性の向上","内部構造の最適化","DeFi プロトコルと Ethereum 開発への対応","Morpho vault v2 アダプターのサポート","コードの可読性の向上"],"ko":["비업그레이드 가능한 Solidity 계약의 리팩토링","코드의 명확성과 유지 보수성의 향상","내부 구조의 최적화","DeFi 프로토콜 및 이더리움 개발에 대한 지원","Morpho vault v2 어댑터 지원","코드의 가독성 향상"],"es":["Refactorización segura de contratos Solidity","Mejora de la claridad y mantenibilidad","Compatibilidad con DeFi y Ethereum","Integración con Morpho vault v2 adapters","Soporte para Foundry y Forge"],"fr":["Refactorisation sûre de contrats Solidity","Amélioration de la clarté et de la maintenabilité","Compatibilité avec DeFi et Ethereum","Intégration avec les adaptateurs Morpho vault v2","Prise en charge de Foundry et Forge"],"de":["Sichere Refaktorierung von Solidity-Verträgen","Verbesserung der Klarheit und Wartbarkeit","Kompatibilität mit DeFi und Ethereum","Integration mit Morpho vault v2-Adaptoren","Unterstützung für Foundry und Forge"],"pt":["Refatoração de contratos Solidity para melhorar a clareza e manutenção","Melhoria da estrutura interna sem alterar o comportamento observable","Remoção de duplicações e simplificação de lógica","Preparação de código para auditoria ou revisão","Integração com Morpho vault v2 adapters para DeFi"],"ru":["Рефакторинг контрактов Solidity для улучшения ясности и поддерживаемости","Улучшение внутренней структуры без изменения наблюдаемого поведения","Удаление дубликатов и упрощение логики","Подготовка кода для аудита или обзора","Интеграция с Morpho vault v2 адаптерами для DeFi"],"ar":["إعادة هيكلة العقود الصلبة لتحسين الوضوح والصيانة","تحسين الهيكل الداخلي دون تغيير السلوك المرئي","إزالة التكرارات وتبسيط المنطق","تحضير الشفرة للتدقيق أو المراجعة","التكامل مع محفظة Morpho v2 لتقنيات الـDeFi"]},"keywords":{"en":["how to use safe-refactor","safe-refactor setup guide","safe-refactor vs foundry","solidity contract refactoring","defi protocol development","ethereum contract optimization","morpho vault v2 adapters","safe-refactor install","safe-refactor alternative"],"zh":["safe-refactor","Solidity 合约","DeFi 协议","Ethereum 开发","Morpho vault v2","代码重构","代码可维护性","代码可读性","AIエージェント"],"ja":["safe-refactor","Solidity コントラクト","DeFi プロトコル","Ethereum 開発","Morpho vault v2","コードリファクタリング","コードの保守性","コードの可読性","AIエージェント"],"ko":["safe-refactor","Solidity 계약","DeFi 프로토콜","이더리움 개발","Morpho vault v2","코드 리팩토링","코드 유지 보수성","코드 가독성","AI 에이전트"],"es":["safe-refactor","refactorización segura","contratos Solidity","DeFi","Ethereum","Morpho vault v2","Foundry","Forge","herramientas de refactorización"],"fr":["safe-refactor","refactorisation sûre","contrats Solidity","DeFi","Ethereum","Morpho vault v2","Foundry","Forge","outils de refactorisation"],"de":["safe-refactor","sichere Refaktorierung","Solidity-Verträge","DeFi","Ethereum","Morpho vault v2","Foundry","Forge","Werkzeuge für Refaktorierung"],"pt":["safe-refactor","DeFi","Solidity","contratos inteligentes","refatoração de código","manutenção de código","Morpho vault v2","adapters DeFi","desenvolvimento de blockchain"],"ru":["safe-refactor","DeFi","Solidity","умные контракты","рефакторинг кода","поддержка кода","Morpho vault v2","адаптеры DeFi","разработка блокчейна"],"ar":["safe-refactor","DeFi","Solidity","العقود الذكية","إعادة هيكلة الشفرة","صيانة الشفرة","Morpho vault v2","معدلات DeFi","تطوير البلوكشين"]}},"owner":"mgnfy-view","repo":"morpho-vault-v2-adapters","repoPath":"mgnfy-view/morpho-vault-v2-adapters","stars":1,"forks":0,"updatedAt":"2026-01-28T12:25:58Z","topics":["adapters","curation","defi","ethereum","forge","fork-testing","foundry","morpho-blockchain-lending","morpho-platform","vaults"],"category":"community","skillMd":{"name":"safe-refactor","description":"Refactor non-upgradeable Solidity contracts for clarity and maintainability without changing observable behavior, interfaces, or tests. Use when behavior is locked and you need structural cleanup.","bodyPreview":"# Skill: safe-refactor\n\n## Purpose\n\nRefactor **non-upgradeable** Solidity contracts to improve clarity,\nmaintainability, and internal structure **without changing any observable behavior**.\n\nThis skill is purely structural. It must not alter semantics, interfaces,\nor externally visible effects.\n\n## When to Invoke\n\n- Code cleanup\n- Duplication removal\n- Readability or maintainability improvements\n- Preparing code for audit or review\n- Simplifying logic after behavior has been locked by tests\n\n##","body":"# Skill: safe-refactor\n\n## Purpose\n\nRefactor **non-upgradeable** Solidity contracts to improve clarity,\nmaintainability, and internal structure **without changing any observable behavior**.\n\nThis skill is purely structural. It must not alter semantics, interfaces,\nor externally visible effects.\n\n## When to Invoke\n\n- Code cleanup\n- Duplication removal\n- Readability or maintainability improvements\n- Preparing code for audit or review\n- Simplifying logic after behavior has been locked by tests\n\n## Inputs Required\n\n- Target Solidity contracts\n- Existing test suite covering the affected behavior\n\n## Actions\n\nPermitted actions include:\n- Extracting internal helper functions\n- Renaming variables and internal functions for clarity\n- Simplifying control flow without semantic change\n- Removing dead code or unreachable branches\n- Reorganizing code to follow repository layout conventions\n\nRefactors must preserve:\n- execution order\n- revert behavior\n- event emission\n- state transitions\n- external call behavior\n\n## Constraints and Safety Rules\n\n- Must not change observable behavior\n- Must not change public or external APIs\n- Must not change custom errors or error parameters\n- Must not introduce or remove external calls\n- Must not introduce new dependencies\n- Must not modify storage semantics\n- Must comply with all rules in `.codex/constraints/solidity-style.md`\n- Tests must pass **unchanged**\n- No new tests may be added as justification for behavior changes\n\nIf a refactor would benefit from behavior changes, use a different skill.\n\n## Outputs\n\n- Refactored Solidity source files with identical behavior\n\n## Verification\n\n- `forge build` passes\n- `forge test` passes with no test changes\n- Behavior is identical under existing unit tests\n\n## Handoff\n\nIf refactoring reveals unclear or risky logic, consider:\n- `security-review` for deeper analysis\n- `docs-generator` to improve documentation without changing code\n\n## Example Prompts\n\n- “Use safe-refactor to simplify withdraw logic without changing behavior.”\n- “Refactor internal helpers in `VaultMath` for readability while preserving semantics.”\n"},"lastSynced":"2026-03-06T13:11:46.817Z","agentAnalysis":{"suitability":{"en":"Perfect for Solidity Analysis Agents needing advanced code refactoring capabilities for Ethereum, Morpho, and Foundry protocols.","zh":"适合需要为以太坊、Morpho和Foundry协议提供高级代码重构能力的Solidity分析代理。","ja":"Ethereum、Morpho、Foundryプロトコル向けの高度なコードリファクタリング機能を必要とするSolidity分析エージェントに適しています。","ko":"이더리움, Morpho 및 Foundry 프로토콜을 위한 고급 코드 리팩토링 기능이 필요한 솔리디티 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Solidity que necesitan capacidades de refactorización de código avanzadas para Ethereum, Morpho y protocolos Foundry.","fr":"Parfait pour les Agents d''Analyse de Solidity ayant besoin de capacités de refactoring de code avancées pour Ethereum, Morpho et les protocoles Foundry.","de":"Perfekt für Solidity-Analyse-Agents, die erweiterte Code-Refactoring-Funktionen für Ethereum, Morpho und Foundry-Protokolle benötigen.","pt":"Perfeito para Agentes de Análise de Solidity que necessitam de capacidades avançadas de refatoração de código para Ethereum, Morpho e protocolos Foundry.","ru":"Идеально для Агентов Анализа Solidity, требующих продвинутых возможностей рефакторинга кода для Ethereum, Morpho и протоколов Foundry.","ar":"مثالي لعميل تحليل Solidity الذي يحتاج إلى قدرات متقدمة لإعادة هيكلة الشفرة لـ Ethereum و Morpho وبروتوكولات Foundry."},"recommendation":{"en":"Empowers agents to refactor non-upgradeable Solidity contracts, improving code clarity and maintainability without altering semantics, using protocols like Ethereum and leveraging tools such as Foundry.","zh":"赋予代理重构不可升级的Solidity合约的能力，改善代码清晰度和可维护性，而不改变语义，使用Ethereum等协议，并利用Foundry等工具。","ja":"非アップグレード可能なSolidityコントラクトをリファクタリングするエージェントの能力を付与し、Ethereumなどのプロトコルを使用して、意味論を変更せずにコードの明確性と保守性を改善し、Foundryなどのツールを利用する。","ko":"에이전트가 업그레이드할 수 없는 솔리디티 계약을 리팩토링할 수 있는 기능을 제공하여 이더리움과 같은 프로토콜을 사용하고 파운드리와 같은 도구를 활용하여 의미를 변경하지 않고 코드의 명확성과 유지보수성을 개선합니다.","es":"Habilita a los agentes a refactorizar contratos de Solidity no actualizables, mejorando la claridad y mantenibilidad del código sin alterar la semántica, utilizando protocolos como Ethereum y aprovechando herramientas como Foundry.","fr":"Permet aux agents de refactoriser des contrats Solidity non mises à jour, améliorant la clarté et la maintenabilité du code sans altérer la sémantique, en utilisant des protocoles tels qu''Ethereum et en exploitant des outils tels que Foundry.","de":"Ermöglicht es Agents, nicht upgradefähige Solidity-Verträge umzuschreiben, wodurch die Klarheit und Wartbarkeit des Codes verbessert werden, ohne die Semantik zu verändern, unter Verwendung von Protokollen wie Ethereum und unter Nutzung von Tools wie Foundry.","pt":"Habilita agentes a refatorar contratos Solidity não atualizáveis, melhorando a clareza e manutenção do código sem alterar a semântica, usando protocolos como Ethereum e aproveitando ferramentas como Foundry.","ru":"Позволяет агентам рефакторить нередактируемые контракты Solidity, улучшая ясность и поддерживаемость кода без изменения семантики, используя протоколы, такие как Ethereum, и используя инструменты, такие как Foundry.","ar":"يمكن العميل من إعادة هيكلة عقود Solidity غير القابلة للتحديث، مما يحسن وضوح الشفرة وقابلية الصيانة دون تغيير الدلالات، باستخدام بروتوكولات مثل Ethereum واستخدام أدوات مثل Foundry."},"useCases":{"en":["Refactoring legacy Solidity contracts for better readability","Simplifying contract logic after locking behavior with tests","Preparing DeFi protocol code for audit or review"],"zh":["重构旧的Solidity合约以提高可读性","在锁定行为后使用测试简化合约逻辑","为审计或审查准备DeFi协议代码"],"ja":["旧のSolidityコントラクトをリファクタリングして可読性を向上させる","テストで動作をロックした後、コントラクトロジックを簡素化する","監査またはレビューのためにDeFiプロトコルコードを準備する"],"ko":["가독성을 높이기 위해 오래된 솔리디티 계약을 리팩토링합니다.","테스트로 동작을 잠금 후 계약 논리를 단순화합니다.","감사 또는 검토를 위해 DeFi 프로토콜 코드를 준비합니다."],"es":["Refactorización de contratos de Solidity heredados para una mejor legibilidad","Simplificación de la lógica de contrato después de bloquear el comportamiento con pruebas","Preparación del código del protocolo DeFi para auditoría o revisión"],"fr":["Refactoring de contrats Solidity hérités pour une meilleure lisibilité","Simplification de la logique de contrat après avoir verrouillé le comportement avec des tests","Préparation du code du protocole DeFi pour une audit ou une revue"],"de":["Umschreiben von veralteten Solidity-Verträgen für eine bessere Lesbarkeit","Vereinfachung der Vertragslogik nach dem Sperren des Verhaltens mit Tests","Vorbereitung des DeFi-Protokoll-Codes für eine Überprüfung oder Prüfung"],"pt":["Refatoração de contratos Solidity legados para melhor legibilidade","Simplificação da lógica do contrato após bloqueio do comportamento com testes","Preparação do código do protocolo DeFi para auditoria ou revisão"],"ru":["Рефакторинг устаревших контрактов Solidity для лучшей читаемости","Упрощение логики контракта после блокировки поведения с помощью тестов","Подготовка кода протокола DeFi к аудиту или обзору"],"ar":["إعادة هيكلة عقود Solidity القديمة من أجل قراءة أفضل","بسط منطق العقد بعد قفل السلوك بالاختبارات","إعداد код بروتوكول DeFi لمراجعة أو استعراض"]},"limitations":{"en":["Limited to non-upgradeable Solidity contracts","Must not alter contract semantics or interfaces"],"zh":["仅限于非升级的Solidity合约","不能改变合约的语义或接口"],"ja":["アップグレード不可能なSolidityコントラクトに限定","コントラクトの意味論またはインターフェースを変更してはならない"],"ko":["업그레이드할 수 없는 솔리디티 계약으로 제한됨","계약의 의미 또는 인터페이스를 변경할 수 없음"],"es":["Limitado a contratos de Solidity no actualizables","No debe alterar la semántica o las interfaces del contrato"],"fr":["Limité à des contrats Solidity non mises à jour","Ne doit pas altérer la sémantique ou les interfaces du contrat"],"de":["Begrenzt auf nicht upgradefähige Solidity-Verträge","Darf die Semantik oder Schnittstellen des Vertrags nicht verändern"],"pt":["Limitado a contratos Solidity não atualizáveis","Não deve alterar a semântica ou interfaces do contrato"],"ru":["Ограничен нередактируемыми контрактами Solidity","Не должно изменять семантику или интерфейсы контракта"],"ar":["محدود بعقود Solidity غير القابلة للتحديث","لا يجب تغيير الدلالات أو واجهات العقد"]},"version":4},"contentHash":"324ae74446e0986cf72330a8fc714d5f55fd01ba23d7ff92ec6d459c8f69417f","qualityScore":47}');
