INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mgnfy-view/morpho-vault-v2-adapters/safe-refactor', 'safe-refactor', 'mgnfy-view', 'morpho-vault-v2-adapters', 'community', 'safe-refactor mgnfy-view morpho-vault-v2-adapters community adapters curation defi ethereum forge fork-testing foundry morpho-blockchain-lending morpho-platform vaults The safe-refactor skill refactors non-upgradeable Solidity contracts for DeFi protocols, improving code clarity and maintainability without altering semantics. It benefits developers working with Ethereum, Morpho, and Foundry. safe-refactor 技术用于重构非升级的 Solidity 合约，提高代码清晰度、可维护性和内部结构，适用于 DeFi 协议和 Ethereum 开发 safe-refactor 技術は、非アップグレード可能な Solidity コントラクトをリファクタリングして、コードの明確性、保守性、内部構造を向上させます。DeFi プロトコルと Ethereum 開発に適しています safe-refactor 기술은 비업그레이드 가능한 Solidity 계약을 리팩토링하여 코드의 명확성, 유지 보수성 및 내부 구조를 향상시키는 데 사용됩니다. DeFi 프로토콜 및 이더리움 개발에 적합합니다 Safe-refactor es una herramienta de refactorización segura para contratos Solidity que mejora la claridad y mantenibilidad sin alterar la semántica Safe-refactor est un outil de refactorisation sûr pour les contrats Solidity qui améliore la clarté et la maintenabilité sans altérer la sémantique Safe-refactor ist ein Werkzeug für sichere Refaktorierung von Solidity-Verträgen, das die Klarheit und Wartbarkeit verbessert, ohne die Semantik zu ändern O safe-refactor é uma habilidade que refatora contratos Solidity para melhorar a clareza e manutenção, sem alterar o comportamento observable. Safe-refactor - это навык, который рефакторит контракты Solidity для улучшения ясности и поддерживаемости, не изменяя наблюдаемое поведение. safe-refactor هو مهارة تقوم بإعادة هيكلة العقود الصلبة لتحسين الوضوح والصيانة، دون تغيير السلوك المرئي. how to use safe-refactor safe-refactor setup guide safe-refactor vs foundry solidity contract refactoring defi protocol development ethereum contract optimization morpho vault v2 adapters safe-refactor install safe-refactor alternative safe-refactor Solidity 合约 DeFi 协议 Ethereum 开发 Morpho vault v2 代码重构 代码可维护性 代码可读性 AIエージェント Refactors non-upgradeable Solidity contracts for improved clarity and maintainability Supports Morpho vault v2 adapters for popular DeFi protocols Ensures no changes to semantics, interfaces, or externally visible effects Improves code readability and simplifies logic after behavior has been locked by tests Prepares code for audit or review Removes duplication and improves code organization safe-refactor is a skill that refactors non-upgradeable Solidity contracts to improve internal structure and maintainability without changing observable behavior.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KyteApp/growth-agents-and-skills/CREATE_DEEP_RESEARCH_PROMPT', 'community', 'KyteApp', 'growth-agents-and-skills', 'KyteApp/growth-agents-and-skills', 'CREATE_DEEP_RESEARCH_PROMPT', 0, 0, 47, '2026-03-07T01:49:01.562Z', '2026-03-07T02:05:52.551Z', '4e64c452ff18ea926cf79c4fa8c7658aa73892fdc0f0a91aa174c7e6af80b856', '{"id":"KyteApp/growth-agents-and-skills/CREATE_DEEP_RESEARCH_PROMPT","name":"CREATE_DEEP_RESEARCH_PROMPT","description":{"en":"CREATE_DEEP_RESEARCH_PROMPT translates vague user requests into specific, effective prompts for Deep Research tools. This skill benefits AI agents, researchers, and developers seeking precise research outcomes.","zh":"CREATE_DEEP_RESEARCH_PROMPT 技术通过将模糊的用户请求转化为高效的研究提示，帮助开发者更好地使用 AI 智能工具","ja":"CREATE_DEEP_RESEARCH_PROMPT 技術は、開発者が AI エージェントを効果的に使用できるように、不明確なユーザー要求を高度な研究プロンプトに変換します","ko":"CREATE_DEEP_RESEARCH_PROMPT 기술은 개발자가 AI 도구를 효율적으로 사용할 수 있도록 모호한 사용자 요청을 심층 연구 프롬프트로 변환합니다","es":"CREATE_DEEP_RESEARCH_PROMPT es una habilidad que traduce solicitudes de usuario vagas en solicitudes de investigación altamente específicas para herramientas de investigación en profundidad","fr":"CREATE_DEEP_RESEARCH_PROMPT est une compétence qui traduit des requêtes utilisateur vagues en requêtes de recherche hautement spécifiques pour les outils de recherche en profondeur","de":"CREATE_DEEP_RESEARCH_PROMPT ist eine Fähigkeit, die vage Benutzeranfragen in hochspezifische Forschungsanfragen für Deep-Research-Tools oder -Agenten übersetzt","pt":"O CREATE_DEEP_RESEARCH_PROMPT é uma habilidade que traduz solicitações de usuário vagas em prompts específicos e eficazes para ferramentas de pesquisa profunda, utilizando contexto e validação técnica","ru":"CREATE_DEEP_RESEARCH_PROMPT — это навык, который переводит нечёткие запросы пользователей в конкретные и эффективные запросы для инструментов глубокого исследования, используя контекст и техническую валидацию","ar":"CREATE_DEEP_RESEARCH_PROMPT هو مهارة تترجم طلبات المستخدم الغامضة إلى محفزات محددة وفعالة لأدوات البحث المتقدم، باستخدام السياق والتحقق الفني"},"seo":{"title":{"en":"CREATE_DEEP_RESEARCH_PROMPT: Effective Prompt Generation ...","zh":"CREATE_DEEP_RESEARCH_PROMPT 指南：AI智能工具有效提示设置","ja":"CREATE_DEEP_RESEARCH_PROMPT のベストプラクティス：AIエージェントの高度な研究プロンプト","ko":"CREATE_DEEP_RESEARCH_PROMPT 설정 가이드: AI 도구를 위한 심층 연구 프롬프트","es":"Guía de configuración de CREATE_DEEP_RESEARCH_PROMPT para...","fr":"Meilleures pratiques pour CREATE_DEEP_RESEARCH_PROMPT ave...","de":"Einrichtungsleitfaden für CREATE_DEEP_RESEARCH_PROMPT in ...","pt":"Guia de Configuração do CREATE_DEEP_RESEARCH_PROMPT para ...","ru":"Настройка CREATE_DEEP_RESEARCH_PROMPT для ИИ Агентов: Луч...","ar":"دليل إعداد CREATE_DEEP_RESEARCH_PROMPT لأدوات الذكاء الاص..."},"description":{"en":"Unlock precise research capabilities with CREATE_DEEP_RESEARCH_PROMPT. Discover how to craft effective prompts for Deep Research tools and agents, ensuring a...","zh":"了解 CREATE_DEEP_RESEARCH_PROMPT 技术，实现 AI 智能工具的高效研究提示，包括 Context 是 King、Tech Validation 和 Classification 等核心原则","ja":"CREATE_DEEP_RESEARCH_PROMPT を使用して、AIエージェントの高度な研究プロンプトを作成しましょう。コンテキスト、テクノロジー検証、分類などのコアプリンシプルを学びます","ko":"CREATE_DEEP_RESEARCH_PROMPT 기술을 사용하여 AI 도구의 효율적인 연구 프롬프트를 생성하세요. 컨텍스트, 기술 검증, 분류 등의 핵심 원칙을 배우세요","es":"Aprende a crear solicitudes de investigación efectivas con CREATE_DEEP_RESEARCH_PROMPT para Agentes de IA y mejora tus resultados","fr":"Découvrez comment créer des requêtes de recherche efficaces avec CREATE_DEEP_RESEARCH_PROMPT pour les Outils d''IA et améliorez vos résultats","de":"Erfahren Sie, wie Sie effektive Forschungsanfragen mit CREATE_DEEP_RESEARCH_PROMPT für KI-Agents erstellen und Ihre Ergebnisse verbessern","pt":"Aprenda a criar prompts de pesquisa profunda eficazes para ferramentas de IA com o CREATE_DEEP_RESEARCH_PROMPT. Entenda como o contexto e a validação técnica...","ru":"Узнайте, как создать эффективные запросы для глубокого исследования с помощью CREATE_DEEP_RESEARCH_PROMPT для ИИ Агентов. Понимайте, как контекст и техническ...","ar":"تعلم كيفية إنشاء محفزات بحث متقدمة فعالة لأدوات الذكاء الاصطناعي مع CREATE_DEEP_RESEARCH_PROMPT. افهم كيف يتحسن السياق والتحقق الفني الدقة"},"definition":{"en":"CREATE_DEEP_RESEARCH_PROMPT is a skill that generates highly specific research prompts for Deep Research tools, ensuring clear objectives and accurate results through context validation and classification.","zh":"CREATE_DEEP_RESEARCH_PROMPT 是一种将用户请求转化为 AI 智能工具的高效研究提示的技术","ja":"CREATE_DEEP_RESEARCH_PROMPT は、ユーザー要求を AI エージェントの高度な研究プロンプトに変換する技術です","ko":"CREATE_DEEP_RESEARCH_PROMPT 는 사용자 요청을 AI 도구의 심층 연구 프롬프트로 변환하는 기술입니다","es":"CREATE_DEEP_RESEARCH_PROMPT es una habilidad de Agentes de IA que crea solicitudes de investigación específicas","fr":"CREATE_DEEP_RESEARCH_PROMPT est une compétence d''Outils d''IA qui crée des requêtes de recherche spécifiques","de":"CREATE_DEEP_RESEARCH_PROMPT ist eine Fähigkeit von KI-Agents, die spezifische Forschungsanfragen erstellt","pt":"O que é CREATE_DEEP_RESEARCH_PROMPT? É uma habilidade de IA que cria prompts de pesquisa personalizados para ferramentas de pesquisa profunda","ru":"Что такое CREATE_DEEP_RESEARCH_PROMPT? Это навык ИИ, который создаёт индивидуальные запросы для инструментов глубокого исследования","ar":"ما هو CREATE_DEEP_RESEARCH_PROMPT؟ إنه مهارة ذكاء اصطناعي لإنشاء محفزات بحث مخصصة لأدوات البحث المتقدم"},"features":{"en":["Utilizes context validation to ensure clear research objectives","Employs tech validation using context7 for accurate term and version identification","Classifies research into distinct categories, such as Market, Bug, and Tech research","Supports the creation of highly specific and effective prompts for Deep Research tools","Integrates with Deep Research agents for streamlined research workflows","Ensures accurate results through precise prompt generation"],"zh":["Context 是 King：明确的目标和上下文","Tech Validation：使用 context7 确保技术术语和版本的正确性","Classification：根据研究类型（市场、错误、技术）进行分类","高效的研究提示生成","支持 AI 智能工具的有效使用","提高研究效率和准确性"],"ja":["コンテキストはキング：明確な目的とコンテキスト","テクノロジー検証：context7 を使用して技術用語とバージョンの正確性を確保","分類：研究タイプ（市場、バグ、テクノロジー）に基づく分類","高度な研究プロンプトの生成","AI エージェントの有効な使用をサポート","研究効率と精度の向上"],"ko":["컨텍스트는 キング：명확한 목적과 컨텍스트","기술 검증：context7 를 사용하여 기술 용어와 버전의 정확성을 보장","분류：연구 유형（시장、버그、기술）에 따른 분류","심층 연구 프롬프트의 생성","AI 도구의 효율적인 사용을 지원","연구 효율성과 정확성의 향상"],"es":["Contextualización para evitar ruido en los resultados","Validación de tecnología con context7","Clasificación de la investigación en diferentes categorías","Uso de términos y versiones correctas de tecnologías","Creación de solicitudes de investigación efectivas"],"fr":["Contextualisation pour éviter le bruit dans les résultats","Validation de la technologie avec context7","Classification de la recherche dans différentes catégories","Utilisation de termes et de versions correctes de technologies","Création de requêtes de recherche efficaces"],"de":["Kontextualisierung, um Rauschen in den Ergebnissen zu vermeiden","Technologievalidierung mit context7","Klassifizierung der Forschung in verschiedene Kategorien","Verwendung korrekter Begriffe und Versionen von Technologien","Erstellung effektiver Forschungsanfragen"],"pt":["Utiliza contexto para melhorar a precisão dos resultados","Validação técnica com `context7` para garantir a exatidão dos termos e versões","Classificação de pesquisas em diferentes categorias (Mercado, Bug, Técnica)","Criação de prompts personalizados para ferramentas de pesquisa profunda","Integração com tecnologias de IA para melhorar a eficácia da pesquisa"],"ru":["Использует контекст для улучшения точности результатов","Техническая валидация с `context7` для обеспечения точности терминов и версий","Классификация исследований по разным категориям (Рынок, Ошибка, Техника)","Создание индивидуальных запросов для инструментов глубокого исследования","Интеграция с технологиями ИИ для улучшения эффективности поиска"],"ar":["يستخدم السياق لتحسين دقة النتائج","التحقق الفني باستخدام `context7` لضمان دقة المصطلحات والإصدارات","تصنيف البحوث في فئات مختلفة (السوق، الخطأ، التقني)","إنشاء محفزات بحث مخصصة لأدوات البحث المتقدم","التكامل مع تقنيات الذكاء الاصطناعي لتحسين فعالية البحث"]},"keywords":{"en":["CREATE_DEEP_RESEARCH_PROMPT setup guide","how to use CREATE_DEEP_RESEARCH_PROMPT for AI agents","CREATE_DEEP_RESEARCH_PROMPT vs traditional research methods","what is CREATE_DEEP_RESEARCH_PROMPT and its benefits","CREATE_DEEP_RESEARCH_PROMPT alternative for research prompt generation","effective prompt generation for Deep Research tools","context7 integration with CREATE_DEEP_RESEARCH_PROMPT","CREATE_DEEP_RESEARCH_PROMPT install for AI researchers","streamlining research workflows with CREATE_DEEP_RESEARCH_PROMPT"],"zh":["CREATE_DEEP_RESEARCH_PROMPT","AI 智能工具","研究提示","Context 是 King","Tech Validation","Classification","AI 研究","高效研究","技术开发"],"ja":["CREATE_DEEP_RESEARCH_PROMPT","AI エージェント","研究プロンプト","コンテキストはキング","テクノロジー検証","分類","AI 研究","高度な研究","技術開発"],"ko":["CREATE_DEEP_RESEARCH_PROMPT","AI 도구","연구 프롬프트","컨텍스트는 キング","기술 검증","분류","AI 연구","심층 연구","기술 개발"],"es":["Agentes de IA","Herramientas de investigación en profundidad","CREATE_DEEP_RESEARCH_PROMPT","context7","Clasificación de la investigación","Tecnología de investigación","Desarrollo de software","IA y machine learning"],"fr":["Outils d''IA","Outils de recherche en profondeur","CREATE_DEEP_RESEARCH_PROMPT","context7","Classification de la recherche","Technologie de recherche","Développement de logiciels","IA et machine learning"],"de":["KI-Agents","Deep-Research-Tools","CREATE_DEEP_RESEARCH_PROMPT","context7","Klassifizierung der Forschung","Forschungstechnologie","Softwareentwicklung","KI und Machine Learning"],"pt":["CREATE_DEEP_RESEARCH_PROMPT","Ferramentas de IA","Pesquisa profunda","Contexto","Validação técnica","Classificação de pesquisas","Prompts personalizados","Tecnologias de IA"],"ru":["CREATE_DEEP_RESEARCH_PROMPT","ИИ Агенты","Глубокое исследование","Контекст","Техническая валидация","Классификация исследований","Индивидуальные запросы","Технологии ИИ"],"ar":["CREATE_DEEP_RESEARCH_PROMPT","أدوات الذكاء الاصطناعي","البحث المتقدم","السياق","التحقق الفني","تصنيف البحوث","محفزات بحث مخصصة","تقنيات الذكاء الاصطناعي"]}},"owner":"KyteApp","repo":"growth-agents-and-skills","repoPath":"KyteApp/growth-agents-and-skills","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.562Z","topics":[],"category":"community","skillMd":{"name":"CREATE_DEEP_RESEARCH_PROMPT","description":"Generate a structured deep research prompt. USE WHEN the user needs to research a complex topic, market, or bug deeply. Capabilities include objective clarification, tech stack validation, and prompt generation.","bodyPreview":"# CREATE DEEP RESEARCH PROMPT\n\n**Owner:** Manny (Product Manager)\n\n## Goal\nTo translate a vague user request (e.g., \"Research AI frameworks\") into a highly specific, effective prompt for a Deep Research tool or agent.\n\n## Core Principles\n- **Context is King:** A research prompt without clear objectives yields noise.\n- **Tech Validation:** If researching technology, use `context7` to ensure terms and versions are correct.\n- **Classification:** Different research (Market vs. Bug vs. Tech) requires","body":"# CREATE DEEP RESEARCH PROMPT\n\n**Owner:** Manny (Product Manager)\n\n## Goal\nTo translate a vague user request (e.g., \"Research AI frameworks\") into a highly specific, effective prompt for a Deep Research tool or agent.\n\n## Core Principles\n- **Context is King:** A research prompt without clear objectives yields noise.\n- **Tech Validation:** If researching technology, use `context7` to ensure terms and versions are correct.\n- **Classification:** Different research (Market vs. Bug vs. Tech) requires different prompt structures.\n\n## Workflow Instructions\n\n### 1. Classification\n- **Action:** Determine the research type.\n  - *Product Validation* (Do users actually need this?)\n  - *Technical Review* (Is this feasible?)\n  - *Bug Diagnosis* (Why is this breaking?)\n  - *Market Analysis* (Who are the benchmarks?)\n\n### 2. Objective Clarification\n- **Action:** Elicit the \"Why.\"\n- **Prompt:** \"What decision will this research enable?\" or \"What is the single most important question to answer?\"\n- **Constraint:** Stop if the goal is \"just curious.\" Push for actionable intent.\n\n### 3. Context & Tech Validation\n- **Action:** If the research involves specific tools/libraries:\n  - Call `context7` MCP to verify the library names and current versions.\n  - *Example:* If user says \"Research Next.js router,\" verify if they mean Pages or App Router.\n\n### 4. Constructing the Prompt\n- **Action:** Assemble the research directive.\n- **Structure:**\n  - **Objective:** The \"North Star\" question.\n  - **Key Questions:** 3-5 specific sub-questions.\n  - **Methodology:** How to search (e.g., \"Compare documentation,\" \"Search forums,\" \"Read whitepapers\").\n  - **Sources:** Define authorized sources (e.g., \"Official docs only,\" \"GitHub issues,\" \"Reddit\").\n  - **Deliverable:** What the output should look like (Table, Summary, Code snippets).\n\n### 5. Review & Export\n- **Action:** Present the draft prompt to the user.\n- **Refine:** Incorporate feedback.\n- **Output:** Save the final prompt as a Markdown file in `outputs/research_prompts/`.\n\n## Anti-Patterns\n- **NEVER** generate a generic \"Tell me about X\" prompt.\n- **NEVER** include hallucinated library versions in a research prompt.\n- **NEVER** skip the \"Success Criteria\" definition.\n\n## Output Format\nA Markdown file containing the structured prompt, ready to be fed into a reasoning model or research agent.\n"},"lastSynced":"2026-03-07T02:05:52.551Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing precise query formulation for Deep Research tools, such as Cursor, Windsurf, or Claude Code.","zh":"适用于需要精确查询表述的研究代理，用于深度研究工具，如Cursor、Windsurf或Claude Code。","ja":"Cursor、Windsurf、またはClaude CodeなどのDeep Researchツールで正確なクエリの作成が必要なResearch Agentsに最適です。","ko":"Cursor, Windsurf 또는 Claude Code와 같은 Deep Research 도구에서 정교한 쿼리 구성을 필요로 하는 연구 에이전트에게 적합합니다.","es":"Perfecto para agentes de investigación que necesitan una formulación de consultas precisa para herramientas de investigación en profundidad, como Cursor, Windsurf o Claude Code.","fr":"Parfait pour les agents de recherche ayant besoin d''une formulation de requête précise pour les outils de recherche approfondie tels que Cursor, Windsurf ou Claude Code.","de":"Perfekt für Forschungsagenten, die eine präzise Abfrageformulierung für Deep-Research-Tools wie Cursor, Windsurf oder Claude Code benötigen.","pt":"Perfeito para Agentes de Pesquisa que precisam de formulação de consulta precisa para ferramentas de Pesquisa Avançada, como Cursor, Windsurf ou Claude Code.","ru":"Идеально подходит для исследовательских агентов, которым требуется точная формулировка запроса для инструментов глубоких исследований, таких как Cursor, Windsurf или Claude Code.","ar":"مثالي للوكلاء البحثيين الذين يحتاجون إلى صياغة استعلام دقيقة لأدوات البحث العميق، مثل Cursor و Windsurf أو Claude Code."},"recommendation":{"en":"Empowers agents to translate vague user requests into highly specific, effective prompts, utilizing context validation and classification to ensure accurate research outcomes, while leveraging tech validation protocols like `context7` for technological research.","zh":"赋予代理将模糊的用户请求转换为高精度、有效的提示，利用上下文验证和分类以确保准确的研究结果，同时利用技术验证协议，如`context7`，进行技术研究。","ja":"エージェントが漠然としたユーザーのリクエストを高精度で効果的なプロンプトに変換できるようにし、コンテキスト検証と分類を使用して正確なリサーチ結果を保証し、テクノロジー研究のための`context7`などのテクノロジー検証プロトコルを利用します。","ko":"에이전트가 모호한 사용자 요청을 높은 精度와 효과적인 프롬프트로 변환할 수 있도록 하며, 컨텍스트 검증 및 분류를 사용하여 정확한 연구 결과를 보장하며, 기술 연구를 위한 `context7`와 같은 기술 검증 프로토콜을 활용합니다.","es":"Habilita a los agentes a traducir solicitudes de usuario vagas en instrucciones altamente específicas y efectivas, utilizando la validación de contexto y la clasificación para garantizar resultados de investigación precisos, mientras aprovecha protocolos de validación tecnológica como `context7` para la investigación tecnológica.","fr":"Permet aux agents de traduire des demandes d''utilisateurs vagues en invites hautement spécifiques et efficaces, en utilisant la validation contextuelle et la classification pour assurer des résultats de recherche précis, tout en exploitant des protocoles de validation technologique tels que `context7` pour la recherche technologique.","de":"Ermächtigt Agenten, vage Benutzersuchen in hochspezifische und effektive Aufforderungen zu übersetzen, indem sie Kontextvalidierung und Klassifizierung verwenden, um genaue Forschungsergebnisse zu gewährleisten, während sie Technologievalidierungsprotokolle wie `context7` für technologische Forschung nutzen.","pt":"Habilita os agentes a traduzir solicitações vagas do usuário em prompts altamente específicos e eficazes, utilizando validação de contexto e classificação para garantir resultados de pesquisa precisos, aproveitando protocolos de validação tecnológica como `context7` para pesquisa tecnológica.","ru":"Наделяет агентов возможностью переводить неясные запросы пользователей в высоко конкретные и эффективные подсказки, используя контекстную проверку и классификацию для обеспечения точных результатов исследования, используя протоколы технической проверки, такие как `context7`, для технических исследований.","ar":"تمكن الوكلاء من ترجمة طلبات المستخدم الغامضة إلى إشارات محددة وفعالة، باستخدام التحقق من السياق والتصنيف لضمان نتائج بحث دقيقة، واستخدام بروتوكولات التحقق التكنولوجي مثل `context7` للبحث التكنولوجي."},"useCases":{"en":["Translating vague user requests into targeted research prompts","Validating research objectives using context-driven analysis","Classifying research types, such as Market, Bug, or Tech research, for tailored prompt generation"],"zh":["将模糊的用户请求转换为有针对性的研究提示","使用上下文驱动分析来验证研究目标","根据研究类型（如市场、错误或技术研究）对研究进行分类以生成定制的提示"],"ja":["ユーザーのリクエストをターゲットにしたリサーチプロンプトに変換する","コンテキスト駆動分析を使用してリサーチ目標を検証する","マーケット、バグ、またはテクノロジーリサーチなどのリサーチタイプを分類してカスタマイズされたプロンプトを生成する"],"ko":["사용자의 요청을 대상으로 한 연구 프롬프트로 변환하는 것","컨텍스트 驅動 분석을 사용하여 연구 목표를 검증하는 것","시장, 버그 또는 기술 연구와 같은 연구 유형을 분류하여 맞춤형 프롬프트를 생성하는 것"],"es":["Traducir solicitudes de usuario vagas en invitaciones de investigación dirigidas","Validar objetivos de investigación utilizando análisis impulsado por contexto","Clasificar tipos de investigación, como investigación de mercado, errores o investigación técnica, para la generación de instrucciones personalizadas"],"fr":["Traduire des demandes d''utilisateurs vagues en invites de recherche ciblées","Valider les objectifs de recherche à l''aide d''une analyse contextuelle","Classer les types de recherche, tels que la recherche de marché, les bogues ou la recherche technique, pour la génération d''invites personnalisées"],"de":["Vage Benutzersuchen in gezielte Forschungsaufforderungen übersetzen","Forschungsziele mithilfe kontextgesteuerter Analyse validieren","Forschungstypen wie Marktforschung, Fehler- oder Technikforschung klassifizieren, um maßgeschneiderte Aufforderungen zu generieren"],"pt":["Traduzir solicitações vagas do usuário em prompts de pesquisa direcionados","Validar objetivos de pesquisa usando análise baseada em contexto","Classificar tipos de pesquisa, como Mercado, Bug ou Pesquisa Técnica, para geração de prompts personalizados"],"ru":["Переводить неясные запросы пользователей в целевые подсказки для исследования","Проверять цели исследования с помощью контекстно-ориентированного анализа","Классифицировать типы исследований, такие как Маркетинг, Поиск ошибок или Технические исследования, для генерации персонализированных подсказок"],"ar":["翻訳 المستخدم الغامضة إلى إشارات بحث محددة","التحقق من أهداف البحث باستخدام التحليل القائم على السياق","تصنيف أنواع البحث، مثل السوق أو البحث الفني أو البحث التكنولوجي، لإنشاء إشارات مخصصة"]},"limitations":{"en":["Requires clear user request input","Depends on the accuracy of `context7` for tech validation","May not perform well with extremely ambiguous or open-ended requests"],"zh":["需要清晰的用户请求输入","依赖于`context7`的准确性进行技术验证","可能无法处理极其模糊或开放式的请求"],"ja":["明確なユーザーのリクエスト入力を必要とする","テクノロジー検証のために`context7`の精度に依存する","非常に漠然とした、またはオープンエンドのリクエストではうまく機能しない可能性がある"],"ko":["명확한 사용자 요청 입력이 필요합니다.","`context7`의 정확도에 의존하여 기술 검증을 수행합니다.","극도로 모호하거나 개방형 요청에서는 잘 작동하지 않을 수 있습니다."],"es":["Requiere una entrada de solicitud de usuario clara","Depende de la precisión de `context7` para la validación técnica","Puede no funcionar bien con solicitudes extremadamente ambiguas o abiertas"],"fr":["Nécessite une entrée de demande d''utilisateur claire","Dépend de l''exactitude de `context7` pour la validation technique","Peut ne pas fonctionner correctement avec des demandes extrêmement ambiguës ou ouvertes"],"de":["Benötigt eine klare Benutzersucheingabe","Hängt von der Genauigkeit von `context7` für die technische Validierung ab","Kann bei extrem vagen oder offenen Anfragen möglicherweise nicht gut funktionieren"],"pt":["Exige entrada de solicitação de usuário clara","Depende da precisão de `context7` para validação técnica","Pode não funcionar bem com solicitações extremamente ambiguas ou abertas"],"ru":["Требует четкого ввода запроса пользователя","Зависит от точности `context7` для технической проверки","Может не работать хорошо с чрезвычайно неоднозначными или открытыми запросами"],"ar":["يتطلب إدخال طلب واضح من المستخدم","يعتمد على دقة `context7` للتحقق التكنولوجي","قد لا يعمل جيدًا مع الطلبات الغامضة أو المفتوحة للغاية"]},"version":4},"contentHash":"4e64c452ff18ea926cf79c4fa8c7658aa73892fdc0f0a91aa174c7e6af80b856","qualityScore":47}');
