INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KyteApp/growth-agents-and-skills/CREATE_DEEP_RESEARCH_PROMPT', 'CREATE_DEEP_RESEARCH_PROMPT', 'KyteApp', 'growth-agents-and-skills', 'community', 'CREATE_DEEP_RESEARCH_PROMPT KyteApp growth-agents-and-skills community CREATE_DEEP_RESEARCH_PROMPT translates vague user requests into specific, effective prompts for Deep Research tools. This skill benefits AI agents, researchers, and developers seeking precise research outcomes. CREATE_DEEP_RESEARCH_PROMPT 技术通过将模糊的用户请求转化为高效的研究提示，帮助开发者更好地使用 AI 智能工具 CREATE_DEEP_RESEARCH_PROMPT 技術は、開発者が AI エージェントを効果的に使用できるように、不明確なユーザー要求を高度な研究プロンプトに変換します CREATE_DEEP_RESEARCH_PROMPT 기술은 개발자가 AI 도구를 효율적으로 사용할 수 있도록 모호한 사용자 요청을 심층 연구 프롬프트로 변환합니다 CREATE_DEEP_RESEARCH_PROMPT es una habilidad que traduce solicitudes de usuario vagas en solicitudes de investigación altamente específicas para herramientas de investigación en profundidad CREATE_DEEP_RESEARCH_PROMPT est une compétence qui traduit des requêtes utilisateur vagues en requêtes de recherche hautement spécifiques pour les outils de recherche en profondeur CREATE_DEEP_RESEARCH_PROMPT ist eine Fähigkeit, die vage Benutzeranfragen in hochspezifische Forschungsanfragen für Deep-Research-Tools oder -Agenten übersetzt O CREATE_DEEP_RESEARCH_PROMPT é uma habilidade que traduz solicitações de usuário vagas em prompts específicos e eficazes para ferramentas de pesquisa profunda, utilizando contexto e validação técnica CREATE_DEEP_RESEARCH_PROMPT — это навык, который переводит нечёткие запросы пользователей в конкретные и эффективные запросы для инструментов глубокого исследования, используя контекст и техническую валидацию CREATE_DEEP_RESEARCH_PROMPT هو مهارة تترجم طلبات المستخدم الغامضة إلى محفزات محددة وفعالة لأدوات البحث المتقدم، باستخدام السياق والتحقق الفني CREATE_DEEP_RESEARCH_PROMPT setup guide how to use CREATE_DEEP_RESEARCH_PROMPT for AI agents CREATE_DEEP_RESEARCH_PROMPT vs traditional research methods what is CREATE_DEEP_RESEARCH_PROMPT and its benefits CREATE_DEEP_RESEARCH_PROMPT alternative for research prompt generation effective prompt generation for Deep Research tools context7 integration with CREATE_DEEP_RESEARCH_PROMPT CREATE_DEEP_RESEARCH_PROMPT install for AI researchers streamlining research workflows with CREATE_DEEP_RESEARCH_PROMPT CREATE_DEEP_RESEARCH_PROMPT AI 智能工具 研究提示 Context 是 King Tech Validation Classification AI 研究 高效研究 技术开发 Utilizes context validation to ensure clear research objectives Employs tech validation using context7 for accurate term and version identification Classifies research into distinct categories, such as Market, Bug, and Tech research Supports the creation of highly specific and effective prompts for Deep Research tools Integrates with Deep Research agents for streamlined research workflows Ensures accurate results through precise prompt generation CREATE_DEEP_RESEARCH_PROMPT is a skill that generates highly specific research prompts for Deep Research tools, ensuring clear objectives and accurate results through context validation and classification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('misha-jatt/Personal-AI-Employee-Hackathon-0/gmail-watcher', 'community', 'misha-jatt', 'Personal-AI-Employee-Hackathon-0', 'misha-jatt/Personal-AI-Employee-Hackathon-0', 'gmail-watcher', 0, 0, 47, '2026-03-02T19:04:17Z', '2026-03-07T04:08:32.818Z', 'be8cc395e13aa9e88f9c84819e98656e84edf9f27d3c2cd6a5a24c0496681ec7', '{"id":"misha-jatt/Personal-AI-Employee-Hackathon-0/gmail-watcher","name":"gmail-watcher","description":{"en":"The gmail-watcher skill polls the Gmail API for unread important emails, classifying them and creating .md files in /Needs_Action for developers and power users.","zh":"Gmail Watcher Skill 可以监控 Gmail 中的未读重要邮件，并将其分类为 .md 文件","ja":"Gmail Watcher スキルは、Gmail の未読の重要メールを監視し、.md ファイルに分類します","ko":"Gmail Watcher 스킬은 Gmail의 읽지 않은 중요한 이메일을 모니터링하고 .md 파일로 분류합니다","es":"El agente gmail-watcher utiliza la API de Gmail para detectar correos electrónicos importantes sin leer y crea archivos .md en la carpeta /Needs_Action","fr":"L''agent gmail-watcher utilise l''API Gmail pour détecter les emails importants non lus et crée des fichiers .md dans le dossier /Needs_Action","de":"Der Agent gmail-watcher verwendet die Gmail-API, um wichtige ungelesene E-Mails zu erkennen und erstellt .md-Dateien im Ordner /Needs_Action","pt":"O Gmail Watcher é uma ferramenta que polla a API do Gmail para e-mails importantes não lidos e cria arquivos .md em /Needs_Action.","ru":"ИИ Агент Gmail Watcher - это инструмент, который опрашивает Gmail API для важных непрочитанных писем и создает файлы .md в /Needs_Action.","ar":"جهاز مراقبة الجيميل هو أداة تراقب واجهة برمجة تطبيقات الجيميل للبريد الإلكتروني المهم غير المقروء وتạo ملفات .md في /Needs_Action."},"seo":{"title":{"en":"Gmail-Watcher: Automated Email Monitoring Setup Guide | A...","zh":"Gmail Watcher 设置指南：监控重要邮件","ja":"Gmail Watcher のベストプラクティス：重要メールの監視","ko":"Gmail Watcher 설정 가이드: 중요한 이메일 모니터링","es":"Guía de configuración de gmail-watcher para desarrolladores","fr":"Guide de mise en route de gmail-watcher pour les développ...","de":"Einrichtungsleitfaden für gmail-watcher-Entwickler","pt":"Guia de Configuração do Gmail Watcher: Monitoramento de E...","ru":"ИИ Агент Gmail Watcher: Настройка и Лучшие Практики","ar":"دليل إعداد جهاز مراقبة الجيميل: مراقبة البريد الإلكتروني"},"description":{"en":"Discover how to automate Gmail monitoring with gmail-watcher. Learn to poll Gmail API, classify emails, and create .md files with this step-by-step guide.","zh":"使用 Gmail Watcher Skill 监控 Gmail 中的未读重要邮件，并将其分类为 .md 文件","ja":"Gmail Watcher スキルを使用して、Gmail の未読の重要メールを監視し、.md ファイルに分類します","ko":"Gmail Watcher 스킬을 사용하여 Gmail의 읽지 않은 중요한 이메일을 모니터링하고 .md 파일로 분류합니다","es":"Aprende a configurar y utilizar el agente de inteligencia artificial gmail-watcher para monitorear correos electrónicos importantes sin leer","fr":"Découvrez comment configurer et utiliser l''agent d''intelligence artificielle gmail-watcher pour surveiller les emails importants non lus","de":"Erfahren Sie, wie Sie den KI-Agenten gmail-watcher einrichten und verwenden, um wichtige ungelesene E-Mails zu überwachen","pt":"Aprenda a configurar o Gmail Watcher para monitorar e-mails importantes e criar arquivos .md em /Needs_Action","ru":"Узнайте, как настроить ИИ Агент Gmail Watcher для мониторинга важных писем и создания файлов .md в /Needs_Action","ar":"تعلم كيفية إعداد جهاز مراقبة الجيميل لمراقبة البريد الإلكتروني المهم وتạo ملفات .md في /Needs_Action"},"definition":{"en":"gmail-watcher is a skill that automates Gmail monitoring by polling the Gmail API for unread important messages and organizing them into .md files.","zh":"Gmail Watcher 是一个 AI 工具，用于监控 Gmail 中的未读重要邮件","ja":"Gmail Watcher は、Gmail の未読の重要メールを監視する AI エージェントです","ko":"Gmail Watcher 는 Gmail의 읽지 않은 중요한 이메일을 모니터링하는 인공지능 툴입니다","es":"El agente de inteligencia artificial gmail-watcher es una herramienta que monitorea la bandeja de entrada de Gmail para detectar correos electrónicos importantes sin leer","fr":"L''agent d''intelligence artificielle gmail-watcher est un outil qui surveille la boîte de réception Gmail pour détecter les emails importants non lus","de":"Der KI-Agent gmail-watcher ist ein Tool, das den Posteingang von Gmail überwacht, um wichtige ungelesene E-Mails zu erkennen","pt":"O que é Gmail Watcher? Uma ferramenta que monitora e-mails importantes não lidos e cria arquivos .md.","ru":"Что такое ИИ Агент Gmail Watcher? Инструмент, который мониторит важные непрочитанные письма и создает файлы .md.","ar":"ما هو جهاز مراقبة الجيميل؟ أداة تراقب البريد الإلكتروني المهم غير المقروء وتạo ملفات .md."},"features":{"en":["Polls Gmail API for unread important messages","Filters out already-processed message IDs using deduplication","Creates .md files in /Needs_Action for classified emails","Triggers on commands like ''check gmail'' and ''monitor emails''","Outputs a list of new emails after polling the Gmail API","Supports classification of emails based on importance"],"zh":["使用 Gmail API 查询未读重要邮件","将邮件分类为 .md 文件","支持重复消息过滤","可触发多个动作，例如 \"check gmail\" 和 \"monitor emails\""],"ja":["Gmail API を使用して未読の重要メールを取得","メールを .md ファイルに分類","重複メッセージのフィルタリングをサポート","複数のアクションをトリガーできる、例 \"check gmail\" と \"monitor emails\""],"ko":["Gmail API를 사용하여 읽지 않은 중요한 이메일을 조회","이메일을 .md 파일로 분류","중복 메시지 필터링 지원","다중 동작을 트리거할 수 있음, 예를 들어 \"check gmail\" 및 \"monitor emails\""],"es":["Polling de la API de Gmail para detectar correos electrónicos importantes sin leer","Filtrado de mensajes procesados para evitar duplicados","Creación de archivos .md en la carpeta /Needs_Action","Soporte para comandos de voz como ''check gmail'' y ''monitor emails''","Integración con la API de Gmail para una mayor precisión","Capacidad de clasificar correos electrónicos según su importancia"],"fr":["Polling de l''API Gmail pour détecter les emails importants non lus","Filtrage des messages traités pour éviter les doublons","Création de fichiers .md dans le dossier /Needs_Action","Prise en charge des commandes vocales comme ''check gmail'' et ''monitor emails''","Intégration avec l''API Gmail pour une plus grande précision","Capacité de classer les emails selon leur importance"],"de":["Polling der Gmail-API, um wichtige ungelesene E-Mails zu erkennen","Filtern von bereits verarbeiteten Nachrichten, um Duplikate zu vermeiden","Erstellung von .md-Dateien im Ordner /Needs_Action","Unterstützung für Sprachbefehle wie ''check gmail'' und ''monitor emails''","Integration mit der Gmail-API für eine höhere Genauigkeit","Fähigkeit, E-Mails nach ihrer Wichtigkeit zu klassifizieren"],"pt":["Polling da API do Gmail para e-mails importantes não lidos","Criação de arquivos .md em /Needs_Action","Filtragem de mensagens já processadas","Classificação de e-mails importantes"],"ru":["Опрос Gmail API для важных непрочитанных писем","Создание файлов .md в /Needs_Action","Фильтрация уже обработанных сообщений","Классификация важных писем"],"ar":["استطلاع واجهة برمجة تطبيقات الجيميل للبريد الإلكتروني المهم غير المقروء","تạo ملفات .md في /Needs_Action","مرشح الرسائل المعالجة بالفعل","تصنيف البريد الإلكتروني المهم"]},"keywords":{"en":["how to use gmail-watcher","gmail-watcher setup guide","gmail-watcher alternative","gmail api monitoring","automated email classification","gmail-watcher vs email clients","gmail-watcher install","what is gmail-watcher","gmail-watcher tutorial"],"zh":["Gmail Watcher","AI 工具","Gmail API","未读重要邮件","监控邮件","分类邮件","重复消息过滤"],"ja":["Gmail Watcher","AI エージェント","Gmail API","未読の重要メール","メールの監視","メールの分類","重複メッセージのフィルタリング"],"ko":["Gmail Watcher","인공지능 툴","Gmail API","읽지 않은 중요한 이메일","이메일 모니터링","이메일 분류","중복 메시지 필터링"],"es":["gmail-watcher","agente de inteligencia artificial","monitoreo de correos electrónicos","API de Gmail","correos electrónicos importantes sin leer","herramientas de productividad","desarrollo de software","integración con Gmail","clasificación de correos electrónicos"],"fr":["gmail-watcher","agent d''intelligence artificielle","surveillance des emails","API Gmail","emails importants non lus","outils de productivité","développement de logiciels","intégration avec Gmail","classification des emails"],"de":["gmail-watcher","KI-Agent","Überwachung von E-Mails","Gmail-API","wichtige ungelesene E-Mails","Produktivitätstools","Softwareentwicklung","Integration mit Gmail","Klassifizierung von E-Mails"],"pt":["Gmail Watcher","monitoramento de e-mails","API do Gmail","e-mails importantes","arquivos .md","ferramentas de produtividade"],"ru":["ИИ Агент Gmail Watcher","мониторинг писем","Gmail API","важные письма","файлы .md","инструменты продуктивности"],"ar":["جهاز مراقبة الجيميل","مراقبة البريد الإلكتروني","واجهة برمجة تطبيقات الجيميل","البريد الإلكتروني المهم","ملفات .md","أدوات الإنتاجية"]}},"owner":"misha-jatt","repo":"Personal-AI-Employee-Hackathon-0","repoPath":"misha-jatt/Personal-AI-Employee-Hackathon-0","stars":0,"forks":0,"updatedAt":"2026-03-02T19:04:17Z","topics":[],"category":"community","skillMd":{"name":"gmail-watcher","description":"Monitor Gmail for unread important emails and create action files in /Needs_Action with email metadata and classification.","version":"0.1.0","bodyPreview":"# Gmail Watcher\n\nPolls Gmail API for unread important emails, classifies them, and creates `.md` files in `/Needs_Action`.\n\n---\n\n## Triggers\n\nUse this skill when:\n- \"check gmail\"\n- \"monitor emails\"\n- \"watch gmail\"\n- \"check for new emails\"\n- \"start gmail watcher\"\n\n---\n\n## Quick Reference\n\n| Step | Action | Output |\n|------|--------|--------|\n| 1. Poll | Query Gmail API for unread important messages | List of new emails |\n| 2. Dedup | Filter out already-processed message IDs | New messages only |","body":"# Gmail Watcher\n\nPolls Gmail API for unread important emails, classifies them, and creates `.md` files in `/Needs_Action`.\n\n---\n\n## Triggers\n\nUse this skill when:\n- \"check gmail\"\n- \"monitor emails\"\n- \"watch gmail\"\n- \"check for new emails\"\n- \"start gmail watcher\"\n\n---\n\n## Quick Reference\n\n| Step | Action | Output |\n|------|--------|--------|\n| 1. Poll | Query Gmail API for unread important messages | List of new emails |\n| 2. Dedup | Filter out already-processed message IDs | New messages only |\n| 3. Classify | Run classifier on subject + snippet | Category + priority |\n| 4. Create | Write `.md` to `/Needs_Action` with frontmatter | `EMAIL_*.md` file |\n| 5. Notify | Slack notification + Calendar event (if due date) | Notifications sent |\n| 6. Log | Audit entry to `/Logs/YYYY-MM-DD.json` | JSON log line |\n\n---\n\n## Process\n\n### Step 1: Poll Gmail\n\nQuery Gmail API with `is:unread is:important` (configurable via `GMAIL_QUERY` env var).\n\n```\nFor each unread important message:\n  - Check if gmail_id already processed → skip\n  - Fetch full message (headers, snippet, body)\n```\n\n### Step 2: Classify\n\nUse the rule-based classifier on `subject + snippet + body`:\n- **Priority**: urgent / high / medium / low\n- **Category**: Urgent / Work / Personal / Idea\n- **Due date**: Based on priority offset\n\n### Step 3: Create Action File\n\nWrite to `/Needs_Action/EMAIL_<timestamp>_<subject>.md`:\n\n```yaml\n---\ntype: email\nsource: gmail\ngmail_id: \"msg_id\"\nfrom: \"sender@example.com\"\nsubject: \"Email Subject\"\ncategory: Work\npriority: high\nsuggested_due_date: \"2026-03-03\"\nstatus: pending\n---\n```\n\n### Step 4: Log and Notify\n\n- Audit log: `action_type: \"email_processed\"`\n- Slack: Task processed notification\n- Calendar: Event created if due date assigned\n\n---\n\n## Configuration\n\n| Env Var | Default | Purpose |\n|---------|---------|---------|\n| `GOOGLE_CREDENTIALS_PATH` | `credentials.json` | OAuth client secrets |\n| `GMAIL_TOKEN_PATH` | `gmail_token.json` | Persisted OAuth token |\n| `GMAIL_CHECK_INTERVAL` | `120` | Poll interval in seconds |\n| `GMAIL_QUERY` | `is:unread is:important` | Gmail search query |\n\n---\n\n## Running\n\n```bash\ncd watchers\nuv run watch-gmail\n```\n\n---\n\n## Safety\n\n- **Read-only**: Uses `gmail.readonly` scope — never modifies emails\n- **DRY_RUN**: Logs intent without creating files or calling APIs\n- **Retry**: 3 attempts per message, then quarantine\n- **Never crashes**: All API errors caught and logged\n- ALWAYS log every action to `/Logs/`\n"},"lastSynced":"2026-03-07T04:08:32.818Z","agentAnalysis":{"suitability":{"en":"Ideal for Email Management Agents requiring automated Gmail monitoring and classification capabilities.","zh":"适用于需要自动化 Gmail 监控和分类能力的电子邮件管理代理。","ja":"Gmail の監視と分類機能を自動化する必要がある電子メール管理エージェントに最適です。","ko":"자동화된 Gmail 모니터링 및 분류 기능이 필요한 이메일 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Correo electrónico que requieren capacidades de monitoreo y clasificación de Gmail automatizadas.","fr":"Idéal pour les Agents de Gestion de Courriels nécessitant des capacités de surveillance et de classification de Gmail automatisées.","de":"Ideal für E-Mail-Management-Agents, die automatisierte Gmail-Überwachungs- und Klassifizierungsfunktionen erfordern.","pt":"Ideal para Agentes de Gerenciamento de E-mail que exigem monitoramento e capacidades de classificação automatizados do Gmail.","ru":"Идеально для агентов по управлению электронной почтой, требующих автоматизированного мониторинга и возможностей классификации Gmail.","ar":"مثالي لعميل إدارة البريد الإلكتروني الذي يتطلب khảيات مراقبة وتصنيف جيميل أوتوماتيكية."},"recommendation":{"en":"Empowers agents to poll the Gmail API for unread important emails, classify them, and create .md files in /Needs_Action using the Gmail API and Markdown file format, enhancing their email management superpower.","zh":"赋予代理使用 Gmail API 轮询未读重要电子邮件、对其进行分类并使用 Gmail API 和 Markdown 文件格式在 /Needs_Action 中创建 .md 文件，从而增强其电子邮件管理超能力。","ja":"エージェントが Gmail API を使用して未読の重要な電子メールをポーリングし、それらを分類し、Gmail API と Markdown ファイル形式を使用して /Needs_Action に .md ファイルを作成することで、電子メール管理の超能力を強化します。","ko":"에이전트가 Gmail API를 사용하여 읽지 않은 중요한 이메일을 폴링하고, 분류하고, Gmail API 및 Markdown 파일 형식을 사용하여 /Needs_Action에 .md 파일을 생성하여 이메일 관리 超能力을 강화합니다.","es":"Habilita a los agentes a consultar la Gmail API para correos electrónicos importantes no leídos, clasificarlos y crear archivos .md en /Needs_Action utilizando la Gmail API y el formato de archivo Markdown, mejorando su superpoder de gestión de correo electrónico.","fr":"Permet aux agents d''interroger la Gmail API pour les courriels importants non lus, de les classer et de créer des fichiers .md dans /Needs_Action en utilisant la Gmail API et le format de fichier Markdown, améliorant ainsi leur superpouvoir de gestion de courriels.","de":"Ermächtigt die Agenten, die Gmail API für ungelesene wichtige E-Mails abzufragen, sie zu klassifizieren und .md-Dateien im Verzeichnis /Needs_Action unter Verwendung der Gmail API und des Markdown-Dateiformats zu erstellen, wodurch ihre E-Mail-Management-Superkraft verbessert wird.","pt":"Habilita os agentes a consultar a API do Gmail para e-mails importantes não lidos, classificá-los e criar arquivos .md no /Needs_Action usando a API do Gmail e o formato de arquivo Markdown, melhorando sua superpotência de gerenciamento de e-mail.","ru":"Наделяет агентов возможностью опроса Gmail API для важных непрочитанных писем, их классификации и создания файлов .md в /Needs_Action с использованием Gmail API и формата файла Markdown, повышая их суперспособность управления электронной почтой.","ar":"يمنح الوكلاء القدرة على استجواب واجهة برمجة تطبيقات جيميل لرسائل البريد الإلكتروني المهمة غير المقروءة، وتصنيفها، وإنشاء ملفات .md في /Needs_Action باستخدام واجهة برمجة تطبيقات جيميل وتنسيق ملف Markdown، وتعزيز قوة إدارة البريد الإلكتروني الفائقة."},"useCases":{"en":["Automating email classification and organization","Generating Markdown files for important emails","Monitoring Gmail accounts for new unread messages"],"zh":["自动化电子邮件分类和组织","为重要电子邮件生成 Markdown 文件","监控 Gmail 帐户以获取新未读消息"],"ja":["電子メールの分類と組織の自動化","重要な電子メールのための Markdown ファイルの生成","新しい未読メッセージのための Gmail アカウントの監視"],"ko":["이메일 분류 및 조직 자동화","중요한 이메일에 대한 Markdown 파일 생성","새로운 읽지 않은 메시지에 대한 Gmail 계정 모니터링"],"es":["Automatización de la clasificación y organización de correos electrónicos","Generación de archivos Markdown para correos electrónicos importantes","Monitoreo de cuentas de Gmail para nuevos mensajes no leídos"],"fr":["Automatisation de la classification et de l''organisation des courriels","Génération de fichiers Markdown pour les courriels importants","Surveillance des comptes Gmail pour les nouveaux messages non lus"],"de":["Automatisierung der Klassifizierung und Organisation von E-Mails","Erstellung von Markdown-Dateien für wichtige E-Mails","Überwachung von Gmail-Konten für neue ungelesene Nachrichten"],"pt":["Automatizar classificação e organização de e-mails","Gerar arquivos Markdown para e-mails importantes","Monitorar contas do Gmail para novas mensagens não lidas"],"ru":["Автоматизация классификации и организации электронной почты","Генерация файлов Markdown для важных писем","Мониторинг аккаунтов Gmail для новых непрочитанных сообщений"],"ar":["تأتمتية تصنيف وتنظيم رسائل البريد الإلكتروني","توليد ملفات Markdown لرسائل البريد الإلكتروني المهمة","مراقبة حسابات جيميل للرسائل الجديدة غير المقروءة"]},"limitations":{"en":["Requires Gmail API access","Limited to unread important emails","Creates files in a specific /Needs_Action directory"],"zh":["需要 Gmail API 访问","仅限于未读重要电子邮件","仅在特定 /Needs_Action 目录中创建文件"],"ja":["Gmail API アクセスが必要","未読の重要な電子メールのみ","特定の /Needs_Action ディレクトリのみでファイルを作成"],"ko":["Gmail API 액세스가 필요","읽지 않은 중요한 이메일만","특정 /Needs_Action 디렉토리에서만 파일을 생성"],"es":["Requiere acceso a la Gmail API","Limitado a correos electrónicos importantes no leídos","Crea archivos en un directorio específico /Needs_Action"],"fr":["Nécessite l''accès à la Gmail API","Limité aux courriels importants non lus","Crée des fichiers dans un répertoire spécifique /Needs_Action"],"de":["Benötigt Zugriff auf die Gmail API","Begrenzt auf ungelesene wichtige E-Mails","Erstellt Dateien in