INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('VIGNESHSIRIKONDA/Vihara/uv-package-manager', 'uv-package-manager', 'VIGNESHSIRIKONDA', 'Vihara', 'community', 'uv-package-manager VIGNESHSIRIKONDA Vihara community The uv-package-manager skill provides a comprehensive guide to using uv, an extremely fast Python package installer and resolver, for modern Python project management and dependency workflows, benefiting developers and teams. It helps with setting up new Python projects quickly and managing depen... uv-package-manager 是一个快速的 Python 包安装器和解析器，用于管理 Python 项目依赖关系 uvパッケージマネージャーは、Python プロジェクトの依存関係を管理するための高速な Python パッケージインストーラーと解析器です uv-package-manager는 Python 프로젝트의 종속성을 관리하기 위한 빠른 Python 패키지 설치자 및 분석기입니다 uv-package-manager es una herramienta de instalación y resolución de paquetes Python escrita en Rust para proyectos modernos uv-package-manager est un outil d''installation et de résolution de paquets Python écrit en Rust pour les projets modernes uv-package-manager ist ein in Rust geschriebenes Tool für die Installation und Auflösung von Python-Paketen für moderne Projekte O uv-package-manager é uma ferramenta de gerenciamento de pacotes Python rápida e eficiente, escrita em Rust, para projetos modernos ИИ Агент uv-package-manager - это быстрый и эффективный менеджер пакетов Python, написанный на Rust, для современных проектов أداة uv-package-manager هي أداة إدارة حزم بايثون سريعة وفعالة، مكتوبة بلغة روست، لمشاريع حديثة how to use uv-package-manager uv-package-manager vs pip uv-package-manager setup guide uv-package-manager install what is uv-package-manager uv-package-manager alternative uv-package-manager for Python developers fast Python package installer Rust-based package resolver optimizing CI/CD pipelines with uv-package-manager uv-package-manager Python 包管理 依赖关系管理 虚拟环境 Python 解释器 AI 에이전트 Python 项目管理 Installs Python packages faster than pip Resolves dependency conflicts efficiently Creates and manages virtual environments Installs Python interpreters Speeds up CI/CD pipelines Migrates projects from pip/pip-tools/poetry uv-package-manager is a fast Python package installer and resolver written in Rust, designed for modern Python project management and dependency workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wakadorimk2/personal-mcp-core/review-preflight', 'community', 'wakadorimk2', 'personal-mcp-core', 'wakadorimk2/personal-mcp-core', 'review-preflight', 0, 0, 47, '2026-03-05T12:34:15Z', '2026-03-07T04:18:32.831Z', '51fc65eda890fb2c0a38979985d942fb829451cec72ebf9e47006008426f059c', '{"id":"wakadorimk2/personal-mcp-core/review-preflight","name":"review-preflight","description":{"en":"The review-preflight skill automates a minimal pre-review safety pass for code reviews, checking lint, tests, and PR diff context. It benefits developers by providing a consistent review process.","zh":"Review-Preflight 是一个自动化代码审查工具，能够运行lint、测试和PR diff检查。它可以帮助开发者提高代码质量和效率","ja":"Review-Preflight は、AIエージェントによるコードレビューを実現するツールです。lint、テスト、PR diffのチェックを自動化し、コード品質と開発効率を向上させます","ko":"Review-Preflight는 자동 코드 리뷰를 위한 도구로, lint, 테스트 및 PR diff 체크를 실행하여 코드 품질과 개발 효율성을 높여줍니다","es":"Review-preflight es una herramienta de observación de condiciones para desarrolladores que ejecuta una verificación de seguridad mínima antes de la revisión del código","fr":"Review-preflight est un outil d''observation des conditions pour les développeurs qui exécute un contrôle de sécurité minimal avant la revue de code","de":"Review-preflight ist ein Tool zur Überwachung von Bedingungen für Entwickler, das eine minimale Sicherheitsprüfung vor der Code-Überprüfung durchführt","pt":"O Review-Preflight é uma ferramenta de análise de código que executa uma verificação de segurança antes da revisão em profundidade, verificando lint, testes e alterações arriscadas","ru":"Review-Preflight - это инструмент ИИ Агентов, который выполняет минимальную проверку безопасности перед более глубокой проверкой, проверяя lint, тесты и очевидные рискованные изменения","ar":"Review-Preflight هي أداة فحص الكود التي تقوم بتشغيل فحص أمان قبل المراجعة العميقة، وتفحص lint واختبارات والتغييرات الخطرة"},"seo":{"title":{"en":"review-preflight: Automated Code Review Setup Guide | AI ...","zh":"Review-Preflight 设置指南：自动化代码审查","ja":"Review-Preflight 導入ガイド：AIエージェントによるコードレビュー","ko":"Review-Preflight 설정 가이드: 자동 코드 리뷰 및 테스트","es":"Guía de configuración de review-preflight para desarrollo...","fr":"Guide de configuration de review-preflight pour un dévelo...","de":"Einrichtungsleitfaden für review-preflight zur sicheren E...","pt":"Guia de Configuração do Review-Preflight: Ferramenta de A...","ru":"Настройка Review-Preflight: Инструмент ИИ Агентов для Про...","ar":"دليل إعداد Review-Preflight: أداة فحص الكود باستخدام أدوا..."},"description":{"en":"Streamline your code review process with review-preflight. Learn how to automate safety checks and integrate with Codex CLI for efficient PR reviews.","zh":"使用 Review-Preflight 实现自动代码审查，提高开发效率。了解如何设置和使用此工具","ja":"Review-Preflight を使用してコードレビューを自動化し、開発効率を向上させる。導入方法と使い方を紹介","ko":"Review-Preflight를 사용하여 자동 코드 리뷰를 구현하고 개발 효율성을 높여보세요. 설정 방법과 사용법을 알아보세요","es":"Aprende a configurar review-preflight para ejecutar una verificación de seguridad previa a la revisión del código","fr":"Découvrez comment configurer review-preflight pour exécuter un contrôle de sécurité avant la revue de code","de":"Erfahren Sie, wie Sie review-preflight einrichten, um eine Sicherheitsprüfung vor der Code-Überprüfung durchzuführen","pt":"Aprenda a configurar o Review-Preflight, uma ferramenta de análise de código que executa uma verificação de segurança antes da revisão em profundidade","ru":"Узнайте, как настроить Review-Preflight, инструмент ИИ Агентов, который выполняет минимальную проверку безопасности перед более глубокой проверкой","ar":"تعرف على كيفية إعداد Review-Preflight، أداة فحص الكود التي تقوم بتشغيل فحص أمان قبل المراجعة العميقة"},"definition":{"en":"review-preflight is a canonical execution contract for running automated code reviews with Codex CLI, ensuring a consistent and efficient review process.","zh":"Review-Preflight 是一个自动化代码审查工具，用于运行代码检查和测试","ja":"Review-Preflight は、AIエージェントによるコードレビューを実現するツールです","ko":"Review-Preflight는 자동 코드 리뷰를 위한 도구로, 코드 체크와 테스트를 실행합니다","es":"Review-preflight es una herramienta de desarrollo que realiza una verificación de seguridad previa a la revisión del código","fr":"Review-preflight est un outil de développement qui effectue un contrôle de sécurité avant la revue de code","de":"Review-preflight ist ein Entwicklungstool, das eine Sicherheitsprüfung vor der Code-Überprüfung durchführt","pt":"O Review-Preflight é uma ferramenta de análise de código que executa uma verificação de segurança antes da revisão em profundidade","ru":"Review-Preflight - это инструмент ИИ Агентов, который выполняет минимальную проверку безопасности перед более глубокой проверкой","ar":"Review-Preflight هي أداة فحص الكود التي تقوم بتشغيل فحص أمان قبل المراجعة العميقة"},"features":{"en":["Runs a minimal pre-review safety pass using Codex CLI","Checks lint, tests, PR diff context, and obvious risky changes","Supports optional PR number and base branch inputs","Provides a fixed order of checks for consistent results","Generates output that can be pasted into a PR comment"],"zh":["自动运行 lint 和测试","PR diff 체크를 지원","Codex CLI 与集成","代码安全性检查","自动化代码审查流程"],"ja":["lint とテストの自動実行","PR diff チェックのサポート","Codex CLI との統合","コードの安全性チェック","コードレビューの自動化"],"ko":["자동 lint 및 테스트 실행","PR diff 체크 지원","Codex CLI와의 통합","코드 보안성 체크","자동 코드 리뷰 프로세스"],"es":["Ejecuta una verificación de seguridad mínima antes de la revisión del código","Comprueba el lint, las pruebas y los cambios obvios en un orden fijo","Soporta la ejecución con Codex CLI","Permite la especificación del número de PR y la rama base","Genera un resultado que se puede pegar en un comentario de PR"],"fr":["Exécute un contrôle de sécurité minimal avant la revue de code","Vérifie le lint, les tests et les changements évidents dans un ordre fixe","Prend en charge l''exécution avec Codex CLI","Permet la spécification du numéro de PR et de la branche de base","Génère un résultat qui peut être collé dans un commentaire de PR"],"de":["Führt eine minimale Sicherheitsprüfung vor der Code-Überprüfung durch","Überprüft den Lint, die Tests und die offensichtlichen Änderungen in einer festen Reihenfolge","Unterstützt die Ausführung mit Codex CLI","Ermöglicht die Angabe der PR-Nummer und des Basisbranches","Erzeugt ein Ergebnis, das in einen PR-Kommentar eingefügt werden kann"],"pt":["Verificação de lint","Execução de testes","Análise de alterações arriscadas","Integração com Codex CLI","Suporte a PR diff context","Verificação de segurança antes da revisão em profundidade"],"ru":["Проверка lint","Выполнение тестов","Анализ очевидных рискованных изменений","Интеграция с Codex CLI","Поддержка PR diff context","Проверка безопасности перед более глубокой проверкой"],"ar":["فحص lint","تشغيل اختبارات","تحليل التغييرات الخطرة","التكامل مع Codex CLI","دعم سياق PR diff","فحص أمان قبل المراجعة العميقة"]},"keywords":{"en":["how to use review-preflight","review-preflight setup guide","automated code review tools","Codex CLI integration","review-preflight vs manual code review","review-preflight install","what is review-preflight","review-preflight alternative","review-preflight tutorial"],"zh":["Review-Preflight","自动代码审查","AI工具","代码质量","开发效率","Codex CLI","代码安全性","自动化代码审查"],"ja":["Review-Preflight","AIエージェント","コードレビュー","コード品質","開発効率","Codex CLI","コードの安全性","自動化コードレビュー"],"ko":["Review-Preflight","자동 코드 리뷰","AI 도구","코드 품질","개발 효율성","Codex CLI","코드 보안성","자동 코드 리뷰 프로세스"],"es":["review-preflight","herramienta de desarrollo","verificación de seguridad","Codex CLI","PR","rama base","lint","pruebas","cambios obvios"],"fr":["review-preflight","outils de développement","contrôle de sécurité","Codex CLI","PR","branche de base","lint","tests","changements évidents"],"de":["review-preflight","Entwicklungstool","Sicherheitsprüfung","Codex CLI","PR","Basisbranch","Lint","Tests","offensichtliche Änderungen"],"pt":["Review-Preflight","análise de código","ferramenta de análise de código","verificação de segurança","Codex CLI","PR diff context","lint","testes","alterações arriscadas"],"ru":["Review-Preflight","ИИ Агенты","инструмент ИИ Агентов","проверка безопасности","Codex CLI","PR diff context","lint","тесты","очевидные рискованные изменения"],"ar":["Review-Preflight","أدوات الذكاء الاصطناعي","أداة فحص الكود","فحص أمان","Codex CLI","سياق PR diff","lint","اختبارات","التغييرات الخطرة"]}},"owner":"wakadorimk2","repo":"personal-mcp-core","repoPath":"wakadorimk2/personal-mcp-core","stars":0,"forks":0,"updatedAt":"2026-03-05T12:34:15Z","topics":[],"category":"community","skillMd":{"name":"review-preflight","description":"Run the Codex PR review preflight in a fixed order and report actionable results without pushing or taking destructive actions.","bodyPreview":"# review-preflight\n\nThis is the canonical execution contract for running the review preflight with Codex CLI.\nThe human-facing intent lives in [`docs/skills/review-preflight.md`](../../../docs/skills/review-preflight.md).\n\n## Goal\n\nRun a minimal pre-review safety pass before deeper review work starts.\nCheck lint, tests, PR diff context, and obvious risky changes in a fixed order so the result can be pasted into a PR comment.\n\n## Inputs\n\n- PR number (optional)\n- Base branch (optional, default: cu","body":"# review-preflight\n\nThis is the canonical execution contract for running the review preflight with Codex CLI.\nThe human-facing intent lives in [`docs/skills/review-preflight.md`](../../../docs/skills/review-preflight.md).\n\n## Goal\n\nRun a minimal pre-review safety pass before deeper review work starts.\nCheck lint, tests, PR diff context, and obvious risky changes in a fixed order so the result can be pasted into a PR comment.\n\n## Inputs\n\n- PR number (optional)\n- Base branch (optional, default: current branch upstream or `main`)\n- Expected commands: `ruff check .`, `pytest`, `gh pr diff <PR>` when PR number is available\n\nIf the PR number is missing, skip `gh pr diff` and use local git diff against the chosen base branch.\nIf the base branch is missing, prefer the current branch upstream; otherwise use `main`.\n\n## Procedure\n\nRun the checks in this order.\n\n1. Run `ruff check .`\n2. Run `pytest`\n3. Collect diff context\n   - If PR number is provided: run `gh pr diff <PR>`\n   - Otherwise: inspect local git diff against the chosen base branch\n4. Summarize the diff in 2 to 5 lines\n5. Flag obvious risks\n   - destructive file operations\n   - wide-scope refactors outside the stated review target\n   - dependency, CI, or release-impacting changes\n   - missing tests for behavior changes\n\n## Output Format\n\nReturn Markdown with the sections below in this order.\n\n## Summary\n\n- Overall status: `✅` / `⚠️` / `❌`\n- One-line summary\n\n## Checks\n\n- `ruff`: `✅` / `⚠️` / `❌`\n- `pytest`: `✅` / `⚠️` / `❌`\n- `diff`: `✅` / `⚠️` / `❌`\n\n## Diff Summary\n\n- 2 to 5 short lines\n\n## Risks\n\n- `None` if no obvious risk was found\n- Otherwise list each risk in one line\n\n## Fix Candidates\n\n- Minimal, local fixes only\n- `None` if no fix is needed before review\n\n## Next Action\n\n- One line stating whether review can proceed\n\n## Constraints\n\n- Do not push\n- Do not use external web search or fetch arbitrary remote content\n- Do not perform destructive operations\n- Do not change files unless explicitly asked in the current task\n- Keep recommendations inside the current review scope\n"},"lastSynced":"2026-03-07T04:18:32.831Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated pre-review safety checks for lint, tests, and PR diff context.","zh":"适用于需要自动化代码审查预检查的代码审查代理，用于lint、测试和PR diff上下文的安全检查。","ja":"コードレビュー代理が自動化された事前レビューの安全性チェックを必要とする場合に適しています。Lint、テスト、PR diffコンテキストの安全性チェックに最適です。","ko":"코드 리뷰 에이전트가 자동화된 사전 리뷰 안전性 확인을 필요로 하는 경우에 적합합니다. 린트, 테스트 및 PR 차이 contexto의 안전성 확인에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan comprobaciones de seguridad de pre-revisión automatizadas para lint, pruebas y contexto de diferencia de solicitud de extracción.","fr":"Parfait pour les agents de revue de code nécessitant des vérifications de sécurité préalables automatisées pour lint, tests et contexte de différence de demande d''extraction.","de":"Perfekt für Code-Review-Agents, die automatisierte Sicherheitsprüfungen vor der Review für Lint, Tests und PR-Diff-Kontext benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de verificações de segurança pré-revisão automatizadas para lint, testes e contexto de diff de PR.","ru":"Идеально подходит для агентов кодового обзора, требующих автоматизированных предварительных проверок безопасности для lint, тестов и контекста diff PR.","ar":"مثالي لعميل مراجعة الشفرة الذي يحتاج إلى فحوصات أمان ما قبل المراجعة آليًا للخامات و الاختبارات و سياق فرق الطلبات الجديدة."},"recommendation":{"en":"Empowers agents to run a minimal pre-review safety pass, checking lint, tests, and PR diff context, providing a consistent review process with tools like Codex CLI, and enabling them to identify obvious risky changes through a fixed order of checks.","zh":"赋予代理运行最小的预审安全检查的能力，检查lint、测试和PR diff上下文，提供使用Codex CLI等工具的一致的审查流程，并使其能够通过固定的检查顺序识别明显的高风险更改。","ja":"エージェントが最小限の事前レビューの安全性チェックを実行する能力を付与し、Lint、テスト、PR diffコンテキストをチェックし、Codex CLIなどのツールを使用した一貫したレビュー処理を提供し、固定のチェック順序で明らかなリスクのある変更を識別することを可能にします。","ko":"에이전트가 최소한의 사전 리뷰 안전성 확인을 실행할 수 있는 능력을 부여하여 린트, 테스트 및 PR 차이 contexto를 확인하고 Codex CLI와 같은 도구를 사용한 일관된 리뷰 프로세스를 제공하며 고정된 확인 순서로 명백한 위험한 변경을 식별할 수 있습니다.","es":"Habilita a los agentes a ejecutar un paso de seguridad de pre-revisión mínimo, que comprueba lint, pruebas y contexto de diferencia de solicitud de extracción, proporcionando un proceso de revisión coherente con herramientas como Codex CLI, y permitiéndoles identificar cambios obviamente riesgosos a través de un orden fijo de comprobaciones.","fr":"Permet aux agents d''exécuter un passage de sécurité préalable minimal, vérifiant lint, tests et contexte de différence de demande d''extraction, fournissant un processus de revue cohérent avec des outils comme Codex CLI, et leur permettant d''identifier des modifications risquées évidentes à travers un ordre fixe de vérifications.","de":"Ermächtigt die Agenten, einen minimalen Sicherheitsprüfungsvorgang vor der Review durchzuführen, der Lint, Tests und PR-Diff-Kontext überprüft, und bietet so einen konsistenten Reviewprozess mit Tools wie Codex CLI, und ermöglicht es ihnen, offensichtlich riskante Änderungen durch eine feste Reihenfolge von Prüfungen zu identifizieren.","pt":"Habilita os agentes a executar uma passagem de segurança pré-revisão mínima, verificando lint, testes e contexto de diff de PR, fornecendo um processo de revisão consistente com ferramentas como Codex CLI, e permitindo que eles identifiquem alterações de risco óbvio por meio de uma ordem fixa de verificações.","ru":"Позволяет агентам выполнить минимальный предварительный обзор безопасности, проверяя lint, тесты и контекст diff PR, обеспечивая последовательный процесс обзора с помощью инструментов, таких как Codex CLI, и позволяя им определять очевидные рисковые изменения через фиксированный порядок проверок.","ar":"تمكّن العميل من تشغيل عملية فحص أمان ما قبل المراجعة الأدنى، للخامات و الاختبارات و سياق فرق الطلبات الجديدة، وتوفير عملية مراجعة متسقة باستخدام أدوات مثل Codex CLI، وتمكينه من تحديد التغييرات الخطرة الواضحة من خلال ترتيب ثابت للفحوصات."},"useCases":{"en":["Automating code review preflight checks for PRs","Validating lint and test results before in-depth review","Identifying high-risk changes in PR diff context"],"zh":["自动化代码审查的预飞行检查，用于PRs","在深入审查之前验证lint和测试结果","在PR diff上下文中识别高风险更改"],"ja":["PRの事前フライトチェックの自動化","詳細なレビューを行う前にLintとテスト結果を検証する","PR diffコンテキストでリスクの高い変更を識別する"],"ko":["PR의 사전 비행 확인을 자동화하는 것","깊은 리뷰를 수행하기 전에 린트 및 테스트 결과를 확인","PR 차이 contexto에서 고위험 변경을 식별"],"es":["Automatizar las comprobaciones de pre-vuelo de revisión de código para solicitudes de extracción","Validar los resultados de lint y pruebas antes de una revisión en profundidad","Identificar cambios de alto riesgo en el contexto de diferencia de solicitud de extracción"],"fr":["Automatiser les vérifications de pré-vol de revue de code pour les demandes d''extraction","Valider les résultats de lint et de tests avant une revue en profondeur","Identifier les modifications à haut risque dans le contexte de différence de demande d''extraction"],"de":["Automatisieren von Code-Review-Vorabprüfungen für Pull-Requests","Validieren von Lint- und Testergebnissen vor einer eingehenden Überprüfung","Identifizieren von hochrisikigen Änderungen im PR-Diff-Kontext"],"pt":["Automatizar verificações pré-voo de revisão de código para PRs","Validar resultados de lint e testes antes de uma revisão aprofundada","Identificar alterações de alto risco no contexto de diff de PR"],"ru":["Автоматизировать предварительные проверки кода для PR","Проверить результаты lint и тестов перед углубленным обзором","Определить изменения с высоким риском в контексте diff PR"],"ar":["تأتمتة فحوصات ما قبل المراجعة للشفرة للطلبات الجديدة","تحقق من نتائج الخامات و الاختبارات قبل المراجعة العميقة","تحديد التغييرات ذات الخطورة العالية في سياق فرق الطلبات الجديدة"]},"limitations":{"en":["Requires PR number and base branch as optional inputs","Default base branch set to ''cu'' if not provided","Limited to running a fixed order of checks"],"zh":["需要PR编号和基准分支作为可选输入","如果未提供，则默认基准分支设置为''cu''","仅限运行固定顺序的检查"],"ja":["PR番号とベースブランチがオプションの入力として必要","提供されていない場合は、デフォルトのベースブランチが''cu''に設定される","固定順序のチェックのみを実行可能"],"ko":["PR 번호 및 기본 분기作为 선택적 입력이 필요","기본 분기가 제공되지 않은 경우 기본 분기가 ''cu''로 설정됨","고정 순서의 확인만 실행"],"es":["Requiere el número de solicitud de extracción y la rama base como entradas opcionales","La rama base predeterminada se establece en ''cu'' si no se proporciona","Limitado a ejecutar un orden fijo de comprobaciones"],"fr":["Nécessite le numéro de demande d''extraction et la branche de base comme entrées optionnelles","La branche de base par défaut est définie sur ''cu'' si elle n''est pas fournie","Limité à l''exécution d''un ordre fixe de vérifications"],"de":["Benötigt die Pull-Request-Nummer und den Basisbranch als optionale Eingaben","Der Standard-Basisbranch wird auf ''cu'' gesetzt, wenn er nicht angegeben wird","Begrenzt auf die Ausführung einer festen Reihenfolge von Prüfungen"],"pt":["Exige número de PR e branch base como entradas opcionais","Branch base padrão definido como ''cu'' se não fornecido","Limitado a executar uma ordem fixa de verificações"],"ru":["Требует номера PR и базовой ветки в качестве необязательных входных данных","Базовая ветка по умолчанию установлена на ''cu'', если не указана","Ограничен выполнением фиксированного порядка проверок"],"ar":["يتطلب رقم الطلبات الجديدة وفرع الأساس كمدخلات اختيارية","الفرع الأساسي الافتراضي هو ''cu'' إذا لم يتم توفيره","محدود بالتشغيل من خلال ترتيب ثابت للفحوصات"]},"version":4},"contentHash":"51fc65eda890fb2c0a38979985d942fb829451cec72ebf9e47006008426f059c","qualityScore":47}');
