INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wakadorimk2/personal-mcp-core/review-preflight', 'review-preflight', 'wakadorimk2', 'personal-mcp-core', 'community', 'review-preflight wakadorimk2 personal-mcp-core community The review-preflight skill automates a minimal pre-review safety pass for code reviews, checking lint, tests, and PR diff context. It benefits developers by providing a consistent review process. Review-Preflight 是一个自动化代码审查工具，能够运行lint、测试和PR diff检查。它可以帮助开发者提高代码质量和效率 Review-Preflight は、AIエージェントによるコードレビューを実現するツールです。lint、テスト、PR diffのチェックを自動化し、コード品質と開発効率を向上させます Review-Preflight는 자동 코드 리뷰를 위한 도구로, lint, 테스트 및 PR diff 체크를 실행하여 코드 품질과 개발 효율성을 높여줍니다 Review-preflight es una herramienta de observación de condiciones para desarrolladores que ejecuta una verificación de seguridad mínima antes de la revisión del código Review-preflight est un outil d''observation des conditions pour les développeurs qui exécute un contrôle de sécurité minimal avant la revue de code Review-preflight ist ein Tool zur Überwachung von Bedingungen für Entwickler, das eine minimale Sicherheitsprüfung vor der Code-Überprüfung durchführt O Review-Preflight é uma ferramenta de análise de código que executa uma verificação de segurança antes da revisão em profundidade, verificando lint, testes e alterações arriscadas Review-Preflight - это инструмент ИИ Агентов, который выполняет минимальную проверку безопасности перед более глубокой проверкой, проверяя lint, тесты и очевидные рискованные изменения Review-Preflight هي أداة فحص الكود التي تقوم بتشغيل فحص أمان قبل المراجعة العميقة، وتفحص lint واختبارات والتغييرات الخطرة how to use review-preflight review-preflight setup guide automated code review tools Codex CLI integration review-preflight vs manual code review review-preflight install what is review-preflight review-preflight alternative review-preflight tutorial Review-Preflight 自动代码审查 AI工具 代码质量 开发效率 Codex CLI 代码安全性 自动化代码审查 Runs a minimal pre-review safety pass using Codex CLI Checks lint, tests, PR diff context, and obvious risky changes Supports optional PR number and base branch inputs Provides a fixed order of checks for consistent results Generates output that can be pasted into a PR comment review-preflight is a canonical execution contract for running automated code reviews with Codex CLI, ensuring a consistent and efficient review process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pyinx/ceo-skills-plugin/ceo', 'community', 'pyinx', 'ceo-skills-plugin', 'pyinx/ceo-skills-plugin', 'ceo', 0, 0, 47, '2026-03-08T01:57:15.272Z', '2026-03-08T02:00:24.785Z', '6e434f81ffef4324e7ea5b5181fe18471b6bcba6a751aefb84b4b026cce5e338', '{"id":"pyinx/ceo-skills-plugin/ceo","name":"ceo","description":{"en":"The CEO skill enables full-stack development teams to deliver products from vague requirements to deployment, leveraging 6 professional agents and 11 Superpowers framework skills. It benefits developers seeking streamlined workflow orchestration.","zh":"CEO Agent是一个全栈开发团队，集成6个专业agents和11个Superpowers框架skills，实现从模糊需求到产品交付的自动化开发流程","ja":"CEOエージェントは、6つの専門エージェントと11つのSuperpowersフレームワークスキルを統合したフルスタック開発チームです","ko":"CEO 에이전트는 6개의 전문 에이전트와 11개의 Superpowers 프레임워크 스킬을 통합한 풀스택 개발 팀입니다","es":"El agente CEO es un equipo de desarrollo de software full-stack que integra 6 agentes profesionales y 11 habilidades de frameworks Superpowers","fr":"L''agent CEO est une équipe de développement de logiciels full-stack qui intègre 6 agents professionnels et 11 compétences de frameworks Superpowers","de":"Der CEO-Agent ist ein Full-Stack-Software-Entwicklungsteam, das 6 professionelle Agenten und 11 Fähigkeiten von Superpowers-Frameworks integriert","pt":"O CEO Agent é um agente de desenvolvimento de software que integra 6 agentes e 11 habilidades do framework Superpowers para fornecer uma solução completa","ru":"ИИ Агент CEO - это агент разработки программного обеспечения, который интегрирует 6 агентов и 11 навыков фреймворка Superpowers для предоставления полного решения","ar":"وكيل الرئيس التنفيذي هو وكيل تطوير برمجي يدمج 6 وكلاء و 11 مهارات إطار العمل Superpowers لتقديم حل كامل"},"seo":{"title":{"en":"CEO: Direct Orchestration Setup Guide | AI Agent Skill","zh":"CEO Agent_SETUP GUIDE：从模糊需求到产品交付的全栈开发","ja":"CEOエージェント Setup Guide：AIエージェントによるソフトウェア開発","ko":"CEO 에이전트 설정 가이드: 요구사항 탐색부터 제품 전달까지","es":"Guía de configuración de CEO Agent para desarrollo de sof...","fr":"Guide de mise en place de l''agent CEO pour le développeme...","de":"Einrichtungsleitfaden für CEO-Agenten zur Softwareentwick...","pt":"CEO Agent: Guia de Configuração para Desenvolvimento de S...","ru":"ИИ Агент CEO: Руководство по Настройке для Разработки Про...","ar":"وكيل الرئيس التنفيذي: دليل الإعداد لتطوير البرمجيات"},"description":{"en":"Unlock efficient software development with CEO''s integrated Superpowers frameworks and workflow automation - learn how to get started today!","zh":"CEO Agent是一个集成6个专业agents和11个Superpowers框架skills的全栈开发团队，实现从模糊需求到产品交付的自动化开发流程","ja":"CEOエージェントは、6つの専門エージェントと11つのSuperpowersフレームワークスキルを統合したフルスタック開発チームです。ソフトウェア開発を自動化します","ko":"CEO 에이전트는 6개의 전문 에이전트와 11개의 Superpowers 프레임워크 스킬을 통합한 풀스택 개발 팀으로, 요구사항 탐색부터 제품 전달까지 자동화 개발 프로세스를 구현합니다","es":"Aprende a integrar el agente CEO con Superpowers frameworks para mejorar tus flujos de trabajo de desarrollo de software","fr":"Découvrez comment intégrer l''agent CEO avec les frameworks Superpowers pour améliorer vos flux de travail de développement de logiciels","de":"Erfahren Sie, wie Sie den CEO-Agenten mit Superpowers-Frameworks integrieren, um Ihre Software-Entwicklungsworkflows zu verbessern","pt":"Aprenda a configurar o CEO Agent para desenvolvimento de software com integração de 6 agentes e 11 habilidades do framework Superpowers","ru":"Узнайте, как настроить ИИ Агент CEO для разработки программного обеспечения с интеграцией 6 агентов и 11 навыков фреймворка Superpowers","ar":"تعرف على كيفية إعداد وكيل الرئيس التنفيذي لتطوير البرمجيات مع دمج 6 وكلاء و 11 مهارات إطار العمل Superpowers"},"definition":{"en":"CEO is a comprehensive AI agent skill integrating multiple professional agents and Superpowers frameworks for direct orchestration of software development workflows.","zh":"CEO Agent是一种集成开发环境，实现从需求探索到产品交付的全栈开发流程","ja":"CEOエージェントは、ソフトウェア開発の自動化を実現するフルス