INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ngxtm/devkit/cpp-pro', 'cpp-pro', 'ngxtm', 'devkit', 'community', 'cpp-pro ngxtm devkit community cpp-pro is a unified multi-agent skill system for AI coding assistants, featuring expertise in modern C++20/23 and systems programming. It benefits senior C++ engineers and developers working on high-performance computing projects. C++ Pro 是一个现代 C++20/23 和高性能计算的 AI 编码助手，支持系统编程和零开销抽象 C++ Pro はモダン C++20/23 とハイパフォーマンスコンピューティングをサポートする AI コーディングアシスタントです。システムプログラミングとゼロオーバーヘッド抽象もサポートしています C++ Pro는 모던 C++20/23 및 고성능 컴퓨팅을 지원하는 AI 코딩 어시스턴트입니다. 시스템 프로그래밍 및 제로 오버헤드 추상을 지원합니다 cpp-pro es un sistema de habilidades multiagente para asistentes de codificación de C++ que ofrece detección de tecnologías y optimización de rendimiento cpp-pro est un système de compétences multi-agents pour les assistants de codage C++ qui propose une détection de technologies et une optimisation des performances cpp-pro ist ein Multi-Agenten-Skill-System für C++-Codierassistenten, das Technologie-Erkennung und Leistungsoptimierung bietet Cpp-Pro é um sistema de habilidades de agente de IA para desenvolvedores C++ experientes, com foco em C++20/23 e programação de sistemas Cpp-Pro - это система навыков агента ИИ для опытных разработчиков на C++, ориентированная на C++20/23 и системное программирование Cpp-Pro هو نظام مهارات وكيل الذكاء الاصطناعي لمنطقي سي++ المخضرمين، مع التركيز على سي++20/23 وبرمجة الأنظمة how to use cpp-pro cpp-pro alternative cpp-pro install what is cpp-pro cpp-pro vs Copilot cpp-pro setup guide modern C++20/23 programming C++ template metaprogramming high-performance computing with cpp-pro C++ Pro 现代 C++20/23 系统编程 高性能计算 AI 编码助手 C++ Core Guidelines 模板元编程 零开销抽象 Supports modern C++20/23 and template metaprogramming Enables performance optimization and zero-overhead abstractions Follows C++ Core Guidelines for production-grade systems Includes smart tech detection and per-project installation Auto-syncs from upstream sources for seamless integration Leverages cutting-edge language features for safety and efficiency cpp-pro is a senior C++ developer skill with deep expertise in modern C++20/23, systems programming, and high-performance computing, following C++ Core Guidelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('prompt-security/clawsec/claw-release', 'community', 'prompt-security', 'clawsec', 'prompt-security/clawsec', 'claw-release', 0, 0, 47, '2026-03-08T01:57:15.280Z', '2026-03-08T02:00:49.004Z', 'cda9f58b3be67876ba4a543d6192af60ea155c2102202340fdfc8770a848f07e', '{"id":"prompt-security/clawsec/claw-release","name":"claw-release","description":{"en":"The claw-release skill provides a comprehensive security suite for OpenClaw''s family of agents, protecting SOUL.md files with features like drift detection and live security recommendations. This internal tool is designed for developers and security professionals.","zh":"Claw Release是一套完整的安全技能套件，提供drift detection、live security recommendations、automated audits和skill integrity verification等功能","ja":"Claw Releaseは、Drift検出、ライブセキュリティ推奨、自動監査、スキル整合性検証などの機能を提供する完全なセキュリティスキル・スイートです","ko":"Claw Release는 Drift 탐지, 실시간 보안 추천, 자동 감사 및 스킬 무결성 검증 등을 제공하는 완전한 보안 스킬套件입니다","es":"Claw-release es una suite de seguridad para agentes de inteligencia artificial que ofrece detección de derivas, recomendaciones de seguridad en vivo y auditorías automatizadas","fr":"Claw-release est une suite de sécurité pour les agents d''intelligence artificielle qui propose une détection de dérives, des recommandations de sécurité en temps réel et des audits automatisés","de":"Claw-release ist eine Sicherheitssuite für KI-Agents, die Drift-Erkennung, Echtzeit-Sicherheitsempfehlungen und automatisierte Audits bietet","pt":"O claw-release é um conjunto de ferramentas de segurança para agentes de inteligência artificial, com recursos como detecção de drift e auditorias automatizadas. Ele protege seus arquivos SOUL.md com recomendações de segurança em tempo real","ru":"claw-release - это набор инструментов безопасности для ИИ Агентов, с функциями zoals обнаружение дрифта и автоматизированные аудиты. Он защищает ваши файлы SOUL.md с рекомендациями безопасности в реальном времени","ar":"claw-release هو مجموعة من أدوات الأمن لعمليات الإستخبارات الاصطناعية، مع ميزات مثل الكشف عن التغيرات والتفتيش الآلي. وهو يحمي ملفاتك SOUL.md مع التوصيات الأمنية في الوقت الفعلي"},"seo":{"title":{"en":"claw-release: Security Suite Setup Guide | AI Agent Skill","zh":"Claw Release 安全套件安装指南","ja":"Claw Release AIエージェントのセキュリティセットアップガイド","ko":"Claw Release 보안 스킬 설치 및 설정 방법","es":"Guía de configuración de claw-release para seguridad de a...","fr":"Guide de configuration de claw-release pour la sécurité d...","de":"Konfigurationsleitfaden für claw-release zur Sicherheit v...","pt":"Guia de Configuração do claw-release: Ferramentas de Segu...","ru":"Настройка claw-release: Инструменты безопасности для ИИ А...","ar":"دليل إعداد claw-release: أدوات أمنية لعمليات الإستخبارات ..."},"description":{"en":"Discover how to protect your SOUL.md with claw-release, featuring drift detection and automated audits. Get started now!","zh":"了解Claw Release安全套件的安装和设置，保护您的SOUL.md和其他文件","ja":"Claw Release AIエージェントのセキュリティ機能を活用して、SOUL.mdなどのファイルを保護する","ko":"Claw Release 보안 스킬을 설치하고 설정하여 SOUL.md와 기타 파일을 보호하세요","es":"Aprende a proteger tus agentes de inteligencia artificial con claw-release, incluyendo detección de derivas y recomendaciones de seguridad en vivo","fr":"Découvrez comment protéger vos agents d''intelligence artificielle avec claw-release, y compris la détection de dérives et les recommandations de sécurité en ...","de":"Erfahren Sie, wie Sie Ihre KI-Agents mit claw-release schützen, einschließlich Drift-Erkennung und Echtzeit-Sicherheitsempfehlungen","pt":"Aprenda a configurar o claw-release, um conjunto de ferramentas de segurança para agentes de inteligência artificial, com recursos como detecção de drift e a...","ru":"Узнайте, как настроить claw-release, набор инструментов безопасности для ИИ Агентов, с функциями zoals обнаружение дрифта и автоматизированные аудиты","ar":"تعرف على كيفية إعداد claw-release، وهو مجموعة من أدوات الأمن لعمليات الإستخبارات الاصطناعية، مع ميزات مثل الكشف عن التغيرات والتفتيش الآلي"},"definition":{"en":"claw-release is an internal security tool for releasing skills and managing the ClawSec catalog, offering features like automated audits and skill integrity verification.","zh":"Claw Release是一套用于保护SOUL.md和其他文件的安全技能套件","ja":"Claw Releaseは、SOUL.mdなどのファイルを保護するためのセキュリティスキル・スイートです","ko":"Claw Release는 SOUL.md와 기타 파일을 보호하는 보안 스킬套件입니다","es":"Claw-release es una herramienta de seguridad para agentes de inteligencia artificial que proporciona protección y recomendaciones de seguridad","fr":"Claw-release est un outil de sécurité pour les agents d''intelligence artificielle qui offre une protection et des recommandations de sécurité","de":"Claw-release ist ein Sicherheitstool für KI-Agents, das Schutz und Sicherheitsempfehlungen bietet","pt":"O claw-release é um conjunto de ferramentas de segurança para agentes de inteligência artificial que protege arquivos SOUL.md com detecção de drift e auditorias automatizadas","ru":"claw-release - это набор инструментов безопасности для ИИ Агентов, который защищает файлы SOUL.md с обнаружением дрифта и автоматизированными аудитами","ar":"claw-release هو مجموعة من أدوات الأمن لعمليات الإستخبارات الاصطناعية التي تحمي ملفات SOUL.md مع الكشف عن التغيرات والتفتيش الآلي"},"features":{"en":["Drift detection for SOUL.md files","Live security recommendations for enhanced protection","Automated audits for skill integrity verification","Supports release workflow via ./scripts/release-skill.sh command","Tag format customization with <name>-v<version> syntax","Pre-release support with beta versioning (e.g., 1.0.0-beta1)"],"zh":["Drift检测","Live安全推荐","自动审计","Skill整合性验证","支持CLI命令","提供预发布和发布版本"],"ja":["Drift検出","ライブセキュリティ推奨","自動監査","スキル整合性検証","CLIコマンド対応","プレリリースとリリースバージョンの提供"],"ko":["Drift 탐지","실시간 보안 추천","자동 감사","스킬 무결성 검증","CLI 명령어 지원","프리 릴리스 및 릴리스 버전 제공"],"es":["Detección de derivas para agentes de inteligencia artificial","Recomendaciones de seguridad en vivo","Auditorías automatizadas para agentes","Verificación de integridad de habilidades","Compatibilidad con CLI para ejecución de comandos"],"fr":["Détection de dérives pour les agents d''intelligence artificielle","Recommandations de sécurité en temps réel","Audits automatisés pour les agents","Vérification de l''intégrité des compétences","Compatibilité avec CLI pour l''exécution de commandes"],"de":["Drift-Erkennung für KI-Agents","Echtzeit-Sicherheitsempfehlungen","Automatisierte Audits für KI-Agents","Integritätsprüfung von Fähigkeiten","Kompatibilität mit CLI für Befehlsausführung"],"pt":["Detecção de drift para agentes de inteligência artificial","Auditorias automatizadas para arquivos SOUL.md","Recomendações de segurança em tempo real","Verificação de integridade de habilidades","Suporte a lançamento de habilidades com scripts personalizados"],"ru":["Обнаружение дрифта для ИИ Агентов","Автоматизированные аудиты для файлов SOUL.md","Рекомендации безопасности в реальном времени","Проверка целостности навыков","Поддержка выпуска навыков с помощью пользовательских скриптов"],"ar":["كشف التغيرات لعمليات الإستخبارات الاصطناعية","التفتيش الآلي لملفات SOUL.md","التوصيات الأمنية في الوقت الفعلي","التحقق من صحة المهارات","دعم إصدار المهارات باستخدام البرامج النصية المخصصة"]},"keywords":{"en":["how to use claw-release","claw-release security suite","claw-release alternative","claw-release vs Prompt Security","claw-release install guide","claw-release setup for AI agents","what is claw-release","claw-release documentation","claw-release tutorial"],"zh":["Claw Release","安全技能套件","SOUL.md保护","Drift检测","Live安全推荐","自动审计","Skill整合性验证","CLI命令","预发布和发布版本"],"ja":["Claw Release","AIエージェント","セキュリティスキル・スイート","SOUL.md保護","Drift検出","ライブセキュリティ推奨","自動監査","スキル整合性検証","CLIコマンド","プレリリースとリリースバージョン"],"ko":["Claw Release","보안 스킬套件","SOUL.md 보호","Drift 탐지","실시간 보안 추천","자동 감사","스킬 무결성 검증","CLI 명령어","프리 릴리스 및 릴리스 버전"],"es":["seguridad de agentes de inteligencia artificial","claw-release","detección de derivas","recomendaciones de seguridad en vivo","auditorías automatizadas","verificación de integridad de habilidades","CLI para agentes de inteligencia artificial"],"fr":["sécurité des agents d''intelligence artificielle","claw-release","détection de dérives","recommandations de sécurité en temps réel","audits automatisés","vérification de l''intégrité des compétences","CLI pour les agents d''intelligence artificielle"],"de":["Sicherheit von KI-Agents","claw-release","Drift-Erkennung","Echtzeit-Sicherheitsempfehlungen","automatisierte Audits","Integritätsprüfung von Fähigkeiten","CLI für KI-Agents"],"pt":["claw-release","segurança de agentes de inteligência artificial","detecção de drift","auditorias automatizadas","recomendações de segurança em tempo real","verificação de integridade de habilidades","lançamento de habilidades com scripts personalizados","ferramentas de segurança para agentes de inteligência artificial"],"ru":["claw-release","безопасность ИИ Агентов","обнаружение дрифта","автоматизированные аудиты","рекомендации безопасности в реальном времени","проверка целостности навыков","выпуск навыков с помощью пользовательских скриптов","инструменты безопасности для ИИ Агентов"],"ar":["claw-release","أدوات أمنية لعمليات الإستخبارات الاصطناعية","كشف التغيرات","التفتيش الآلي","التوصيات الأمنية في الوقت الفعلي","التحقق من صحة المهارات","إصدار المهارات باستخدام البرامج النصية المخصصة","أدوات أمنية لعمليات الإستخبارات الاصطناعية"]}},"owner":"prompt-security","repo":"clawsec","repoPath":"prompt-security/clawsec","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.280Z","topics":[],"category":"community","skillMd":{"name":"claw-release","description":"Release automation for Claw skills and website. Guides through version bumping, tagging, and release verification.","version":"0.0.1","bodyPreview":"# Claw Release\n\nInternal tool for releasing skills and managing the ClawSec catalog.\n\n**An internal tool by [Prompt Security](https://prompt.security)**\n\n---\n\n## Quick Reference\n\n| Release Type | Command | Tag Format |\n|-------------|---------|------------|\n| Skill release | `./scripts/release-skill.sh <name> <version>` | `<name>-v<version>` |\n| Pre-release | `./scripts/release-skill.sh <name> 1.0.0-beta1` | `<name>-v1.0.0-beta1` |\n\n---\n\n## Release Workflow\n\n### Step 1: Determine Version Type\n\nA","body":"# Claw Release\n\nInternal tool for releasing skills and managing the ClawSec catalog.\n\n**An internal tool by [Prompt Security](https://prompt.security)**\n\n---\n\n## Quick Reference\n\n| Release Type | Command | Tag Format |\n|-------------|---------|------------|\n| Skill release | `./scripts/release-skill.sh <name> <version>` | `<name>-v<version>` |\n| Pre-release | `./scripts/release-skill.sh <name> 1.0.0-beta1` | `<name>-v1.0.0-beta1` |\n\n---\n\n## Release Workflow\n\n### Step 1: Determine Version Type\n\nAsk what changed:\n- **Bug fixes only** → Patch (1.0.0 → 1.0.1)\n- **New features, backward compatible** → Minor (1.0.0 → 1.1.0)\n- **Breaking changes** → Major (1.0.0 → 2.0.0)\n- **Testing/unstable** → Pre-release (1.0.0-beta1, 1.0.0-rc1)\n\n### Step 2: Pre-flight Checks\n\n```bash\n# Check for uncommitted changes\ngit status\n\n# Verify skill directory exists\nls skills/<skill-name>/skill.json\n\n# Get current version\njq -r ''.version'' skills/<skill-name>/skill.json\n```\n\n### Step 3: Run Release Script\n\n```bash\n./scripts/release-skill.sh <skill-name> <new-version>\n```\n\nThe script will:\n1. Validate version format (semver)\n2. Check tag doesn''t already exist\n3. Update skill.json version\n4. Update SKILL.md frontmatter version (if file exists)\n5. Update hardcoded version URLs (feed_url)\n6. Commit changes\n7. Create annotated git tag\n\n### Step 4: Push Release\n\n```bash\ngit push && git push origin <skill-name>-v<version>\n```\n\n### Step 5: Verify Release\n\nAfter pushing, the CI/CD pipeline will:\n1. Validate skill exists\n2. Verify version matches skill.json\n3. Verify version matches SKILL.md frontmatter (if exists)\n4. Generate checksums from SBOM\n5. Create .skill package (ZIP)\n6. Create GitHub Release\n7. Trigger website rebuild (for non-internal skills)\n\nVerify at:\n- **GitHub Releases:** `https://github.com/prompt-security/clawsec/releases/tag/<skill-name>-v<version>`\n- **GitHub Actions:** Check workflow run status\n\n---\n\n## Undo a Release (Before Push)\n\nIf you need to undo before pushing:\n\n```bash\ngit reset --hard HEAD~1 && git tag -d <skill-name>-v<version>\n```\n\n---\n\n## Pre-release Versions\n\nFor beta, alpha, or release candidates:\n\n```bash\n./scripts/release-skill.sh <skill-name> 1.2.0-beta1\n./scripts/release-skill.sh <skill-name> 1.2.0-alpha1\n./scripts/release-skill.sh <skill-name> 1.2.0-rc1\n```\n\nPre-releases are automatically marked in GitHub Releases.\n\n---\n\n## Common Issues\n\n| Error | Solution |\n|-------|----------|\n| `Tag already exists` | Choose a different version number |\n| `Version mismatch in CI` | Ensure you used the release script (not manual tagging) |\n| `SKILL.md version mismatch` | Ensure you used the release script which updates both skill.json and SKILL.md |\n| `Uncommitted changes` | Commit or stash first: `git stash` or `git add . && git commit` |\n| `skill.json not found` | Verify skill directory path is correct |\n\n---\n\n## Internal Skills\n\nSkills with `\"internal\": true` in their `openclaw` section:\n- Are released normally via GitHub Releases\n- Are NOT shown in the public skills catalog website\n- Can still be downloaded directly from release URLs\n\nThis skill (`claw-release`) is an internal skill.\n\n---\n\n## Existing Skills\n\n| Skill | Category | Internal |\n|-------|----------|----------|\n| clawsec-feed | security | No |\n| clawtributor | security | No |\n| openclaw-audit-watchdog | security | No |\n| soul-guardian | security | No |\n| claw-release | utility | Yes |\n\n---\n\n## Verification Checklist\n\nAfter release, confirm:\n- [ ] GitHub Release exists with correct tag\n- [ ] Release has: skill.json, SKILL.md, checksums.json, .skill package\n- [ ] Release is marked as pre-release if applicable\n- [ ] GitHub Actions workflow completed successfully\n- [ ] Website updated (for non-internal skills only)\n\n---\n\n## License\n\nGNU AGPL v3.0 or later - See repository for details.\n\nBuilt by the [Prompt Security](https://prompt.security) team.\n"},"lastSynced":"2026-03-08T02:00:49.004Z","agentAnalysis":{"suitability":{"en":"Perfect for Security Agents needing advanced SOUL.md file protection and drift detection capabilities.","zh":"非常适合需要高级SOUL.md文件保护和偏差检测功能的安全代理。","ja":"高度なSOUL.mdファイル保護とドリフト検出機能を必要とするセキュリティエージェントに最適です。","ko":"고급 SOUL.md 파일 보호 및 드리프트 감지 기능이 필요한 보안 에이전트에게 적합합니다.","es":"Perfecto para agentes de seguridad que necesitan protección avanzada de archivos SOUL.md y capacidades de detección de derivas.","fr":"Parfait pour les agents de sécurité ayant besoin d''une protection avancée des fichiers SOUL.md et de capacités de détection de dérive.","de":"Perfekt für Sicherheitsagenten, die eine erweiterte SOUL.md-Dateischutz und Drift-Erkennungsfunktionen benötigen.","pt":"Perfeito para Agentes de Segurança que precisam de proteção avançada de arquivos SOUL.md e capacidades de detecção de derivação.","ru":"Идеально для агентов безопасности, которым необходима расширенная защита файлов SOUL.md и возможности обнаружения дрейфа.","ar":"مثالي لعمليات وكيل الأمان التي تحتاج إلى حماية متقدمة لملفات SOUL.md وقدرات الكشف عن الانحراف."},"recommendation":{"en":"Empowers agents to protect SOUL.md files with features like drift detection and live security recommendations, utilizing the ClawSec catalog for comprehensive security management and release workflow automation through scripts like `./scripts/release-skill.sh`.","zh":"赋予代理保护SOUL.md文件的能力，具有偏差检测和实时安全建议等功能，利用ClawSec目录实现全面安全管理，并通过脚本如`./scripts/release-skill.sh`实现发布工作流自动化。","ja":"ドリフト検出やライブセキュリティ推奨などの機能でSOUL.mdファイルを保護するエージェントをEmpowerし、ClawSecカタログを使用して包括的なセキュリティ管理とスクリプトのような`./scripts/release-skill.sh`を使用したリリースワークフロー自動化を実現します。","ko":"에이전트가 드리프트 감지 및 실시간 보안 추천과 같은 기능으로 SOUL.md 파일을 보호할 수 있도록Empower하고, ClawSec 카탈로그를 사용하여 종합 보안 관리 및 스크립트와 같은 `./scripts/release-skill.sh`를 사용한 릴리스 워크플로 자동화를 구현합니다.","es":"Habilita a los agentes a proteger los archivos SOUL.md con características como la detección de derivas y recomendaciones de seguridad en vivo, utilizando el catálogo ClawSec para una gestión de seguridad integral y la automatización del flujo de trabajo de lanzamiento a través de scripts como `./scripts/release-skill.sh`.","fr":"Permet aux agents de protéger les fichiers SOUL.md avec des fonctionnalités comme la détection de dérive et des recommandations de sécurité en temps réel, en utilisant le catalogue ClawSec pour une gestion de sécurité complète et l''automatisation du workflow de publication via des scripts tels que `./scripts/release-skill.sh`.","de":"Ermächtigt Agenten, SOUL.md-Dateien mit Funktionen wie Drift-Erkennung und Live-Sicherheitsempfehlungen zu schützen, indem sie den ClawSec-Katalog für eine umfassende Sicherheitsverwaltung und die Automatisierung des Release-Workflows über Skripte wie `./scripts/release-skill.sh` nutzen.","pt":"Habilita os agentes a proteger arquivos SOUL.md com recursos como detecção de derivação e recomendações de segurança ao vivo, utilizando o catálogo ClawSec para gerenciamento de segurança abrangente e automação de fluxo de trabalho de lançamento por meio de scripts como `./scripts/release-skill.sh`.","ru":"Наделяет агентов возможностью защищать файлы SOUL.md с функциями, такими как обнаружение дрейфа и живые рекомендации по безопасности, используя каталог ClawSec для всестороннего управления безопасностью и автоматизации рабочего процесса выпуска через скрипты, такие как `./scripts/release-skill.sh`.","ar":"تمكّن الوكيل من حماية ملفات SOUL.md بميزات مثل الكشف عن الانحراف والتوصيات الأمنية الحية، باستخدام كتالوج ClawSec لإدارة الأمن الشاملة وتأتمة تدفق عمل الإصدار من خلال سكريبتات مثل `./scripts/release-skill.sh`."},"useCases":{"en":["Automating skill releases with version control","Detecting drift in SOUL.md files for enhanced security","Managing the ClawSec catalog for unified security protocols"],"zh":["使用版本控制自动化技能发布","检测SOUL.md文件中的偏差以增强安全性","管理ClawSec目录以实现统一的安全协议"],"ja":["バージョン管理を使用してスキルリリースを自動化する","SOUL.mdファイルのドリフトを検出してセキュリティを強化する","ClawSecカタログを管理して統一されたセキュリティプロトコルを実現する"],"ko":["버전 관리를 사용하여 스킬 릴리스를 자동화하는","SOUL.md 파일의 드리프트를 감지하여 보안을 강화하는","ClawSec 카탈로그를 관리하여 통일된 보안 프로토콜을 구현하는"],"es":["Automatización de lanzamientos de habilidades con control de versiones","Detección de derivas en archivos SOUL.md para una mayor seguridad","Administración del catálogo ClawSec para protocolos de seguridad unificados"],"fr":["Automatisation des publications de compétences avec contrôle de version","Détection de dérive dans les fichiers SOUL.md pour une sécurité renforcée","Gestion du catalogue ClawSec pour des protocoles de sécurité unifiés"],"de":["Automatisierung von Fähigkeitsveröffentlichungen mit Versionskontrolle","Erkennung von Drift in SOUL.md-Dateien für eine verbesserte Sicherheit","Verwaltung des ClawSec-Katalogs für einheitliche Sicherheitsprotokolle"],"pt":["Automatizar lançamentos de habilidades com controle de versão","Detectar derivação em arquivos SOUL.md para segurança aprimorada","Gerenciar o catálogo ClawSec para protocolos de segurança unificados"],"ru":["Автоматизировать выпуски навыков с помощью контроля версий","Обнаруживать дрейф в файлах SOUL.md для повышения безопасности","Управлять каталогом ClawSec для унифицированных протоколов безопасности"],"ar":["توفير إصدارات مهارات مع التحكم في الإصدار","الكشف عن الانحراف في ملفات SOUL.md لتعزيز الأمن","إدارة كتالوج ClawSec لبروتوكولات الأمن الموحدة"]},"limitations":{"en":["Requires access to OpenClaw''s family of agents","Designed for developers and security professionals only","Internal tool by Prompt Security"],"zh":["需要访问OpenClaw的代理家族","仅适用于开发人员和安全专业人员","Prompt Security的内部工具"],"ja":["OpenClawのエージェントファミリーにアクセスする必要がある","開発者とセキュリティ専門家のみが対象","Prompt Securityの内部ツール"],"ko":["OpenClaw의 에이전트 패밀리에 접근해야 함","개발자와 보안 전문가만을 대상으로 함","Prompt Security의 내부 도구"],"es":["Requiere acceso a la familia de agentes de OpenClaw","Diseñado solo para desarrolladores y profesionales de la seguridad","Herramienta interna de Prompt Security"],"fr":["Nécessite un accès à la famille d''agents OpenClaw","Conçu uniquement pour les développeurs et les professionnels de la sécurité","Outil interne de Prompt Security"],"de":["Benötigt Zugriff auf die Familie von OpenClaw-Agents","Nur für Entwickler und Sicherheitsexperten konzipiert","Interne Werkzeug von Prompt Security"],"pt":["Requer acesso à família de agentes da OpenClaw","Projetado apenas para desenvolvedores e profissionais de segurança","Ferramenta interna da Prompt Security"],"ru":["Требует доступа к семейству агентов OpenClaw","Разработан только для разработчиков и специалистов по безопасности","Внутренний инструмент компании Prompt Security"],"ar":["يتطلب الوصول إلى عائلة وكيل OpenClaw","صمّم فقط لمطوري الأمن والمهنيين","أداة داخلية لشركة Prompt Security"]},"version":4},"contentHash":"cda9f58b3be67876ba4a543d6192af60ea155c2102202340fdfc8770a848f07e","qualityScore":47}');
