INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('prompt-security/clawsec/claw-release', 'claw-release', 'prompt-security', 'clawsec', 'community', 'claw-release prompt-security clawsec community The claw-release skill provides a comprehensive security suite for OpenClaw''s family of agents, protecting SOUL.md files with features like drift detection and live security recommendations. This internal tool is designed for developers and security professionals. Claw Release是一套完整的安全技能套件，提供drift detection、live security recommendations、automated audits和skill integrity verification等功能 Claw Releaseは、Drift検出、ライブセキュリティ推奨、自動監査、スキル整合性検証などの機能を提供する完全なセキュリティスキル・スイートです Claw Release는 Drift 탐지, 실시간 보안 추천, 자동 감사 및 스킬 무결성 검증 등을 제공하는 완전한 보안 스킬套件입니다 Claw-release es una suite de seguridad para agentes de inteligencia artificial que ofrece detección de derivas, recomendaciones de seguridad en vivo y auditorías automatizadas Claw-release est une suite de sécurité pour les agents d''intelligence artificielle qui propose une détection de dérives, des recommandations de sécurité en temps réel et des audits automatisés Claw-release ist eine Sicherheitssuite für KI-Agents, die Drift-Erkennung, Echtzeit-Sicherheitsempfehlungen und automatisierte Audits bietet O claw-release é um conjunto de ferramentas de segurança para agentes de inteligência artificial, com recursos como detecção de drift e auditorias automatizadas. Ele protege seus arquivos SOUL.md com recomendações de segurança em tempo real claw-release - это набор инструментов безопасности для ИИ Агентов, с функциями zoals обнаружение дрифта и автоматизированные аудиты. Он защищает ваши файлы SOUL.md с рекомендациями безопасности в реальном времени claw-release هو مجموعة من أدوات الأمن لعمليات الإستخبارات الاصطناعية، مع ميزات مثل الكشف عن التغيرات والتفتيش الآلي. وهو يحمي ملفاتك SOUL.md مع التوصيات الأمنية في الوقت الفعلي how to use claw-release claw-release security suite claw-release alternative claw-release vs Prompt Security claw-release install guide claw-release setup for AI agents what is claw-release claw-release documentation claw-release tutorial Claw Release 安全技能套件 SOUL.md保护 Drift检测 Live安全推荐 自动审计 Skill整合性验证 CLI命令 预发布和发布版本 Drift detection for SOUL.md files Live security recommendations for enhanced protection Automated audits for skill integrity verification Supports release workflow via ./scripts/release-skill.sh command Tag format customization with <name>-v<version> syntax Pre-release support with beta versioning (e.g., 1.0.0-beta1) claw-release is an internal security tool for releasing skills and managing the ClawSec catalog, offering features like automated audits and skill integrity verification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flutter-it/get_it/flutter-architecture-expert', 'community', 'flutter-it', 'get_it', 'flutter-it/get_it', 'flutter-architecture-expert', 0, 0, 47, '2026-03-08T01:57:15.283Z', '2026-03-08T02:00:54.348Z', '71b05c718fd82432c40093d42f55a3edef1eb7609c6f5d9b036000f9aa519101', '{"id":"flutter-it/get_it/flutter-architecture-expert","name":"flutter-architecture-expert","description":{"en":"The flutter-architecture-expert skill provides architecture guidance for Flutter apps using the flutter_it construction set. It helps developers decouple interfaces from concrete implementations.","zh":"Flutter 架构专家提供 Get It 服务定位器，用于解耦接口和具体实现，优化应用程序结构和模式。使用 flutter_it 构造集（get_it + watch_it + command_it + listen_it）构建强大的 Flutter 应用程序","ja":"Flutter アーキテクチャ エキスパートは、Get It サービス ロケーターを提供してインターフェイスと具体的な実装を解結し、アプリケーションの構造とパターンを最適化します。flutter_it 構築セット（get_it + watch_it + command_it + listen_it）を使用して強力な Flutter アプリケーションを構築します","ko":"Flutter 아키텍처 전문가는 Get It 서비스 로케이터를 제공하여 인터페이스와 구체적인 구현을 분리하고 애플리케이션의 구조와 패턴을 최적화합니다. flutter_it 구축 세트（get_it + watch_it + command_it + listen_it）를 사용하여 강력한 Flutter 애플리케이션을 구축합니다","es":"flutter-architecture-expert es una guía de arquitectura para aplicaciones Flutter que utiliza el conjunto de construcción flutter_it, incluyendo get_it, watch_it, command_it y listen_it","fr":"flutter-architecture-expert est un guide d''architecture pour les applications Flutter qui utilise l''ensemble de construction flutter_it, y compris get_it, watch_it, command_it et listen_it","de":"flutter-architecture-expert ist ein Architekturleitfaden für Flutter-Anwendungen, der den flutter_it-Baukasten verwendet, einschließlich get_it, watch_it, command_it und listen_it","pt":"O flutter-architecture-expert é um conjunto de ferramentas para melhorar a estrutura e os padrões dos aplicativos Flutter, incluindo get_it, watch_it, command_