INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('flutter-it/get_it/flutter-architecture-expert', 'flutter-architecture-expert', 'flutter-it', 'get_it', 'community', 'flutter-architecture-expert flutter-it get_it community The flutter-architecture-expert skill provides architecture guidance for Flutter apps using the flutter_it construction set. It helps developers decouple interfaces from concrete implementations. Flutter 架构专家提供 Get It 服务定位器，用于解耦接口和具体实现，优化应用程序结构和模式。使用 flutter_it 构造集（get_it + watch_it + command_it + listen_it）构建强大的 Flutter 应用程序 Flutter アーキテクチャ エキスパートは、Get It サービス ロケーターを提供してインターフェイスと具体的な実装を解結し、アプリケーションの構造とパターンを最適化します。flutter_it 構築セット（get_it + watch_it + command_it + listen_it）を使用して強力な Flutter アプリケーションを構築します Flutter 아키텍처 전문가는 Get It 서비스 로케이터를 제공하여 인터페이스와 구체적인 구현을 분리하고 애플리케이션의 구조와 패턴을 최적화합니다. flutter_it 구축 세트（get_it + watch_it + command_it + listen_it）를 사용하여 강력한 Flutter 애플리케이션을 구축합니다 flutter-architecture-expert es una guía de arquitectura para aplicaciones Flutter que utiliza el conjunto de construcción flutter_it, incluyendo get_it, watch_it, command_it y listen_it flutter-architecture-expert est un guide d''architecture pour les applications Flutter qui utilise l''ensemble de construction flutter_it, y compris get_it, watch_it, command_it et listen_it flutter-architecture-expert ist ein Architekturleitfaden für Flutter-Anwendungen, der den flutter_it-Baukasten verwendet, einschließlich get_it, watch_it, command_it und listen_it O flutter-architecture-expert é um conjunto de ferramentas para melhorar a estrutura e os padrões dos aplicativos Flutter, incluindo get_it, watch_it, command_it e listen_it. ИИ Агент flutter-architecture-expert - это набор инструментов для улучшения структуры и шаблонов приложений Flutter, включающий get_it, watch_it, command_it и listen_it. خبير هندسة Flutter هو مجموعة من الأدوات لتحسين هيكل وتطبيقات Flutter، بما في ذلك get_it و watch_it و command_it و listen_it. how to use flutter-architecture-expert flutter-architecture-expert setup guide flutter-architecture-expert alternative flutter-architecture-expert vs get_it what is flutter-architecture-expert flutter-architecture-expert install flutter_it construction set tutorial decoupling interfaces in Flutter Simple Service Locator in Flutter Flutter 架构 Get It 服务定位器 依赖注入 服务定位 flutter_it Flutter 应用程序开发 AI エージェント 移动应用程序开发 Registers all services synchronously using configureDependencies() Supports async services with SplashScreen waiting for initialization Utilizes get_it, watch_it, command_it, and listen_it for app structure Enables access to concrete implementations from anywhere in the app Provides architecture guidance for efficient Flutter app development flutter-architecture-expert is a Simple Service Locator that enables decoupling of interfaces from concrete implementations in Flutter apps');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flutter-it/watch_it/feed-datasource-expert', 'community', 'flutter-it', 'watch_it', 'flutter-it/watch_it', 'feed-datasource-expert', 0, 0, 47, '2026-03-08T01:57:15.285Z', '2026-03-08T02:00:56.198Z', '0b015cfa3e991f1a2c2b3329e0778e6d449430ff13da9b7101b8b212112843e2', '{"id":"flutter-it/watch_it/feed-datasource-expert","name":"feed-datasource-expert","description":{"en":"The feed-datasource-expert skill enables developers to create paginated, reactive list/feed widgets using ValueNotifiers and Commands, integrating with proxy patterns for entity lifecycle management. This skill benefits developers building data-intensive applications.","zh":"feed-datasource-expert 是一种使用 ValueNotifiers 和 Commands 实现分页列表和无限滚动的技术，适用于需要高效数据加载的应用场景","ja":"feed-datasource-expertは、ValueNotifiersとCommandsを使用してページングリストと無限スクロールを実現するAIエージェントの技術です","ko":"feed-datasource-expert는 ValueNotifiers와 Commands를 사용하여 페이지네이션 리스트와 무한 스크롤을 구현하는 기술로, 효율적인 데이터 로딩이 필요한 애플리케이션에 적합합니다","es":"El patrón de lista paginada de feed-datasource-expert utiliza ValueNotifiers y Commands para gestionar listas reactivas.","fr":"Le modèle de liste paginée de feed-datasource-expert utilise ValueNotifiers et Commands pour gérer des listes réactives.","de":"Das Muster für paginierte Listen von feed-datasource-expert verwendet ValueNotifiers und Commands für die Verwaltung reaktiver Listen.","pt":"O Feed DataSource Expert é um padrão para listas paginadas e infinitas que integra ValueNotifiers e Commands","ru":"ИИ Агент Feed DataSource Expert - это шаблон для пагинированных и реактивных списков, интегрирующий ValueNotifiers и Commands","ar":"مصدر البيانات التلقائي للمحتوى المتجدد هو نمط لتقديم قائمة متجدة ومتجددة باستخدام ValueNotifiers و Commands"},"seo":{"title":{"en":"feed-datasource-expert: Paged Lists & Infinite Scroll Set...","zh":"feed-datasource-expert 设置指南 - 基于 ValueNotifiers 和 Command...","ja":"feed-datasource-expert 導入ガイド - AIエージェントによるValueNotifiersと...","ko":"feed-datasource-expert 설정 가이드 - ValueNotifiers와 Commands를...","es":"Guía de configuración de feed-datasource-expert para list...","fr":"Guide de mise en place de feed-datasource-expert pour lis...","de":"Einrichtungsleitfaden für feed-datasource-expert mit pagi...","pt":"Guia de Configuração do Feed DataSource Expert para Lista...","ru":"Настройка ИИ Агента Feed DataSource Expert для бесконечно...","ar":"دليل إعداد مصدر البيانات التلقائي للمحتوى المتجدد"},"description":{"en":"Unlock efficient data handling with feed-datasource-expert. Learn how to implement auto-pagination, ValueNotifiers, and Commands for seamless list/feed widge...","zh":"了解 feed-datasource-expert 技术，实现基于 ValueNotifiers 和 Commands 的分页列表和无限滚动，提升开发效率","ja":"AIエージェントのfeed-datasource-expertを使用して、ValueNotifiersとCommandsを使用したページングリストと無限スクロールを実現する方法を紹介します","ko":"feed-datasource-expert 기술을 활용하여 ValueNotifiers와 Commands를 사용한 페이지네이션 리스트와 무한 스크롤을 구현하는 방법을 알아보세요","es":"Aprende a implementar el patrón de lista paginada con ValueNotifiers y Commands en feed-datasource-expert, Herramientas de Inteligencia Artificial","fr":"Découvrez comment mettre en œuvre le modèle de liste paginée avec ValueNotifiers et Commands dans feed-datasource-expert, Outils d''Intelligence Artificielle","de":"Erfahren Sie, wie Sie das Muster für paginierte Listen mit ValueNotifiers und Commands in feed-datasource-expert, KI-Tools, umsetzen","pt":"Aprenda a configurar o Feed DataSource Expert para criar listas paginadas e infinitas com ValueNotifiers e Commands","ru":"Узнайте, как настроить ИИ Агент Feed DataSource Expert для создания реактивных списков и бесконечной прокрутки","ar":"تعلم كيفية إعداد مصدر البيانات التلقائي للمحتوى المتجدد باستخدام ValueNotifiers و Commands"},"definition":{"en":"feed-datasource-expert is a pattern for paginated, reactive list/feed widgets using ValueNotifiers and Commands, designed for efficient data handling and entity lifecycle management.","zh":"feed-datasource-expert 是一种技术，使用 ValueNotifiers 和 Commands 实现分页列表和无限滚动","ja":"feed-datasource-expertは、ValueNotifiersとCommandsを使用してページングリストと無限スクロールを実現するAIエージェントの技術です","ko":"feed-datasource-expert는 ValueNotifiers와 Commands를 사용하여 페이지네이션 리스트와 무한 스크롤을 구현하는 기술입니다","es":"feed-datasource-expert es un patrón para listas paginadas que utiliza ValueNotifiers y Commands.","fr":"feed-datasource-expert est un modèle pour listes paginées qui utilise ValueNotifiers et Commands.","de":"feed-datasource-expert ist ein Muster für paginierte Listen, das ValueNotifiers und Commands verwendet.","pt":"O que é Feed DataSource Expert? É um padrão para listas paginadas e infinitas","ru":"Что такое ИИ Агент Feed DataSource Expert? Это шаблон для пагинированных и реактивных списков","ar":"ما هو مصدر البيانات التلقائي للمحتوى المتجدد? هو نمط لتقديم قائمة متجدة ومتجددة"},"features":{"en":["Auto-pagination triggers at items.length - 3 for efficient data loading","Utilizes updateDataCommand for initial and refresh loads","Employs requestNextPageCommand for pagination with separate commands","Integrates with proxy pattern for entity lifecycle management","Supports release of old proxies after replacing with new ones for refreshing data"],"zh":["基于 ValueNotifiers 和 Commands 的分页列表","支持无限滚动","自动分页触发","使用 updateDataCommand 和 requestNextPageCommand","与代理模式集成"],"ja":["ValueNotifiersとCommandsを使用したページングリスト","無限スクロールのサポート","自動ページングのトリガー","updateDataCommandとrequestNextPageCommandの使用","代理モードとの統合"],"ko":["ValueNotifiers와 Commands를 사용한 페이지네이션 리스트","무한 스크롤 지원","자동 페이지네이션 트리거","updateDataCommand와 requestNextPageCommand 사용","프록시 모드와의 통합"],"es":["Patrón de lista paginada con ValueNotifiers","Uso de Commands para gestionar la carga de datos","Integración con el patrón de proxy para la gestión del ciclo de vida de entidades","Desencadenamiento de la paginación automática en items.length - 3","Uso de updateDataCommand para cargas iniciales y de refresco","Uso de requestNextPageCommand para la paginación"],"fr":["Modèle de liste paginée avec ValueNotifiers","Utilisation de Commands pour gérer le chargement de données","Intégration avec le modèle de proxy pour la gestion du cycle de vie des entités","Déclenchement de la pagination automatique à items.length - 3","Utilisation de updateDataCommand pour les chargements initiaux et de rafraîchissement","Utilisation de requestNextPageCommand pour la pagination"],"de":["Muster für paginierte Listen mit ValueNotifiers","Verwendung von Commands zur Verwaltung der Datenladung","Integration mit dem Proxy-Muster für die Verwaltung des Entitätslebenszyklus","Auslösen der automatischen Paginierung bei items.length - 3","Verwendung von updateDataCommand für die anfängliche und die Aktualisierungsladung","Verwendung von requestNextPageCommand für die Paginierung"],"pt":["Integração com ValueNotifiers e Commands","Paginação automática em `items.length - 3`","Comandos separados para carregamento inicial e refresh","Gerenciamento de ciclo de vida de entidades com proxy pattern"],"ru":["Интеграция с ValueNotifiers и Commands","Автоматическая пагинация при `items.length - 3`","Отдельные команды для初ального и обновленного загрузки","Управление циклом жизни сущностей с помощью шаблона proxy"],"ar":["دمج ValueNotifiers و Commands","تنقّل صفحات تلقائي عند `items.length - 3`","أوامر منفصلة للتحميل الأولي والتجديد","إدارة دورة حياة الكيانات باستخدام نمط Proxy"]},"keywords":{"en":["how to use feed-datasource-expert","feed-datasource-expert alternative","feed-datasource-expert setup guide","what is feed-datasource-expert","feed-datasource-expert vs other data handling solutions","feed-datasource-expert install and configuration"],"zh":["feed-datasource-expert","ValueNotifiers","Commands","分页列表","无限滚动","自动分页","updateDataCommand","requestNextPageCommand","代理模式"],"ja":["feed-datasource-expert","AIエージェント","ValueNotifiers","Commands","ページングリスト","無限スクロール","自動ページング","updateDataCommand","requestNextPageCommand","代理モード"],"ko":["feed-datasource-expert","ValueNotifiers","Commands","페이지네이션 리스트","무한 스크롤","자동 페이지네이션","updateDataCommand","requestNextPageCommand","프록시 모드"],"es":["feed-datasource-expert","listas paginadas","ValueNotifiers","Commands","patrón de proxy","gestión del ciclo de vida de entidades","Herramientas de Inteligencia Artificial","desarrollo de software","patrones de diseño"],"fr":["feed-datasource-expert","listes paginées","ValueNotifiers","Commands","modèle de proxy","gestion du cycle de vie des entités","Outils d''Intelligence Artificielle","développement de logiciels","modèles de conception"],"de":["feed-datasource-expert","paginierte Listen","ValueNotifiers","Commands","Proxy-Muster","Verwaltung des Entitätslebenszyklus","KI-Tools","Software-Entwicklung","Entwurfsmuster"],"pt":["Feed DataSource Expert","listas paginadas","infinite scroll","ValueNotifiers","Commands","padrão de projeto","desenvolvimento de software","React","programação"],"ru":["ИИ Агент Feed DataSource Expert","пагинированные списки","бесконечная прокрутка","ValueNotifiers","Commands","шаблон проектирования","разработка программного обеспечения","React","программирование"],"ar":["مصدر البيانات التلقائي للمحتوى المتجدد","قوائم متجدة","التجديدة اللانهائية","ValueNotifiers","Commands","نمط التصميم","تطوير البرمجيات","React","البرمجة"]}},"owner":"flutter-it","repo":"watch_it","repoPath":"flutter-it/watch_it","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.285Z","topics":[],"category":"community","skillMd":{"name":"feed-datasource-expert","description":"Expert guidance on implementing paginated feeds and infinite scroll in Flutter using FeedDataSource and PagedFeedDataSource patterns. Covers base feed data source, cursor-based pagination, auto-pagination at length-3, proxy lifecycle with reference counting, feed widget implementation, filtered feeds, event bus integration, and creation with createOnce. Use when building paginated lists, infinite scroll, feed views, or managing proxy lifecycle in feeds.","version":"1.0","bodyPreview":"# Feed DataSource Expert - Paged Lists & Infinite Scroll\n\n**What**: Pattern for paginated, reactive list/feed widgets using ValueNotifiers and Commands. Integrates with proxy pattern for entity lifecycle management.\n\n## CRITICAL RULES\n\n- Auto-pagination triggers at `items.length - 3` (not at the last item)\n- `updateDataCommand` for initial/refresh loads, `requestNextPageCommand` for pagination - separate commands\n- When refreshing with proxies: release OLD proxies AFTER replacing with new ones (","body":"# Feed DataSource Expert - Paged Lists & Infinite Scroll\n\n**What**: Pattern for paginated, reactive list/feed widgets using ValueNotifiers and Commands. Integrates with proxy pattern for entity lifecycle management.\n\n## CRITICAL RULES\n\n- Auto-pagination triggers at `items.length - 3` (not at the last item)\n- `updateDataCommand` for initial/refresh loads, `requestNextPageCommand` for pagination - separate commands\n- When refreshing with proxies: release OLD proxies AFTER replacing with new ones (delay release for animations)\n- `itemCount` is a ValueNotifier - watch it to rebuild the list widget\n- Feed data sources are typically created with `createOnce` in widgets, NOT registered in get_it\n- `getItemAtIndex(index)` both returns the item AND triggers auto-pagination\n\n## Base FeedDataSource\n\nNon-paged feed for finite data sets:\n\n```dart\nabstract class FeedDataSource<TItem> {\n  FeedDataSource({List<TItem>? initialItems})\n      : items = initialItems ?? [];\n\n  final List<TItem> items;\n  final _itemCount = CustomValueNotifier<int>(0);\n  ValueListenable<int> get itemCount => _itemCount;\n  bool updateWasCalled = false;\n\n  late final updateDataCommand = Command.createAsyncNoParamNoResult(\n    () async {\n      await updateFeedData();\n      updateWasCalled = true;\n      refreshItemCount();\n    },\n    errorFilter: const LocalOnlyErrorFilter(),\n  );\n\n  ValueListenable<bool> get isFetchingNextPage => updateDataCommand.isRunning;\n  ValueListenable<CommandError?> get commandErrors => updateDataCommand.errors;\n\n  /// Subclasses implement - fetch data and populate items list\n  Future<void> updateFeedData();\n\n  /// Subclasses implement - compare items for deduplication\n  bool itemsAreEqual(TItem item1, TItem item2);\n\n  TItem getItemAtIndex(int index) {\n    assert(index >= 0 && index < items.length);\n    return items[index];\n  }\n\n  void refreshItemCount() {\n    _itemCount.value = items.length;\n  }\n\n  void addItemAtStart(TItem item) {\n    items.insert(0, item);\n    refreshItemCount();\n  }\n\n  void removeObject(TItem itemToRemove) {\n    items.removeWhere((item) => itemsAreEqual(item, itemToRemove));\n    refreshItemCount();\n  }\n\n  void reset() {\n    items.clear();\n    updateWasCalled = false;\n    refreshItemCount();\n  }\n\n  void dispose() {\n    _itemCount.dispose();\n  }\n}\n```\n\n## PagedFeedDataSource\n\nExtends FeedDataSource with cursor-based pagination:\n\n```dart\nabstract class PagedFeedDataSource<TItem> extends FeedDataSource<TItem> {\n  String? nextPageUrl;\n  bool? datasetExpired;\n\n  bool get hasNextPage => nextPageUrl != null && datasetExpired != true;\n\n  late final requestNextPageCommand = Command.createAsyncNoParamNoResult(\n    () async {\n      await requestNextPage();\n      refreshItemCount();\n    },\n    errorFilter: const LocalOnlyErrorFilter(),\n  );\n\n  /// Subclasses implement - fetch next page and append to items\n  Future<void> requestNextPage();\n\n  /// Call after parsing API response to store next page URL\n  void extractNextPageParams(String? url) {\n    nextPageUrl = url;\n  }\n\n  /// Auto-pagination: triggers when scrolling near the end\n  @override\n  TItem getItemAtIndex(int index) {\n    if (index >= items.length - 3 &&\n        commandErrors.value == null &&\n        hasNextPage &&\n        !requestNextPageCommand.isRunning.value) {\n      requestNextPageCommand.run();\n    }\n    return super.getItemAtIndex(index);\n  }\n\n  // Merged loading/error state from both commands\n  late final ValueNotifier<bool> _isFetchingNextPage = ValueNotifier(false);\n  @override\n  ValueListenable<bool> get isFetchingNextPage => _isFetchingNextPage;\n\n  // Listen to both commands and merge their isRunning states\n  // _isFetchingNextPage.value = updateDataCommand.isRunning.value ||\n  //                              requestNextPageCommand.isRunning.value;\n\n  @override\n  void reset() {\n    nextPageUrl = null;\n    datasetExpired = null;\n    super.reset();\n  }\n}\n```\n\n## Concrete Implementation with Proxies\n\n```dart\nclass PostsFeedSource extends PagedFeedDataSource<PostProxy> {\n  PostsFeedSource(this.feedType);\n  final PostFeedType feedType;\n\n  @override\n  bool itemsAreEqual(PostProxy a, PostProxy b) => a.id == b.id;\n\n  @override\n  Future<void> updateFeedData() async {\n    final api = PostApi(di<ApiClient>());\n    final response = await api.getPosts(type: feedType);\n    if (response == null) return;\n\n    // Release old proxies (delay for exit animations)\n    final oldItems = List<PostProxy>.from(items);\n    items.clear();\n\n    // Create new proxies via manager (increments ref count)\n    final proxies = di<PostsManager>().createProxies(response.data);\n    items.addAll(proxies);\n    extractNextPageParams(response.links?.next);\n\n    // Release old proxies after animations complete\n    Future.delayed(const Duration(milliseconds: 1000), () {\n      di<PostsManager>().releaseProxies(oldItems);\n    });\n  }\n\n  @override\n  Future<void> requestNextPage() async {\n    if (nextPageUrl == null) return;\n    final response = await callNextPageWithUrl<PostListResponse>(nextPageUrl!);\n    if (response == null) return;\n\n    final proxies = di<PostsManager>().createProxies(response.data);\n    items.addAll(proxies);\n    extractNextPageParams(response.links?.next);\n  }\n\n  // Override to manage reference counting on individual operations\n  @override\n  void addItemAtStart(PostProxy item) {\n    item.incrementReferenceCount();\n    super.addItemAtStart(item);\n  }\n\n  @override\n  void removeObject(PostProxy item) {\n    super.removeObject(item);\n    di<PostsManager>().releaseProxy(item);\n  }\n}\n```\n\n## Feed Widget\n\n```dart\nclass FeedView<TItem> extends WatchingWidget {\n  const FeedView({\n    required this.feedSource,\n    required this.itemBuilder,\n    this.emptyListWidget,\n  });\n\n  final FeedDataSource<TItem> feedSource;\n  final Widget Function(BuildContext, TItem) itemBuilder;\n  final Widget? emptyListWidget;\n\n  @override\n  Widget build(BuildContext context) {\n    final itemCount = watch(feedSource.itemCount).value;\n    final isFetching = watch(feedSource.isFetchingNextPage).value;\n\n    // Trigger initial load\n    callOnce((_) => feedSource.updateDataCommand.run());\n\n    // Error handler\n    registerHandler(\n      target: feedSource.commandErrors,\n      handler: (context, error, _) {\n        showErrorSnackbar(context, error.error);\n      },\n    );\n\n    // Error state with retry\n    if (feedSource.commandErrors.value != null && itemCount == 0) {\n      return ErrorWidget(\n        onRetry: () => feedSource.updateDataCommand.run(),\n      );\n    }\n\n    // Initial loading\n    if (!feedSource.updateWasCalled && isFetching) {\n      return Center(child: CircularProgressIndicator());\n    }\n\n    // Empty state\n    if (itemCount == 0 && feedSource.updateWasCalled) {\n      return emptyListWidget ?? Text(''No items'');\n    }\n\n    // List with pull-to-refresh\n    return RefreshIndicator(\n      onRefresh: () => feedSource.updateDataCommand.runAsync(),\n      child: ListView.builder(\n        itemCount: itemCount + (isFetching ? 1 : 0),\n        itemBuilder: (context, index) {\n          if (index >= itemCount) {\n            return Center(child: CircularProgressIndicator());\n          }\n          // getItemAtIndex auto-triggers pagination near end\n          final item = feedSource.getItemAtIndex(index);\n          return itemBuilder(context, item);\n        },\n      ),\n    );\n  }\n}\n```\n\n## Creation Pattern\n\n```dart\n// Create with createOnce in the widget that owns the feed\nclass PostsFeedPage extends WatchingWidget {\n  @override\n  Widget build(BuildContext context) {\n    final feedSource = createOnce(\n      () => PostsFeedSource(PostFeedType.latest),\n      dispose: (source) => source.dispose(),\n    );\n\n    return FeedView<PostProxy>(\n      feedSource: feedSource,\n      itemBuilder: (context, post) => PostCard(post: post),\n      emptyListWidget: Text(''No posts yet''),\n    );\n  }\n}\n```\n\n## Filtered Feeds\n\nSame data, different views via filter functions:\n\n```dart\nclass ChatsListSource extends PagedFeedDataSource<ChatProxy> {\n  ChatFilterType _filter = ChatFilterType.ALL;\n  String _query = '''';\n\n  void setTypeFilter(ChatFilterType filter) {\n    _filter = filter;\n    updateDataCommand.run();  // Re-fetch with new filter\n  }\n\n  void setSearchQuery(String query) {\n    _query = query;\n    updateDataCommand.run();\n  }\n}\n```\n\n## Event Bus Integration\n\nFeeds can react to events from other parts of the app:\n\n```dart\n// In FeedDataSource constructor\ndi<EventBus>().on<FeedEvent>().listen((event) {\n  if (event.feedsToApply.contains(feedId)) {\n    switch (event.action) {\n      case FeedEventActions.update:\n        updateDataCommand.run();\n      case FeedEventActions.addItem:\n        addItemAtStart(event.data as TItem);\n      case FeedEventActions.removeItem:\n        removeObject(event.data as TItem);\n    }\n  }\n});\n\n// Trigger from anywhere in the app\ndi<EventBus>().fire(FeedEvent(\n  action: FeedEventActions.addItem,\n  data: newPostProxy,\n  feedsToApply: [FeedIds.latestPostsFeed, FeedIds.followingPostsFeed],\n));\n```\n\n## Anti-Patterns\n\n```dart\n// ❌ Releasing proxies immediately on refresh (breaks exit animations)\nitems.clear();\ndi<Manager>().releaseProxies(oldItems);  // Widgets still animating!\nitems.addAll(newProxies);\n\n// ✅ Delay release for animations\nfinal oldItems = List.from(items);\nitems.clear();\nitems.addAll(newProxies);\nFuture.delayed(Duration(milliseconds: 1000), () {\n  di<Manager>().releaseProxies(oldItems);\n});\n\n// ❌ Registering feed in get_it as singleton\ndi.registerSingleton<PostsFeed>(PostsFeedSource());\n// ✅ Create with createOnce in the widget that owns it\nfinal feed = createOnce(() => PostsFeedSource());\n\n// ❌ Manually checking scroll position for pagination\nscrollController.addListener(() {\n  if (scrollController.position.pixels >= ...) loadMore();\n});\n// ✅ Auto-pagination via getItemAtIndex triggers at length - 3\n\n// ❌ Single command for both initial load and pagination\n// ✅ Separate commands: updateDataCommand + requestNextPageCommand\n//    Allows independent loading/error states and restrictions\n```\n"},"lastSynced":"2026-03-08T02:00:56.198Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced paginated list/feed widget capabilities with ValueNotifiers and Commands.","zh":"非常适合需要高级分页列表/信息流小部件功能的前端代理，包括ValueNotifiers和Commands。","ja":"フロントエンドエージェントが高度なページングリスト/フィードウィジェットの機能を必要とする場合に最適です。ValueNotifiersとCommandsが含まれます。","ko":"고급 페이징 목록/피드 위젯 기능이 필요한 프론트엔드 에이전트에 적합합니다. ValueNotifiers 및 Commands가 포함됩니다.","es":"Perfecto para agentes Frontend que necesitan capacidades avanzadas de widget de lista/pagina con ValueNotifiers y Commands.","fr":"Parfait pour les agents Frontend ayant besoin de capacités avancées de widget de liste/flux paginé avec ValueNotifiers et Commands.","de":"Perfekt für Frontend-Agents, die erweiterte Paginierungs-Liste/Feed-Widget-Funktionen mit ValueNotifiers und Commands benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de widget de lista/página paginada com ValueNotifiers e Commands.","ru":"Идеально для агентов Frontend, которым необходимы продвинутые возможности виджета списка/ленты с постраничной навигацией и ValueNotifiers и Commands.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى إمكانيات متقدمة لwidget قائمة/تغذية مع ValueNotifiers و Commands."},"recommendation":{"en":"Empowers agents to create reactive, data-intensive applications with seamless pagination and entity lifecycle management using proxy patterns, ValueNotifiers, and separate commands like updateDataCommand and requestNextPageCommand.","zh":"赋予代理创建具有无缝分页和实体生命周期管理的反应式、数据密集型应用程序的能力，使用代理模式、ValueNotifiers和单独的命令，如updateDataCommand和requestNextPageCommand。","ja":"エージェントがreative、データ集中型アプリケーションを作成できるようにします。シームレスなページングとエンティティライフサイクル管理を使用して、プロキシパターン、ValueNotifiers、およびupdateDataCommandとrequestNextPageCommandなどの独立したコマンド。","ko":"에이전트가 반응형, 데이터 집중형 애플리케이션을 생성할 수 있도록 합니다. 시ーム리스 페이징 및 엔티티 수명 주기 관리를 사용하여 프록시 패턴, ValueNotifiers 및 updateDataCommand 및 requestNextPageCommand와 같은 별도의 명령어를 사용합니다.","es":"Habilita a los agentes a crear aplicaciones reactivas e intensivas en datos con paginación fluida y gestión del ciclo de vida de entidades utilizando patrones de proxy, ValueNotifiers y comandos separados como updateDataCommand y requestNextPageCommand.","fr":"Permet aux agents de créer des applications réactives et intensives en données avec une pagination fluide et une gestion du cycle de vie des entités en utilisant des modèles de proxy, ValueNotifiers et des commandes séparées comme updateDataCommand et requestNextPageCommand.","de":"Ermöglicht es Agenten, reaktive, datenintensive Anwendungen mit nahtloser Paginierung und Entitätslebenszyklusverwaltung zu erstellen, indem Proxy-Muster, ValueNotifiers und separate Befehle wie updateDataCommand und requestNextPageCommand verwendet werden.","pt":"Habilita os agentes a criarem aplicações reativas, intensivas em dados, com paginação contínua e gerenciamento de ciclo de vida de entidades usando padrões de proxy, ValueNotifiers e comandos separados como updateDataCommand e requestNextPageCommand.","ru":"Наделяет агентов возможностью создавать реактивные, интенсивные приложения с бесшовной постраничной навигацией и управлением жизненным циклом сущностей с помощью шаблонов прокси, ValueNotifiers и отдельных команд, таких как updateDataCommand и requestNextPageCommand.","ar":"يمنح العميل القدرة على إنشاء تطبيقات تفاعلية وكثيفة البيانات مع التصفح الصفحي المستمر وإدارة دورة حياة الكيان باستخدام أنماط وكيل، ValueNotifiers والأوامر المنفصلة مثل updateDataCommand و requestNextPageCommand."},"useCases":{"en":["Implementing infinite scroll for dynamic content feeds","Building paginated lists with auto-pagination triggers","Managing entity lifecycles with proxy patterns for data-intensive applications"],"zh":["为动态内容信息流实现无限滚动","使用自动分页触发器构建分页列表","使用代理模式管理数据集约应用程序的实体生命周期"],"ja":["動的コンテンツフィードの無限スクロールを実装する","自動ページングトリガーを使用してページングリストを構築する","データ集中型アプリケーションのエンティティライフサイクルをプロキシパターンで管理する"],"ko":["동적 컨텐츠 피드에 대한 무한 스크롤 구현","자동 페이징 트리거를 사용하여 페이징 목록을 구축","데이터 집중형 애플리케이션의 엔티티 수명 주기 관리를 프록시 패턴으로 수행"],"es":["Implementar desplazamiento infinito para feeds de contenido dinámico","Crear listas paginadas con disparadores de autopaginación","Gestionar ciclos de vida de entidades con patrones de proxy para aplicaciones intensivas en datos"],"fr":["Mettre en œuvre un défilement infini pour les flux de contenu dynamique","Construire des listes paginées avec des déclencheurs d''autopagination","Gérer les cycles de vie des entités avec des modèles de proxy pour des applications intensives en données"],"de":["Implementierung von unendlichem Scrollen für dynamische Inhalts-Feeds","Erstellen von paginierten Listen mit Auto-Paginierungs-Trigger","Verwaltung von Entitäts-Lebenszyklen mit Proxy-Mustern für datenintensive Anwendungen"],"pt":["Implementar rolagem infinita para feeds de conteúdo dinâmico","Construir listas paginadas com gatilhos de auto-paginação","Gerenciar ciclos de vida de entidades com padrões de proxy para aplicações intensivas em dados"],"ru":["Реализация бесконечной прокрутки для динамических лент","Создание постраничных списков с автоматическими триггерами страниц","Управление жизненным циклом сущностей с помощью шаблонов прокси для интенсивных приложений"],"ar":["تنفيذ التمرير اللانهائي للبيانات الديناميكية","بناء القوائم الصفحية مع الزنادات التلقائية للصفحات","إدارة دورة حياة الكيان باستخدام أنماط الوكيل لتطبيقات كثيفة البيانات"]},"limitations":{"en":["Requires integration with ValueNotifiers and Commands","Auto-pagination triggers at items.length - 3, not at the last item","Proxies must be released after replacing with new ones during refresh"],"zh":["需要与ValueNotifiers和Commands集成","自动分页触发器在items.length - 3处触发，而不是在最后一项","刷新期间用新代理替换后，必须释放代理"],"ja":["ValueNotifiersとCommandsとの統合が必要","自動ページングトリガーはitems.length - 3でトリガーされ、最後のアイテムではトリガーされない","リフレッシュ中に新しいプロキシに置き換えられた後、プロキシを解放する必要がある"],"ko":["ValueNotifiers 및 Commands와의 통합이 필요합니다.","자동 페이징 트리거는 items.length - 3에서 트리거되며, 마지막 항목에서는 트리거되지 않습니다.","새로운 프록시로 대체된 후에는 프록시를 해제해야 합니다."],"es":["Requiere integración con ValueNotifiers y Commands","Los disparadores de autopaginación se activan en items.length - 3, no en el último elemento","Los proxies deben ser liberados después de reemplazarlos con nuevos durante la actualización"],"fr":["Nécessite une intégration avec ValueNotifiers et Commands","Les déclencheurs d''autopagination se déclenchent à items.length - 3, et non à la dernière élément","Les proxies doivent être libérés après les remplacer par de nouveaux lors de la mise à jour"],"de":["Erfordert Integration mit ValueNotifiers und Commands","Auto-Paginierungs-Trigger werden bei items.length - 3 ausgelöst, nicht beim letzten Element","Proxys müssen nach dem Ersetzen durch neue während der Aktualisierung freigegeben werden"],"pt":["Requer integração com ValueNotifiers e Commands","Gatilhos de auto-paginação em items.length - 3, não no último item","Os proxies devem ser liberados após serem substituídos por novos durante a atualização"],"ru":["Требует интеграции с ValueNotifiers и Commands","Автоматические триггеры страницы срабатывают при items.length - 3, а не на последнем элементе","Прокси должны быть освобождены после замены на новые во время обновления"],"ar":["يتطلب التكامل مع ValueNotifiers و Commands","الزنادات التلقائية للصفحات في items.length - 3، وليس في العنصر الأخير","يجب إصدار الوكيل بعد استبداله بوكيل جديد أثناء التحديث"]},"version":4},"contentHash":"0b015cfa3e991f1a2c2b3329e0778e6d449430ff13da9b7101b8b212112843e2","qualityScore":47}');
