INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('flutter-it/watch_it/feed-datasource-expert', 'feed-datasource-expert', 'flutter-it', 'watch_it', 'community', 'feed-datasource-expert flutter-it watch_it community The feed-datasource-expert skill enables developers to create paginated, reactive list/feed widgets using ValueNotifiers and Commands, integrating with proxy patterns for entity lifecycle management. This skill benefits developers building data-intensive applications. feed-datasource-expert 是一种使用 ValueNotifiers 和 Commands 实现分页列表和无限滚动的技术，适用于需要高效数据加载的应用场景 feed-datasource-expertは、ValueNotifiersとCommandsを使用してページングリストと無限スクロールを実現するAIエージェントの技術です feed-datasource-expert는 ValueNotifiers와 Commands를 사용하여 페이지네이션 리스트와 무한 스크롤을 구현하는 기술로, 효율적인 데이터 로딩이 필요한 애플리케이션에 적합합니다 El patrón de lista paginada de feed-datasource-expert utiliza ValueNotifiers y Commands para gestionar listas reactivas. Le modèle de liste paginée de feed-datasource-expert utilise ValueNotifiers et Commands pour gérer des listes réactives. Das Muster für paginierte Listen von feed-datasource-expert verwendet ValueNotifiers und Commands für die Verwaltung reaktiver Listen. O Feed DataSource Expert é um padrão para listas paginadas e infinitas que integra ValueNotifiers e Commands ИИ Агент Feed DataSource Expert - это шаблон для пагинированных и реактивных списков, интегрирующий ValueNotifiers и Commands مصدر البيانات التلقائي للمحتوى المتجدد هو نمط لتقديم قائمة متجدة ومتجددة باستخدام ValueNotifiers و Commands how to use feed-datasource-expert feed-datasource-expert alternative feed-datasource-expert setup guide what is feed-datasource-expert feed-datasource-expert vs other data handling solutions feed-datasource-expert install and configuration feed-datasource-expert ValueNotifiers Commands 分页列表 无限滚动 自动分页 updateDataCommand requestNextPageCommand 代理模式 Auto-pagination triggers at items.length - 3 for efficient data loading Utilizes updateDataCommand for initial and refresh loads Employs requestNextPageCommand for pagination with separate commands Integrates with proxy pattern for entity lifecycle management Supports release of old proxies after replacing with new ones for refreshing data feed-datasource-expert is a pattern for paginated, reactive list/feed widgets using ValueNotifiers and Commands, designed for efficient data handling and entity lifecycle management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alex-ilgayev/MCPSpy/github-issue-creator', 'community', 'alex-ilgayev', 'MCPSpy', 'alex-ilgayev/MCPSpy', 'github-issue-creator', 0, 0, 47, '2026-03-08T01:57:15.295Z', '2026-03-08T02:01:11.775Z', '3719971b7e2f0da37d3fecb022fcffcb6994a0fbb907183ada0ce57724a286b8', '{"id":"alex-ilgayev/MCPSpy/github-issue-creator","name":"github-issue-creator","description":{"en":"The github-issue-creator skill automates the creation of well-structured GitHub issues for the MCPSpy project, benefiting developers and project managers. It utilizes the gh issue CLI tool for efficient issue creation.","zh":"GitHub Issue Creator Skill 自动创建结构化的 GitHub 问题，支持 MCP 监控和 eBPF 技术","ja":"GitHub Issue Creator スキルは、MCP モニタリングと eBPF 技術を使用して構造化された GitHub の問題を作成します","ko":"GitHub Issue Creator 스킬은 MCP 모니터링 및 eBPF 기술을 사용하여 구조화된 GitHub 문제를 자동 생성합니다","es":"El skill github-issue-creator automatiza la creación de problemas de GitHub estructurados para el proyecto MCPSpy, utilizando herramientas como gh issue CLI","fr":"Le skill github-issue-creator automatise la création de problèmes GitHub structurés pour le projet MCPSpy, en utilisant des outils tels que gh issue CLI","de":"Der Skill github-issue-creator automatisiert die Erstellung strukturierter GitHub-Probleme für das Projekt MCPSpy, unter Verwendung von Tools wie gh issue CLI","pt":"O github-issue-creator é uma ferramenta que automatiza a criação de problemas no GitHub para o projeto MCPSpy, utilizando o CLI tool gh issue.","ru":"ИИ Агент github-issue-creator автоматизирует создание проблем на GitHub для проекта MCPSpy, используя CLI tool gh issue.","ar":"وظيفة github-issue-creator هي أداة ت自动 إنشاء مشاكل على GitHub لمشروع MCPSpy، باستخدام أداة CLI gh issue."},"seo":{"title":{"en":"github-issue-creator: Automated GitHub Issue Creation Set...","zh":"GitHub Issue Creator 设置指南 - MCP 监控与 eBPF","ja":