INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alex-ilgayev/MCPSpy/github-issue-creator', 'github-issue-creator', 'alex-ilgayev', 'MCPSpy', 'community', 'github-issue-creator alex-ilgayev MCPSpy community The github-issue-creator skill automates the creation of well-structured GitHub issues for the MCPSpy project, benefiting developers and project managers. It utilizes the gh issue CLI tool for efficient issue creation. GitHub Issue Creator Skill 自动创建结构化的 GitHub 问题，支持 MCP 监控和 eBPF 技术 GitHub Issue Creator スキルは、MCP モニタリングと eBPF 技術を使用して構造化された GitHub の問題を作成します GitHub Issue Creator 스킬은 MCP 모니터링 및 eBPF 기술을 사용하여 구조화된 GitHub 문제를 자동 생성합니다 El skill github-issue-creator automatiza la creación de problemas de GitHub estructurados para el proyecto MCPSpy, utilizando herramientas como gh issue CLI Le skill github-issue-creator automatise la création de problèmes GitHub structurés pour le projet MCPSpy, en utilisant des outils tels que gh issue CLI Der Skill github-issue-creator automatisiert die Erstellung strukturierter GitHub-Probleme für das Projekt MCPSpy, unter Verwendung von Tools wie gh issue CLI O github-issue-creator é uma ferramenta que automatiza a criação de problemas no GitHub para o projeto MCPSpy, utilizando o CLI tool gh issue. ИИ Агент github-issue-creator автоматизирует создание проблем на GitHub для проекта MCPSpy, используя CLI tool gh issue. وظيفة github-issue-creator هي أداة ت自动 إنشاء مشاكل على GitHub لمشروع MCPSpy، باستخدام أداة CLI gh issue. github-issue-creator setup guide how to use github-issue-creator github-issue-creator vs manual issue creation github-issue-creator install github-issue-creator for MCPSpy project automated github issue creation gh issue CLI tool tutorial github issue naming convention best practices GitHub Issue Creator MCP 监控 eBPF AI 工具 自动创建 GitHub 问题 结构化 GitHub 问题 gh issue CLI 临时 markdown 文件 Utilizes the gh issue CLI tool for creating GitHub issues Supports creation of issues with long bodies using temporary markdown files Follows standard prefixes for issue naming, such as feat(component) and fix(component) Compatible with MCPSpy project components, including library-manager, ebpf, and http Allows for efficient issue creation using the gh issue create --body-file option github-issue-creator is a skill that automates the creation of well-structured GitHub issues using standard prefixes and the gh issue CLI tool');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sandervw/CorpLore/literary-revision', 'community', 'sandervw', 'CorpLore', 'sandervw/CorpLore', 'literary-revision', 0, 0, 47, '2026-03-08T01:57:15.302Z', '2026-03-08T02:01:44.733Z', '65f2abad20b84f65a3240ece6a92b3733ed3047f2204805fdbad152e75bfd677', '{"id":"sandervw/CorpLore/literary-revision","name":"literary-revision","description":{"en":"The literary-revision skill transforms user-provided prose into specific literary styles, preserving core narrative beats. It benefits developers and writers seeking to enhance their storytelling.","zh":"文学修订工具用于CorpLore故事构建，通过加载样式参考和提取核心情节来修订用户提供的散文","ja":"CorpLore設定用の文学修正AIエージェントは、スタイルの参考をロードし、コアの物語要素を抽出してユーザー提供の散文を修正する","ko":"CorpLore 설정을 위한 문학수정도구는 스타일 참조를 로드하고 핵심 플롯을 추출하여 사용자 제공 텍스트를 수정","es":"La revisión literaria es una habilidad que revisa el lenguaje y el estilo de los documentos y el código, para adecuarlos a un estilo específico","fr":"La révision littéraire est une compétence qui révise le langage et le style des documents et du code, pour les adapter à un style spécifique","de":"Die literarische Revision ist eine Fähigkeit, die die Sprache und den Stil von Dokumenten und Code überprüft, um sie an einen bestimmten Stil anzupassen","pt":"O literary-revision é uma ferramenta que revisa textos em diferentes estilos literários, preservando as batidas narrativas principais. Ele funciona carregando referências de estilo e aplicando diretrizes de estilo de forma sistemática.","ru":"ИИ Агент literary-revision пересматривает тексты в различных литературных стилях, сохраняя основные повествовательные ритмы. Он работает, загружая справочные материалы по стилю и применяя руководства по стилю систематически.","ar":"برنامج literary-revision هو أداة لتصحيح النصوص في أساليب أدبية مختلفة، مع الحفاظ على الإيقاعات السردية الأساسية. يعمل عن طريق تحميل المراجع بالأساليب وتنفيذ إرشادات الأسلوب بشكل منهجي."},"seo":{"title":{"en":"Literary-Revision: Style Transformation for AI Agents | A...","zh":"文学修订工具：CorpLore故事构建指南","ja":"文学修正AIエージェント：CorpLore設定ガイド","ko":"문학수정도구: CorpLore 설정 가이드","es":"Guía de Configuración de Revisión Literaria para Desarrol...","fr":"Guide de Mise en Place de la Révision Littéraire pour les...","de":"Einrichtungsleitfaden für Literarische Revision für Entwi...","pt":"Guia de Configuração do literary-revision: Revisão de Est...","ru":"ИИ Агенты: Настройка literary-revision для Пересмотра Лит...","ar":"دليل الإعداد لبرنامج literary-revision: تصحيح الأسلوب الأدبي"},"description":{"en":"Unlock the power of literary style transformation with our AI agent skill. Learn how to revise prose into specific styles while preserving core narrative beats.","zh":"了解文学修订工具的技术细节，包括工作流程和样式指南，用于CorpLore故事构建","ja":"CorpLore設定用の文学修正AIエージェントの技術的詳細を確認しよう","ko":"CorpLore 설정을 위한 문학수정도구의 기술적 세부사항 확인","es":"Aprende a integrar la revisión literaria en tus proyectos con nuestro agente de inteligencia artificial, herramienta de revisión de código y estilo","fr":"Découvrez comment intégrer la révision littéraire dans vos projets avec notre agent d''intelligence artificielle, outil de révision de code et de style","de":"Erfahren Sie, wie Sie die literarische Revision in Ihre Projekte integrieren können, mit unserem KI-Agenten, Code- und Stil-Überprüfungstool","pt":"Aprenda a configurar o literary-revision para revisar textos em diferentes estilos literários, preservando as batidas narrativas principais.","ru":"Узнайте, как настроить literary-revision для пересмотра текстов в различных литературных стилях, сохраняя основные повествовательные ритмы.","ar":"تعرف على كيفية تكوين برنامج literary-revision لتصحيح النصوص في أساليب أدبية مختلفة، مع الحفاظ على الإيقاعات السردية الأساسية."},"definition":{"en":"Literary-revision is a skill that revises user-provided prose into a specific literary style while preserving core narrative beats using a systematic approach.","zh":"文学修订工具是一种AI工具，用于修订用户提供的散文以符合特定的文学风格","ja":"文学修正AIエージェントは、ユーザー提供の散文を特定の文学スタイルに修正するAIツールです","ko":"문학수정도구는 사용자 제공 텍스트를 특정 문학 스타일로 수정하는 AI 도구","es":"La revisión literaria es un proceso que utiliza inteligencia artificial para revisar y mejorar el estilo y la coherencia de los textos","fr":"La révision littéraire est un processus qui utilise l''intelligence artificielle pour réviser et améliorer le style et la cohérence des textes","de":"Die literarische Revision ist ein Prozess, der künstliche Intelligenz verwendet, um den Stil und die Kohärenz von Texten zu überprüfen und zu verbessern","pt":"O literary-revision é uma ferramenta de revisão de texto que aplica estilos literários específicos a textos.","ru":"ИИ Агент literary-revision - это инструмент для пересмотра текстов, который применяет определенные литературные стили к текстам.","ar":"برنامج literary-revision هو أداة لتصحيح النصوص التي تنطبق أساليب أدبية محددة على النصوص."},"features":{"en":["Identifies requested style from user input","Loads appropriate style reference from references/","Extracts core beats from source prose using outline extraction","Applies style guidelines systematically","Verifies output respects character limits"],"zh":["支持多种文学风格","加载样式参考以指导修订","提取核心情节以保留原有故事","系统地应用样式指南","验证输出以确保字符限制"],"ja":["複数の文学スタイルをサポート","スタイルの参考をロードして修正を導く","コアの物語要素を抽出して元の物語を保持","スタイルのガイドラインをシステム的に適用","出力を検証して文字数制限を確保"],"ko":["다양한 문학 스타일 지원","스타일 참조 로딩을 통해 수정 지침 제공","핵심 플롯 추출을 통해 원래 스토리 유지","시스템적으로 스타일 지침 적용","출력 검증을 통해 문자 수 제한 확인"],"es":["Identificación del estilo solicitado por el usuario","Carga de referencias de estilo desde `references/`","Extracción de los elementos narrativos clave del texto fuente","Aplicación sistemática de las directrices de estilo","Verificación del respeto de los límites de caracteres especificados"],"fr":["Identification du style demandé par l''utilisateur","Chargement des références de style depuis `references/`","Extraction des éléments narratifs clés du texte source","Application systématique des directives de style","Vérification du respect des limites de caractères spécifiées"],"de":["Identifizierung des vom Benutzer angeforderten Stils","Laden von Stilreferenzen aus `references/`","Extraktion der wichtigsten Erzählungselemente aus dem Quelltext","Systematische Anwendung der Stilrichtlinien","Überprüfung der Einhaltung der angegebenen Zeichenlimits"],"pt":["Identificação do estilo literário solicitado","Carregamento de referências de estilo","Extração de batidas narrativas principais","Aplicação sistemática de diretrizes de estilo","Verificação do limite de caracteres"],"ru":["Определение запрошенного литературного стиля","Загрузка справочных материалов по стилю","Извлечение основных повествовательных ритмов","Систематическое применение руководств по стилю","Проверка ограничения символов"],"ar":["تحديد الأسلوب الأدبي المطلوب","تحميل المراجع بالأسلوب","استخراج الإيقاعات السردية الأساسية","تنفيذ إرشادات الأسلوب بشكل منهجي","التحقق من حد الحروف"]},"keywords":{"en":["how to use literary-revision","literary-revision alternative","literary-revision setup guide","what is literary-revision","literary-revision vs style transfer","install literary-revision"],"zh":["文学修订工具","CorpLore故事构建","AI文学修订","文学风格转换","散文修订","故事构建工具"],"ja":["文学修正AIエージェント","CorpLore設定","AI文学修正","文学スタイル変換","散文修正","物語構築ツール"],"ko":["문학수정도구","CorpLore 설정","AI 문학수정","문학 스타일 변환","텍스트 수정","스토리 빌딩 도구"],"es":["revisión literaria","agente de inteligencia artificial","herramienta de revisión de código","estilo de escritura","desarrollo de software","integración de AI","procesamiento de lenguaje natural"],"fr":["révision littéraire","agent d''intelligence artificielle","outil de révision de code","style d''écriture","développement de logiciels","intégration de l''IA","traitement automatique des langues"],"de":["literarische Revision","KI-Agent","Code-Überprüfungstool","Schreibstil","Software-Entwicklung","AI-Integration","natürliche Sprachverarbeitung"],"pt":["literary-revision","revisão de estilo literário","ferramentas de texto","estilos literários","batidas narrativas","diretrizes de estilo","limites de caracteres"],"ru":["ИИ Агенты","литературный пересмотр","инструменты для текста","литературные стили","повествовательные ритмы","руководства по стилю","ограничения символов"],"ar":["برامج الذكاء الاصطناعي","تصحيح الأسلوب الأدبي","أدوات النص","الأساليب الأدبية","الإيقاعات السردية","إرشادات الأسلوب","حد الحروف"]}},"owner":"sandervw","repo":"CorpLore","repoPath":"sandervw/CorpLore","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.302Z","topics":[],"category":"community","skillMd":{"name":"literary-revision","description":"Revise, rewrite, or redo prose in specific literary styles. Use when user asks to revise text in Howard, Thorogood, Peake, Conan, Eddison, or archaic style. Also use for any request to rewrite with a particular tone or aesthetic.","bodyPreview":"# Literary Revision\n\nRevise user-provided prose into a specific literary style while preserving core narrative beats.\n\n## Workflow\n\n1. Identify requested style from user input\n2. Load the appropriate style reference from `references/`\n3. Extract core beats from source prose (outline, not rewrite)\n4. Apply style guidelines systematically\n5. Verify output respects any character limit specified\n\n## Available Styles\n\n| Style         | Voice                                    | Use Case","body":"# Literary Revision\n\nRevise user-provided prose into a specific literary style while preserving core narrative beats.\n\n## Workflow\n\n1. Identify requested style from user input\n2. Load the appropriate style reference from `references/`\n3. Extract core beats from source prose (outline, not rewrite)\n4. Apply style guidelines systematically\n5. Verify output respects any character limit specified\n\n## Available Styles\n\n| Style         | Voice                                    | Use Case                                      | Reference            |\n| ------------- | ---------------------------------------- | --------------------------------------------- | -------------------- |\n| **Thorogood** | Bar-band storyteller, 2nd person, bluesy | Punchy, rhythmic retellings with attitude     | [thorogood-style.md] |\n| **Peake**     | Slow gothic camera, animate inanimate    | Dense atmospheric description, uncanny mood   | [peake-style.md]     |\n| **Howard**    | Pulp heroic, elevated diction            | Dramatic adventure prose, visceral action     | [howard-style.md]    |\n| **Eddison**   | Archaic diction, inverted syntax         | Elevated courtly prose, high fantasy gravitas | [eddison-style.md]   |\n\n## Style Selection\n\n- User says \"Thorogood,\" \"bluesy,\" \"bar story,\" \"roadhouse\" → Load thorogood-style.md\n- User says \"Peake,\" \"gothic,\" \"Gormenghast,\" \"atmospheric\" → Load peake-style.md  \n- User says \"Howard,\" \"Conan,\" \"pulp,\" \"heroic fantasy\" → Load howard-style.md\n- User says \"Eddison,\" \"Shakespearean,\" \"Mallory,\" \"archaic,\" \"courtly\" → Load eddison-style.md\n- Ambiguous request → Ask user to specify style\n\n## Output Guidelines\n\n- Preserve all core narrative beats from source\n- Respect character limits if specified (default: no limit)\n- Do not add plot elements absent from source\n- Style transformation only—not content invention\n"},"lastSynced":"2026-03-08T02:01:44.733Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing advanced literary style transformation capabilities.","zh":"非常适合需要高级文学风格转换能力的语言代理。","ja":"高度な文学スタイルの変換能力が必要な言語エージェントに最適です。","ko":"고급 문학 스타일 변환 기능이 필요한 언어 에이전트에게 적합합니다.","es":"Perfecto para agentes de lenguaje que necesitan capacidades avanzadas de transformación de estilo literario.","fr":"Parfait pour les agents de langage ayant besoin de capacités de transformation de style littéraire avancées.","de":"Perfekt für Sprachagenten, die erweiterte literarische Stiltransformationen benötigen.","pt":"Perfeito para Agentes de Linguagem que necessitam de capacidades avançadas de transformação de estilo literário.","ru":"Идеально для языковых агентов, которым необходимы продвинутые возможности преобразования литературного стиля.","ar":"مثالي للوكلاء اللغويين الذين يحتاجون إلى قدرات متقدمة لتحويل الأسلوب الأدبي."},"recommendation":{"en":"Empowers agents to transform user-provided prose into specific literary styles, preserving core narrative beats, using systematic style guidelines and respecting character limits, all while leveraging reference materials from directories like ''references/''.","zh":"赋予代理人将用户提供的散文转换为特定文学风格的能力，保留核心叙事节奏，使用系统的风格指南，并尊重字符限制，同时利用目录如 ''references/'' 中的参考材料。","ja":"エージェントがユーザー提供の散文を特定の文学スタイルに変換する能力を与え、核心的な物語のリズムを保ち、体系的なスタイルガイドラインを使用し、文字数制限を尊重し、''references/'' などのディレクトリからの参考資料を利用します。","ko":"에이전트가 사용자 제공의 산문으로 특정 문학 스타일을 변환할 수 있는 능력을 부여하며, 핵심적인 내레이션 리듬을 유지하고, 체계적인 스타일 가이드라인을 사용하며, 문자 수 제한을尊重하고, ''references/''와 같은 디렉토리에서 참조 자료를 활용합니다.","es":"Permite a los agentes transformar la prosa proporcionada por el usuario en estilos literarios específicos, conservando los ritmos narrativos básicos, utilizando pautas de estilo sistemáticas y respetando los límites de caracteres, todo mientras aprovecha los materiales de referencia de directorios como ''references/''.","fr":"Permet aux agents de transformer la prose fournie par l''utilisateur en styles littéraires spécifiques, en préservant les battements narratifs de base, en utilisant des lignes directrices de style systématiques et en respectant les limites de caractères, le tout en exploitant les documents de référence de répertoires tels que ''references/''.","de":"Ermöglicht es Agenten, die vom Benutzer bereitgestellte Prosa in bestimmte literarische Stile zu transformieren, die Kernnarrativelemente zu bewahren, systematische Stilrichtlinien zu verwenden und die Zeichenbegrenzungen zu respektieren, und zwar unter Ausnutzung der Referenzmaterialien aus Verzeichnissen wie ''references/''.","pt":"Habilita os agentes a transformar a prosa fornecida pelo usuário em estilos literários específicos, preservando as batidas narrativas principais, usando diretrizes de estilo sistemáticas e respeitando os limites de caracteres, tudo isso aproveitando materiais de referência de diretórios como ''references/''.","ru":"Наделяет агентов возможностью преобразовывать пользовательский текст в определенные литературные стили, сохраняя основные повествовательные ритмы, используя систематические рекомендации по стилю и соблюдая ограничения на количество символов, все это при использовании справочных материалов из каталогов типа ''references/''.","ar":"يمنح الوكلاء القدرة على تحويل النثر المقدم من قبل المستخدم إلى أساليب أدبية محددة ، مع الحفاظ على الإيقاعات السردية الأساسية ، واستخدام إرشادات الأسلوب المنهجية ، واحترام حدود الأحرف ، كل ذلك مع الاستفادة من المواد المرجعية من المجلدات مثل ''references/''."},"useCases":{"en":["Transforming user-generated content into engaging literary pieces","Automating style consistency checks for large volumes of text","Generating stylistically coherent outlines from raw prose"],"zh":["将用户生成的内容转换为吸引人的文学作品","自动化大容量文本的风格一致性检查","从原始散文中生成风格上的一致的提纲"],"ja":["ユーザー生成コンテンツを魅力的な文学作品に変換する","大容量テキストのスタイルの一貫性チェックを自動化する","生の散文からスタイル上の一貫したアウトラインを生成する"],"ko":["사용자 생성 콘텐츠를 매력적인 문학 작품으로 변환하는 것","대량의 텍스트에 대한 스타일 일관성 검사를 자동화하는 것","원시 산문에서 스타일적으로 일관된 개요를 생성하는 것"],"es":["Transformar contenido generado por el usuario en piezas literarias atractivas","Automatizar comprobaciones de coherencia de estilo para grandes volúmenes de texto","Generar esquemas coherentes estilísticamente a partir de prosa bruta"],"fr":["Transformer le contenu généré par l''utilisateur en pièces littéraires engageantes","Automatiser les vérifications de cohérence de style pour de grands volumes de texte","Générer des plans cohérents sur le plan du style à partir de prose brute"],"de":["Benutzergenerierten Inhalt in ansprechende literarische Stücke umwandeln","Stil-Konsistenz-Prüfungen für große Textmengen automatisieren","Stilistisch kohärente Umrisse aus roher Prosa generieren"],"pt":["Transformar o conteúdo gerado pelo usuário em peças literárias atraentes","Automatizar verificações de consistência de estilo para grandes volumes de texto","Gerar esboços coerentes com estilo a partir de prosa bruta"],"ru":["Преобразовывать пользовательский контент в увлекательные литературные произведения","Автоматизировать проверки последовательности стиля для больших объемов текста","Генерировать стилистически связанные планы из сырого текста"],"ar":["تحويل المحتوى الذي تم إنشاؤه بواسطة المستخدم إلى قطع أدبية جذابة","توفير فحص التماسك في الأسلوب لأحجام كبيرة من النص","إنتاج مخططات متسقة الأسلوب من النثر الخام"]},"limitations":{"en":["Requires access to style reference materials","Character limit restrictions apply to output","Limited to available styles loaded from ''references/'' directory"],"zh":["需要访问风格参考材料","字符限制对输出有效","仅限于从 ''references/'' 目录加载的可用风格"],"ja":["スタイル参考資料へのアクセスが必要","文字数制限が出力に適用される","''references/'' ディレクトリから読み込まれた利用可能なスタイルに限定される"],"ko":["스타일 참조 자료에 대한 액세스가 필요합니다","문자 수 제한이 출력에 적용됩니다"," ''references/'' 디렉토리에서 로드된 사용 가능한 스타일로 제한됩니다"],"es":["Requiere acceso a materiales de referencia de estilo","Se aplican restricciones de límite de caracteres a la salida","Limitado a los estilos disponibles cargados desde el directorio ''references/''"],"fr":["Nécessite un accès à des documents de référence de style","Des restrictions de limite de caractères s''appliquent à la sortie","Limité aux styles disponibles chargés à partir du répertoire ''references/''"],"de":["Benötigt Zugriff auf Stil-Referenzmaterialien","Zeichenbegrenzungsbeschränkungen gelten für die Ausgabe","Begrenzt auf verfügbare Stile, die aus dem Verzeichnis ''references/'' geladen werden"],"pt":["Requer acesso a materiais de referência de estilo","Restrições de limite de caracteres se aplicam à saída","Limitado aos estilos disponíveis carregados do diretório ''references/''"],"ru":["Требует доступа к справочным материалам по стилю","Ограничения на количество символов применяются к выводу","Ограничен доступными стилями, загруженными из каталога ''references/''"],"ar":["يتطلب الوصول إلى مواد مرجعية للأسلوب","تطبق قيود حدود الأحرف على الإخراج","محدود بالأسلوب المتاح الذي يتم تحميله من مجلد ''references/''"]},"version":4},"contentHash":"65f2abad20b84f65a3240ece6a92b3733ed3047f2204805fdbad152e75bfd677","qualityScore":47}');
