INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sandervw/CorpLore/literary-revision', 'literary-revision', 'sandervw', 'CorpLore', 'community', 'literary-revision sandervw CorpLore community The literary-revision skill transforms user-provided prose into specific literary styles, preserving core narrative beats. It benefits developers and writers seeking to enhance their storytelling. 文学修订工具用于CorpLore故事构建，通过加载样式参考和提取核心情节来修订用户提供的散文 CorpLore設定用の文学修正AIエージェントは、スタイルの参考をロードし、コアの物語要素を抽出してユーザー提供の散文を修正する CorpLore 설정을 위한 문학수정도구는 스타일 참조를 로드하고 핵심 플롯을 추출하여 사용자 제공 텍스트를 수정 La revisión literaria es una habilidad que revisa el lenguaje y el estilo de los documentos y el código, para adecuarlos a un estilo específico La révision littéraire est une compétence qui révise le langage et le style des documents et du code, pour les adapter à un style spécifique Die literarische Revision ist eine Fähigkeit, die die Sprache und den Stil von Dokumenten und Code überprüft, um sie an einen bestimmten Stil anzupassen O literary-revision é uma ferramenta que revisa textos em diferentes estilos literários, preservando as batidas narrativas principais. Ele funciona carregando referências de estilo e aplicando diretrizes de estilo de forma sistemática. ИИ Агент literary-revision пересматривает тексты в различных литературных стилях, сохраняя основные повествовательные ритмы. Он работает, загружая справочные материалы по стилю и применяя руководства по стилю систематически. برنامج literary-revision هو أداة لتصحيح النصوص في أساليب أدبية مختلفة، مع الحفاظ على الإيقاعات السردية الأساسية. يعمل عن طريق تحميل المراجع بالأساليب وتنفيذ إرشادات الأسلوب بشكل منهجي. how to use literary-revision literary-revision alternative literary-revision setup guide what is literary-revision literary-revision vs style transfer install literary-revision 文学修订工具 CorpLore故事构建 AI文学修订 文学风格转换 散文修订 故事构建工具 Identifies requested style from user input Loads appropriate style reference from references/ Extracts core beats from source prose using outline extraction Applies style guidelines systematically Verifies output respects character limits Literary-revision is a skill that revises user-provided prose into a specific literary style while preserving core narrative beats using a systematic approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('simnova/sharethrift/apollo-client', 'community', 'simnova', 'sharethrift', 'simnova/sharethrift', 'apollo-client', 0, 0, 47, '2026-03-08T01:57:15.327Z', '2026-03-08T02:03:03.802Z', 'eed94d5d00ae06c79a59d1f1d97b9f93e4307763b3da59a37891999082dfc8a8', '{"id":"simnova/sharethrift/apollo-client","name":"apollo-client","description":{"en":"Apollo Client is a comprehensive state management library for JavaScript, enabling local and remote data management with GraphQL. It benefits developers building modern React applications.","zh":"Apollo Client 4.x 是一个全面的状态管理库，支持 GraphQL 和 React 19 兼容性","ja":"Apollo Client 4.x は、GraphQL と React 19 互換性をサポートする包括的な状態管理ライブラリ","ko":"Apollo Client 4.x는 GraphQL과 React 19 호환성을 지원하는 포괄적인 상태 관리 라이브러리","es":"Apollo Client es una biblioteca de gestión de estado para JavaScript que permite gestionar datos locales y remotos con GraphQL. La versión 4.x ofrece mejoras en caché y compatibilidad con TypeScript.","fr":"Apollo Client est une bibliothèque de gestion d''état pour JavaScript qui permet de gérer les données locales et distantes avec GraphQL. La version 4.x propose des améliorations de mise en cache et de la compatibilité avec TypeScript.","de":"Apollo Client ist eine Bibliothek zur Zustandsverwaltung für JavaScript, die es ermöglicht, lokale und remote Daten mit GraphQL zu verwalten. Die Version 4.x bietet Verbesserungen bei der Zwischenspeicherung und der Kompatibilität mit TypeScript.","pt":"O Apollo Client 4.x é uma biblioteca de gerenciamento de estado para JavaScript que permite gerenciar dados locais e remotos com GraphQL.","ru":"Apollo Client 4.x - это комплексная библиотека управления состоянием для JavaScript, которая позволяет управлять локальными и удаленными данными с помощью GraphQL.","ar":"Apollo Client 4.x هو مكتبة إدارة حالة شاملة لجافا سكريبت التي تمكنك من إدارة البيانات المحلية والبعيدة مع GraphQL"},"seo":{"title":{"en":"Apollo-Client: GraphQL State Management Setup Guide | AI ...","zh":"Apollo Client 4.x 设置指南","ja":"Apollo Client 4.x セットアップガイド","ko":"Apollo Client 4.x 설정 가이드","es":"Guía de configuración de Apollo Client 4.x para React","fr":"Guide de configuration d''Apollo Client 4.x pour React","de":"Apollo Client 4.x Konfigurationsleitfaden für React","pt":"Guia de Configuração do Apollo Client 4.x para Desenvolve...","ru":"ИИ Агенты: Руководство по настройке Apollo Client 4.x","ar":"دليل إعداد Apollo Client 4.x للبرمجة"},"description":{"en":"Unlock efficient state management with Apollo Client 4.x. Discover setup guides for Next.js and React, and learn how to leverage GraphQL for seamless data ha...","zh":"了解 Apollo Client 4.x 的功能和设置方法，实现高效的状态管理和 GraphQL 数据管理","ja":"Apollo Client 4.x の機能と設定方法を学び、効率的な状態管理と GraphQL データ管理を実現","ko":"Apollo Client 4.x 기능과 설정 방법을 알아보고 효율적인 상태 관리와 GraphQL 데이터 관리를 구현","es":"Aprende a configurar Apollo Client 4.x con React y aprovecha mejoras en caché y compatibilidad con TypeScript","fr":"Découvrez comment configurer Apollo Client 4.x avec React et profitez des améliorations de mise en cache et de la compatibilité avec TypeScript","de":"Erfahren Sie, wie Sie Apollo Client 4.x mit React konfigurieren und profitieren Sie von Verbesserungen bei der Zwischenspeicherung und der Kompatibilität mit...","pt":"Aprenda a configurar o Apollo Client 4.x para gerenciar dados locais e remotos com GraphQL e melhor suporte ao TypeScript","ru":"Узнайте, как настроить Apollo Client 4.x для управления локальными и удаленными данными с помощью GraphQL и лучшей поддержки TypeScript","ar":"تعلم كيفية配置 Apollo Client 4.x لتدبير البيانات المحلية والبعيدة مع GraphQL ودعم أفضل للtypescript"},"definition":{"en":"Apollo-client is a JavaScript state management library that enables efficient local and remote data management using GraphQL, with features like improved caching and TypeScript support.","zh":"Apollo Client 是一个 JavaScript 库，用于管理本地和远程数据，特别是 GraphQL 数据","ja":"Apollo Client は、ローカルとリモートデータを管理する JavaScript ライブラリ、特に GraphQL データ","ko":"Apollo Client는 로컬과 리모트 데이터를 관리하는 JavaScript 라이브러리, 특히 GraphQL 데이터","es":"Apollo Client es una biblioteca de gestión de estado para JavaScript que utiliza GraphQL para gestionar datos","fr":"Apollo Client est une bibliothèque de gestion d''état pour JavaScript qui utilise GraphQL pour gérer les données","de":"Apollo Client ist eine Bibliothek zur Zustandsverwaltung für JavaScript, die GraphQL zur Datenverwaltung verwendet","pt":"O que é Apollo Client? É uma biblioteca de gerenciamento de estado para JavaScript que usa GraphQL","ru":"Что такое Apollo Client? Это библиотека управления состоянием для JavaScript, которая использует GraphQL","ar":"ما هو Apollo Client؟ هو مكتبة إدارة حالة لجافا سكريبت تستخدم GraphQL"},"features":{"en":["Improved caching for optimized data handling","Better TypeScript support for enhanced code maintainability","React 19 compatibility for seamless integration","Specialized setup guides for Next.js App Router","GraphQL support for efficient data management","Version 4.x for enhanced performance and features"],"zh":["支持 GraphQL 数据管理","改进的缓存机制","增强的 TypeScript 支持","React 19 兼容性","Next.js App Router 设置指南"],"ja":["GraphQL データ管理のサポート","キャッシュメカニズムの改善","TypeScript サポートの強化","React 19 互換性","Next.js App Router 設定ガイド"],"ko":["GraphQL 데이터 관리 지원","캐시 메커니즘 개선","TypeScript 지원 강화","React 19 호환성","Next.js App Router 설정 가이드"],"es":["Mejoras en caché para una mejor experiencia del usuario","Compatibilidad con TypeScript para una mayor seguridad y mantenimiento","Compatibilidad con React 19 para las últimas características de React","Guías de configuración especializadas para Next.js y App Router","Gestión de datos locales y remotos con GraphQL","Soporte para aplicaciones modernas de React con SSR"],"fr":["Améliorations de mise en cache pour une meilleure expérience utilisateur","Compatibilité avec TypeScript pour une plus grande sécurité et maintenance","Compatibilité avec React 19 pour les dernières fonctionnalités de React","Guides de configuration spécialisées pour Next.js et App Router","Gestion des données locales et distantes avec GraphQL","Prise en charge des applications modernes de React avec SSR"],"de":["Verbesserungen bei der Zwischenspeicherung für eine bessere Benutzererfahrung","Kompatibilität mit TypeScript für eine größere Sicherheit und Wartung","Kompatibilität mit React 19 für die neuesten Funktionen von React","Spezielle Konfigurationsleitfäden für Next.js und App Router","Verwaltung von lokalen und remote Daten mit GraphQL","Unterstützung für moderne React-Anwendungen mit SSR"],"pt":["Melhor caching com o Apollo Client 4.x","Suporte melhorado ao TypeScript","Compatibilidade com React 19","Guia de configuração para Next.js App Router","Suporte a GraphQL para gerenciar dados locais e remotos","Integração com frameworks modernos de React"],"ru":["Улучшенный кэширование с Apollo Client 4.x","Лучшая поддержка TypeScript","Совместимость с React 19","Руководство по настройке для Next.js App Router","Поддержка GraphQL для управления локальными и удаленными данными","Интеграция с современными фреймворками React"],"ar":["تحسين الذاكرة المؤقتة مع Apollo Client 4.x","دعم أفضل للtypescript","توافق مع React 19","دليل إعداد ل Next.js App Router","دعم GraphQL لإدارة البيانات المحلية والبعيدة","تكامل مع إطار العمل الحديث ل React"]},"keywords":{"en":["how to use apollo-client","apollo-client setup guide","graphql state management","apollo-client vs relay","apollo-client install","react 19 compatibility","next.js app router setup","typescript support"],"zh":["Apollo Client","GraphQL","React 19","状态管理","缓存机制","TypeScript","Next.js","AIエージェント","JavaScript 库"],"ja":["Apollo Client","GraphQL","React 19","状態管理","キャッシュメカニズム","TypeScript","Next.js","AIエージェント","JavaScript ライブラリ"],"ko":["Apollo Client","GraphQL","React 19","상태 관리","캐시 메커니즘","TypeScript","Next.js","AI 에이전트","JavaScript 라이브러리"],"es":["apollo client","react","graphql","typescript","next.js","app router","gestión de estado","caché","compatibilidad con react 19","desarrollo de aplicaciones modernas"],"fr":["apollo client","react","graphql","typescript","next.js","app router","gestion d''état","mise en cache","compatibilité avec react 19","développement d''applications modernes"],"de":["apollo client","react","graphql","typescript","next.js","app router","zustandsverwaltung","zwischenspeicherung","kompatibilität mit react 19","entwicklung von modernen anwendungen"],"pt":["apollo client 4.x","guia de configuração","graphql","typescript","react 19","next.js app router","gerenciamento de estado","desenvolvimento de aplicativos","bibliotecas de javascript"],"ru":["apollo client 4.x","руководство по настройке","graphql","typescript","react 19","next.js app router","управление состоянием","разработка приложений","библиотеки javascript"],"ar":["apollo client 4.x","دليل إعداد","graphql","typescript","react 19","next.js app router","إدارة حالة","تطوير التطبيقات","مكتبات جافا سكريبت"]}},"owner":"simnova","repo":"sharethrift","repoPath":"simnova/sharethrift","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.327Z","topics":[],"category":"community","skillMd":{"name":"apollo-client","description":">","version":"1.0","bodyPreview":"# Apollo Client 4.x Guide\n\nApollo Client is a comprehensive state management library for JavaScript that enables you to manage both local and remote data with GraphQL. Version 4.x brings improved caching, better TypeScript support, and React 19 compatibility.\n\n## Framework-Specific Setup Guides\n\nFor modern React frameworks with SSR support, use these specialized setup guides:\n\n- **[Next.js App Router Setup](references/setup-nextjs.md)** - For Next.js applications using the App Router with React","body":"# Apollo Client 4.x Guide\n\nApollo Client is a comprehensive state management library for JavaScript that enables you to manage both local and remote data with GraphQL. Version 4.x brings improved caching, better TypeScript support, and React 19 compatibility.\n\n## Framework-Specific Setup Guides\n\nFor modern React frameworks with SSR support, use these specialized setup guides:\n\n- **[Next.js App Router Setup](references/setup-nextjs.md)** - For Next.js applications using the App Router with React Server Components\n- **[React Router Framework Mode Setup](references/setup-react-router.md)** - For React Router 7 applications with streaming SSR\n- **[TanStack Start Setup](references/setup-tanstack-start.md)** - For TanStack Start applications with modern routing\n\nThese guides provide framework-specific integration packages and patterns optimized for SSR, streaming, and React Server Components.\n\n## Quick Start\n\n### Step 1: Install\n\n```bash\nnpm install @apollo/client graphql rxjs\n```\n\n### Step 1.5: Set up TypeScript Code Generation (optional but recommended)\n\nFor TypeScript type generation (recommended):\n\n```bash\nnpm install -D @graphql-codegen/cli @graphql-codegen/typescript @graphql-codegen/typescript-operations @graphql-codegen/typed-document-node\n```\n\n```typescript\n// codegen.ts\nimport { CodegenConfig } from \"@graphql-codegen/cli\";\n\nconst config: CodegenConfig = {\n  overwrite: true,\n  schema: \"<URL_OF_YOUR_GRAPHQL_API>\",\n  // This assumes that all your source files are in a top-level `src/` directory - you might need to adjust this to your file structure\n  documents: [\"src/**/*.{ts,tsx}\"],\n  // Don''t exit with non-zero status when there are no documents\n  ignoreNoDocuments: true,\n  generates: {\n    // Use a path that works the best for the structure of your application\n    \"./src/types/__generated__/graphql.ts\": {\n      plugins: [\"typescript\", \"typescript-operations\", \"typed-document-node\"],\n      config: {\n        avoidOptionals: {\n          // Use `null` for nullable fields instead of optionals\n          field: true,\n          // Allow nullable input fields to remain unspecified\n          inputValue: false,\n        },\n        // Use `unknown` instead of `any` for unconfigured scalars\n        defaultScalarType: \"unknown\",\n        // Apollo Client always includes `__typename` fields\n        nonOptionalTypename: true,\n        // Apollo Client doesn''t add the `__typename` field to root types so\n        // don''t generate a type for the `__typename` for root operation types.\n        skipTypeNameForRoot: true,\n      },\n    },\n  },\n};\n\nexport default config;\n```\n\nThe typed-document-node plugin might have a bundle size tradeoff but can prevent inconsistencies and is best suited for usage with LLMs, so it is recommended for most applications.\nSee the [GraphQL Code Generator documentation](https://www.apollographql.com/docs/react/development-testing/graphql-codegen#recommended-starter-configuration) for other recommended configuration patterns if required.\n\n### Step 2: Create Client\n\n```typescript\nimport { ApolloClient, InMemoryCache, HttpLink } from \"@apollo/client\";\nimport { SetContextLink } from \"@apollo/client/link/context\";\n\nconst httpLink = new HttpLink({\n  uri: \"https://your-graphql-endpoint.com/graphql\",\n});\n\n// Use SetContextLink for auth headers to update dynamically per request\nconst authLink = new SetContextLink(({ headers }) => {\n  const token = localStorage.getItem(\"token\");\n  return {\n    headers: {\n      ...headers,\n      authorization: token ? `Bearer ${token}` : \"\",\n    },\n  };\n});\n\nconst client = new ApolloClient({\n  link: authLink.concat(httpLink),\n  cache: new InMemoryCache(),\n});\n```\n\n### Step 3: Setup Provider\n\n```tsx\nimport { ApolloProvider } from \"@apollo/client\";\nimport App from \"./App\";\n\nfunction Root() {\n  return (\n    <ApolloProvider client={client}>\n      <App />\n    </ApolloProvider>\n  );\n}\n```\n\n### Step 4: Execute Query\n\n```tsx\nimport { gql } from \"@apollo/client\";\nimport { useQuery } from \"@apollo/client/react\";\n\nconst GET_USERS = gql`\n  query GetUsers {\n    users {\n      id\n      name\n      email\n    }\n  }\n`;\n\nfunction UserList() {\n  const { loading, error, data } = useQuery(GET_USERS);\n\n  if (loading) return <p>Loading...</p>;\n  if (error) return <p>Error: {error.message}</p>;\n\n  return (\n    <ul>\n      {data.users.map((user) => (\n        <li key={user.id}>{user.name}</li>\n      ))}\n    </ul>\n  );\n}\n```\n\n## Basic Query Usage\n\n### Using Variables\n\n```tsx\nconst GET_USER = gql`\n  query GetUser($id: ID!) {\n    user(id: $id) {\n      id\n      name\n      email\n    }\n  }\n`;\n\nfunction UserProfile({ userId }: { userId: string }) {\n  const { loading, error, data, dataState } = useQuery(GET_USER, {\n    variables: { id: userId },\n  });\n\n  if (loading) return <p>Loading...</p>;\n  if (error) return <p>Error: {error.message}</p>;\n\n  return <div>{data.user.name}</div>;\n}\n```\n\n> **Note for TypeScript users**: Use [`dataState`](https://www.apollographql.com/docs/react/data/typescript#type-narrowing-data-with-datastate) for more robust type safety and better type narrowing in Apollo Client 4.x.\n\n### TypeScript Integration\n\n```typescript\n// Define types for codegen or TypedDocumentNode\ninterface GetUserData {\n  user: {\n    id: string;\n    name: string;\n    email: string;\n  };\n}\n\ninterface GetUserVariables {\n  id: string;\n}\n\n// Types are inferred from TypedDocumentNode - never use manual generics\nconst GET_USER: TypedDocumentNode<GetUserData, GetUserVariables> = gql`\n  query GetUser($id: ID!) {\n    user(id: $id) {\n      id\n      name\n      email\n    }\n  }\n`;\n\nconst { data } = useQuery(GET_USER, {\n  variables: { id: userId },\n});\n\n// data.user is automatically typed from GET_USER\n```\n\n## Basic Mutation Usage\n\n```tsx\nimport { gql, TypedDocumentNode } from \"@apollo/client\";\nimport { useMutation } from \"@apollo/client/react\";\n\ninterface CreateUserMutation {\n  createUser: {\n    id: string;\n    name: string;\n    email: string;\n  };\n}\n\ninterface CreateUserMutationVariables {\n  input: {\n    name: string;\n    email: string;\n  };\n}\n\nconst CREATE_USER: TypedDocumentNode<\n  CreateUserMutation,\n  CreateUserMutationVariables\n> = gql`\n  mutation CreateUser($input: CreateUserInput!) {\n    createUser(input: $input) {\n      id\n      name\n      email\n    }\n  }\n`;\n\nfunction CreateUserForm() {\n  const [createUser, { loading, error }] = useMutation(CREATE_USER);\n\n  const handleSubmit = async (formData: FormData) => {\n    const { data } = await createUser({\n      variables: {\n        input: {\n          name: formData.get(\"name\") as string,\n          email: formData.get(\"email\") as string,\n        },\n      },\n    });\n    if (data) {\n      console.log(\"Created user:\", data.createUser);\n    }\n  };\n\n  return (\n    <form\n      onSubmit={(e) => {\n        e.preventDefault();\n        handleSubmit(new FormData(e.currentTarget));\n      }}\n    >\n      <input name=\"name\" placeholder=\"Name\" />\n      <input name=\"email\" placeholder=\"Email\" />\n      <button type=\"submit\" disabled={loading}>\n        {loading ? \"Creating...\" : \"Create User\"}\n      </button>\n      {error && <p>Error: {error.message}</p>}\n    </form>\n  );\n}\n```\n\n## Client Configuration Options\n\n```typescript\nconst client = new ApolloClient({\n  // Required: The cache implementation\n  cache: new InMemoryCache({\n    typePolicies: {\n      Query: {\n        fields: {\n          // Field-level cache configuration\n        },\n      },\n    },\n  }),\n\n  // Network layer\n  link: new HttpLink({ uri: \"/graphql\" }),\n\n  // Avoid defaultOptions if possible as they break TypeScript expectations.\n  // Configure options per-query/mutation instead for better type safety.\n  // defaultOptions: {\n  //   watchQuery: { fetchPolicy: ''cache-and-network'' },\n  // },\n\n  // DevTools are enabled by default in development\n  // Only configure when enabling in production\n  devtools: {\n    enabled: true, // Only needed for production\n  },\n\n  // Custom name for this client instance\n  clientAwareness: {\n    name: \"web-client\",\n    version: \"1.0.0\",\n  },\n});\n```\n\n## Reference Files\n\nDetailed documentation for specific topics:\n\n- [Queries](references/queries.md) - useQuery, useLazyQuery, polling, refetching\n- [Mutations](references/mutations.md) - useMutation, optimistic UI, cache updates\n- [Caching](references/caching.md) - InMemoryCache, typePolicies, cache manipulation\n- [State Management](references/state-management.md) - Reactive variables, local state\n- [Error Handling](references/error-handling.md) - Error policies, error links, retries\n- [Troubleshooting](references/troubleshooting.md) - Common issues and solutions\n\n## Key Rules\n\n### Query Best Practices\n\n- **Each page should generally only have one query, composed from colocated fragments.** Use `useFragment` or `useSuspenseFragment` in all non-page-components. Use `@defer` to allow slow fields below the fold to stream in later and avoid blocking the page load.\n- **Fragments are for colocation, not reuse.** Each fragment should describe exactly the data needs of a specific component, not be shared across components for common fields. See [Fragment Colocation](https://www.apollographql.com/docs/react/data/fragments#colocating-fragments).\n- Always handle `loading` and `error` states in UI when using non-suspenseful hooks (`useQuery`, `useLazyQuery`). When using Suspense hooks (`useSuspenseQuery`, `useBackgroundQuery`), React handles this through `<Suspense>` boundaries and error boundaries.\n- Use `fetchPolicy` to control cache behavior per query\n- Use the TypeScript type server to look up documentation for functions and options (Apollo Client has extensive docblocks)\n\n### Mutation Best Practices\n\n- **If the schema permits, mutation return values should return everything necessary to update the cache.** Neither manual updates nor refetching should be necessary.\n- If the mutation response is insufficient, carefully weigh manual cache manipulation vs refetching. Manual updates risk missing server logic. Consider optimistic updates with a granular refetch if needed.\n- Handle errors gracefully in the UI\n- Use `refetchQueries` sparingly (prefer letting the cache update automatically)\n\n### Caching Best Practices\n\n- Configure `keyFields` for types without `id` field\n- Disable normalization by setting `keyFields: false` for types that don''t include an identifier and are meant to group related fields under the parent\n- Use `typePolicies` for pagination and computed fields\n- Understand cache normalization to debug issues\n- **Enable [data masking](https://www.apollographql.com/docs/react/data/fragments#data-masking) for all new applications** - it prevents components from accessing fragment data they don''t own, enforcing proper data boundaries and preventing over-rendering\n\n### Performance\n\n- Avoid over-fetching with proper field selection\n- Configure appropriate `fetchPolicy` per use case\n- Use `@defer` for incremental delivery of deferred query parts, and `@stream` for streaming list fields (`@stream` available in Apollo Client 4.1+)\n- **Prefer Suspense hooks (`useSuspenseQuery`, `useBackgroundQuery`) in modern applications** for better loading state handling and code simplicity\n\n## Ground Rules\n\n- ALWAYS use Apollo Client 4.x patterns (not v3 or earlier)\n- ALWAYS wrap your app with `ApolloProvider`\n- ALWAYS handle loading and error states when using non-suspenseful hooks\n- PREFER Suspense hooks (`useSuspenseQuery`, `useBackgroundQuery`) in modern applications for better DX\n- NEVER store Apollo Client in React state (use module-level or context)\n- PREFER `cache-first` for read-heavy data, `network-only` for real-time data\n- USE TypeScript for better type safety with GraphQL\n- IMPLEMENT proper cache updates instead of refetching entire queries\n- ADVISE the human steering you to look into Apollo DevTools when collaboratively debugging Apollo Client issues\n"},"lastSynced":"2026-03-08T02:03:03.802Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Development Agents needing GraphQL state management in React applications.","zh":"非常适合需要在 React 应用程序中进行 GraphQL 状态管理的前端开发代理。","ja":"React アプリケーションで GraphQL 状態管理が必要なフロントエンド開発エージェントに最適です。","ko":"React 애플리케이션에서 GraphQL 상태 관리가 필요한 프론트엔드 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo Frontend que necesitan administración de estado GraphQL en aplicaciones React.","fr":"Parfait pour les agents de développement Frontend ayant besoin d''une gestion d''état GraphQL dans les applications React.","de":"Perfekt für Frontend-Entwicklungsagenten, die GraphQL-Zustandsverwaltung in React-Anwendungen benötigen.","pt":"Perfeito para agentes de desenvolvimento Frontend que necessitam de gerenciamento de estado GraphQL em aplicações React.","ru":"Идеально подходит для агентов разработки Frontend, требующих управления состоянием GraphQL в приложениях React.","ar":"مثالي للوكلاء الذين يحتاجون إلى إدارة حالة GraphQL في تطبيقات React."},"recommendation":{"en":"Enables comprehensive local and remote data management with GraphQL, providing improved caching mechanisms and React 19 compatibility. Offers specialized Next.js App Router integration for SSR applications with enhanced TypeScript support.","zh":"启用了全面性的本地和远程数据管理，具有改进的缓存机制和 React 19 兼容性。提供了针对 SSR 应用程序的 Next.js App Router 集成，支持增强的 TypeScript。","ja":"ローカルとリモートのデータ管理を包括的に行え、GraphQL を提供し、キャッシュ機構の改善と React 19 との互換性を提供します。SSR アプリケーション用の Next.js App Router 統合を提供し、TypeScript の強化されたサポートを提供します。","ko":"로컬과 원격 데이터 관리를 포괄적으로 수행하며 GraphQL을 제공하고 캐싱 메커니즘의 개선과 React 19 호환성을 제공합니다. SSR 애플리케이션을 위한 Next.js App Router 통합을 제공하며 강화된 TypeScript 지원을 제공합니다.","es":"Habilita una gestión de datos local y remota integral con GraphQL, proporcionando mecanismos de caché mejorados y compatibilidad con React 19. Ofrece integración especializada de Next.js App Router para aplicaciones SSR con compatibilidad mejorada con TypeScript.","fr":"Permet une gestion de données locale et distante complète avec GraphQL, offrant des mécanismes de mise en cache améliorés et une compatibilité avec React 19. Propose une intégration spécialisée de Next.js App Router pour les applications SSR avec une prise en charge améliorée de TypeScript.","de":"Ermöglicht umfassendes lokales und remote Datenmanagement mit GraphQL, mit verbesserten Cachemechanismen und React 19-Kompatibilität. Bietet spezialisierte Next.js App Router-Integration für SSR-Anwendungen mit verbesserter TypeScript-Unterstützung.","pt":"Permite gerenciamento de dados locais e remotos abrangente com GraphQL, fornecendo mecanismos de cache aprimorados e compatibilidade com React 19. Oferece integração especializada do Next.js App Router para aplicações SSR com suporte aprimorado ao TypeScript.","ru":"Позволяет выполнять комплексное управление локальными и удаленными данными с помощью GraphQL, обеспечивая улучшенные механизмы кэширования и совместимость с React 19. Предлагает специализированную интеграцию Next.js App Router для приложений SSR с улучшенной поддержкой TypeScript.","ar":"يمكن إدارة البيانات المحلية والبعيدة بشكل شامل مع GraphQL، وتوفير آليات ذاكرة مؤقتة محسنة ومتوافقة مع React 19. كما يقدم دمجًا متخصصًا لـ Next.js App Router لتنفيذ تطبيقات SSR مع دعم متقدم لـ TypeScript."},"useCases":{"en":["Managing remote GraphQL API data fetching","Handling local state management with GraphQL","Implementing SSR in Next.js applications","Optimizing caching strategies for React apps"],"zh":["管理远程 GraphQL API 数据获取","处理本地状态管理与 GraphQL","在 Next.js 应用程序中实现 SSR","为 React 应用程序优化缓存策略"],"ja":["リモート GraphQL API データ取得の管理","ローカル状態管理と GraphQL の処理","Next.js アプリケーションでの SSR の実装","React アプリケーションのキャッシュ戦略の最適化"],"ko":["원격 GraphQL API 데이터 가져오기 관리","로컬 상태 관리와 GraphQL 처리","Next.js 애플리케이션에서 SSR 구현","React 애플리케이션의 캐싱 전략 최적화"],"es":["Gestión de extracción de datos de API de GraphQL remota","Administración de gestión de estado local con GraphQL","Implementación de SSR en aplicaciones Next.js","Optimización de estrategias de caché para aplicaciones React"],"fr":["Gestion de la récupération de données d''API GraphQL distante","Gestion de l''état local avec GraphQL","Mise en œuvre de SSR dans les applications Next.js","Optimisation des stratégies de mise en cache pour les applications React"],"de":["Verwaltung von Remote-GraphQL-API-Datenabruf","Verwaltung von lokalem Zustandsmanagement mit GraphQL","Implementierung von SSR in Next.js-Anwendungen","Optimierung von Cachestrategien für React-Apps"],"pt":["Gerenciar obtenção de dados de API GraphQL remota","Lidar com gerenciamento de estado local com GraphQL","Implementar SSR em aplicações Next.js","Otimizar estratégias de cache para aplicativos React"],"ru":["Управлять получением данных удаленной API GraphQL","Обрабатывать локальное управление состоянием с помощью GraphQL","Реализовывать SSR в приложениях Next.js","Оптимизировать стратегии кэширования для приложений React"],"ar":["إدارة استرجاع بيانات واجهة برمجة تطبيقات GraphQL البعيدة","معالجة إدارة الحالة المحلية مع GraphQL","تنفيذ SSR في تطبيقات Next.js","تحسين استراتيجيات الذاكرة المؤقتة لتطبيقات React"]},"limitations":{"en":["JavaScript/TypeScript only","Requires GraphQL backend","React framework dependency"],"zh":["仅限 JavaScript/TypeScript","需要 GraphQL 后端","React 框架依赖"],"ja":["JavaScript/TypeScript のみ","GraphQL バックエンドが必要","React フレームワーク依存"],"ko":["JavaScript/TypeScript만","GraphQL 백엔드 필요","React 프레임워크 의존"],"es":["Solo JavaScript/TypeScript","Requiere backend de GraphQL","Dependencia del framework React"],"fr":["Uniquement JavaScript/TypeScript","Nécessite un backend GraphQL","Dépendance du framework React"],"de":["Nur JavaScript/TypeScript","Benötigt GraphQL-Backend","React-Framework-Abhängigkeit"],"pt":["Apenas JavaScript/TypeScript","Requer backend GraphQL","Dependência do framework React"],"ru":["Только JavaScript/TypeScript","Требуется backend GraphQL","Зависимость от фреймворка React"],"ar":["فقط JavaScript/TypeScript","يتطلب backend GraphQL","اعتماد على إطار React"]},"version":4},"contentHash":"eed94d5d00ae06c79a59d1f1d97b9f93e4307763b3da59a37891999082dfc8a8","qualityScore":47}');
