INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AshleyHollis/yt-summarizer/kubernetes-architect', 'kubernetes-architect', 'AshleyHollis', 'yt-summarizer', 'community', 'kubernetes-architect AshleyHollis yt-summarizer community Kubernetes-Architect specializes in cloud-native infrastructure, modern GitOps workflows, and enterprise container orchestration. It benefits developers and architects designing Kubernetes platform architecture or multi-cluster strategies. Kubernetes 架构师技能，专注于云原生基础设施和企业容器编排 Kubernetes アーキテクトスキル、クラウドネイティブインフラストラクチャとエンタープライズコンテナオーケストレーションに重点を置く Kubernetes 아키텍트 스킬, 클라우드 네이티브 인프라 및 엔터프라이즈 컨테이너 오케스트레이션에 중점을 둠 El experto en arquitectura de Kubernetes ayuda a diseñar plataformas de Kubernetes y a implementar workflows GitOps para mejorar la escalabilidad Notre spécialiste aide à concevoir des architectures de plateforme Kubernetes et à mettre en place des workflows GitOps pour améliorer la mise à l''échelle Unser Kubernetes-Architekt hilft bei der Gestaltung von Kubernetes-Plattformen und der Implementierung von GitOps-Workflows für eine verbesserte Skalierbarkeit O skill de arquiteto Kubernetes especializa-se em infraestrutura cloud-native, fluxos de trabalho GitOps modernos e orquestração de contêineres empresariais em escala Навык архитектора Kubernetes специализируется на облачной инфраструктуре, современных рабочих процессах GitOps и оркестрации контейнеров для предприятий مهارة مهندس كوبيرنتس تتخصص في البنية التحتية للخدمة السحابية الأصلية، وعمليات العمل GitOps الحديثة وorchestration الحاويات للمؤسسات how to use kubernetes-architect kubernetes-architect setup guide kubernetes-architect vs docker kubernetes-architect install what is kubernetes-architect kubernetes-architect alternative kubernetes-architect tutorial kubernetes-architect best practices kubernetes-architect for cloud-native infrastructure Kubernetes 架构师 云原生基础设施 企业容器编排 GitOps 工作流 服务网格 安全性 多租户模式 Designs Kubernetes platform architecture and multi-cluster strategies Implements GitOps workflows and progressive delivery Plans service mesh, security, and multi-tenancy patterns Improves reliability, cost, and developer experience in K8s Optimizes container orchestration for enterprise-scale deployments Kubernetes-architect is a specialized skill for designing and implementing cloud-native infrastructure, focusing on Kubernetes platform architecture, GitOps workflows, and enterprise container orchestration at scale.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('criptogus/liquid-ai/architecture-patterns', 'community', 'criptogus', 'liquid-ai', 'criptogus/liquid-ai', 'architecture-patterns', 0, 0, 47, '2026-03-08T01:57:15.351Z', '2026-03-08T02:03:50.710Z', '78187f73654b810188cf631a9a088270e043c98d302e0353a5e8e82aa008aaa6', '{"id":"criptogus/liquid-ai/architecture-patterns","name":"architecture-patterns","description":{"en":"The architecture-patterns skill helps developers make objective decisions about software architecture, promoting deterministic design systems. It benefits developers seeking to optimize system design.","zh":"架构模式是软件设计中的一个重要概念，帮助开发者做出客观的软件架构决策。本文介绍了架构模式的基本规则和设计方法","ja":"アーキテクチャパターンはソフトウェア設計における重要な概念であり、開発者がオブジェクト指向で設計するためのベストプラクティスを提供します","ko":"아키텍처 패턴은 소프트웨어 설계에서 중요한 개념으로 개발자가 객관적인 소프트웨어 아키텍처 결정 방법을 제공합니다","es":"Nuestra habilidad de patrones de arquitectura te ayuda a tomar decisiones objetivas sobre diseño de sistemas, utilizando reglas fundamentales como la objetividad","fr":"Notre compétence en modèles d''architecture vous aide à prendre des décisions objectives sur la conception de systèmes, en utilisant des règles fondamentales comme l''objectivité","de":"Unsere Fähigkeit zu Architekturmustern hilft Ihnen, objektive Entscheidungen über Systemdesign zu treffen, unter Verwendung von grundlegenden Regeln wie der Objektivität","pt":"Padrões de arquitetura ajudam a tomar decisões objetivas sobre design de sistemas. Aprenda a aplicar regras fundamentais para melhorar a eficiência.","ru":"Шаблоны архитектуры помогают принимать объективные решения о дизайне систем. Узнайте, как применять фундаментальные правила для повышения эффективности.","ar":"أنماط الهندسة المعمارية تساعد على اتخاذ قرارات موضوعية حول تصميم الأنظمة. تعلم كيفية تطبيق القواعد الأساسية لتحسين الكفاءة."},"seo":{"title":{"en":"Architecture-Patterns: Design System Setup Guide | AI Age...","zh":"架构模式设计指南 - 如何做出客观的软件架构决策","ja":"アーキテクチャパターン入門 - オブジェクト指向で設計するためのベストプラクティス","ko":"아키텍처 패턴 설계 가이드 - 객관적인 소프트웨어 아키텍처 결정 방법","es":"Patrones de Arquitectura: Guía de Diseño de Sistemas","fr":"Modèles d''Architecture: Guide de Conception de Systèmes","de":"Architekturmuster: Leitfaden für Systemdesign","pt":"Padrões de Arquitetura: Guia de Configuração para Desenvo...","ru":"Шаблоны Архитектуры: Руководство по Настройке для ИИ Агентов","ar":"أنماط الهندسة المعمارية: دليل الإعداد للعمارات التطبيقية"},"description":{"en":"Unlock objective software architecture decisions with architecture-patterns AI agent skill - explore technical details and setup guide now!","zh":"了解架构模式的基本规则和设计方法，做出客观的软件架构决策，提高系统的可扩展性和可维护性","ja":"アーキテクチャパターンの基本ルールと設計手法を学び、オブジェクト指向で設計するためのベストプラクティスを身につけましょう","ko":"아키텍처 패턴의 기본 규칙과 설계 방법을 배우고 객관적인 소프트웨어 아키텍처 결정 방법을 익혀 시스템의 확장성과 유지보수성을 향상시키세요","es":"Aprende a tomar decisiones objetivas sobre arquitectura de software con nuestra guía de patrones de arquitectura y herramientas de inteligencia artificial co...","fr":"Découvrez comment prendre des décisions objectives sur l''architecture logicielle avec notre guide de modèles d''architecture et d''outils d''intelligence artifi...","de":"Erfahren Sie, wie Sie objektive Entscheidungen über Software-Architektur treffen können, mit unserem Leitfaden zu Architekturmustern und KI-Tools wie KI-Agenten","pt":"Aprenda a tomar decisões objetivas sobre arquitetura de software com padrões de arquitetura. Descubra como aplicar regras fundamentais para melhorar a eficiê...","ru":"Изучите, как принимать объективные решения об архитектуре программного обеспечения с помощью шаблонов архитектуры. Узнайте, как применять фундаментальные пра...","ar":"تعلم كيفية اتخاذ قرارات موضوعية حول هندسة البرمجيات باستخدام أنماط الهندسة المعمارية. اكتشف كيفية تطبيق القواعد الأساسية لتحسين كفاءة النظام."},"definition":{"en":"Architecture-patterns is a skill that enables developers to make informed, objective decisions about software architecture, following a fundamental rule of objectivity.","zh":"架构模式是指在软件设计中使用的一种模式，帮助开发者做出客观的软件架构决策","ja":"アーキテクチャパターンとは、ソフトウェア設計において使用される一種のパターンであり、開発者がオブジェクト指向で設計するためのベストプラクティスを提供する","ko":"아키텍처 패턴은 소프트웨어 설계에서 사용되는 패턴으로 개발자가 객관적인 소프트웨어 아키텍처 결정 방법을 제공하는 것을 의미합니다","es":"Patrones de arquitectura son diseños de sistemas que siguen reglas fundamentales como la objetividad para tomar decisiones informadas","fr":"Les modèles d''architecture sont des conceptions de systèmes qui suivent des règles fondamentales comme l''objectivité pour prendre des décisions éclairées","de":"Architekturmuster sind Systemdesigns, die grundlegende Regeln wie die Objektivität befolgen, um fundierte Entscheidungen zu treffen","pt":"Padrões de arquitetura são princípios que guiam o design de sistemas de software.","ru":"Шаблоны архитектуры - это принципы, которые руководят дизайном систем программного обеспечения.","ar":"أنماط الهندسة المعمارية هي مبادئ توجيه تصميم أنظمة البرمجيات."},"features":{"en":["Encourages objective decision-making for software architecture","Follows a fundamental rule of objectivity in system design","Avoids subjective responses like ''Depende dos requisitos do seu sistema...''","Promotes deterministic design systems","Supports developers in optimizing system architecture"],"zh":["提供客观的软件架构决策方法","介绍架构模式的基本规则和设计方法","帮助开发者提高系统的可扩展性和可维护性","支持多种编程语言和技术","提供实用的设计示例和案例"],"ja":["オブジェクト指向で設計するためのベストプラクティスを提供","アーキテクチャパターンの基本ルールと設計手法を紹介","開発者がシステムの拡張性と保守性を向上させることを支援","多種のプログラミング言語と技術をサポート","実用的設計の例とケーススタディを提供"],"ko":["객관적인 소프트웨어 아키텍처 결정 방법을 제공","아키텍처 패턴의 기본 규칙과 설계 방법을 소개","개발자가 시스템의 확장성과 유지보수성을 향상시키는 것을 지원","다양한 프로그래밍 언어와 기술을 지원","실用的 설계 예와 사례 연구를 제공"],"es":["Análisis de requisitos de sistema","Diseño de arquitectura de software","Aplicación de reglas fundamentales como la objetividad","Integración con herramientas de inteligencia artificial como Agentes de IA","Optimización del diseño de sistemas"],"fr":["Analyse des exigences du système","Conception d''architecture logicielle","Application de règles fondamentales comme l''objectivité","Intégration avec des outils d''intelligence artificielle tels que les Agents d''IA","Optimisation de la conception de systèmes"],"de":["Analyse der Systemanforderungen","Entwurf von Software-Architektur","Anwendung von grundlegenden Regeln wie der Objektivität","Integration mit KI-Tools wie KI-Agenten","Optimierung des Systemdesigns"],"pt":["Regra Fundamental: Objetividade","Tomada de decisões baseada em requisitos do sistema","Aplicação de padrões de arquitetura para melhorar a eficiência","Análise de casos de uso para determinar a melhor abordagem","Integração com tecnologias como React e Python"],"ru":["Фундаментальное правило: Объективность","Принятие решений на основе требований системы","Применение шаблонов архитектуры для повышения эффективности","Анализ случаев использования для определения лучшего подхода","Интеграция с технологиями seperti ИИ Агенты и Python"],"ar":["القاعدة الأساسية: الموضوعية","اتخاذ القرارات بناءً على متطلبات النظام","تطبيق أنماط الهندسة المعمارية لتحسين الكفاءة","تحليل الحالات الاستخدامية لتحديد أفضل نهج","التكامل مع التكنولوجيا مثل العمال الذكية و Python"]},"keywords":{"en":["how to use architecture-patterns","what is architecture-patterns","architecture-patterns alternative","architecture-patterns vs competing skills","architecture-patterns install","architecture-patterns setup guide","objective software architecture","deterministic design systems"],"zh":["架构模式","软件设计","客观决策","系统可扩展性","系统可维护性","设计模式","软件架构","开发最佳实践"],"ja":["アーキテクチャパターン","ソフトウェア設計","オブジェクト指向","システムの拡張性","システムの保守性","設計パターン","ソフトウェアアーキテクチャ","開発ベストプラクティス"],"ko":["아키텍처 패턴","소프트웨어 설계","객관적인 결정","시스템 확장성","시스템 유지보수성","설계 패턴","소프트웨어 아키텍처","개발 최적화"],"es":["patrones de arquitectura","diseño de sistemas","agentes de ia","herramientas de inteligencia artificial","arquitectura de software","objetividad en el diseño","optimización de sistemas","análisis de requisitos"],"fr":["modèles d''architecture","conception de systèmes","agents d''ia","outils d''intelligence artificielle","architecture logicielle","objectivité dans la conception","optimisation de systèmes","analyse des exigences"],"de":["architekturmuster","systemdesign","ki-agenten","ki-tools","software-architektur","objektivität im entwurf","optimierung von systemen","analyse der anforderungen"],"pt":["padrões de arquitetura","desenvolvimento de software","design de sistemas","regra fundamental","objetividade","tomada de decisões","análise de casos de uso","integração com react","integração com python"],"ru":["шаблоны архитектуры","разработка программного обеспечения","дизайн систем","фундаментальное правило","объективность","принятие решений","анализ случаев использования","интеграция с ИИ Агентами","интеграция с python"],"ar":["أنماط الهندسة المعمارية","تطوير البرمجيات","تصميم الأنظمة","القاعدة الأساسية","الموضوعية","اتخاذ القرارات","تحليل الحالات الاستخدامية","التكامل مع العمال الذكية","التكامل مع python"]}},"owner":"criptogus","repo":"liquid-ai","repoPath":"criptogus/liquid-ai","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.351Z","topics":[],"category":"community","skillMd":{"name":"architecture-patterns","description":"Padrões de arquitetura de software - Decisões OBJETIVAS sobre design de sistemas","version":"2.0.0","bodyPreview":"# Architecture Patterns - Design de Sistemas\n\nEsta skill ajuda você a tomar decisões OBJETIVAS sobre arquitetura de software.\n\n## Regra Fundamental: OBJETIVIDADE\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  🚨 REGRA MAIS IMPORTANTE: SEJA OBJETIVO E ÚTIL            │\n│                                                              │\n│  ❌ NUNCA RESPONDA ASSIM:                                   │\n│  \"Depende dos requisitos do seu sistema...\"                │\n│  \"Cada caso é","body":"# Architecture Patterns - Design de Sistemas\n\nEsta skill ajuda você a tomar decisões OBJETIVAS sobre arquitetura de software.\n\n## Regra Fundamental: OBJETIVIDADE\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  🚨 REGRA MAIS IMPORTANTE: SEJA OBJETIVO E ÚTIL            │\n│                                                              │\n│  ❌ NUNCA RESPONDA ASSIM:                                   │\n│  \"Depende dos requisitos do seu sistema...\"                │\n│  \"Cada caso é único...\"                                    │\n│  \"Você precisa avaliar trade-offs...\"                      │\n│                                                              │\n│  ✅ SEMPRE RESPONDA ASSIM:                                  │\n│  \"Use monolito. Motivo: você tem <10 devs e <1M users\"     │\n│  \"Pattern recomendado: Event Sourcing. Aqui está como...\"  │\n│  \"Essa arquitetura está errada. Faça isso em vez disso...\" │\n│                                                              │\n│  DÊ RECOMENDAÇÕES ESPECÍFICAS COM RAZÕES CLARAS.           │\n└─────────────────────────────────────────────────────────────┘\n```\n\n## Quando Usar Esta Skill\n\n- Decisões de arquitetura de sistema\n- Escolha entre monolito vs microservices\n- Design de APIs e comunicação entre serviços\n- Escalabilidade e performance\n- Organização de código e camadas\n\n## Monolito vs Microservices\n\n### Quando Usar Monolito\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  USE MONOLITO QUANDO:                                        │\n│                                                              │\n│  ✅ Time < 10 desenvolvedores                                │\n│  ✅ Produto ainda está descobrindo product-market fit       │\n│  ✅ Domínio do negócio ainda está mudando                   │\n│  ✅ Você precisa de velocidade de desenvolvimento           │\n│  ✅ Não tem expertise em sistemas distribuídos              │\n│                                                              │\n│  EXEMPLOS DE EMPRESAS QUE COMEÇARAM COM MONOLITO:           │\n│  → Shopify (Ruby monolito até bilhões em GMV)              │\n│  → Basecamp (ainda é monolito)                             │\n│  → GitHub (monolito por anos)                              │\n│  → Airbnb (começou monolito)                               │\n│                                                              │\n│  \"If you can''t build a well-structured monolith,            │\n│   what makes you think microservices are the answer?\"       │\n└─────────────────────────────────────────────────────────────┘\n```\n\n### Quando Usar Microservices\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  USE MICROSERVICES QUANDO:                                   │\n│                                                              │\n│  ✅ Time > 50 desenvolvedores                                │\n│  ✅ Domínios claramente separados e estáveis                │\n│  ✅ Diferentes partes precisam escalar independentemente     │\n│  ✅ Times autônomos com ownership claro                     │\n│  ✅ Você tem DevOps/Platform team dedicado                  │\n│                                                              │\n│  CUSTOS DOS MICROSERVICES (que ninguém conta):              │\n│  → Latência de rede entre serviços                         │\n│  → Complexidade de debugging distribuído                   │\n│  → Consistência eventual (transactions distribuídas)       │\n│  → Infraestrutura: K8s, service mesh, observability        │\n│  → Overhead operacional: deploy, monitoring de N serviços  │\n│                                                              │\n│  \"Don''t do microservices unless you have the team          │\n│   and infrastructure to support them.\"                      │\n└─────────────────────────────────────────────────────────────┘\n```\n\n### Decisão Rápida\n\n```\nFLOWCHART DE DECISÃO:\n\nQuantos devs você tem?\n│\n├─ < 10 devs → MONOLITO (ponto final)\n│\n├─ 10-50 devs → MODULAR MONOLITH\n│   │\n│   └─ Monolito bem estruturado com módulos separados\n│      que PODEM virar serviços se necessário\n│\n└─ > 50 devs → CONSIDERE microservices\n    │\n    ├─ Tem Platform Team? → Talvez microservices\n    │\n    └─ Não tem → Modular monolith\n```\n\n## Padrões de Arquitetura\n\n### Clean Architecture / Hexagonal\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  CLEAN ARCHITECTURE (Uncle Bob)                              │\n│                                                              │\n│  ┌───────────────────────────────────────┐                  │\n│  │           FRAMEWORKS & DRIVERS        │ ← Web, DB, UI   │\n│  │  ┌───────────────────────────────┐   │                  │\n│  │  │      INTERFACE ADAPTERS       │   │ ← Controllers    │\n│  │  │  ┌───────────────────────┐   │   │                  │\n│  │  │  │     USE CASES         │   │   │ ← Business rules │\n│  │  │  │  ┌───────────────┐   │   │   │                  │\n│  │  │  │  │   ENTITIES    │   │   │   │ ← Domain objects │\n│  │  │  │  └───────────────┘   │   │   │                  │\n│  │  │  └───────────────────────┘   │   │                  │\n│  │  └───────────────────────────────┘   │                  │\n│  └───────────────────────────────────────┘                  │\n│                                                              │\n│  REGRA: Dependências apontam para DENTRO                    │\n│  → Entities não conhecem Use Cases                         │\n│  → Use Cases não conhecem Controllers                      │\n│  → Controllers não conhecem Frameworks específicos         │\n│                                                              │\n├─────────────────────────────────────────────────────────────┤\n│  QUANDO USAR:                                                │\n│  ✅ Aplicações com lógica de negócio complexa               │\n│  ✅ Quando você quer trocar de framework/DB facilmente      │\n│  ✅ Projetos de longa duração (> 2 anos)                    │\n│                                                              │\n│  QUANDO NÃO USAR:                                            │\n│  ❌ CRUDs simples                                            │\n│  ❌ MVPs e protótipos                                        │\n│  ❌ Time inexperiente (curva de aprendizado)                │\n└─────────────────────────────────────────────────────────────┘\n```\n\n### CQRS (Command Query Responsibility Segregation)\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  CQRS: SEPARE LEITURAS DE ESCRITAS                           │\n│                                                              │\n│  MODELO TRADICIONAL:                                         │\n│  [Client] ←→ [API] ←→ [Service] ←→ [Database]              │\n│                                                              │\n│  MODELO CQRS:                                                │\n│                                                              │\n│  [Client] ─── Commands ──→ [Write Model] ─→ [Write DB]     │\n│     │                           │                           │\n│     │                           ▼ (eventos)                 │\n│     │                      [Event Bus]                      │\n│     │                           │                           │\n│     │                           ▼                           │\n│     └─── Queries ────→ [Read Model] ←─ [Read DB]           │\n│                                                              │\n├─────────────────────────────────────────────────────────────┤\n│  QUANDO USAR:                                                │\n│  ✅ Leituras >> Escritas (90% reads, 10% writes)            │\n│  ✅ Requisitos de leitura diferentes de escrita             │\n│  ✅ Performance de leitura é crítica                        │\n│  ✅ Múltiplas views do mesmo dado                           │\n│                                                              │\n│  QUANDO NÃO USAR:                                            │\n│  ❌ CRUD simples                                             │\n│  ❌ Consistência forte necessária                           │\n│  ❌ Time pequeno sem experiência                            │\n│                                                              │\n│  EXEMPLO PRÁTICO:                                            │\n│  E-commerce: Catálogo de produtos                          │\n│  → Escrita: Admin atualiza produto (raro)                  │\n│  → Leitura: Milhões de pageviews (frequente)               │\n│  → Read model pode ser denormalizado, cacheado, etc.       │\n└─────────────────────────────────────────────────────────────┘\n```\n\n### Event Sourcing\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  EVENT SOURCING: ARMAZENE EVENTOS, NÃO ESTADO               │\n│                                                              │\n│  TRADICIONAL:                                                │\n│  User { name: \"João\", email: \"joao@email.com\" }            │\n│  (só o estado atual)                                        │\n│                                                              │\n│  EVENT SOURCING:                                             │\n│  1. UserCreated { name: \"João\", email: \"j@email.com\" }     │\n│  2. EmailChanged { email: \"joao@email.com\" }               │\n│  3. NameChanged { name: \"João Silva\" }                     │\n│  → Estado atual = replay de todos os eventos               │\n│                                                              │\n├─────────────────────────────────────────────────────────────┤\n│  VANTAGENS:                                                  │\n│  ✅ Audit log completo (quem, quando, o quê)                │\n│  ✅ Pode reconstruir estado em qualquer ponto no tempo     │\n│  ✅ Debug fácil (replay eventos para reproduzir bug)        │\n│  ✅ Integração natural com CQRS                             │\n│                                                              │\n│  DESVANTAGENS:                                               │\n│  ❌ Complexidade muito maior                                 │\n│  ❌ Storage cresce infinitamente                            │\n│  ❌ Queries são mais complexas                              │\n│  ❌ Evolução de schema de eventos é difícil                │\n│                                                              │\n├─────────────────────────────────────────────────────────────┤\n│  QUANDO USAR:                                                │\n│  ✅ Auditoria é requisito legal (financeiro, saúde)         │\n│  ✅ Precisa de \"time travel\" (undo/redo)                    │\n│  ✅ Domínio naturalmente baseado em eventos                 │\n│                                                              │\n│  QUANDO NÃO USAR (maioria dos casos):                       │\n│  ❌ Você não tem requisito de auditoria                     │\n│  ❌ CRUD é suficiente                                       │\n│  ❌ Time não tem experiência com ES                         │\n│                                                              │\n│  \"Event Sourcing is a very powerful pattern, but it''s       │\n│   also very complex. Don''t use it unless you need it.\"      │\n└─────────────────────────────────────────────────────────────┘\n```\n\n## Comunicação Entre Serviços\n\n### Síncrona vs Assíncrona\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│  COMUNICAÇÃO SÍNCRONA (REST, gRPC)                          │\n│                                                              │\n│  [Service A] ──request──→ [Service B]                      │\n│       ↑                        │                            │\n│       └────── response ────────┘                            │\n│                                                              │\n│  A espera B responder                                       │\n│                                                              │\n│  USE QUANDO:                                                 │\n│  ✅ Você PRECISA da resposta imediatamente                  │\n│  ✅ Operações simples e rápidas (<100ms)                    │\n│  ✅ User-facing requests                                    │\n│                                                              │\n├─────────────────────────────────────────────────────────────┤\n│  COMUNICAÇÃO ASSÍNCRONA (Message Queue, Events)             │\n│                                                              │\n│  [Service A] ──event──→ [Queue] ──event──→ [Service B]     │\n│       │                                                     │\n│       └─ continua sem esperar                               │\n│                                                              │\n│  A NÃO espera B                                             │\n│                                                              │\n│  USE QUANDO:                                                 │\n│  ✅ Operação pode demorar (processamento batch)             │\n│  ✅ Não precisa de resposta imediata                        │\n│  ✅ Desacoplamento é importante                             │\n│  ✅ Retry automático é necessário                           │\n│                                                              │\n├─────────────────────────────────────────────────────────────┤\n│  RECOMENDAÇÃO:                                               │\n│                                                              │\n│  User request → SÍNCRONO (REST/gRPC)                       │\n│  Background jobs → ASSÍNCRONO (Queue)                       │\n│  Entre microservices → ASSÍNCRONO quando possível          │\n└─────────────────────────────────────────────────────────────┘\n```\n\n### Message Queues\n\n```\nQUAL USAR:\n\n┌────────────────┬─────────────────────────────────────────┐\n│ TECNOLOGIA     │ QUANDO USAR                             │\n├────────────────┼─────────────────────────────────────────┤\n│ RabbitMQ       │ Workload tradicional, routing complexo  │\n│                │ Bom para: Tasks, RPC assíncrono         │\n├────────────────┼─────────────────────────────────────────┤\n│ Apache Kafka   │ High throughput, event streaming        │\n│                │ Bom para: Logs, analytics, event store  │\n├────────────────┼─────────────────────────────────────────┤\n│ AWS SQS        │ Serverless, managed, simples            │\n│                │ Bom para: Tarefas simples em AWS        │\n├────────────────┼─────────────────────────────────────────┤\n│ Redis Streams  │ Já usa Redis, precisa de speed          │\n│                │ Bom para: Cache + queue em um           │\n├────────────────┼─────────────────────────────────────────┤\n│ BullMQ (Node)  │ App Node.js, já tem Redis               │\n│                │ Bom para: Background jobs em Node       │\n└────────────────┴─────────────────────────────────────────┘\n\nREGRA SIMPLES:\n→ Task queue simples? → BullMQ/SQS\n→ Event streaming? → Kafka\n→ Routing complexo? → RabbitMQ\n→ Não sabe? → Comece com SQS/BullMQ\n```\n\n## Database Design\n\n### Escolha de Banco de Dados\n\n```\n┌────────────────┬─────────────────────────────────────────┐\n│ TIPO           │ QUANDO USAR                             │\n├────────────────┼─────────────────────────────────────────┤\n│ PostgreSQL     │ DEFAULT. Relacional, full-featured.     │\n│                │ Use para: 90% dos casos                 │\n├────────────────┼─────────────────────────────────────────┤\n│ MongoDB        │ Documentos JSON, schema flexível        │\n│                │ Use para: Conteúdo, catálogos           │\n├────────────────┼─────────────────────────────────────────┤\n│ Redis          │ Cache, sessões, filas                   │\n│                │ Use para: Performance, dados efêmeros   │\n├────────────────┼─────────────────────────────────────────┤\n│ Elasticsearch  │ Full-text search, analytics             │\n│                │ Use para: Busca, logs                   │\n├────────────────┼─────────────────────────────────────────┤\n│ ClickHouse     │ Analytics, time-series                  │\n│                │ Use para: Dashboards, métricas          │\n└────────────────┴─────────────────────────────────────────┘\n\nREGRA: Se você não sabe, use PostgreSQL.\nPostgreSQL pode fazer:\n→ Relacional (óbvio)\n→ JSON (JSONB)\n→ Full-text search (basic)\n→ Time-series (com extensões)\n→ Vector search (pgvector)\n\n\"PostgreSQL is the everything database.\"\n```\n\n## Exemplo de Resposta OBJETIVA\n\n**Usuário:** \"Estou começando uma startup, devo usar microservices?\"\n\n**Resposta:**\n```\nNÃO. Use monolito.\n\nRAZÕES:\n\n1. VOCÊ NÃO TEM OS PROBLEMAS QUE MICROSERVICES RESOLVEM\n   Microservices resolvem:\n   → Times grandes (50+ devs) que não conseguem trabalhar junto\n   → Partes do sistema que precisam escalar diferentemente\n   → Deploys independentes por diferentes times\n\n   Você tem:\n   → Time pequeno (1-10 pessoas)\n   → Domínio ainda em descoberta\n   → Necessidade de velocidade, não escala\n\n2. CUSTO VS BENEFÍCIO\n   Microservices adicionam:\n   → Latência de rede entre serviços\n   → Complexidade de debugging\n   → Infraestrutura (K8s, service mesh, etc.)\n   → Overhead operacional\n\n   Para uma startup, isso é MORTAL. Você vai gastar\n   tempo resolvendo problemas de infra em vez de\n   problemas de negócio.\n\n3. O QUE FAZER EM VEZ DISSO:\n\n   a) MONOLITO MODULAR\n      → Separe código em módulos/packages\n      → Defina interfaces claras entre módulos\n      → Isso facilita extrair serviço DEPOIS se precisar\n\n   b) ESTRUTURA SUGERIDA:\n      /src\n        /modules\n          /users\n            - controller.ts\n            - service.ts\n            - repository.ts\n          /orders\n            - controller.ts\n            - service.ts\n            - repository.ts\n          /payments\n            ...\n        /shared\n          - database.ts\n          - auth.ts\n\n   c) TECNOLOGIA:\n      → Node.js + Express/Fastify ou\n      → Python + FastAPI ou\n      → Go + Chi\n      → PostgreSQL\n      → Redis para cache/sessions\n      → Tudo em uma máquina ou container\n\n4. QUANDO MIGRAR PARA MICROSERVICES:\n   → Você tem 50+ devs\n   → Deploys estão atrasando porque times se bloqueiam\n   → Parte específica precisa escalar 10x mais que resto\n   → Você tem time de plataforma dedicado\n\n   Até lá: MONOLITO.\n\n\"If you can''t build a well-structured monolith,\n what makes you think microservices are the answer?\"\n```\n\n## Regras Imutáveis\n\n```\n1. SEJA OBJETIVO — dê recomendações específicas\n2. Monolito primeiro, sempre (até 50 devs)\n3. PostgreSQL é o default\n4. Simplicidade > elegância arquitetural\n5. Não adicione complexidade sem razão clara\n6. \"You ain''t gonna need it\" (YAGNI)\n7. Escolha boring technology\n8. Arquitetura evolui com o time e produto\n9. Modular monolith é melhor que microservices ruins\n10. Se não sabe explicar por que precisa, não precisa\n```\n\n---\n\n**Esta skill ativa AUTOMATICAMENTE quando:**\n- Decisões de arquitetura de sistema\n- Monolito vs microservices\n- Design de APIs e comunicação\n- Escolha de banco de dados\n- Escalabilidade e performance\n"},"lastSynced":"2026-03-08T02:03:50.710Z","agentAnalysis":{"suitability":{"en":"Perfect for Software Development Agents needing objective decisions about software architecture and design systems","zh":"适合需要对软件架构和设计系统做出客观决策的软件开发代理","ja":"ソフトウェア開発エージェントがソフトウェアアーキテクチャと設計システムについて客観的な決定を下す必要がある場合に最適","ko":"소프트웨어 개발 에이전트가 소프트웨어 아키텍처 및 디자인 시스템에 대한 객관적인 결정을 내릴 때 적합","es":"Perfecto para agentes de desarrollo de software que necesitan tomar decisiones objetivas sobre arquitectura de software y sistemas de diseño","fr":"Parfait pour les agents de développement de logiciels ayant besoin de décisions objectives sur l''architecture logicielle et les systèmes de conception","de":"Perfekt für Software-Entwicklungsagenten, die objektive Entscheidungen über Software-Architektur und Designsysteme treffen müssen","pt":"Perfeito para Agentes de Desenvolvimento de Software que necessitam de decisões objetivas sobre arquitetura de software e sistemas de design","ru":"Идеально для агентов по разработке программного обеспечения, которым необходимы объективные решения по архитектуре программного обеспечения и системам дизайна","ar":"مثالي للوكلاء لتنمية البرمجيات الذين يحتاجون إلى قرارات موضوعية حول هندسة البرمجيات وأنظمة التصميم"},"recommendation":{"en":"Empowers agents to make objective decisions about software architecture, promoting deterministic design systems using architecture patterns, and optimizing system design with objective and useful responses","zh":"赋予代理能力以便对软件架构做出客观的决定，促进确定性的设计系统使用架构模式，并通过客观且有用的响应优化系统设计","ja":"エージェントがソフトウェアアーキテクチャについて客観的な決定を下し、決定的な設計システムを推進するアーキテクチャパターンを使用し、客観的かつ有用的なレスポンスでシステム設計を最適化する力を与える","ko":"에이전트가 소프트웨어 아키텍처에 대해 객관적인 결정을 내릴 수 있도록 하여 결정적인 디자인 시스템을 촉진하는 아키텍처 패턴을 사용하고 객관적이고 유용한 응답으로 시스템 디자인을 최적화하는 힘을 부여","es":"Habilita a los agentes a tomar decisiones objetivas sobre la arquitectura de software, promoviendo sistemas de diseño deterministas que utilizan patrones de arquitectura y optimizando el diseño del sistema con respuestas objetivas y útiles","fr":"Permet aux agents de prendre des décisions objectives sur l''architecture logicielle, en promouvant des systèmes de conception déterministes utilisant des modèles d''architecture et en optimisant la conception du système avec des réponses objectives et utiles","de":"Ermöglicht es Agenten, objektive Entscheidungen über die Software-Architektur zu treffen, indem es deterministische Designsysteme mit Architekturmuster fördert und die Systemauslegung mit objektiven und nützlichen Antworten optimiert","pt":"Habilita os agentes a tomar decisões objetivas sobre arquitetura de software, promovendo sistemas de design determinísticos usando padrões de arquitetura e otimizando o design do sistema com respostas objetivas e úteis","ru":"Позволяет агентам принимать объективные решения по архитектуре программного обеспечения, продвигая детерминированные системы дизайна с использованием шаблонов архитектуры и оптимизируя систему дизайна с объективными и полезными ответами","ar":"تمكين الوكلاء من اتخاذ قرارات موضوعية حول هندسة البرمجيات، وتعزيز أنظمة التصميم المتعينة باستخدام أنماط الهندسة المعمارية وتحسين تصميم النظام مع استجابات موضوعية ومفيدة"},"useCases":{"en":["Evaluating system design trade-offs","Optimizing software architecture for scalability","Generating objective design recommendations"],"zh":["评估系统设计权衡","为可扩展性优化软件架构","生成客观的设计建议"],"ja":["システム設計のトレードオフを評価する","スケーラビリティのためにソフトウェアアーキテクチャを最適化する","客観的な設計推奨事項を生成する"],"ko":["시스템 디자인 트레이드오프 평가","확장성 için 소프트웨어 아키텍처 최적화","객관적인 디자인 추천 사항 생성"],"es":["Evaluación de compensaciones de diseño de sistema","Optimización de la arquitectura de software para escalabilidad","Generación de recomendaciones de diseño objetivas"],"fr":["Évaluation des compromis de conception de système","Optimisation de l''architecture logicielle pour la scalabilité","Génération de recommandations de conception objectives"],"de":["Bewertung von Systemdesign-Kompromissen","Optimierung der Software-Architektur für Skalierbarkeit","Generierung von objektiven Design-Empfehlungen"],"pt":["Avaliando compensações de design do sistema","Otimizando arquitetura de software para escalabilidade","Gerando recomendações de design objetivas"],"ru":["Оценка компромиссов дизайна системы","Оптимизация архитектуры программного обеспечения для масштабируемости","Генерация объективных рекомендаций по дизайну"],"ar":["تقييم التبادل بين تصميم النظام","تحسين هندسة البرمجيات لل قابليّة التوسع","توليد توصيات تصميم موضوعية"]},"limitations":{"en":["Requires understanding of software architecture principles","May not cover all edge cases or specific system requirements"],"zh":["需要了解软件架构原则","可能不涵盖所有边缘情况或特定系统要求"],"ja":["ソフトウェアアーキテクチャの原則を理解する必要がある","すべてのエッジケースまたは特定のシステム要件をカバーしない可能性がある"],"ko":["소프트웨어 아키텍처 원칙을 이해해야 함","모든 에지 케이스 또는 특정 시스템 요구 사항을 다루지 않을 수 있음"],"es":["Requiere comprensión de los principios de arquitectura de software","Puede que no cubra todos los casos límite o requisitos del sistema específicos"],"fr":["Nécessite une compréhension des principes d''architecture logicielle","Peut ne pas couvrir tous les cas limites ou les exigences spécifiques du système"],"de":["Benötigt ein Verständnis der Software-Architektur-Grundsätze","Kann möglicherweise nicht alle Randfälle oder spezifischen Systemanforderungen abdecken"],"pt":["Requer entendimento de princípios de arquitetura de software","Pode não cobrir todos os casos de bordo ou requisitos específicos do sistema"],"ru":["Требует понимания принципов архитектуры программного обеспечения","Может не охватывать все краевые случаи или конкретные требования системы"],"ar":["يتطلب فهم مبادئ هندسة البرمجيات","قد لا يغطي جميع الحالات الحدودية أو المتطلبات الخاصة للنظام"]},"version":4},"contentHash":"78187f73654b810188cf631a9a088270e043c98d302e0353a5e8e82aa008aaa6","qualityScore":47}');
