INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('criptogus/liquid-ai/architecture-patterns', 'architecture-patterns', 'criptogus', 'liquid-ai', 'community', 'architecture-patterns criptogus liquid-ai community The architecture-patterns skill helps developers make objective decisions about software architecture, promoting deterministic design systems. It benefits developers seeking to optimize system design. 架构模式是软件设计中的一个重要概念，帮助开发者做出客观的软件架构决策。本文介绍了架构模式的基本规则和设计方法 アーキテクチャパターンはソフトウェア設計における重要な概念であり、開発者がオブジェクト指向で設計するためのベストプラクティスを提供します 아키텍처 패턴은 소프트웨어 설계에서 중요한 개념으로 개발자가 객관적인 소프트웨어 아키텍처 결정 방법을 제공합니다 Nuestra habilidad de patrones de arquitectura te ayuda a tomar decisiones objetivas sobre diseño de sistemas, utilizando reglas fundamentales como la objetividad Notre compétence en modèles d''architecture vous aide à prendre des décisions objectives sur la conception de systèmes, en utilisant des règles fondamentales comme l''objectivité Unsere Fähigkeit zu Architekturmustern hilft Ihnen, objektive Entscheidungen über Systemdesign zu treffen, unter Verwendung von grundlegenden Regeln wie der Objektivität Padrões de arquitetura ajudam a tomar decisões objetivas sobre design de sistemas. Aprenda a aplicar regras fundamentais para melhorar a eficiência. Шаблоны архитектуры помогают принимать объективные решения о дизайне систем. Узнайте, как применять фундаментальные правила для повышения эффективности. أنماط الهندسة المعمارية تساعد على اتخاذ قرارات موضوعية حول تصميم الأنظمة. تعلم كيفية تطبيق القواعد الأساسية لتحسين الكفاءة. how to use architecture-patterns what is architecture-patterns architecture-patterns alternative architecture-patterns vs competing skills architecture-patterns install architecture-patterns setup guide objective software architecture deterministic design systems 架构模式 软件设计 客观决策 系统可扩展性 系统可维护性 设计模式 软件架构 开发最佳实践 Encourages objective decision-making for software architecture Follows a fundamental rule of objectivity in system design Avoids subjective responses like ''Depende dos requisitos do seu sistema...'' Promotes deterministic design systems Supports developers in optimizing system architecture Architecture-patterns is a skill that enables developers to make informed, objective decisions about software architecture, following a fundamental rule of objectivity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('starwards/starwards/starwards-colyseus', 'community', 'starwards', 'starwards', 'starwards/starwards', 'starwards-colyseus', 0, 0, 47, '2026-03-08T01:57:15.360Z', '2026-03-08T02:04:11.596Z', 'a06757b7677225c15acb2f4e8c946db6cc0adbbe953bfc72d5f5082c6c929ac9', '{"id":"starwards/starwards/starwards-colyseus","name":"starwards-colyseus","description":{"en":"starwards-colyseus is a spaceship simulator for LARPs that utilizes Colyseus v0.15 for real-time multiplayer state synchronization, benefiting developers and gamers alike.","zh":"Starwards-Colyseus 是一个基于 Colyseus v0.15 的实时多人游戏模拟器，用于LARPs。它实现了状态同步和自动更新","ja":"Starwards-Colyseus はColyseus v0.15を使用したリアルタイムマルチプレイヤーシミュレーターで、LARPs向けです。状態同期と自動更新を実現しています","ko":"Starwards-Colyseus는 Colyseus v0.15를 기반으로 하는 실시간 멀티플레이어 시뮬레이터로, LARPs용으로 설계되었습니다. 상태 동기화 및 자동 업데이트 기능을 제공합니다","es":"Starwards-colyseus es un simulador de naves espaciales que utiliza Colyseus v0.15 para la sincronización de estado en tiempo real","fr":"Starwards-colyseus est un simulateur de vaisseaux spatiaux qui utilise Colyseus v0.15 pour la synchronisation d''état en temps réel","de":"Starwards-colyseus ist ein Schiffssimulator, der Colyseus v0.15 für die Echtzeit-Zustandssynchronisation verwendet","pt":"O starwards-colyseus é uma ferramenta de simulação de naves espaciais que utiliza Colyseus v0.15 para sincronização de estado em tempo real.","ru":"Starwards-colyseus - это инструмент для симуляции космических кораблей, использующий Colyseus v0.15 для синхронизации состояния в реальном времени.","ar":"أداة starwards-colyseus هي أداة لمحاكاة الفضاء التي تستخدم Colyseus v0.15 لتزامن الحالة في الوقت الفعلي."},"seo":{"title":{"en":"starwards-colyseus: Real-Time Multiplayer Setup Guide | A...","zh":"Starwards-Colyseus 多人游戏模拟器设置指南","ja":"Starwards-Colyseus マルチプレイヤーシミュレーター ベストプラクティス","ko":"Starwards-Colyseus 멀티플레이어 시뮬레이터 구축 가이드","es":"Guía de configuración de starwards-colyseus para simulado...","fr":"Guide de mise en place de starwards-colyseus pour simulat...","de":"Einrichtungsleitfaden für starwards-colyseus-Schiffssimul...","pt":"Guia de Configuração do starwards-colyseus para Simulação...","ru":"ИИ Агенты: Руководство по Настройке starwards-colyseus дл...","ar":"إعداد أداة starwards-colyseus ل симуляции الفضاء مع تقنيا..."},"description":{"en":"Discover how starwards-colyseus enables seamless multiplayer state synchronization. Learn to set up Colyseus v0.15 for your LARP spaceship simulator today!","zh":"了解 Starwards-Colyseus 的技术细节，包括 Colyseus v0.15 和实时多人游戏状态同步","ja":"Starwards-Colyseus の技術的詳細を学び、Colyseus v0.15 とリアルタイムマルチプレイヤー状態同期を理解する","ko":"Starwards-Colyseus의 기술적 세부 사항을 알아보세요. Colyseus v0.15 및 실시간 멀티플레이어 상태 동기화를 포함합니다","es":"Aprende a utilizar starwards-colyseus para crear experiencias de juego de rol en tiempo real con sincronización de estado","fr":"Découvrez comment utiliser starwards-colyseus pour créer des expériences de jeu de rôle en temps réel avec synchronisation d''état","de":"Erfahren Sie, wie Sie starwards-colyseus verwenden, um Echtzeit-Rollenspiele mit Zustandssynchronisation zu erstellen","pt":"Aprenda a configurar o starwards-colyseus para simulações de naves espaciais em tempo real com Colyseus v0.15","ru":"Настройте starwards-colyseus для мультиплеерных симуляций с помощью Colyseus v0.15 и получите автоматические обновления","ar":"تعلم كيفية إعداد أداة starwards-colyseus ل симуляции الفضاء مع تقنيات Colyseus v0.15 و حصول على تحديثات تلقائية"},"definition":{"en":"starwards-colyseus is a multiplayer spaceship simulator that uses Colyseus for real-time state synchronization over WebSocket connections.","zh":"Starwards-Colyseus 是一个实时多人游戏模拟器，使用 Colyseus v0.15 实现状态同步","ja":"Starwards-Colyseus はリアルタイムマルチプレイヤー状態同期を実現するColyseus v0.15を使用したシミュレーターです","ko":"Starwards-Colyseus는 상태 동기화를 실현하는 Colyseus v0.15를 사용하는 실시간 멀티플레이어 시뮬레이터입니다","es":"Starwards-colyseus es un agente de inteligencia artificial para la creación de simuladores de naves espaciales en tiempo real","fr":"Starwards-colyseus est un agent d''intelligence artificielle pour la création de simulateurs de vaisseaux spatiaux en temps réel","de":"Starwards-colyseus ist ein KI-Agent für die Erstellung von Echtzeit-Schiffssimulatoren","pt":"O starwards-colyseus é uma ferramenta de simulação de naves espaciais que utiliza Colyseus para sincronização de estado em tempo real.","ru":"Starwards-colyseus - это инструмент для симуляции космических кораблей, использующий Colyseus для синхронизации состояния.","ar":"أداة starwards-colyseus هي أداة لمحاكاة الفضاء التي تستخدم Colyseus لتزامن الحالة."},"features":{"en":["Utilizes Colyseus v0.15 for real-time multiplayer state synchronization","Employs decorators, rooms, and state sync for bug prevention","Supports automatic client updates via WebSocket connections","Follows a core principle where state is the source of truth and commands modify state","Features a client-server architecture with Room (Server) owning State (Schema)","Enables clients to receive automatic updates to Client State (Mirror)"],"zh":["基于 Colyseus v0.15 的实时多人游戏状态同步","自动更新机制","状态为源头，命令修改状态","客户端和服务器之间的 WebSocket 连接","Room 和 State 的概念"],"ja":["Colyseus v0.15を使用したリアルタイムマルチプレイヤー状態同期","自動更新メカニズム","状態が源となる、コマンドによる状態変更","クライアントとサーバー間のWebSocket接続","RoomとStateの概念"],"ko":["Colyseus v0.15를 기반으로 하는 실시간 멀티플레이어 상태 동기화","자동 업데이트 메커니즘","상태가 출처가 되는, 명령에 의한 상태 변경","클라이언트와 서버 간의 WebSocket 연결","Room과 State의 개념"],"es":["Utiliza Colyseus v0.15 para la sincronización de estado en tiempo real","Decoradores para la gestión de estado","Habitaciones para la gestión de clientes","Sincronización automática de estado entre clientes y servidor","Arquitectura de cliente-servidor con conexión WebSocket"],"fr":["Utilise Colyseus v0.15 pour la synchronisation d''état en temps réel","Décorateurs pour la gestion d''état","Salles pour la gestion de clients","Synchronisation automatique d''état entre clients et serveur","Architecture client-serveur avec connexion WebSocket"],"de":["Verwendet Colyseus v0.15 für die Echtzeit-Zustandssynchronisation","Dekoratoren für die Zustandsverwaltung","Räume für die Clientverwaltung","Automatische Zustandssynchronisation zwischen Clients und Server","Client-Server-Architektur mit WebSocket-Verbindung"],"pt":["Utiliza Colyseus v0.15 para sincronização de estado em tempo real","Suporta simulações de naves espaciais em tempo real","Permite a criação de salas de simulação personalizadas","Fornece atualizações automáticas para os clientes","Utiliza WebSocket para conexão em tempo real","Suporta arquitetura de cliente-servidor"],"ru":["Использует Colyseus v0.15 для синхронизации состояния в реальном времени","Поддерживает симуляции космических кораблей в реальном времени","Позволяет создавать индивидуальные комнаты для симуляций","Предоставляет автоматические обновления для клиентов","Использует WebSocket для подключения в реальном времени","Поддерживает архитектуру клиент-сервер"],"ar":["تستخدم Colyseus v0.15 لتزامن الحالة في الوقت الفعلي","تدعم симуляции الفضاء في الوقت الفعلي","تسمح بإنشاء غرف симуляции مخصصة","توفر تحديثات تلقائية للعملاء","تستخدم WebSocket للاتصال في الوقت الفعلي","تدعم هندسة عميل-خادم"]},"keywords":{"en":["how to use starwards-colyseus","starwards-colyseus alternative","starwards-colyseus setup guide","what is starwards-colyseus","starwards-colyseus vs Colyseus","starwards-colyseus install","Colyseus v0.15 tutorial","real-time multiplayer state synchronization","LARPs spaceship simulator"],"zh":["Starwards-Colyseus","Colyseus v0.15","实时多人游戏","状态同步","自动更新","LARPs","AIエージェント","游戏开发"],"ja":["Starwards-Colyseus","Colyseus v0.15","リアルタイムマルチプレイヤー","状態同期","自動更新","LARPs","AIエージェント","ゲーム開発"],"ko":["Starwards-Colyseus","Colyseus v0.15","실시간 멀티플레이어","상태 동기화","자동 업데이트","LARPs","AI 에이전트","게임 개발"],"es":["starwards-colyseus","simulador de naves espaciales","Colyseus v0.15","sincronización de estado en tiempo real","agentes de inteligencia artificial","desarrollo de juegos de rol","tecnologías de juego en tiempo real"],"fr":["starwards-colyseus","simulateur de vaisseaux spatiaux","Colyseus v0.15","synchronisation d''état en temps réel","agents d''intelligence artificielle","développement de jeux de rôle","technologies de jeu en temps réel"],"de":["starwards-colyseus","Schiffssimulator","Colyseus v0.15","Echtzeit-Zustandssynchronisation","KI-Agenten","Entwicklung von Echtzeit-Spielen","Technologien für Echtzeit-Spiele"],"pt":["starwards-colyseus","simulação de naves espaciais","Colyseus v0.15","sincronização de estado em tempo real","simulações em tempo real","desenvolvimento de jogos","WebSocket","arquitetura de cliente-servidor"],"ru":["starwards-colyseus","симуляция космических кораблей","Colyseus v0.15","синхронизация состояния в реальном времени","симуляции в реальном времени","разработка игр","WebSocket","архитектура клиент-сервер"],"ar":["starwards-colyseus","симуляция الفضاء","Colyseus v0.15","تزامن الحالة في الوقت الفعلي","симуляции في الوقت الفعلي","تطوير الألعاب","WebSocket","هندسة عميل-خادم"]}},"owner":"starwards","repo":"starwards","repoPath":"starwards/starwards","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.360Z","topics":[],"category":"community","skillMd":{"name":"starwards-colyseus","description":"Colyseus multiplayer patterns for Starwards - @gameField decorators, state sync, JSON Pointer commands, room architecture, and avoiding common Colyseus pitfalls; state is source of truth, server authoritative","version":"2025-11-04","bodyPreview":"# Colyseus Multiplayer Patterns for Starwards\n\n## Overview\n\nStarwards uses Colyseus v0.15 for real-time multiplayer state synchronization. Understanding decorators, rooms, and state sync prevents bugs.\n\n**Core principle:** State is the source of truth. Commands modify state. Clients receive automatic updates.\n\n## Architecture\n\n```\nClient (Browser)\n  ↓ WebSocket connection\nRoom (Server)\n  ↓ owns\nState (Schema)\n  ↓ syncs to\nClient State (Mirror)\n```\n\n**Flow:**\n1. Client sends command → Room\n2. Roo","body":"# Colyseus Multiplayer Patterns for Starwards\n\n## Overview\n\nStarwards uses Colyseus v0.15 for real-time multiplayer state synchronization. Understanding decorators, rooms, and state sync prevents bugs.\n\n**Core principle:** State is the source of truth. Commands modify state. Clients receive automatic updates.\n\n## Architecture\n\n```\nClient (Browser)\n  ↓ WebSocket connection\nRoom (Server)\n  ↓ owns\nState (Schema)\n  ↓ syncs to\nClient State (Mirror)\n```\n\n**Flow:**\n1. Client sends command → Room\n2. Room modifies State\n3. Colyseus patches → Client\n4. Client state updates automatically\n5. UI reacts to state changes\n\n## The @gameField Decorator\n\n**Purpose:** Marks properties for automatic Colyseus synchronization\n\n**Location:** `modules/core/src/game-field.ts`\n\n**Usage:**\n\n```typescript\nimport { gameField } from ''../game-field'';\n\nclass Shield extends SystemState {\n  // Primitive types\n  @gameField(''float32'') strength = 1000;\n  @gameField(''float32'') power = 1.0;\n  @gameField(''boolean'') broken = false;\n\n  // Nested Schema\n  @gameField(ShieldDesign) design = new ShieldDesign();\n\n  // Arrays\n  @gameField([Emitter]) emitters = new ArraySchema<Emitter>();\n\n  // Maps\n  @gameField({ map: Target }) targets = new MapSchema<Target>();\n}\n```\n\n**Types:**\n- `''float32''` - 32-bit float (precision loss vs 64-bit number!)\n- `''float64''` - 64-bit float\n- `''int8''`, `''int16''`, `''int32''` - Signed integers\n- `''uint8''`, `''uint16''`, `''uint32''` - Unsigned integers\n- `''boolean''` - Boolean\n- `''string''` - String\n- `SchemaClass` - Nested Schema\n- `[SchemaClass]` - Array of Schema\n- `{map: SchemaClass}` - Map of Schema\n\n## Critical @gameField Rules\n\n### Rule 1: @gameField Must Be Last Decorator\n\n```typescript\n// CORRECT order\n@range([0, 1])           // 1st\n@tweakable(''number'')     // 2nd\n@gameField(''float32'')    // 3rd - LAST\npower = 1.0;\n\n// WRONG order\n@gameField(''float32'')    // Can''t be first\n@range([0, 1])\npower = 1.0;\n```\n\n**Why:** Decorators execute bottom-to-top. @gameField must wrap the final property.\n\n### Rule 2: Initialize Collections\n\n```typescript\n// CORRECT\n@gameField([Thruster])\nthrusters = new ArraySchema<Thruster>();\n\n@gameField({map: Spaceship})\nships = new MapSchema<Spaceship>();\n\n// WRONG\n@gameField([Thruster])\nthrusters: ArraySchema<Thruster>;  // Not initialized!\n```\n\n**Why:** Colyseus needs instances, not undefined.\n\n### Rule 3: Use Correct Types\n\n```typescript\n// CORRECT\n@gameField(''float32'') speed = 0;      // 32-bit float\n@gameField(''int16'') count = 0;        // 16-bit int\n\n// WRONG\n@gameField(''number'') speed = 0;       // No ''number'' type\n@gameField(''float'') speed = 0;        // No ''float'' type (use float32/float64)\n```\n\n**Why:** Colyseus schema types are explicit.\n\n### Rule 4: Don''t Sync Everything\n\n```typescript\n// Only sync state that clients need\n@gameField(''float32'') health = 100;   // ✅ Clients need this\n@gameField(''float32'') damage = 10;    // ❌ Internal calculation, don''t sync\n\n// Derive internally\nget damage() {\n  return this.weapon.baseDamage * this.effectiveness;\n}\n```\n\n**Why:** Less sync = better performance.\n\n## Float32 Precision Gotcha\n\n**Problem:** JavaScript numbers are 64-bit, Colyseus `float32` is 32-bit\n\n```typescript\n@gameField(''float32'') speed = 123.456789;\nconsole.log(speed);  // 123.46 (precision lost!)\n```\n\n**Solution:** Use `toBeCloseTo()` in tests\n\n```typescript\n// WRONG\nexpect(ship.speed).toBe(123.456789);\n\n// CORRECT\nexpect(ship.speed).toBeCloseTo(123.46, 1);\n```\n\n## State vs Non-State\n\n**State (synced):**\n```typescript\nclass ShipState extends Schema {\n  @gameField(''float32'') health = 100;   // Synced\n  @gameField(Reactor) reactor!: Reactor;  // Synced\n}\n```\n\n**Non-State (server only):**\n```typescript\nclass ShipManager {\n  updateRate = 60;                      // Not synced\n  lastUpdate = Date.now();              // Not synced\n\n  update(dt: number) {\n    this.state.health -= 10 * dt;       // Modify state → syncs\n  }\n}\n```\n\n**Rule:** Only Schema classes with @gameField sync. Plain properties don''t sync.\n\n## Commands: Client → Server\n\nTwo patterns:\n\n### 1. JSON Pointer (Dynamic)\n\n**Client:**\n```typescript\nroom.send({\n  type: ''/Spaceship/ship-1/reactor/power'',\n  value: 0.8\n});\n```\n\n**Server (auto-handled in ShipRoom):**\n```typescript\n// No code needed - JSON Pointer auto-applies to state\n```\n\n**Use when:** Simple property updates, GM interface, debugging\n\n### 2. Typed Commands (Optimized)\n\n**Define (in core):**\n```typescript\nexport const setShieldPower: StateCommand<number, ShipState, void> = {\n  cmdName: ''setShieldPower'',\n  setValue: (state, value) => {\n    state.shield.power = value;\n  }\n};\n```\n\n**Server (register in room):**\n```typescript\nthis.onMessage(setShieldPower.cmdName, cmdReceiver(this.manager, setShieldPower));\n```\n\n**Client (send):**\n```typescript\nconst send = cmdSender(room, setShieldPower, undefined);\nsend(0.5);  // Type-safe!\n```\n\n**Use when:** High-frequency commands, complex validation, type safety\n\n## Room Architecture\n\n### AdminRoom\n\n**Purpose:** Game management, map selection, start/stop\n\n**State:** `AdminState` (has SpaceState)\n\n**Clients:** GM interface, admin panel\n\n**Commands:** `startGame`, `stopGame`, `loadMap`\n\n### SpaceRoom\n\n**Purpose:** Space-level gameplay, physics simulation\n\n**State:** `SpaceState` (all space objects)\n\n**Clients:** Tactical displays, overview screens\n\n**Managed by:** `GameManager`, `SpaceManager`\n\n### ShipRoom (per ship)\n\n**Purpose:** Individual ship control\n\n**State:** `ShipState` (ship systems)\n\n**Clients:** Ship stations (weapons, engineering, etc.)\n\n**roomId:** Equals `shipId` (`ship-0`, `ship-1`, etc.)\n\n**Commands:** JSON Pointer only (for flexibility)\n\n## State Sync Patterns\n\n### Pattern 1: Server Modifies, Clients React\n\n**Server:**\n```typescript\nclass ShieldManager {\n  update(dt: number) {\n    // Modify state → auto-syncs\n    this.state.shield.strength += rechargeRate * dt;\n  }\n}\n```\n\n**Client:**\n```typescript\n// Listen for changes\nship.state.shield.onChange(() => {\n  updateUI(ship.state.shield.strength);\n});\n```\n\n### Pattern 2: Client Commands, Server Validates\n\n**Client:**\n```typescript\n// User adjusts power slider\npowerSlider.on(''change'', (value) => {\n  room.send({type: ''/Spaceship/ship-0/reactor/power'', value});\n});\n```\n\n**Server:**\n```typescript\n// Receives command, validates, applies\nthis.onMessage((client, message) => {\n  const value = clamp(0, 1, message.value);  // Validate\n  applyJsonPointer(this.state, message.type, value);  // Apply\n  // Auto-syncs to all clients\n});\n```\n\n**Client:**\n```typescript\n// UI updates automatically from synced state\nship.state.reactor.listen(''power'', (value) => {\n  powerSlider.value = value;\n});\n```\n\n### Pattern 3: Multiplayer Testing\n\n**Use `ShipTestHarness`:**\n```typescript\nimport { ShipTestHarness } from ''./ship-test-harness'';\n\ntest(''client receives server state updates'', async () => {\n  const harness = new ShipTestHarness();\n  await harness.connect();\n\n  // Server modifies\n  harness.shipManager.state.shield.strength = 750;\n\n  // Wait for sync\n  await harness.waitForSync();\n\n  // Client receives\n  expect(harness.shipDriver.state.shield.strength).toBe(750);\n\n  await harness.cleanup();\n});\n```\n\n**Use `MultiClientDriver`:**\n```typescript\nimport { MultiClientDriver } from ''@starwards/server/test/multi-client-driver'';\n\ntest(''multiple clients see same state'', async () => {\n  const driver = new MultiClientDriver();\n  await driver.start();\n\n  const [c1, c2] = await Promise.all([\n    driver.joinShip(''ship-1''),\n    driver.joinShip(''ship-1'')\n  ]);\n\n  // Modify server state\n  driver.getShipManager(''ship-1'').state.shield.strength = 800;\n  await driver.waitForSync();\n\n  // Both clients updated\n  expect(c1.state.shield.strength).toBe(800);\n  expect(c2.state.shield.strength).toBe(800);\n\n  await driver.cleanup();\n});\n```\n\nSee `docs/testing/UTILITIES.md` for full API.\n\n## Common Colyseus Pitfalls\n\n### Pitfall 1: Modifying State Without @gameField\n\n```typescript\n// WRONG - doesn''t sync\nclass Shield {\n  strength = 1000;  // No decorator\n}\n\n// CORRECT - syncs\nclass Shield extends Schema {\n  @gameField(''float32'') strength = 1000;\n}\n```\n\n### Pitfall 2: Setting Objects Instead of Properties\n\n```typescript\n// WRONG - breaks references\nstate.velocity = {x: 10, y: 0};\n\n// CORRECT - update properties\nstate.velocity.setValue({x: 10, y: 0});\n// Or:\nstate.velocity.x = 10;\nstate.velocity.y = 0;\n```\n\n**Why:** Colyseus tracks property changes, not object replacement.\n\n### Pitfall 3: Forgetting await harness.waitForSync()\n\n```typescript\n// WRONG - client not updated yet\nharness.shipManager.state.health = 50;\nexpect(harness.shipDriver.state.health).toBe(50);  // FAILS\n\n// CORRECT - wait for replication\nharness.shipManager.state.health = 50;\nawait harness.waitForSync();\nexpect(harness.shipDriver.state.health).toBe(50);  // PASSES\n```\n\n### Pitfall 4: Using State in Client-Side Logic\n\n```typescript\n// WRONG - client shouldn''t have business logic\nif (ship.state.health < 50) {\n  ship.state.broken = true;  // Don''t modify from client\n}\n\n// CORRECT - send command, server decides\nif (ship.state.health < 50) {\n  room.send({type: ''checkBroken''});  // Server validates & applies\n}\n```\n\n**Why:** Server is authoritative. Client is display only.\n\n### Pitfall 5: Float32 Precision in Tests\n\n```typescript\n// WRONG - exact match fails\nexpect(ship.speed).toBe(123.456789);\n\n// CORRECT - close enough\nexpect(ship.speed).toBeCloseTo(123.46, 1);\n```\n\n### Pitfall 6: Not Cleaning Up Test Harness\n\n```typescript\n// WRONG - leaves connections open\ntest(''something'', async () => {\n  const harness = new ShipTestHarness();\n  await harness.connect();\n  // Test code\n});  // MISSING cleanup()!\n\n// CORRECT\ntest(''something'', async () => {\n  const harness = new ShipTestHarness();\n  await harness.connect();\n  // Test code\n  await harness.cleanup();  // Clean up\n});\n```\n\n## Debugging Colyseus Issues\n\n### 1. Colyseus Monitor\n\n```\nhttp://localhost:2567/colyseus-monitor\nLogin: admin / admin\n```\n\n**See:**\n- Active rooms\n- Connected clients\n- State tree (live values)\n\n### 2. Chrome DevTools Network Tab\n\n**WebSocket messages:**\n1. Open DevTools (F12)\n2. Network tab → WS filter\n3. Click connection\n4. See Messages: commands sent, patches received\n\n### 3. State Logging\n\n**Server:**\n```typescript\nconsole.log(''[SERVER] Shield strength:'', this.state.shield.strength);\n```\n\n**Client:**\n```typescript\nconsole.log(''[CLIENT] Shield strength:'', ship.state.shield.strength);\n```\n\nCompare values to find sync issues.\n\n### 4. JSON Pointer Path Validation\n\n**Test paths:**\n```typescript\nconst path = ''/Spaceship/ship-1/shield/power'';\nconst obj = resolveJsonPointer(state, path);\nconsole.log(''Resolved:'', obj);  // Should not be undefined\n```\n\n## Performance Considerations\n\n### Minimize Sync Frequency\n\n```typescript\n// WRONG - syncs 60 times/sec\nupdate(dt: number) {\n  this.state.position.x += velocity.x * dt;\n  this.state.position.y += velocity.y * dt;\n}\n\n// BETTER - sync only when significant change\nupdate(dt: number) {\n  const newX = this.state.position.x + velocity.x * dt;\n  const newY = this.state.position.y + velocity.y * dt;\n\n  if (Math.abs(newX - this.state.position.x) > 0.1) {\n    this.state.position.x = newX;\n  }\n  if (Math.abs(newY - this.state.position.y) > 0.1) {\n    this.state.position.y = newY;\n  }\n}\n```\n\n**But:** Starwards updates are already optimized. Don''t prematurely optimize.\n\n### Use Appropriate Types\n\n```typescript\n// WRONG - wastes bandwidth\n@gameField(''float64'') health = 100;  // 8 bytes\n\n// CORRECT - sufficient precision\n@gameField(''float32'') health = 100;  // 4 bytes\n```\n\n### Batch Commands\n\n```typescript\n// WRONG - multiple round trips\nroom.send({type: ''/Spaceship/ship-0/reactor/power'', value: 0.8});\nroom.send({type: ''/Spaceship/ship-0/thrusters/0/enabled'', value: true});\nroom.send({type: ''/Spaceship/ship-0/thrusters/1/enabled'', value: true});\n\n// BETTER - single batch command\nroom.send(''batchUpdate'', {\n  ''/reactor/power'': 0.8,\n  ''/thrusters/0/enabled'': true,\n  ''/thrusters/1/enabled'': true\n});\n```\n\n**But:** Only if actually a bottleneck. JSON Pointer is fine for normal use.\n\n## Integration with Other Skills\n\n- **starwards-tdd** - Test state sync with harnesses\n- **starwards-debugging** - Debug sync issues with tools\n- **starwards-verification** - Verify multiplayer scenarios\n\n## Quick Reference\n\n| Task | Pattern |\n|------|---------|\n| Add synced property | `@gameField(''type'') prop = value` |\n| Nested Schema | `@gameField(Class) obj = new Class()` |\n| Array | `@gameField([Class]) arr = new ArraySchema()` |\n| Map | `@gameField({map: Class}) map = new MapSchema()` |\n| Send command (client) | `room.send({type: ''/path'', value})` |\n| Listen to changes (client) | `state.onChange(() => {})` |\n| Test sync | `await harness.waitForSync()` |\n| Debug state | Colyseus Monitor (port 2567) |\n\n## The Bottom Line\n\n**Remember:**\n1. @gameField must be last decorator\n2. State is source of truth (server authoritative)\n3. Commands go client → server, patches go server → client\n4. Use harnesses for multiplayer tests\n5. Float32 has precision loss (use toBeCloseTo)\n6. Clean up test connections (await cleanup())\n7. When in doubt, check Colyseus Monitor\n"},"lastSynced":"2026-03-08T02:04:11.596Z","agentAnalysis":{"suitability":{"en":"Perfect for Real-Time Multiplayer Agents needing state synchronization capabilities with Colyseus v0.15","zh":"非常适合需要使用Colyseus v0.15进行状态同步的实时多人游戏代理","ja":"Colyseus v0.15を使用して状態を同期する必要があるリアルタイムマルチプレイヤーエージェントに最適","ko":"Colyseus v0.15를 사용하여 상태를同步해야 하는 실시간 멀티플레이어 에이전트에 적합","es":"Perfecto para Agentes de Tiempo Real Multijugador que necesitan capacidades de sincronización de estado con Colyseus v0.15","fr":"Parfait pour les agents de jeu en temps réel multijoueur nécessitant des capacités de synchronisation d''état avec Colyseus v0.15","de":"Perfekt für Echtzeit-Mehrspieler-Agents, die Zustands-Synchronisierungsfunktionen mit Colyseus v0.15 benötigen","pt":"Perfeito para Agentes de Multiplayer em Tempo Real que precisam de capacidades de sincronização de estado com Colyseus v0.15","ru":"Идеально подходит для агентов реального времени с поддержкой многопользовательской игры, требующих возможностей синхронизации состояния с Colyseus v0.15","ar":"مثالي لعميل متصفح متعدد اللاعبين في الوقت الفعلي الذي يحتاج إلى إمكانيات مزامنة الحالة مع Colyseus v0.15"},"recommendation":{"en":"Empowers agents to manage real-time multiplayer state synchronization using Colyseus, enabling seamless client-server communication over WebSocket connections and automatic state updates, while leveraging decorators, rooms, and state sync to prevent bugs","zh":"赋予代理管理实时多人游戏状态同步的能力，使用Colyseus实现无缝的客户端-服务器通信和自动状态更新，同时利用装饰器、房间和状态同步来防止错误","ja":"エージェントにリアルタイムマルチプレイヤーの状態同期を管理する能力を付与し、Colyseusを使用してクライアントとサーバーの間で無шовの通信と自動状態更新を実現し、デコレーター、ルーム、状態同期を利用してバグを防ぐ","ko":"에이전트에 실시간 멀티플레이어 상태同步을 관리하는 능력을 부여하고, Colyseus를 사용하여 클라이언트와 서버 간의 무шов한 통신과 자동 상태 업데이트를 구현하며, 데코레이터, 룸, 상태 동기화를 이용하여 버그를 방지","es":"Habilita a los agentes a gestionar la sincronización de estado de tiempo real multijugador mediante Colyseus, lo que permite una comunicación cliente-servidor sin problemas a través de conexiones WebSocket y actualizaciones de estado automáticas, aprovechando decoradores, salas y sincronización de estado para prevenir errores","fr":"Permet aux agents de gérer la synchronisation d''état de jeu en temps réel multijoueur à l''aide de Colyseus, ce qui permet une communication client-serveur transparente via des connexions WebSocket et des mises à jour d''état automatiques, tout en exploitant les décorateurs, les salles et la synchronisation d''état pour prévenir les bogues","de":"Ermöglich es Agents, die Zustands-Synchronisierung von Echtzeit-Mehrspieler-Spielen mit Colyseus zu verwalten, wodurch eine nahtlose Client-Server-Kommunikation über WebSocket-Verbindungen und automatische Zustandsaktualisierungen ermöglicht wird, während Dekoratoren, Räume und Zustandssynchronisierung genutzt werden, um Fehler zu vermeiden","pt":"Habilita os agentes a gerenciar a sincronização de estado de multiplayer em tempo real usando Colyseus, permitindo uma comunicação cliente-servidor transparente por meio de conexões WebSocket e atualizações de estado automáticas, aproveitando decoradores, salas e sincronização de estado para prevenir bugs","ru":"Предоставляет агентам возможность управлять синхронизацией состояния многопользовательской игры в реальном времени с помощью Colyseus, что позволяет осуществлять бесперебойную связь между клиентом и сервером по соединениям WebSocket и автоматические обновления состояния, используя декораторы, комнаты и синхронизацию состояния для предотвращения ошибок","ar":"تمكّن الوكلاء من إدارة مزامنة الحالة المتعددة اللاعبين في الوقت الفعلي باستخدام Colyseus، مما يسمح بالاتصال العامل بين العميل والخادم عبر اتصالات WebSocket وتحديثات الحالة التلقائية، واستخدام ز khوائض والغرف ومزامنة الحالة لتجنب الأخطاء"},"useCases":{"en":["Synchronizing spaceship simulator states in LARPs","Debugging real-time multiplayer issues with Colyseus","Implementing command-based state modifications for clients"],"zh":["在LARPs中同步宇宙飞船模拟器状态","使用Colyseus调试实时多人游戏问题","为客户端实现基于命令的状态修改"],"ja":["LARPsでの宇宙船シミュレーターの状態を同期する","Colyseusを使用してリアルタイムマルチプレイヤーの問題をデバッグする","クライアントのコマンドベースの状態変更を実装する"],"ko":["LARPs에서 우주선 시