INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('starwards/starwards/starwards-colyseus', 'starwards-colyseus', 'starwards', 'starwards', 'community', 'starwards-colyseus starwards starwards community starwards-colyseus is a spaceship simulator for LARPs that utilizes Colyseus v0.15 for real-time multiplayer state synchronization, benefiting developers and gamers alike. Starwards-Colyseus 是一个基于 Colyseus v0.15 的实时多人游戏模拟器，用于LARPs。它实现了状态同步和自动更新 Starwards-Colyseus はColyseus v0.15を使用したリアルタイムマルチプレイヤーシミュレーターで、LARPs向けです。状態同期と自動更新を実現しています Starwards-Colyseus는 Colyseus v0.15를 기반으로 하는 실시간 멀티플레이어 시뮬레이터로, LARPs용으로 설계되었습니다. 상태 동기화 및 자동 업데이트 기능을 제공합니다 Starwards-colyseus es un simulador de naves espaciales que utiliza Colyseus v0.15 para la sincronización de estado en tiempo real Starwards-colyseus est un simulateur de vaisseaux spatiaux qui utilise Colyseus v0.15 pour la synchronisation d''état en temps réel Starwards-colyseus ist ein Schiffssimulator, der Colyseus v0.15 für die Echtzeit-Zustandssynchronisation verwendet O starwards-colyseus é uma ferramenta de simulação de naves espaciais que utiliza Colyseus v0.15 para sincronização de estado em tempo real. Starwards-colyseus - это инструмент для симуляции космических кораблей, использующий Colyseus v0.15 для синхронизации состояния в реальном времени. أداة starwards-colyseus هي أداة لمحاكاة الفضاء التي تستخدم Colyseus v0.15 لتزامن الحالة في الوقت الفعلي. how to use starwards-colyseus starwards-colyseus alternative starwards-colyseus setup guide what is starwards-colyseus starwards-colyseus vs Colyseus starwards-colyseus install Colyseus v0.15 tutorial real-time multiplayer state synchronization LARPs spaceship simulator Starwards-Colyseus Colyseus v0.15 实时多人游戏 状态同步 自动更新 LARPs AIエージェント 游戏开发 Utilizes Colyseus v0.15 for real-time multiplayer state synchronization Employs decorators, rooms, and state sync for bug prevention Supports automatic client updates via WebSocket connections Follows a core principle where state is the source of truth and commands modify state Features a client-server architecture with Room (Server) owning State (Schema) Enables clients to receive automatic updates to Client State (Mirror) starwards-colyseus is a multiplayer spaceship simulator that uses Colyseus for real-time state synchronization over WebSocket connections.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jayteealao/Aperture/review:infra', 'community', 'jayteealao', 'Aperture', 'jayteealao/Aperture', 'review:infra', 0, 0, 47, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:15.566Z', '548c3f33f9ff31fd8a18b9e24060dcd87273bd4cd538b469c52768ddee536820', '{"id":"jayteealao/Aperture/review:infra","name":"review:infra","description":{"en":"The review:infra skill performs infrastructure-focused code reviews using 6 checklists, benefiting developers and DevOps teams. It runs via the senior-review-specialist agent.","zh":"review:infra是一种基础设施代码审查工具，使用6个检查清单确保部署配置、最小权限和操作清晰度","ja":"review:infraはインフラストラクチャコードレビュー工具で、6つのチェックリストを使用してデプロイ構成、最小権限、操作の明確性を 確保する","ko":"review:infra는 인프라 코드 리뷰 도구로 6개의 체크리스트를 사용하여 배포 구성, 최소 권한, 운영 명확성을 보장합니다","es":"La revisión de infraestructura utiliza 6 listas de verificación para evaluar la configuración de despliegue, la seguridad de la canalización y la claridad operativa","fr":"La revue d''infrastructure utilise 6 listes de vérification pour évaluer la configuration de déploiement, la sécurité de la canalisation et la clarté opérationnelle","de":"Die Infrastruktur-Überprüfung verwendet 6 Prüflisten, um die Konfiguration des Deployments, die Sicherheit der Pipeline und die operative Klarheit zu bewerten","pt":"O skill review:infra executa uma revisão de infraestrutura focada usando 6 listas de verificação de infraestrutura via o agente senior-review-specialist.","ru":"Навык review:infra выполняет проверку инфраструктуры, ориентированную на использование 6 контрольных списков инфраструктуры через агента senior-review-specialist.","ar":"المهارة review:infra تقوم بتشغيل مراجعة البنية باستخدام 6 قوائم مراجعة البنية من خلال وكيل المراجعة المتقدم."},"seo":{"title":{"en":"review:infra: Infrastructure Code Review Setup Guide | AI...","zh":"review:infra 基础设施代码审查设置指南","ja":"review:infra インフラストラクチャコードレビ