INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jayteealao/Aperture/review:infra', 'review:infra', 'jayteealao', 'Aperture', 'community', 'review:infra jayteealao Aperture community The review:infra skill performs infrastructure-focused code reviews using 6 checklists, benefiting developers and DevOps teams. It runs via the senior-review-specialist agent. review:infra是一种基础设施代码审查工具，使用6个检查清单确保部署配置、最小权限和操作清晰度 review:infraはインフラストラクチャコードレビュー工具で、6つのチェックリストを使用してデプロイ構成、最小権限、操作の明確性を 確保する review:infra는 인프라 코드 리뷰 도구로 6개의 체크리스트를 사용하여 배포 구성, 최소 권한, 운영 명확성을 보장합니다 La revisión de infraestructura utiliza 6 listas de verificación para evaluar la configuración de despliegue, la seguridad de la canalización y la claridad operativa La revue d''infrastructure utilise 6 listes de vérification pour évaluer la configuration de déploiement, la sécurité de la canalisation et la clarté opérationnelle Die Infrastruktur-Überprüfung verwendet 6 Prüflisten, um die Konfiguration des Deployments, die Sicherheit der Pipeline und die operative Klarheit zu bewerten O skill review:infra executa uma revisão de infraestrutura focada usando 6 listas de verificação de infraestrutura via o agente senior-review-specialist. Навык review:infra выполняет проверку инфраструктуры, ориентированную на использование 6 контрольных списков инфраструктуры через агента senior-review-specialist. المهارة review:infra تقوم بتشغيل مراجعة البنية باستخدام 6 قوائم مراجعة البنية من خلال وكيل المراجعة المتقدم. how to use review:infra review:infra setup guide infrastructure code review tools review:infra alternative review:infra vs manual code review what is review:infra review:infra install automated infrastructure review review:infra for DevOps teams infrastructure review best practices review:infra 基础设施代码审查 AI驱动的代码审查 部署配置 最小权限 操作清晰度 CI/CD管道安全 版本控制 Applies 6 infrastructure checklists, including deployment config and pipeline security Loads review checklists from files like commands/review/infra.md and commands/review/ci.md Runs via the senior-review-specialist agent for automated reviews Checks for least privilege, operational clarity, and deployment safety Reviews versioning, rollout, and monitoring strategies Supports infrastructure code review using markdown files like commands/review/release.md review:infra is an AI agent skill that automates infrastructure code review using predefined checklists, ensuring operational clarity and security.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('go-tapd/tapd/implement-api', 'community', 'go-tapd', 'tapd', 'go-tapd/tapd', 'implement-api', 0, 0, 47, '2026-03-08T01:57:15.371Z', '2026-03-08T02:04:29.255Z', '71a5e7d1a102dfb88666e27799f5651152665714c2224e5e61c529d992b55a76', '{"id":"go-tapd/tapd/implement-api","name":"implement-api","description":{"en":"The implement-api skill enables developers to access the Tapd API using the Go client library, streamlining workflow and conventions. It benefits developers working with Go and Tapd API.","zh":"Go Tapd SDK是Go客户端库，用于访问TAPD API，实现API端点，提高开发效率","ja":"Go Tapd SDKはGoクライアントライブラリであり、TAPD APIにアクセスしてAPIエンドポイントを実装する","ko":"Go Tapd SDK는 Go 클라이언트 라이브러리로서 TAPD API에 접근하여 API 엔드포인트를 구현","es":"La implementación de la API de TAPD utilizando el SDK de Go Tapd permite el acceso a la API de TAPD de manera estándar","fr":"La mise en œuvre de l''API TAPD à l''aide du SDK Go Tapd permet l''accès à l''API TAPD de manière standard","de":"Die Implementierung der TAPD-API mit dem Go Tapd SDK ermöglicht den Zugriff auf die TAPD-API nach Standard","pt":"O Go Tapd SDK é uma biblioteca de cliente Go para acessar a API Tapd, permitindo a implementação de endpoints de API de forma eficiente","ru":"Go Tapd SDK — это клиентская библиотека Go для доступа к API Tapd, позволяющая реализовывать API-конечные точки эффективно","ar":"Go Tapd SDK هو مكتبة عميل Go لوصول إلى API Tapd، مما يسمح بتنفيذ نقاط نهاية API بطريقة فعالة"},"seo":{"title":{"en":"Implement-api: Tapd API Endpoint Setup Guide | AI Agent S...","zh":"实现API集成：Go Tapd SDK开发指南","ja":"API実装ガイド：Go Tapd SDKを使用した開発","ko":"API 구현 가이드: Go Tapd SDK를 사용한 개발","es":"Implementar API con Go Tapd SDK: Guía de configuración","fr":"Mettre en œuvre l''API avec Go Tapd SDK: Meilleures pratiques","de":"API-Implementierung mit Go Tapd SDK: Einrichtungsleitfaden","pt":"Guia de Implementação de API com Go Tapd SDK","ru":"ИИ Агенты: Реализация API с помощью Go Tapd SDK","ar":"دليل تنفيذ واجهة برمجة التطبيقات باستخدام Go Tapd SDK"},"description":{"en":"Discover how to implement TAPD API endpoints with the Go Tapd SDK. Get started with our step-by-step guide and checklist for a seamless integration experience.","zh":"使用Go Tapd SDK实现TAPD API端点，按照标准工作流程和惯例进行开发，提高开发效率","ja":"Go Tapd SDKを使用してTAPD APIエンドポイントを実装し、標準的なワークフローと規範に従って開発を行う","ko":"Go Tapd SDK를 사용하여 TAPD API 엔드포인트를 구현하고 표준 워크플로우와 규칙에 따라 개발","es":"Aprende a implementar la API de TAPD con el SDK de Go Tapd y sigue las convenciones estándar para un workflow óptimo","fr":"Découvrez comment mettre en œuvre l''API TAPD avec le SDK Go Tapd et suivez les conventions standard pour un workflow optimal","de":"Erfahren Sie, wie Sie die TAPD-API mit dem Go Tapd SDK implementieren und folgen Sie den Standardkonventionen für einen optimalen Workflow","pt":"Aprenda a implementar endpoints de API com o Go Tapd SDK, seguindo o fluxo de trabalho padrão e convenções","ru":"Освойте реализацию API-конечных точек с помощью Go Tapd SDK, следуя стандартному рабочему процессу и соглашениям","ar":"تعرف على كيفية تنفيذ نقاط نهاية API باستخدام Go Tapd SDK، باتباع سير العمل القياسي والاتفاقيات"},"definition":{"en":"Implement-api is a Go client library skill for accessing the Tapd API, following standard workflow and conventions for endpoint implementation.","zh":"实现API是指使用Go Tapd SDK实现TAPD API端点的过程","ja":"API実装とは、Go Tapd SDKを使用してTAPD APIエンドポイントを実装すること","ko":"API 구현이란 Go Tapd SDK를 사용하여 TAPD API 엔드포인트를 구현하는 것을 말함","es":"Implementar API se refiere a la integración de la API de TAPD en un proyecto utilizando el SDK de Go Tapd","fr":"La mise en œuvre d''une API fait référence à l''intégration de l''API TAPD dans un projet à l''aide du SDK Go Tapd","de":"API-Implementierung bezeichnet die Integration der TAPD-API in ein Projekt mit dem Go Tapd SDK","pt":"Implementação de API é o processo de criar endpoints de API usando o Go Tapd SDK","ru":"Реализация API — это процесс создания API-конечных точек с помощью Go Tapd SDK","ar":"تنفيذ واجهة برمجة التطبيقات هو عملية إنشاء نقاط نهاية API باستخدام Go Tapd SDK"},"features":{"en":["Fetches API doc content from provided URLs","Extracts required parameters and response fields","Mirrors patterns and naming from existing api_*.go and api_*_test.go implementations","Implements code using the Go Tapd SDK","Follows project guidance from guide.md and references/implement-api.md"],"zh":["使用Go Tapd SDK访问TAPD API","按照标准工作流程和惯例进行开发","提取API文档内容和所需参数","镜像现有实现以简化开发","支持API文档URL、服务类型和简要描述的输入"],"ja":["Go Tapd SDKを使用してTAPD APIにアクセス","標準的なワークフローと規範に従って開発を行う","APIドキュメントの内容と必要なパラメータを抽出","既存の実装をミラーして開発を簡素化","APIドキュメントURL、サービスタイプ、簡単な説明の入力をサポート"],"ko":["Go Tapd SDK를 사용하여 TAPD API에 접근","표준 워크플로우와 규칙에 따라 개발","API 문서 내용과 필요한 파라미터를 추출","기존 구현을鏡像하여 개발을 단순화","API 문서 URL, 서비스 유형, 간단한 설명의 입력 지원"],"es":["Uso del SDK de Go Tapd para acceder a la API de TAPD","Implementación de endpoints de API según las convenciones estándar","Extracción de parámetros y campos de respuesta requeridos","Uso de patrones y nombres de implementaciones similares","Implementación de código en archivos `api_*.go` y `api_*_test.go`"],"fr":["Utilisation du SDK Go Tapd pour accéder à l''API TAPD","Mise en œuvre d''endpoints d''API selon les conventions standard","Extraction de paramètres et de champs de réponse requis","Utilisation de modèles et de noms d''implémentation similaires","Mise en œuvre de code dans les fichiers `api_*.go` et `api_*_test.go`"],"de":["Verwendung des Go Tapd SDK für den Zugriff auf die TAPD-API","Implementierung von API-Endpunkten nach Standardkonventionen","Extraktion von erforderlichen Parametern und Antwortfeldern","Verwendung von Mustern und Namen ähnlicher Implementierungen","Implementierung von Code in Dateien `api_*.go` und `api_*_test.go`"],"pt":["Implementação de endpoints de API com o Go Tapd SDK","Seguimento do fluxo de trabalho padrão e convenções","Extração de parâmetros e campos de resposta necessários","Utilização de padrões e nomes semelhantes em implementações existentes","Implementação de código em Go"],"ru":["Реализация API-конечных точек с помощью Go Tapd SDK","Следование стандартному рабочему процессу и соглашениям","Извлечение необходимых параметров и полей ответа","Использование аналогичных шаблонов и имен в существующих реализациях","Реализация кода на Go"],"ar":["تنفيذ نقاط نهاية API باستخدام Go Tapd SDK","اتباع سير العمل القياسي والاتفاقيات","استخراج المعلمات والحقول اللازمة للاستجابة","استخدام أنماط وأسماء مشابهة في التنفيذات الحالية","تنفيذ الكود بلغة Go"]},"keywords":{"en":["how to use implement-api","what is implement-api","implement-api setup guide","Tapd API endpoint implementation","Go Tapd SDK tutorial","implement-api vs Go API client","implement-api install","implement-api alternative"],"zh":["Go Tapd SDK","TAPD API","API实现","Go开发","API集成","标准工作流程","AI开发工具","AIエージェント"],"ja":["Go Tapd SDK","TAPD API","API実装","Go開発","API統合","標準的なワークフロー","AI開発ツール","AIエージェント"],"ko":["Go Tapd SDK","TAPD API","API 구현","Go 개발","API 통합","표준 워크플로우","AI 개발 도구","인공지능 에이전트"],"es":["implementar api","go tapd sdk","tapd api","integración de api","desarrollo de software","herramientas de desarrollo","agentes de ia","sdk de go"],"fr":["mettre en œuvre une api","go tapd sdk","tapd api","intégration d''api","développement de logiciels","outils de développement","agents d''ia","sdk de go"],"de":["api implementieren","go tapd sdk","tapd api","api-integration","softwareentwicklung","entwicklungstools","künstliche intelligenz agenten","go sdk"],"pt":["implementação de api","go tapd sdk","desenvolvimento de api","api tapd","biblioteca de cliente go","fluxo de trabalho padrão","convenções de código"],"ru":["реализация api","go tapd sdk","разработка api","api tapd","клиентская библиотека go","стандартный рабочий процесс","соглашения кода"],"ar":["تنفيذ واجهة برمجة التطبيقات","go tapd sdk","تطوير واجهة برمجة التطبيقات","api tapd","مكتبة عميل go","سير العمل القياسي","اتفاقيات الكود"]}},"owner":"go-tapd","repo":"tapd","repoPath":"go-tapd/tapd","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.371Z","topics":[],"category":"community","skillMd":{"name":"implement-api","description":"Implement a new TAPD API endpoint in the go-tapd SDK when a user provides an API documentation URL or asks to add/implement an endpoint (Story/Bug/Task/Iteration/etc.), including request/response structs, service methods, tests, test data, and features.md updates.","bodyPreview":"# Implement API\n\n## Overview\nImplement a TAPD API endpoint in this repo using the standard workflow and conventions.\n\n## Workflow\n1. Collect inputs: API doc URL, service type, brief description.\n2. Read project guidance: `guide.md`; use `references/implement-api.md` as a checklist.\n3. Fetch the API doc content when a URL is provided; extract required params/response fields.\n4. Locate a similar implementation in `api_*.go` and `api_*_test.go`; mirror patterns and naming.\n5. Implement code:\n   - R","body":"# Implement API\n\n## Overview\nImplement a TAPD API endpoint in this repo using the standard workflow and conventions.\n\n## Workflow\n1. Collect inputs: API doc URL, service type, brief description.\n2. Read project guidance: `guide.md`; use `references/implement-api.md` as a checklist.\n3. Fetch the API doc content when a URL is provided; extract required params/response fields.\n4. Locate a similar implementation in `api_*.go` and `api_*_test.go`; mirror patterns and naming.\n5. Implement code:\n   - Request struct: pointer fields, `url` tags, Chinese comments.\n   - Response struct: value fields with nullable pointers, `json` tags, Chinese comments.\n   - Service interface method and implementation with API doc link in the comment.\n6. Add tests:\n   - Test data in `internal/testdata/api/{resource}/{endpoint}.json`.\n   - Unit test in `api_*_test.go` validating method/path/params and key fields.\n   - Integration test in `tests/api_*_prod_test.go` (single-test run only).\n7. Update docs: mark the endpoint in `features.md`.\n8. Run tests and report results.\n\n## Conventions and checks\n- Follow `guide.md` exactly for naming, request/response types, and patterns.\n- Preserve existing response wrappers and helpers; do not invent new ones.\n- Always include the API documentation link in the method comment.\n- Keep comments in Chinese for exported fields.\n- Do not run integration tests in batch.\n\n## Output expectations\n- Provide a short summary of the API implemented.\n- List modified files with line numbers.\n- Provide test commands executed and their results.\n- Provide a usage snippet for the new method.\n- Call out any assumptions or missing API details.\n\n## Resources\n- `references/implement-api.md`: Checklist and repo entry points.\n"},"lastSynced":"2026-03-08T02:04:29.255Z","agentAnalysis":{"suitability":{"en":"Ideal for Go-based AI Agents requiring streamlined access to the Tapd API for workflow automation and convention management.","zh":"适合于需要简化访问Tapd API以实现工作流自动化和约定管理的Go-based AI Agents。","ja":"Tapd APIへの簡素化されたアクセスを必要とするGoベースのAIエージェントに適しています。","ko":"Tapd API에 대한 스트림 라인 접근이 필요한 Go 기반 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA basados en Go que requieren acceso optimizado a la API de Tapd para la automatización de flujos de trabajo y la gestión de convenciones.","fr":"Idéal pour les agents d''IA basés sur Go nécessitant un accès optimisé à l''API Tapd pour l''automatisation des flux de travail et la gestion des conventions.","de":"Ideal für Go-basierte KI-Agents, die einen optimierten Zugriff auf die Tapd-API für die Automatisierung von Workflows und die Konventionsverwaltung benötigen.","pt":"Ideal para Agentes de IA baseados em Go que requerem acesso simplificado à API do Tapd para automação de fluxo de trabalho e gerenciamento de convenções.","ru":"Идеально подходит для агентов ИИ на основе Go, требующих упрощенного доступа к API Tapd для автоматизации рабочих процессов и управления конвенциями.","ar":"متوافق تماما مع وكلاء الذكاء الاصطناعي الذين يعتمدون على لغة Go ويحتاجون إلى وصول مبسط إلى واجهة برمجة التطبيقات Tapd من أجل 자동ة سير العمل وإدارة الاتفاقيات."},"recommendation":{"en":"Empowers agents to leverage the Go client library for seamless interaction with the Tapd API, utilizing standard workflow and conventions to fetch API documentation and implement endpoints efficiently, handling parameters and response fields with ease.","zh":"使代理能够利用Go客户端库与Tapd API进行无缝交互，利用标准工作流和约定来获取API文档并高效地实现端点，轻松处理参数和响应字段。","ja":"エージェントがGoクライアントライブラリを利用してTapd APIと無縫にやり取りを行い、標準的なワークフローと規約を使用してAPIドキュメントを取得し、エンドポイントを効率的に実装し、パラメータとレスポンスフィールドを簡単に処理できるようにします。","ko":"에이전트가 Go 클라이언트 라이브러리를 사용하여 Tapd API와 원활하게 상호 작용할 수 있도록 하여 표준 워크플ロー 및 규약을 사용하여 API 문서를 가져오고 엔드ポイント를 효율적으로 구현하며 매개 변수 및 응답 필드를 쉽게 처리할 수 있습니다.","es":"Habilita a los agentes a aprovechar la biblioteca de cliente Go para interactuar de forma fluida con la API de Tapd, utilizando flujos de trabajo y convenciones estándar para recuperar la documentación de la API y implementar puntos de conexión de forma eficiente, manejando parámetros y campos de respuesta con facilidad.","fr":"Permet aux agents d''utiliser la bibliothèque client Go pour interagir en toute transparence avec l''API Tapd, en utilisant des flux de travail et des conventions standard pour récupérer la documentation de l''API et mettre en œuvre des points de terminaison de manière efficiente, en gérant les paramètres et les champs de réponse avec facilité.","de":"Ermächtigt Agents, die Go-Client-Bibliothek zu nutzen, um nahtlos mit der Tapd-API zu interagieren, indem standardmäßige Workflows und Konventionen zur Abrufung der API-Dokumentation und zur effizienten Implementierung von Endpunkten verwendet werden, wobei Parameter und Antwortfelder mühelos gehandhabt werden.","pt":"Permite que os agentes utilizem a biblioteca de cliente Go para interagir de forma transparente com a API do Tapd, utilizando fluxos de trabalho e convenções padrão para buscar documentação de API e implementar pontos de extremidade de forma eficiente, lidando com parâmetros e campos de resposta com facilidade.","ru":"Предоставляет агентам возможность использовать клиентскую библиотеку Go для бесшовного взаимодействия с API Tapd, используя стандартные рабочие процессы и конвенции для получения документации API и эффективной реализации конечных точек, обрабатывая параметры и поля ответа с легкостью.","ar":"تمكن الوكلاء من استخدام مكتبة العميل Go للتفاعل بطريقة سهلة مع واجهة برمجة التطبيقات Tapd، باستخدام سير العمل والاتفاقيات القياسية لجلب وثائق واجهة برمجة التطبيقات وتنفيذ النقاط النهائية بفعالية، وتحديد المعاملات وحقول الاستجابة بسهولة."},"useCases":{"en":["Implementing TAPD API endpoints using the Go client library","Automating workflow by fetching API documentation and extracting required parameters","Streamlining convention management through standardized API implementations"],"zh":["使用Go客户端库实现TAPD API端点","通过获取API文档和提取所需参数来自动化工作流","通过标准化API实现来简化约定管理"],"ja":["Goクライアントライブラリを使用してTAPD APIエンドポイントを実装する","APIドキュメントを取得して必要なパラメータを抽出してワークフローを自動化する","標準化されたAPI実装を使用して規約管理を簡素化する"],"ko":["Go 클라이언트 라이브러리를 사용하여 TAPD API 엔드포인트를 구현하는 것","API 문서를 가져와 필요한 매개 변수를 추출하여 워크플ロー 자동화를 수행하는 것","표준화된 API 구현을 사용하여 규약 관리를 간소화하는 것"],"es":["Implementar puntos de conexión de la API de TAPD mediante la biblioteca de cliente Go","Automatizar flujos de trabajo mediante la recuperación de la documentación de la API y la extracción de parámetros necesarios","Optimizar la gestión de convenciones a través de implementaciones de API estandarizadas"],"fr":["Mettre en œuvre des points de terminaison de l''API TAPD à l''aide de la bibliothèque client Go","Automatiser les flux de travail en récupérant la documentation de l''API et en extrayant les paramètres nécessaires","Optimiser la gestion des conventions via des mises en œuvre d''API standardisées"],"de":["Implementierung von TAPD-API-Endpunkten mithilfe der Go-Client-Bibliothek","Automatisierung von Workflows durch Abrufung der API-Dokumentation und Extraktion der erforderlichen Parameter","Optimierung der Konventionsverwaltung durch standardisierte API-Implementierungen"],"pt":["Implementar pontos de extremidade da API do TAPD usando a biblioteca de cliente Go","Automatizar o fluxo de trabalho buscando documentação de API e extrair parâmetros necessários","Simplificar o gerenciamento de convenções por meio de implementações de API padronizadas"],"ru":["Реализация конечных точек API TAPD с помощью клиентской библиотеки Go","Автоматизация рабочего процесса путем получения документации API и извлечения необходимых параметров","Упрощение управления конвенциями посредством стандартизированных реализаций API"],"ar":["تنفيذ نقاط النهاية لواجهة برمجة التطبيقات TAPD باستخدام مكتبة العميل Go","أتمتة سير العمل بالبحث عن وثائق واجهة برمجة التطبيقات واستخراج المعاملات المطلوبة","تبسيط إدارة الاتفاقيات من خلال تنفيذ واجهة برمجة التطبيقات الموحدة"]},"limitations":{"en":["Requires Go programming language","Dependent on Tapd API availability and documentation","Needs access to project guidance and reference materials"],"zh":["需要Go编程语言","依赖于Tapd API的可用性和文档","需要访问项目指南和参考资料"],"ja":["Goプログラミング言語が必要","Tapd APIの可用性とドキュメントに依存する","プロジェクトガイドと参考資料へのアクセスが必要"],"ko":["Go 프로그래밍 언어가 필요함","Tapd API의 가용성 및 문서에 의존함","프로젝트 가이드 및 참고 자료에 대한 액세스가 필요함"],"es":["Requiere el lenguaje de programación Go","Dependiente de la disponibilidad y documentación de la API de Tapd","Necesita acceso a orientación y materiales de referencia del proyecto"],"fr":["Nécessite le langage de programmation Go","Dépend de la disponibilité et de la documentation de l''API Tapd","Nécessite un accès à la guidance et aux documents de référence du projet"],"de":["Erfordert die Go-Programmiersprache","Abhängig von der Verfügbarkeit und Dokumentation der Tapd-API","Benötigt Zugriff auf Projektanleitungen und Referenzmaterialien"],"pt":["Exige a linguagem de programação Go","Depende da disponibilidade e documentação da API do Tapd","Necessita de acesso a orientações e materiais de referência do projeto"],"ru":["Требует языка программирования Go","Зависит от доступности и документации API Tapd","Требует доступа к руководствам и справочным материалам проекта"],"ar":["يتطلب لغة برمجة Go","يعتمد على توافر وثائق واجهة برمجة التطبيقات Tapd","يحتاج إلى الوصول إلى إرشادات ومواد مرجعية للمشروع"]},"version":4},"contentHash":"71a5e7d1a102dfb88666e27799f5651152665714c2224e5e61c529d992b55a76","qualityScore":47}');
