INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('go-tapd/tapd/implement-api', 'implement-api', 'go-tapd', 'tapd', 'community', 'implement-api go-tapd tapd community The implement-api skill enables developers to access the Tapd API using the Go client library, streamlining workflow and conventions. It benefits developers working with Go and Tapd API. Go Tapd SDK是Go客户端库，用于访问TAPD API，实现API端点，提高开发效率 Go Tapd SDKはGoクライアントライブラリであり、TAPD APIにアクセスしてAPIエンドポイントを実装する Go Tapd SDK는 Go 클라이언트 라이브러리로서 TAPD API에 접근하여 API 엔드포인트를 구현 La implementación de la API de TAPD utilizando el SDK de Go Tapd permite el acceso a la API de TAPD de manera estándar La mise en œuvre de l''API TAPD à l''aide du SDK Go Tapd permet l''accès à l''API TAPD de manière standard Die Implementierung der TAPD-API mit dem Go Tapd SDK ermöglicht den Zugriff auf die TAPD-API nach Standard O Go Tapd SDK é uma biblioteca de cliente Go para acessar a API Tapd, permitindo a implementação de endpoints de API de forma eficiente Go Tapd SDK — это клиентская библиотека Go для доступа к API Tapd, позволяющая реализовывать API-конечные точки эффективно Go Tapd SDK هو مكتبة عميل Go لوصول إلى API Tapd، مما يسمح بتنفيذ نقاط نهاية API بطريقة فعالة how to use implement-api what is implement-api implement-api setup guide Tapd API endpoint implementation Go Tapd SDK tutorial implement-api vs Go API client implement-api install implement-api alternative Go Tapd SDK TAPD API API实现 Go开发 API集成 标准工作流程 AI开发工具 AIエージェント Fetches API doc content from provided URLs Extracts required parameters and response fields Mirrors patterns and naming from existing api_*.go and api_*_test.go implementations Implements code using the Go Tapd SDK Follows project guidance from guide.md and references/implement-api.md Implement-api is a Go client library skill for accessing the Tapd API, following standard workflow and conventions for endpoint implementation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Zendevve/opentweak/mcaf-feature-spec', 'community', 'Zendevve', 'opentweak', 'Zendevve/opentweak', 'mcaf-feature-spec', 0, 0, 47, '2026-03-08T01:57:15.376Z', '2026-03-08T02:04:39.232Z', '7aeb0a2d07133990745bb6192aa1df908d5371c5f72d4fccd23b365d3d55b282', '{"id":"Zendevve/opentweak/mcaf-feature-spec","name":"mcaf-feature-spec","description":{"en":"The mcaf-feature-spec skill generates and updates feature specifications in Markdown format, creating docs/Features/<feature>.md files and updating links to ADRs and architecture maps.","zh":"MCAF 功能规格是一种确保开发和验证无猜测的方法，通过创建具体的模块和规则","ja":"MCAF 機能仕様は、開発と検証を無猜測で行うための方法論で、具体的なモジュールとルールを使用します","ko":"MCAF 기능 규격은 개발과 검증을無猜測で行うための 방법으로, 구체적인 모듈과 규칙을 사용합니다","es":"mcaf-feature-spec es una habilidad que ayuda a crear y actualizar documentos de características técnicas para agentes de IA","fr":"mcaf-feature-spec est une compétence qui aide à créer et à mettre à jour des documents de spécifications techniques pour les outils d''IA","de":"mcaf-feature-spec ist eine Fähigkeit, die dabei hilft, technische Dokumente für KI-Agents zu erstellen und zu aktualisieren","pt":"O mcaf-feature-spec é uma ferramenta para criar especificações de recursos claras e implementáveis, sem palpites, usando módulos concretos e regras testáveis","ru":"ИИ Агенты: mcaf-feature-spec - инструмент для создания функциональных спецификаций без предположений, с помощью реальных модулей и тестируемых правил","ar":"مcaf-feature-spec هو أداة لإنشاء مواصفات ميزات واضحة وقابلة للتنفيذ، بدون تخمين، باستخدام وحدات ملموسة وقواعد قابلة للاختبار"},"seo":{"title":{"en":"mcaf-feature-spec: Technical Spec Setup Guide | AI Agent ...","zh":"MCAF 功能规格设置指南","ja":"MCAF 機能仕様のベストプラクティス - AIエージェント","ko":"MCAF 기능 규격 설정 가이드 - AI 도구","es":"Guía de configuración de mcaf-feature-spec para agentes d...","fr":"Configurer mcaf-feature-spec pour les outils d''IA","de":"Einrichtungsleitfaden für mcaf-feature-spec in KI-Agents","pt":"Guia de Configuração do mcaf-feature-spec: Especificação ...","ru":"ИИ Агенты: Настройка mcaf-feature-spec для Функциональных...","ar":"إعداد مcaf-feature-spec: دليل أفضل الممارسات لتصميم الميزات"},"description":{"en":"Discover how to implement mcaf-feature-spec for precise feature specification, ensuring guesswork-free development. Get started with our expert guide today!","zh":"了解 MCAF 功能规格的设置和最佳实践，实现高效的开发和验证","ja":"MCAF 機能仕様を設定するためのベストプラクティスとガイドライン - AIエージェント開発","ko":"MCAF 기능 규격을 설정하고 최적화하는 방법을 알아보세요 - AI 도구 개발 가이드","es":"Aprende a configurar mcaf-feature-spec para agentes de IA y mejora la calidad de tus especificaciones técnicas con nuestras mejores prácticas","fr":"Découvrez comment configurer mcaf-feature-spec pour les outils d''IA et améliorer la qualité de vos spécifications techniques","de":"Erfahren Sie, wie Sie mcaf-feature-spec für KI-Agents einrichten und die Qualität Ihrer technischen Spezifikationen verbessern","pt":"Aprenda a configurar o mcaf-feature-spec para criar especificações de recursos claras e implementáveis, sem palpites","ru":"Настройте mcaf-feature-spec для создания функциональных спецификаций без предположений, с помощью ИИ Агентов","ar":"تعلم كيفية إعداد مcaf-feature-spec لإنشاء مواصفات ميزات واضحة وقابلة للتنفيذ، بدون تخمين"},"definition":{"en":"mcaf-feature-spec is a technical specification skill that ensures implementable and verifiable feature specs without guesswork, using concrete module names and testable rules.","zh":"MCAF 功能规格是一种软件开发方法，确保功能的实现和验证无需猜测","ja":"MCAF 機能仕様は、機能の実装と検証を無猜測で行うためのソフトウェア開発方法論です","ko":"MCAF 기능 규격은 기능의 구현과 검증을無猜測で行うための 소프트웨어 개발 방법입니다","es":"mcaf-feature-spec es una habilidad de agentes de IA que genera documentos de características técnicas","fr":"mcaf-feature-spec est une compétence d''outils d''IA qui génère des documents de spécifications techniques","de":"mcaf-feature-spec ist eine Fähigkeit von KI-Agents, die technische Dokumente generiert","pt":"O mcaf-feature-spec é uma ferramenta de especificação de recursos que ajuda a criar documentos claros e implementáveis","ru":"mcaf-feature-spec - это инструмент функциональной спецификации, помогающий создавать ясные и реализуемые документы","ar":"مcaf-feature-spec هو أداة لتصميم الميزات التي تساعد في إنشاء مستندات واضحة وقابلة للتنفيذ"},"features":{"en":["Generates docs/Features/<feature>.md files for clear feature documentation","Updates links to and from ADRs and architecture maps for consistent navigation","Enforces spec quality with anti-guesswork checklists and explicit questions","Utilizes concrete module/boundary names from docs/Architecture/Overview.md for accuracy","Ensures rules are testable with numbered specifications for reliable implementation"],"zh":["创建或更新功能规格文档","避免使用占位符，确保规格的明确性","使用具体的模块和边界名称","确保规则是可测试的"],"ja":["機能仕様ドキュメントの作成または更新","占位文字の使用を避け、仕様の明確性を確保する","具体的なモジュールと境界名称を使用する","ルールがテスト可能であることを確認する"],"ko":["기능 규격 문서의 생성 또는 업데이트","자리 표시자의 사용을 피하고, 규격의 명확성을 보장한다","구체적인 모듈과 경계 이름을 사용한다","규칙이 테스트 가능하다는 것을 확인한다"],"es":["Genera documentos de características técnicas en formato Markdown","Actualiza enlaces desde y hacia ADRs y mapas de arquitectura","Utiliza módulos concretos de la arquitectura","Permite la creación de reglas verificables y testables"],"fr":["Génère des documents de spécifications techniques au format Markdown","Met à jour les liens depuis et vers les ADRs et les cartes d''architecture","Utilise des modules concrets de l''architecture","Permet la création de règles vérifiables et testables"],"de":["Generiert technische Dokumente im Markdown-Format","Aktualisiert Links von und zu ADRs und Architekturkarten","Verwendet konkrete Module der Architektur","Ermöglicht die Erstellung von überprüfbaren und testbaren Regeln"],"pt":["Criação de documentos de recursos claros e implementáveis","Uso de módulos concretos do arquivo docs/Architecture/Overview.md","Regras testáveis para garantir a qualidade da especificação","Atualização de links para/from ADRs e mapa de arquitetura quando necessário","Evitação de placeholders e palpites na especificação"],"ru":["Создание ясных и реализуемых документов функциональных спецификаций","Использование реальных модулей из файла docs/Architecture/Overview.md","Тестируемые правила для обеспечения качества спецификации","Обновление ссылок на/с ADR и карту архитектуры при необходимости","Избежание плейсхолдеров и предположений в спецификации"],"ar":["إنشاء مستندات مواصفات ميزات واضحة وقابلة للتنفيذ","استخدام وحدات ملموسة من الملف docs/Architecture/Overview.md","قواعد قابلة للاختبار لضمان جودة المواصفة","تحديث الروابط من/إلى ADRs وخرائط الهندسة عندما لزم الأمر","تجنب المحلول وافتراضات في المواصفة"]},"keywords":{"en":["how to use mcaf-feature-spec","mcaf-feature-spec setup guide","mcaf-feature-spec alternative","mcaf-feature-spec vs competing specs","what is mcaf-feature-spec","mcaf-feature-spec install","mcaf-feature-spec technical specification","feature specification best practices","mcaf-feature-spec documentation"],"zh":["MCAF 功能规格","AI 工具开发","软件开发方法","功能规格设置","开发和验证","无猜测开发"],"ja":["MCAF 機能仕様","AIエージェント開発","ソフトウェア開発方法","機能仕様設定","開発と検証","無猜測開発"],"ko":["MCAF 기능 규격","AI 도구 개발","소프트웨어 개발 방법","기능 규격 설정","개발과 검증","無猜測 개발"],"es":["agentes de IA","mcaf-feature-spec","especificaciones técnicas","documentación técnica","Markdown","ADR","arquitectura de software"],"fr":["outils d''IA","mcaf-feature-spec","spécifications techniques","documentation technique","Markdown","ADR","architecture logicielle"],"de":["KI-Agents","mcaf-feature-spec","technische Spezifikationen","technische Dokumentation","Markdown","ADR","Software-Architektur"],"pt":["mcaf-feature-spec","especificação de recursos","desenvolvimento de software","documentação de arquitetura","regras testáveis","módulos concretos","ADR","mapa de arquitetura"],"ru":["mcaf-feature-spec","функциональная спецификация","разработка программного обеспечения","документация архитектуры","тестируемые правила","реальные модули","ИИ Агенты","карта архитектуры"],"ar":["مcaf-feature-spec","مواصفات الميزات","تطوير البرمجيات","توثيق الهندسة","قواعد قابلة للاختبار","وحدات ملموسة","أدوات الذكاء الاصطناعي","خرائط الهندسة"]}},"owner":"Zendevve","repo":"opentweak","repoPath":"Zendevve/opentweak","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.376Z","topics":[],"category":"community","skillMd":{"name":"mcaf-feature-spec","description":"Create or update a feature spec under `docs/Features/` using `docs/templates/Feature-Template.md`: business rules, user flows, system behaviour, Mermaid diagram(s), verification plan, and Definition of Done. Use before implementing a non-trivial feature or when behaviour changes; keep the spec executable (test flows + traceability to tests).","bodyPreview":"# MCAF: Feature Spec\n\n## Outputs\n\n- `docs/Features/<feature>.md` (create or update)\n- Update links from/to ADRs and architecture map when needed\n\n## Spec Quality (anti-guesswork checklist)\n\nWrite a spec that can be implemented and verified **without guessing**:\n\n- **No placeholders**: avoid “TBD”, “later”, “etc.”; if something is unknown, list it as an explicit question.\n- **Concrete modules**: use real module/boundary names from `docs/Architecture/Overview.md`.\n- **Rules are testable**: numbere","body":"# MCAF: Feature Spec\n\n## Outputs\n\n- `docs/Features/<feature>.md` (create or update)\n- Update links from/to ADRs and architecture map when needed\n\n## Spec Quality (anti-guesswork checklist)\n\nWrite a spec that can be implemented and verified **without guessing**:\n\n- **No placeholders**: avoid “TBD”, “later”, “etc.”; if something is unknown, list it as an explicit question.\n- **Concrete modules**: use real module/boundary names from `docs/Architecture/Overview.md`.\n- **Rules are testable**: numbered business rules with clear inputs → outputs (no vague adjectives).\n- **Flows are executable**: scenarios include preconditions, steps, expected results (happy + negative + edge).\n- **Verification is real**: commands copied from `AGENTS.md`, and scenarios mapped to test IDs.\n- **Stakeholders covered**: Product / Dev / DevOps / QA each get the information they need to ship safely.\n\n## Workflow\n\n1. Start from `docs/Architecture/Overview.md` to pick the affected module(s).\n2. Create/update the feature doc using `docs/templates/Feature-Template.md`.\n   - follow `AGENTS.md` scoping rules (do not scan the whole repo; use the architecture map to stay focused)\n   - keep the feature’s `## Implementation plan (step-by-step)` updated while executing\n3. Define behaviour precisely:\n   - purpose and scope (in/out)\n   - business rules (numbered, testable)\n   - primary flow + edge cases\n4. Describe system behaviour in terms of **entry points, reads/writes, side effects, idempotency, and errors**.\n5. Add a Mermaid diagram for the main flow (modules + interactions; keep it readable).\n6. Write verification that can be executed:\n   - test environment assumptions\n   - concrete test flows (positive/negative/edge)\n   - mapping to where tests live (or will live)\n   - traceability: rules/flows → test IDs (so tests reflect the spec)\n7. Keep Definition of Done strict:\n   - behaviour covered by automated tests\n   - static analysis clean\n   - docs updated (feature + ADR + architecture overview if boundaries changed)\n\n## Guardrails\n\n- If the feature introduces a new dependency/boundary, write an ADR and update `docs/Architecture/Overview.md`.\n- Don’t hide decisions inside the feature doc: decisions go to ADRs.\n"},"lastSynced":"2026-03-08T02:04:39.232Z","agentAnalysis":{"suitability":{"en":"Perfect for Architectural Agents needing precise feature specification generation in Markdown format.","zh":"非常适合需要在 Markdown 格式中生成精确特性规范的架构代理","ja":"アーキテクチャエージェントが Markdown 形式で正確な機能仕様を生成する必要がある場合に最適","ko":"마크다운 형식에서 정확한 기능 사양을 생성해야 하는 아키텍처 에이전트에 적합","es":"Perfecto para agentes arquitectónicos que necesitan generación de especificaciones de características precisas en formato Markdown.","fr":"Parfait pour les agents architecturaux ayant besoin de génération de spécifications de fonctionnalités précises au format Markdown.","de":"Perfekt für architektonische Agenten, die präzise Generierung von Featurespezifikationen im Markdown-Format benötigen.","pt":"Perfeito para Agentes Arquitetônicos que necessitam de geração precisa de especificações de recursos no formato Markdown.","ru":"Идеально подходит для архитектурных агентов, которым требуется точная генерация спецификаций функций в формате Markdown.","ar":"مثالي لعميل الهندسة المعمارية الذي يحتاج إلى توليد دقيق لمواصفات الميزات بالشكل Markdown."},"recommendation":{"en":"Empowers agents to create and update feature specifications with concrete modules and testable rules, utilizing Markdown format and linking to ADRs and architecture maps.","zh":"赋予代理创建和更新功能规范的能力，利用 Markdown 格式和链接到 ADRs 和架构地图，并具有可测试的规则","ja":"エージェントが機能仕様を Markdown 形式で作成および更新し、ADR およびアーキテクチャマップへのリンクを使用し、テスト可能なルールを使用できるようにする","ko":"에이전트가 마크다운 형식으로 기능 사양을 생성하고 업데이트할 수 있도록 하며, ADR 및 아키텍처 맵에 대한 링크와 테스트 가능한 규칙을 사용","es":"Habilita a los agentes a crear y actualizar especificaciones de características con módulos concretos y reglas probables, utilizando el formato Markdown y enlazando a ADRs y mapas de arquitectura.","fr":"Permet aux agents de créer et de mettre à jour des spécifications de fonctionnalités avec des modules concrets et des règles testables, en utilisant le format Markdown et en lien avec les ADR et les cartes d''architecture.","de":"Ermächtigt Agenten, Featurespezifikationen mit konkreten Modulen und testbaren Regeln zu erstellen und zu aktualisieren, unter Verwendung des Markdown-Formats und Verknüpfung mit ADRs und Architekturkarten.","pt":"Habilita os agentes a criar e atualizar especificações de recursos com módulos concretos e regras testáveis, utilizando o formato Markdown e linkando para ADRs e mapas de arquitetura.","ru":"Наделяет агентов возможностью создавать и обновлять спецификации функций с помощью конкретных модулей и тестируемых правил, используя формат Markdown и связывая с ADR и картами архитектуры.","ar":"يمنح العميل القدرة على إنشاء مواصفات الميزات وتحديثها باستخدام الوحدات المحددة وقواعد قابلة للاختبار، باستخدام تنسيق Markdown وربطه بالتعريفات والخرائط الهندسية."},"useCases":{"en":["Generating feature specifications in docs/Features/<feature>.md files","Updating links to ADRs and architecture maps","Creating testable rules for feature implementation"],"zh":["在 docs/Features/<feature>.md 文件中生成功能规范","更新 ADRs 和架构地图的链接","为功能实现创建可测试的规则"],"ja":["docs/Features/<feature>.md ファイルで機能仕様を生成する","ADR およびアーキテクチャマップへのリンクを更新する","機能実装のためのテスト可能なルールを作成する"],"ko":["docs/Features/<feature>.md 파일에서 기능 사양을 생성","ADR 및 아키텍처 맵에 대한 링크를 업데이트","기능 구현을 위한 테스트 가능한 규칙을 생성"],"es":["Generación de especificaciones de características en archivos docs/Features/<feature>.md","Actualización de enlaces a ADRs y mapas de arquitectura","Creación de reglas probables para la implementación de características"],"fr":["Génération de spécifications de fonctionnalités dans les fichiers docs/Features/<feature>.md","Mise à jour des liens vers les ADR et les cartes d''architecture","Création de règles testables pour la mise en œuvre de fonctionnalités"],"de":["Generierung von Featurespezifikationen in Dateien docs/Features/<feature>.md","Aktualisierung von Links zu ADRs und Architekturkarten","Erstellung von testbaren Regeln für die Implementierung von Features"],"pt":["Gerar especificações de recursos em arquivos docs/Features/<feature>.md","Atualizar links para ADRs e mapas de arquitetura","Criar regras testáveis para implementação de recursos"],"ru":["Генерировать спецификации функций в файлах docs/Features/<feature>.md","Обновлять ссылки на ADR и карты архитектуры","Создавать тестируемые правила для реализации функций"],"ar":["توليد مواصفات الميزات في الملفات docs/Features/<feature>.md","تحديث الروابط إلى التعريفات والخرائط الهندسية","إنشاء قواعد قابلة للاختبار لتنفيذ الميزات"]},"limitations":{"en":["Requires access to docs/Architecture/Overview.md for module names","Markdown format only","Needs explicit questions for unknown specifications"],"zh":["需要访问 docs/Architecture/Overview.md 以获取模块名称","仅支持 Markdown 格式","需要明确的问题以处理未知规范"],"ja":["モジュール名を取得するために docs/Architecture/Overview.md へのアクセスが必要","Markdown 形式のみをサポート","未知の仕様を処理するために明確な質問が必要"],"ko":["모듈 이름을 얻기 위해 docs/Architecture/Overview.md에 접근할 필요가 있음","마크다운 형식만 지원","알 수 없는 사양을 처리하기 위해 명확한 질문이 필요"],"es":["Requiere acceso a docs/Architecture/Overview.md para nombres de módulos","Solo formato Markdown","Necesita preguntas explícitas para especificaciones desconocidas"],"fr":["Nécessite un accès à docs/Architecture/Overview.md pour les noms de modules","Format Markdown uniquement","Nécessite des questions explicites pour les spécifications inconnues"],"de":["Benötigt Zugriff auf docs/Architecture/Overview.md für Modulnamen","Nur Markdown-Format","Benötigt explizite Fragen für unbekannte Spezifikationen"],"pt":["Requer acesso a docs/Architecture/Overview.md para nomes de módulos","Somente formato Markdown","Necessita de perguntas explícitas para especificações desconhecidas"],"ru":["Требует доступа к docs/Architecture/Overview.md для имен модулей","Только формат Markdown","Требует явных вопросов для неизвестных спецификаций"],"ar":["يتطلب الوصول إلى docs/Architecture/Overview.md لأسماء الوحدات","تنسيق Markdown فقط","يحتاج إلى أسئلة صريحة لمواصفات غير معروفة"]},"version":4},"contentHash":"7aeb0a2d07133990745bb6192aa1df908d5371c5f72d4fccd23b365d3d55b282","qualityScore":47}');
