INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Zendevve/opentweak/mcaf-feature-spec', 'mcaf-feature-spec', 'Zendevve', 'opentweak', 'community', 'mcaf-feature-spec Zendevve opentweak community The mcaf-feature-spec skill generates and updates feature specifications in Markdown format, creating docs/Features/<feature>.md files and updating links to ADRs and architecture maps. MCAF 功能规格是一种确保开发和验证无猜测的方法，通过创建具体的模块和规则 MCAF 機能仕様は、開発と検証を無猜測で行うための方法論で、具体的なモジュールとルールを使用します MCAF 기능 규격은 개발과 검증을無猜測で行うための 방법으로, 구체적인 모듈과 규칙을 사용합니다 mcaf-feature-spec es una habilidad que ayuda a crear y actualizar documentos de características técnicas para agentes de IA mcaf-feature-spec est une compétence qui aide à créer et à mettre à jour des documents de spécifications techniques pour les outils d''IA mcaf-feature-spec ist eine Fähigkeit, die dabei hilft, technische Dokumente für KI-Agents zu erstellen und zu aktualisieren O mcaf-feature-spec é uma ferramenta para criar especificações de recursos claras e implementáveis, sem palpites, usando módulos concretos e regras testáveis ИИ Агенты: mcaf-feature-spec - инструмент для создания функциональных спецификаций без предположений, с помощью реальных модулей и тестируемых правил مcaf-feature-spec هو أداة لإنشاء مواصفات ميزات واضحة وقابلة للتنفيذ، بدون تخمين، باستخدام وحدات ملموسة وقواعد قابلة للاختبار how to use mcaf-feature-spec mcaf-feature-spec setup guide mcaf-feature-spec alternative mcaf-feature-spec vs competing specs what is mcaf-feature-spec mcaf-feature-spec install mcaf-feature-spec technical specification feature specification best practices mcaf-feature-spec documentation MCAF 功能规格 AI 工具开发 软件开发方法 功能规格设置 开发和验证 无猜测开发 Generates docs/Features/<feature>.md files for clear feature documentation Updates links to and from ADRs and architecture maps for consistent navigation Enforces spec quality with anti-guesswork checklists and explicit questions Utilizes concrete module/boundary names from docs/Architecture/Overview.md for accuracy Ensures rules are testable with numbered specifications for reliable implementation mcaf-feature-spec is a technical specification skill that ensures implementable and verifiable feature specs without guesswork, using concrete module names and testable rules.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('KengoTODA/inspequte/inspequte-rule-spec', 'community', 'KengoTODA', 'inspequte', 'KengoTODA/inspequte', 'inspequte-rule-spec', 0, 0, 47, '2026-03-08T01:57:15.376Z', '2026-03-08T02:05:19.500Z', '091d73c3c9602cabec7e305faa59525c6bcc6b8a5ffd8ca5216c9333b4c698d8', '{"id":"KengoTODA/inspequte/inspequte-rule-spec","name":"inspequte-rule-spec","description":{"en":"inspequte-rule-spec is a fast, CLI-first static analysis tool designed for coding agents, analyzing JVM class and JAR files. It benefits developers by creating or updating spec.md files.","zh":"inspequte-rule-spec 是一种快速的 CLI-first 静态分析工具，用于分析 JVM 类和 JAR 文件","ja":"inspequte-rule-spec は、AIエージェント向けの高速な静的分析ツールです","ko":"inspequte-rule-spec는 JVM 클래스 및 JAR 파일을 위한 빠른 정적 분석 도구입니다","es":"inspequte-rule-spec es una herramienta de análisis estático para archivos de clase y JAR de JVM, diseñada para agentes de codificación, que ofrece una configuración rápida y sencilla","fr":"inspequte-rule-spec est un outil d''analyse statique pour les fichiers de classe et JAR JVM, conçu pour les agents de codage, qui propose une configuration rapide et simple","de":"inspequte-rule-spec ist ein statisches Analyse-Tool für JVM-Klassen- und JAR-Dateien, entwickelt für Codierungsagenten, das eine schnelle und einfache Konfiguration bietet","pt":"O inspequte-rule-spec é uma ferramenta de análise estática CLI-first para arquivos de classe e JAR do JVM, projetada para agentes de codificação. Ele fornece uma forma rápida de criar ou atualizar regras de análise","ru":"Inspequte-rule-spec - это быстрый инструмент статического анализа для файлов классов и JAR JVM, предназначенный для кодирования агентов ИИ. Он предоставляет возможность быстро создавать или обновлять правила анализа","ar":"inspequte-rule-spec هو أداة تحليل ثابت سريع لملفات فئة و JAR JVM، مصممة لأدوات التشفير. إنه يوفر وسيلة