INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('KengoTODA/inspequte/inspequte-rule-spec', 'inspequte-rule-spec', 'KengoTODA', 'inspequte', 'community', 'inspequte-rule-spec KengoTODA inspequte community inspequte-rule-spec is a fast, CLI-first static analysis tool designed for coding agents, analyzing JVM class and JAR files. It benefits developers by creating or updating spec.md files. inspequte-rule-spec 是一种快速的 CLI-first 静态分析工具，用于分析 JVM 类和 JAR 文件 inspequte-rule-spec は、AIエージェント向けの高速な静的分析ツールです inspequte-rule-spec는 JVM 클래스 및 JAR 파일을 위한 빠른 정적 분석 도구입니다 inspequte-rule-spec es una herramienta de análisis estático para archivos de clase y JAR de JVM, diseñada para agentes de codificación, que ofrece una configuración rápida y sencilla inspequte-rule-spec est un outil d''analyse statique pour les fichiers de classe et JAR JVM, conçu pour les agents de codage, qui propose une configuration rapide et simple inspequte-rule-spec ist ein statisches Analyse-Tool für JVM-Klassen- und JAR-Dateien, entwickelt für Codierungsagenten, das eine schnelle und einfache Konfiguration bietet O inspequte-rule-spec é uma ferramenta de análise estática CLI-first para arquivos de classe e JAR do JVM, projetada para agentes de codificação. Ele fornece uma forma rápida de criar ou atualizar regras de análise Inspequte-rule-spec - это быстрый инструмент статического анализа для файлов классов и JAR JVM, предназначенный для кодирования агентов ИИ. Он предоставляет возможность быстро создавать или обновлять правила анализа inspequte-rule-spec هو أداة تحليل ثابت سريع لملفات فئة و JAR JVM، مصممة لأدوات التشفير. إنه يوفر وسيلة سريعة لإنشاء أو تحديث قواعد التحليل how to use inspequte-rule-spec inspequte-rule-spec setup guide inspequte-rule-spec alternative inspequte-rule-spec vs static analysis tools inspequte-rule-spec install what is inspequte-rule-spec inspequte-rule-spec for AI agents JVM class file analysis JAR file static analysis inspequte-rule-spec JVM 类分析 JAR 文件分析 静态分析工具 CLI-first AI 工具 静态分析 Creates or updates src/rules/<rule-id>/spec.md files Analyzes JVM class and JAR files using CLI-first approach Follows a fixed template with sections like Summary, Motivation, and Examples Supports optional src/rules/<rule-id>/plan.md files Generates output with contractual scope, avoiding implementation details Provides performance considerations and acceptance criteria inspequte-rule-spec is a static analysis tool for JVM class and JAR files, designed for coding agents, providing fast CLI-first analysis capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EEstevanell/codex-planning-kit/review-issue-implementation', 'community', 'EEstevanell', 'codex-planning-kit', 'EEstevanell/codex-planning-kit', 'review-issue-implementation', 0, 0, 47, '2026-03-08T01:57:15.379Z', '2026-03-08T02:05:32.424Z', '5e0d6dd6b366518bfdc9423ab35c4120f58f92ad4348d84055fb7d2420683add', '{"id":"EEstevanell/codex-planning-kit/review-issue-implementation","name":"review-issue-implementation","description":{"en":"The review-issue-implementation skill helps developers verify code changes against issue cards and ExecPlans, identifying implementation mistakes and best practice violations. It benefits development teams by providing clear ratings and prioritized findings.","zh":"review-issue-implementation AI工具帮助开发人员验证代码更改，评估回归风险，并提供清晰的评级和优先的发现，确保代码质量和遵循最佳实践","ja":"review-issue-implementation AIエージェントは、開発者がコード変更を検証し、回帰リスクを評価し、明確な評価と優先順位のある発見を提供するのに役立ち、コードの品質とベストプラクティスの遵守を確保します","ko":"review-issue-implementation AI 에이전트는 개발자가 코드 변경을 검증하고 회귀 위험을 평가하며 명확한 평가 및 우선 순위가 있는 발견을 제공하는 데 도움을 주어 코드 품질과 최선의 관행을 따르도록 합니다","es":"La revisión de implementación de problemas verifica que los cambios de código satisfagan las tarjetas de problemas y los planes de ejecución, evaluando el riesgo de regresión y proporcionando una calificación clara con hallazgos prioritarios","fr":"La révision de la mise en œuvre des problèmes vérifie que les modifications de code satisfont aux cartes de problèmes et aux plans d''exécution, en évaluant le risque de régression et en fournissant une notation claire avec des résultats prioritaires","de":"Die Überprüfung der Implementierung von Problemen stellt sicher, dass Codeänderungen die Problemkarten und Ausführungspläne erfüllen, den Regressionsrisiko bewertet und eine klare Bewertung mit priorisierten Ergebnissen liefert","pt":"A revisão de problemas é um processo crítico que ajuda a garantir a qualidade do código e reduzir riscos de regressão","ru":"Проверка проблем является критическим процессом, который помогает обеспечить качество кода и снизить риск регрессии","ar":"مراجعة المشكلات هي عملية حرجة تساعد على ضمان جودة الكود وتقليل مخاطر الانحدار"},"seo":{"title":{"en":"review-issue-implementation: Code Review Setup Guide | AI...","zh":"AI工具：代码审查和错误检测实现指南","ja":"AIエージェント：コードレビューとエラー検出の実装ガイド","ko":"AI 에이전트: 코드 리뷰 및 오류検出 구현 가이드","es":"Guía de configuración de revisión de implementación de pr...","fr":"Guide de configuration de la révision de la mise en œuvre...","de":"Einrichtungsleitfaden für die Überprüfung der Implementie...","pt":"Guia de Implementação de Revisão de Problemas com Ferrame...","ru":"Настройка реализации проверки проблем с помощью ИИ Агентов","ar":"دليل تنفيذ مراجعة المشكلات باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Streamline code reviews with review-issue-implementation. Learn how to verify code changes, assess regression risk, and prioritize findings. Get started now!","zh":"了解如何使用review-issue-implementation AI工具来验证代码更改，评估回归风险，并提供清晰的评级和优先的发现","ja":"review-issue-implementation AIエージェントを使用してコード変更を検証し、回帰リスクを評価し、明確な評価と優先順位のある発見を提供する方法を学びます","ko":"review-issue-implementation AI 에이전트를 사용하여 코드 변경을 검증하고 회귀 위험을 평가하며 명확한 평가 및 우선 순위가 있는 발견을 제공하는 방법을 알아보세요","es":"Aprende a verificar que los cambios de código satisfagan las tarjetas de problemas y los planes de ejecución con nuestra guía de revisión de implementación d...","fr":"Découvrez comment vérifier que les modifications de code satisfont aux cartes de problèmes et aux plans d''exécution avec notre guide de révision de la mise e...","de":"Erfahren Sie, wie Sie überprüfen können, ob Codeänderungen die Problemkarten und Ausführungspläne erfüllen, mit unserem Leitfaden zur Überprüfung der Impleme...","pt":"Aprenda a implementar a revisão de problemas com ferramentas de IA para garantir a qualidade do código e reduzir riscos de regressão","ru":"Узнайте, как реализовать проверку проблем с помощью ИИ Агентов, чтобы обеспечить качество кода и снизить риск регрессии","ar":"تعرف على كيفية تنفيذ مراجعة المشكلات باستخدام أدوات الذكاء الاصطناعي لضمان جودة الكود وتقليل مخاطر الانحدار"},"definition":{"en":"review-issue-implementation is a skill that assesses code changes against issue cards and ExecPlans, ensuring adherence to the DRY principle and best practices.","zh":"review-issue-implementation AI工具是一种代码审查和错误检测工具，帮助开发人员验证代码更改并提供清晰的评级","ja":"review-issue-implementation AIエージェントは、コードレビューとエラー検出ツールであり、開発者がコード変更を検証し、明確な評価を提供するのに役立ちます","ko":"review-issue-implementation AI 에이전트는 코드 리뷰 및 오류検出 도구로서 개발자가 코드 변경을 검증하고 명확한 평가를 제공하는 데 도움을 줍니다","es":"La revisión de implementación de problemas es una habilidad que verifica que los cambios de código satisfagan las tarjetas de problemas y los planes de ejecución","fr":"La révision de la mise en œuvre des problèmes est une compétence qui vérifie que les modifications de code satisfont aux cartes de problèmes et aux plans d''exécution","de":"Die Überprüfung der Implementierung von Problemen ist eine Fähigkeit, die überprüft, ob Codeänderungen die Problemkarten und Ausführungspläne erfüllen","pt":"Revisão de problemas é o processo de verificar se as alterações de código atendem aos cartões de problemas e planos de execução","ru":"Проверка проблем является процессом проверки того, соответствуют ли изменения кода проблемным картам и планам выполнения","ar":"مراجعة المشكلات هي عملية التحقق من是否 تتطابق تعديلات الكود مع بطاقات المشكلات وخطط التنفيذ"},"features":{"en":["Verifies code changes against issue card files (ISSUE_PATH)","Assesses regression risk and provides prioritized findings","Identifies implementation mistakes and bad practices","Enforces the DRY principle and best practices","Supports ExecPlan verification","Provides clear ratings for code reviews"],"zh":["验证代码更改是否满足问题卡和执行计划","评估回归风险和提供清晰的评级","检测实现错误和不良实践","遵循DRY原则和最佳实践","优先的发现和错误报告","支持ISSUE_PATH和EXECPLAN输入"],"ja":["コード変更が問題カードと実行計画を満たしていることを検証する","回帰リスクを評価し、明確な評価を提供する","実装エラーと不良な実践を検出する","DRY原則とベストプラクティスに従う","優先順位のある発見とエラーレポート","ISSUE_PATHとEXECPLAN入力をサポートする"],"ko":["코드 변경이 문제 카드와 실행 계획을满た하는지 검증하는","회귀 위험을 평가하고 명확한 평가를 제공하는","구현 오류와 나쁨 실천을 검출하는","DRY 원칙과 최선의 관행을 따르는","우선 순위가 있는 발견과 오류 보고서","ISSUE_PATH와 EXECPLAN 입력을 지원하는"],"es":["Verificación de implementación de problemas","Evaluación del riesgo de regresión","Proporciona una calificación clara con hallazgos prioritarios","Seguimiento del principio DRY","Mejores prácticas y directrices para la implementación"],"fr":["Vérification de la mise en œuvre des problèmes","Évaluation du risque de régression","Fournit une notation claire avec des résultats prioritaires","Respect du principe DRY","Meilleures pratiques et lignes directrices pour la mise en œuvre"],"de":["Überprüfung der Implementierung von Problemen","Bewertung des Regressionsrisikos","Lieferung einer klaren Bewertung mit priorisierten Ergebnissen","Einhaltung des DRY-Prinzips","Beste Praktiken und Richtlinien für die Implementierung"],"pt":["Verificação de implementação de problemas","Avaliação de risco de regressão","Avaliação de código com base no princípio DRY","Verificação de boas práticas de codificação","Integração com cartões de problemas e planos de execução"],"ru":["Проверка реализации проблем","Оценка риска регрессии","Оценка кода на основе принципа DRY","Проверка хороших практик кодирования","Интеграция с проблемными картами и планами выполнения"],"ar":["التحقق من تنفيذ المشكلات","تقييم مخاطر الانحدار","التحقق من الكود بناءً على مبدأ DRY","التحقق من أفضل الممارسات لكتابة الكود","التكامل مع بطاقات المشكلات وخطط التنفيذ"]},"keywords":{"en":["how to use review-issue-implementation","review-issue-implementation setup guide","what is review-issue-implementation","review-issue-implementation alternative","review-issue-implementation vs code review tools","review-issue-implementation install","review-issue-implementation for AI agents","code review best practices with review-issue-implementation","review-issue-implementation and ExecPlan verification"],"zh":["AI工具","代码审查","错误检测","代码质量","最佳实践","DRY原则","ISSUE_PATH","EXECPLAN","代码更改","回归风险"],"ja":["AIエージェント","コードレビュー","エラー検出","コード品質","ベストプラクティス","DRY原則","ISSUE_PATH","EXECPLAN","コード変更","回帰リスク"],"ko":["AI 에이전트","코드 리뷰","오류검출","코드 품질","최선의 관행","DRY 원칙","ISSUE_PATH","EXECPLAN","코드 변경","회귀 위험"],"es":["revisión de implementación de problemas","Agentes de IA","tarjetas de problemas","planes de ejecución","riesgo de regresión","principio DRY","mejores prácticas de implementación"],"fr":["révision de la mise en œuvre des problèmes","Outils d''IA","cartes de problèmes","plans d''exécution","risque de régression","principe DRY","meilleures pratiques de mise en œuvre"],"de":["Überprüfung der Implementierung von Problemen","KI-Tools","Problemkarten","Ausführungspläne","Regressionsrisiko","DRY-Prinzip","Beste Praktiken für die Implementierung"],"pt":["revisão de problemas","ferramentas de IA","qualidade de código","redução de riscos","princípio DRY","boas práticas de codificação","cartões de problemas","planos de execução"],"ru":["проверка проблем","ИИ Агенты","качество кода","снижение рисков","принцип DRY","хорошие практики кодирования","проблемные карты","планы выполнения"],"ar":["مراجعة المشكلات","أدوات الذكاء الاصطناعي","جودة الكود","تقليل المخاطر","مبدأ DRY","أفضل الممارسات لكتابة الكود","بطاقات المشكلات","خطط التنفيذ"]}},"owner":"EEstevanell","repo":"codex-planning-kit","repoPath":"EEstevanell/codex-planning-kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.379Z","topics":[],"category":"community","skillMd":{"name":"review-issue-implementation","description":"Review and rate code implementations against issue cards and ExecPlans using git diffs, AGENTS.md, and PLANS.md. Use when a user asks for an implementation review, compliance check, regression risk assessment, or to validate changes against one or more issue cards or ExecPlans.","bodyPreview":"# Review Issue Implementation\n\n## Overview\n\nUse this skill to verify that code changes satisfy issue cards and ExecPlans, assess regression risk, and provide a clear rating with prioritized findings. Look for implementation mistakes, things that can lead to errors, or bad practices. We do not want over engineering, nor cluttering too much. We must follow the DRY principle and the best practices and guidelines.\n\n## Inputs (required)\n\n- ISSUE_PATH: Path to the issue card file (required).\n- EXECPLA","body":"# Review Issue Implementation\n\n## Overview\n\nUse this skill to verify that code changes satisfy issue cards and ExecPlans, assess regression risk, and provide a clear rating with prioritized findings. Look for implementation mistakes, things that can lead to errors, or bad practices. We do not want over engineering, nor cluttering too much. We must follow the DRY principle and the best practices and guidelines.\n\n## Inputs (required)\n\n- ISSUE_PATH: Path to the issue card file (required).\n- EXECPLAN_PATH: Path to the ExecPlan file (required).\n- DIFF_RANGE: Diff range to review (optional). Default to `STAGED` (staged changes) when not provided. Use `WORKING_TREE` for working tree vs `HEAD`, or provide an explicit range (for example, `main..feature-branch`, `<base>..<head>`, or a commit hash).\n- Require ISSUE_PATH and EXECPLAN_PATH; ask for them if missing or ambiguous.\n\n## Inputs (optional)\n\n- SCOPE_NOTES: Focus area or high-risk surfaces to emphasize (for example, auth, data migrations, UI flows).\n- TEST_EVIDENCE: Commands run and key results, if already executed by the user.\n\n## Workflow (default)\n\n1. Intake and scope\n   - Collect issue card path(s), ExecPlan path(s), and the diff range (working tree vs HEAD, commit range, or branch).\n   - If any are missing, ask for the minimum needed to review (prefer file paths and a diff range).\n2. Load governing docs\n   - Read `AGENTS.md` and `PLANS.md` from the repo root if they are not already in context.\n   - Read each issue card and ExecPlan; extract explicit requirements, acceptance criteria, and any approved scope expansions.\n3. Diff-first review\n   - Use `git status`, `git diff --stat`, and `git diff` (plus `git diff --cached` if staged) to identify touched files.\n   - Open files only to validate behavior or get precise line references.\n4. Requirements alignment\n   - Map each requirement to the actual change; mark gaps, partial coverage, or behavior mismatches.\n   - If a refactor or file move appears, verify explicit approval in the issue/plan; otherwise flag as scope risk.\n5. Risk and regression analysis\n   - Evaluate correctness, safety, and unintended side-effects (security, data integrity, background jobs, UI flows).\n   - Look for masked invalid states; changes should fail explicitly with clear errors.\n6. Tests and verification\n   - Note new/updated tests, and gaps. Highlight required checks from `AGENTS.md` if not evident.\n7. Output\n   - Produce findings first (ordered by severity, with file/line references).\n   - Provide rating and risk summary using the rubric in `.codex\\skills\\review-issue-implementation\\references\\review-checklist.md`.\n   - Follow with open questions/assumptions and a brief change-summary (only after findings).\n\n## Output order (use this sequence)\n\n1. Findings (severity order; include file path + line)\n2. Open questions / assumptions\n3. Rating (per category + overall status + risk level)\n4. Change summary (brief)\n\n## Resources\n\nUse `.codex\\skills\\review-issue-implementation\\references\\review-checklist.md` for the rating rubric, risk prompts, and repo-specific checks.\n"},"lastSynced":"2026-03-08T02:05:32.424Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced implementation analysis and best practice validation.","zh":"适用于需要高级实现分析和最佳实践验证的代码审查代理。","ja":"コードレビュー代理が高度な実装分析とベストプラクティス検証を必要とする場合に最適です。","ko":"고급 구현 분석 및 최선의 관행 검증이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan un análisis de implementación avanzado y validación de mejores prácticas.","fr":"Parfait pour les Agents de Révision de Code ayant besoin d''une analyse d''implémentation avancée et d''une validation des meilleures pratiques.","de":"Perfekt für Code-Review-Agenten, die eine erweiterte Implementierungsanalyse und eine Validierung von Best Practices benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de análise de implementação avançada e validação de boas práticas.","ru":"Идеально подходит для агентов код-ревью, которым необходима продвинутая анализ реализации и проверка на соответствие лучшим практикам.","ar":"مثالي لعميل استعراض الكود الذي يحتاج إلى تحليل التطبيق المتقدم وتحقق ممارسات أفضل"},"recommendation":{"en":"Empowers agents to verify code changes against issue cards and ExecPlans, assessing regression risk and providing clear ratings with prioritized findings using the DRY principle and best practices.","zh":"赋予代理验证代码更改与问题卡和ExecPlans的能力，评估回归风险并提供清晰的评级和优先的发现，使用DRY原则和最佳实践。","ja":"コード変更を問題カードとExecPlansに対して検証するエージェントを可能にし、回帰リスクを評価し、DRY原則とベストプラクティスを使用して優先順位の付いた発見と明確な評価を提供します。","ko":"에이전트가 코드 변경을 문제 카드 및 ExecPlans와 확인할 수 있도록 하며, 회귀 위험을 평가하고 DRY 원칙 및 최선의 관행을 사용하여 명확한 등급 및 우선 순위가 지정된 결과를 제공합니다.","es":"Habilita a los agentes a verificar los cambios de código contra tarjetas de problemas y ExecPlans, evaluando el riesgo de regresión y proporcionando calificaciones claras con hallazgos prioritarios utilizando el principio DRY y las mejores prácticas.","fr":"Permet aux agents de vérifier les modifications de code contre les cartes de problèmes et les ExecPlans, en évaluant le risque de régression et en fournissant des notes claires avec des résultats prioritaires en utilisant le principe DRY et les meilleures pratiques.","de":"Ermächtigt die Agenten, Codeänderungen gegen Issue-Karten und ExecPlans zu überprüfen, das Regressionsrisiko zu bewerten und klare Bewertungen mit priorisierten Ergebnissen unter Verwendung des DRY-Prinzips und der Best Practices bereitzustellen.","pt":"Habilita agentes a verificar alterações de código contra cartões de problemas e ExecPlans, avaliando o risco de regressão e fornecendo classificações claras com descobertas prioritárias usando o princípio DRY e boas práticas.","ru":"Наделяет агентов возможностью проверять изменения кода против карточек задач и ExecPlans, оценивая риск регрессии и предоставляя明ные рейтинги с приоритизированными результатами, используя принцип DRY и лучшие практики.","ar":"يمنح الوكيل القدرة على التحقق من تغييرات الكود مقابل بطاقات المشكلات والخطة التنفيذية، وتقييم مخاطر الانحدار وتوفير التصنيفات الواضحة مع نتائج ذات أولوية باستخدام مبدأ DRY وأفضل الممارسات"},"useCases":{"en":["Automating code reviews for implementation mistakes","Identifying best practice violations in code changes","Assessing regression risk for issue card implementations"],"zh":["自动化代码审查以发现实现错误","识别代码更改中的最佳实践违规","评估问题卡实现的回归风险"],"ja":["実装ミスのコードレビューを自動化する","コード変更でのベストプラクティス違反を特定する","問題カードの実装の回帰リスクを評価する"],"ko":["구현 오류에 대한 코드 리뷰 자동화","코드 변경에서 최선의 관행 위반을 식별","문제 카드 구현에 대한 회귀 위험 평가"],"es":["Automatización de revisiones de código para errores de implementación","Identificación de violaciones de las mejores prácticas en los cambios de código","Evaluación del riesgo de regresión para implementaciones de tarjetas de problemas"],"fr":["Automatisation des révisions de code pour les erreurs d''implémentation","Identification des violations des meilleures pratiques dans les modifications de code","Évaluation du risque de régression pour les implémentations de cartes de problèmes"],"de":["Automatisierung von Code-Reviews für Implementierungsfehler","Identifizierung von Verstößen gegen Best Practices in Codeänderungen","Bewertung des Regressionsrisikos für die Implementierung von Issue-Karten"],"pt":["Automatizar revisões de código para erros de implementação","Identificar violações de boas práticas em alterações de código","Avaliar o risco de regressão para implementações de cartões de problemas"],"ru":["Автоматизация код-ревью для ошибок реализации","Определение нарушений лучших практик в изменениях кода","Оценка риска регрессии для реализаций карточек задач"],"ar":["توفير مراجعة الكود الآلية للأخطاء في التنفيذ","تحديد انتهاكات أفضل الممارسات في تغييرات الكود","تقييم مخاطر الانحدار لتنفيذ بطاقات المشكلات"]},"limitations":{"en":["Requires ISSUE_PATH and EXECPLA inputs","Must follow the DRY principle and best practices","No support for over-engineering or cluttered code"],"zh":["需要ISSUE_PATH和EXECPLA输入","必须遵循DRY原则和最佳实践","不支持过度工程化或混乱的代码"],"ja":["ISSUE_PATHとEXECPLAの入力が必要","DRY原則とベストプラクティスに従う必要があります","過度のエンジニアリングや混乱したコードはサポートされません"],"ko":["ISSUE_PATH 및 EXECPLA 입력이 필요함","DRY 원칙 및 최선의 관행을 따라야 함","과도한 엔지니어링 또는 혼란스러운 코드는 지원되지 않음"],"es":["Requiere entradas ISSUE_PATH y EXECPLA","Debe seguir el principio DRY y las mejores prácticas","No admite la sobreeingeniería ni el código desordenado"],"fr":["Nécessite des entrées ISSUE_PATH et EXECPLA","Doit suivre le principe DRY et les meilleures pratiques","N''a pas de prise en charge pour la sur-ingénierie ou le code encombré"],"de":["Erfordert ISSUE_PATH- und EXECPLA-Eingaben","Muss dem DRY-Prinzip und den Best Practices folgen","Unterstützt keine Über-Ingenieurskunst oder chaotischen Code"],"pt":["Exige ISSUE_PATH e EXECPLA como entradas","Deve seguir o princípio DRY e boas práticas","Não há suporte para codificação excessiva ou confusa"],"ru":["Требует ISSUE_PATH и EXECPLA в качестве входных данных","Должен следовать принципу DRY и лучшим практикам","Нет поддержки для чрезмерного проектирования или загромождённого кода"],"ar":["يتطلب ISSUE_PATH و EXECPLA كمدخلات","يجب اتباع مبدأ DRY وأفضل الممارسات","لا يدعم البرمجة المفرطة أو الكود المزدحم"]},"version":4},"contentHash":"5e0d6dd6b366518bfdc9423ab35c4120f58f92ad4348d84055fb7d2420683add","qualityScore":47}');
