INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EEstevanell/codex-planning-kit/review-issue-implementation', 'review-issue-implementation', 'EEstevanell', 'codex-planning-kit', 'community', 'review-issue-implementation EEstevanell codex-planning-kit community The review-issue-implementation skill helps developers verify code changes against issue cards and ExecPlans, identifying implementation mistakes and best practice violations. It benefits development teams by providing clear ratings and prioritized findings. review-issue-implementation AI工具帮助开发人员验证代码更改，评估回归风险，并提供清晰的评级和优先的发现，确保代码质量和遵循最佳实践 review-issue-implementation AIエージェントは、開発者がコード変更を検証し、回帰リスクを評価し、明確な評価と優先順位のある発見を提供するのに役立ち、コードの品質とベストプラクティスの遵守を確保します review-issue-implementation AI 에이전트는 개발자가 코드 변경을 검증하고 회귀 위험을 평가하며 명확한 평가 및 우선 순위가 있는 발견을 제공하는 데 도움을 주어 코드 품질과 최선의 관행을 따르도록 합니다 La revisión de implementación de problemas verifica que los cambios de código satisfagan las tarjetas de problemas y los planes de ejecución, evaluando el riesgo de regresión y proporcionando una calificación clara con hallazgos prioritarios La révision de la mise en œuvre des problèmes vérifie que les modifications de code satisfont aux cartes de problèmes et aux plans d''exécution, en évaluant le risque de régression et en fournissant une notation claire avec des résultats prioritaires Die Überprüfung der Implementierung von Problemen stellt sicher, dass Codeänderungen die Problemkarten und Ausführungspläne erfüllen, den Regressionsrisiko bewertet und eine klare Bewertung mit priorisierten Ergebnissen liefert A revisão de problemas é um processo crítico que ajuda a garantir a qualidade do código e reduzir riscos de regressão Проверка проблем является критическим процессом, который помогает обеспечить качество кода и снизить риск регрессии مراجعة المشكلات هي عملية حرجة تساعد على ضمان جودة الكود وتقليل مخاطر الانحدار how to use review-issue-implementation review-issue-implementation setup guide what is review-issue-implementation review-issue-implementation alternative review-issue-implementation vs code review tools review-issue-implementation install review-issue-implementation for AI agents code review best practices with review-issue-implementation review-issue-implementation and ExecPlan verification AI工具 代码审查 错误检测 代码质量 最佳实践 DRY原则 ISSUE_PATH EXECPLAN 代码更改 回归风险 Verifies code changes against issue card files (ISSUE_PATH) Assesses regression risk and provides prioritized findings Identifies implementation mistakes and bad practices Enforces the DRY principle and best practices Supports ExecPlan verification Provides clear ratings for code reviews review-issue-implementation is a skill that assesses code changes against issue cards and ExecPlans, ensuring adherence to the DRY principle and best practices.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Nepopams/vr_ai_platform/contract-checker', 'community', 'Nepopams', 'vr_ai_platform', 'Nepopams/vr_ai_platform', 'contract-checker', 0, 0, 47, '2026-03-08T01:57:15.381Z', '2026-03-08T02:05:40.106Z', '96ea51541c0f8626324542947b365868cc7cba117c4efc2d47e1b36fc43a9379', '{"id":"Nepopams/vr_ai_platform/contract-checker","name":"contract-checker","description":{"en":"The contract-checker skill validates JSON fixtures against command and decision schemas, providing a validation report and non-zero exit status for mismatches. It benefits developers working with JSON data and schema validation.","zh":"Contract Checker Skill是一个用于验证JSON fixtures和命令、决策schema的工具。它可以加载schema、验证fixtures并输出报告","ja":"Contract Checker スキルは、JSON フィクスチャとコマンド、意思決定スキーマを検証するツールです。スキーマのロード、フィクスチャの検証、レポートの出力などが可能","ko":"컨트랙트 체커 스킬은 JSON fixtures와 명령, 의사 결정 스키마를 검증하는 도구입니다. 스키마 로드, fixtures 검증, 보고서 출력 등을 지원합니다","es":"Contract Checker es una herramienta que valida JSON fixtures contra esquemas de comando y decisión. Proporciona un informe de validación y un estado de salida no cero cuando los fixtures no coinciden con los esquemas","fr":"Contract Checker est un outil qui valide les fixtures JSON par rapport aux schémas de commande et de décision. Il fournit un rapport de validation et un statut de sortie non nul lorsque les fixtures ne correspondent pas aux schémas","de":"Contract Checker ist ein Tool, das JSON-Fixtures gegen Befehls- und Entscheidungsschemata validiert. Es liefert einen Validierungsbericht und einen Nicht-Null-Ausgangsstatus, wenn die Fixtures nicht mit den Schemata übereinstimmen","pt":"O Verificador de Contrato é uma habilidade que valida fixtures JSON contra esquemas de comando e decisão","ru":"Проверка Контрактов - это навык, который проверяет JSON-файлы на соответствие схемам команд и решений","ar":"مدقق العقود هو مهارة تقوم بالتحقق من صحة الملفات JSON مع مخططات الأوامر والقرارات"},"seo":{"title":{"en":"contract-checker: JSON Schema Validation Setup Guide | AI...","zh":"合同检查器设置指南 - Contract Checker Skill","ja":"Contract Checker スキルのベストプラクティス - AIエージェント","ko":"컨트랙트 체커 스킬 구축 가이드 - AI 도구","es":"Guía de configuración de Contract Checker para desarrolla...","fr":"Guide d''installation de Contract Checker pour les dévelop...","de":"Einrichtungsleitfaden für Contract Checker-Tools für Entw...","pt":"Guia de Configuração do Verificador de Contrato","ru":"ИИ Агент: Руководство по Настройке Проверки Контрактов","ar":"دليل إعداد مدقق العقود الإلكترونية"},"description":{"en":"Discover how contract-checker simplifies JSON fixture validation against command and decision schemas. Get started with our expert guide and optimize your wo...","zh":"了解Contract Checker Skill的技术细节，包括输入、输出和步骤。提高您的开发效率","ja":"Contract Checker スキルの仕組みを解説。JSON フィクスチャの検証とスキーマのロード方法を紹介","ko":"컨트랙트 체커 스킬의 기능과 사용 방법을 알아보세요. JSON fixtures와 스키마를 사용한 검증을 포함합니다","es":"Aprende a utilizar Contract Checker para validar JSON fixtures contra esquemas de comando y decisión. Mejora la precisión de tus proyectos con esta herramien...","fr":"Découvrez comment utiliser Contract Checker pour valider les fixtures JSON par rapport aux schémas de commande et de décision. Améliorez la précision de vos ...","de":"Erfahren Sie, wie Sie Contract Checker verwenden, um JSON-Fixtures gegen Befehls- und Entscheidungsschemata zu validieren. Verbessern Sie die Genauigkeit Ihr...","pt":"Aprenda a configurar o Verificador de Contrato para validação de fixtures JSON e esquemas de comando e decisão","ru":"Узнайте, как настроить Проверку Контрактов для валидации JSON-файлов и схем команд и решений с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد مدقق العقود لتحقق من صحة الملفات JSON و مخططات الأوامر والقرارات"},"definition":{"en":"contract-checker is a skill that validates JSON fixtures against predefined schemas, ensuring data integrity and consistency.","zh":"Contract Checker Skill是一种AI工具，用于验证JSON数据和schema的一致性","ja":"Contract Checker スキルは、AIエージェントの一種で、JSON データとスキーマの整合性を検証する","ko":"컨트랙트 체커 스킬은 AI 도구 중 하나로, JSON 데이터와 스키마의 일관성을 검증하는 데 사용됩니다","es":"Contract Checker es una herramienta de verificación de contratos que utiliza esquemas JSON para validar fixtures","fr":"Contract Checker est un outil de vérification de contrats qui utilise des schémas JSON pour valider des fixtures","de":"Contract Checker ist ein Vertragsprüfungstool, das JSON-Schemata verwendet, um Fixtures zu validieren","pt":"O que é Verificador de Contrato? É uma ferramenta que valida a conformidade de fixtures JSON com esquemas definidos","ru":"Что такое Проверка Контрактов? Это инструмент, который проверяет соответствие JSON-файлов схемам","ar":"ما هو مدقق العقود؟ هو أداة لتحقق من مطابقة الملفات JSON لمخططات معينة"},"features":{"en":["Loads command and decision schemas from contracts/schemas/","Validates each JSON fixture against the correct schema","Treats invalid_*.json fixtures as expected failures","Emits a summary and exits with status 1 if expectations are not met","Prints validation reports to stdout"],"zh":["加载命令和决策schema","验证JSON fixtures","输出验证报告","支持非零退出状态","使用JSON fixtures进行预期失败测试"],"ja":["コマンドと意思決定スキーマのロード","JSON フィクスチャの検証","検証レポートの出力","非ゼロ終了ステータスのサポート","JSON フィクスチャを使用した予想される失敗テスト"],"ko":["명령과 의사 결정 스키마 로드","JSON fixtures 검증","검증 보고서 출력","非영존 종료 상태 지원","JSON fixtures를 사용한 예상 실패 테스트"],"es":["Carga de esquemas de comando y decisión","Validación de fixtures JSON contra esquemas","Informe de validación y estado de salida no cero","Tratamiento de fixtures de fallo esperado","Compatibilidad con JSON fixtures y esquemas"],"fr":["Chargement des schémas de commande et de décision","Validation des fixtures JSON par rapport aux schémas","Rapport de validation et statut de sortie non nul","Traitement des fixtures de défaillance attendue","Compatibilité avec les fixtures et les schémas JSON"],"de":["Laden von Befehls- und Entscheidungsschemata","Validierung von JSON-Fixtures gegen Schemata","Validierungsbericht und Nicht-Null-Ausgangsstatus","Behandlung von erwarteten Fehlern in Fixtures","Kompatibilität mit JSON-Fixtures und -Schemata"],"pt":["Validação de fixtures JSON contra esquemas de comando e decisão","Carregamento de esquemas de comando e decisão","Emitir relatório de validação para stdout","Tratamento de fixtures inválidos como falhas esperadas","Suporte a saída de status não zero em caso de falha"],"ru":["Проверка JSON-файлов на соответствие схемам команд и решений","Загрузка схем команд и решений","Вывод отчета о валидации в stdout","Обработка недействительных файлов как ожидаемых ошибок","Поддержка выходного статуса не ноль в случае ошибки"],"ar":["التحقق من صحة الملفات JSON مع مخططات الأوامر والقرارات","تحميل مخططات الأوامر والقرارات","إخراج تقرير التحقق إلى stdout","معالجة الملفات غير الصالحة كأخطاء متوقعة","دعم إخراج حالة غير صفر في حالة الخطأ"]},"keywords":{"en":["how to use contract-checker","contract-checker setup guide","JSON schema validation","contract-checker vs jsonschema","contract-checker install","what is contract-checker","contract-checker alternative","contract-checker tutorial"],"zh":["Contract Checker Skill","JSON fixtures","命令schema","决策schema","AI工具","验证报告","非零退出状态"],"ja":["Contract Checker スキル","JSON フィクスチャ","コマンドスキーマ","意思決定スキーマ","AIエージェント","検証レポート","非ゼロ終了ステータス"],"ko":["컨트랙트 체커 스킬","JSON fixtures","명령 스키마","의사 결정 스키마","AI 도구","검증 보고서","비영존 종료 상태"],"es":["Contract Checker","herramienta de verificación de contratos","validación de JSON","esquemas de comando y decisión","fixtures JSON","desarrollo de software","pruebas de software","herramientas de desarrollo"],"fr":["Contract Checker","outil de vérification de contrats","validation JSON","schémas de commande et de décision","fixtures JSON","développement de logiciels","tests de logiciels","outils de développement"],"de":["Contract Checker","Vertragsprüfungstool","JSON-Validierung","Befehls- und Entscheidungsschemata","JSON-Fixtures","Software-Entwicklung","Software-Tests","Entwicklungstools"],"pt":["Verificador de Contrato","Validação de fixtures JSON","Esquemas de comando e decisão","Parsers JSON","CLI para validação de contratos","Desenvolvimento de software com contratos","Testes de unidade para contratos","Integração contínua para validação de contratos"],"ru":["Проверка Контрактов","Валидация JSON-файлов","Схемы команд и решений","Парсеры JSON","CLI для проверки контрактов","Разработка ПО с контрактами","Юнит-тесты для контрактов","CI для проверки контрактов","ИИ Агенты для проверки контрактов"],"ar":["مدقق العقود","التحقق من صحة الملفات JSON","مخططات الأوامر والقرارات","معالجات JSON","سطر الأوامر لمدقق العقود","تطوير البرمجيات مع العقود","اختبارات الوحدة للعقود","التكامل المستمر لمدقق العقود","أدوات الذكاء الاصطناعي لمدقق العقود"]}},"owner":"Nepopams","repo":"vr_ai_platform","repoPath":"Nepopams/vr_ai_platform","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.381Z","topics":[],"category":"community","skillMd":{"name":"contract-checker","description":"Validates contract JSON Schemas and fixtures, fails fast on breaking format issues.","bodyPreview":"# Contract Checker Skill\n\n\n...\n\n\n## Inputs\n- JSON fixtures in `skills/contract-checker/fixtures/`.\n- Command and decision JSON schemas in `contracts/schemas/`.\n\n## Outputs\n- Validation report printed to stdout.\n- Non-zero exit status when fixtures do not match schemas.\n\n## Steps\n1. Load command and decision schemas.\n2. Validate each fixture against the correct schema.\n3. Treat `invalid_*.json` fixtures as expected failures.\n4. Emit a summary and exit with status 1 if expectations are not met.\n\n#","body":"# Contract Checker Skill\n\n\n...\n\n\n## Inputs\n- JSON fixtures in `skills/contract-checker/fixtures/`.\n- Command and decision JSON schemas in `contracts/schemas/`.\n\n## Outputs\n- Validation report printed to stdout.\n- Non-zero exit status when fixtures do not match schemas.\n\n## Steps\n1. Load command and decision schemas.\n2. Validate each fixture against the correct schema.\n3. Treat `invalid_*.json` fixtures as expected failures.\n4. Emit a summary and exit with status 1 if expectations are not met.\n\n## Definition of Done (DoD)\n- All fixtures validate against their expected schema outcome.\n- Invalid fixtures fail validation as expected.\n- Script exits cleanly with status 0 when expectations are met.\n"},"lastSynced":"2026-03-08T02:05:40.106Z","agentAnalysis":{"suitability":{"en":"Ideal for JSON Validation Agents requiring precise schema validation and reporting against command and decision schemas.","zh":"适用于需要精确模式验证和对命令和决策模式进行报告的JSON验证代理。","ja":"JSONのバリデーションエージェントに適しており、コマンドと決定スキーマの精密なスキーマバリデーションとレポートが必要です。","ko":"정확한 스키마 검증과 명령 및 의사 결정 스키마에 대한 보고가 필요한 JSON 검증 에이전트에 적합합니다.","es":"Ideal para agentes de validación JSON que requieren una validación de esquema precisa y generación de informes contra esquemas de comando y decisión.","fr":"Idéal pour les agents de validation JSON nécessitant une validation de schéma précise et la génération de rapports contre les schémas de commande et de décision.","de":"Ideal für JSON-Validierungsagenten, die eine präzise Schema-Validierung und Berichterstellung gegen Befehls- und Entscheidungsschemata erfordern.","pt":"Ideal para Agentes de Validação JSON que exigem validação de esquema precisa e relatórios contra esquemas de comando e decisão.","ru":"Идеально для агентов валидации JSON, требующих точной валидации схемы и отчетов против командных и решающих схем.","ar":"مثالي لعميل التحقق من JSON الذي يتطلب التحقق الدقيق من مخطط و تقارير ضد مخططات الأمر و القرار."},"recommendation":{"en":"Empowers agents to validate JSON fixtures against predefined schemas using JSON schema validation, providing detailed validation reports and non-zero exit status for mismatches, leveraging JSON data and schema validation protocols.","zh":"赋予代理验证JSON固定数据与预定义的模式，使用JSON模式验证，提供详细的验证报告和非零退出状态用于不匹配，利用JSON数据和模式验证协议。","ja":"エージェントに、JSON 固定データを事前定義されたスキーマと比較検証する機能を付与し、JSON スキーマ検証を使用して詳細な検証レポートと不一致の場合の非ゼロ終了ステータスを提供し、JSON データとスキーマ検証プロトコルを活用します。","ko":"에이전트가 사전 정의된 스키마와 비교하여 JSON 고정 데이터를 검증할 수 있도록 하며, JSON 스키마 검증을 사용하여 자세한 검증 보고서와 불일치의 경우 0이 아닌 종료 상태를 제공하며, JSON 데이터 및 스키마 검증 프로토콜을 활용합니다.","es":"Habilita a los agentes a validar fijaciones JSON contra esquemas predefinidos utilizando la validación de esquema JSON, proporcionando informes de validación detallados y un estado de salida distinto de cero para las discrepancias, aprovechando los protocolos de validación de datos y esquema JSON.","fr":"Permet aux agents de valider les fixtures JSON contre des schémas prédéfinis en utilisant la validation de schéma JSON, fournissant des rapports de validation détaillés et un statut de sortie non nul pour les discordances, en exploitant les protocoles de validation de données et de schéma JSON.","de":"Ermächtigt Agenten, JSON-Fixture gegen vordefinierte Schemata zu validieren, indem sie die JSON-Schema-Validierung verwenden, und stellt detaillierte Validierungsberichte und einen Nicht-Null-Ausgangsstatus für Abweichungen bereit, indem sie die JSON-Daten- und Schema-Validierungsprotokolle nutzen.","pt":"Habilita os agentes a validar fixtures JSON contra esquemas pré-definidos usando a validação de esquema JSON, fornecendo relatórios de validação detalhados e status de saída não-zero para discordâncias, aproveitando protocolos de validação de dados e esquema JSON.","ru":"Наделяет агентов возможностью проверять фикстуры JSON против предопределенных схем с помощью проверки схемы JSON, обеспечивая подробные отчеты о проверке и ненулевой статус выхода для несоответствий, используя протоколы проверки данных и схемы JSON.","ar":"يمكن العملاء من التحقق من إصلاحات JSON ضد المخططات المحددة مسبقا باستخدام التحقق من مخطط JSON، وتقديم تقارير تحقق مفصلة وحالة إنهاء غير صفرية للتناقضات، واستخدام بروتوكولات بيانات JSON والتحقق من مخطط JSON."},"useCases":{"en":["Validating JSON data against command schemas","Debugging decision schema mismatches","Automating JSON fixture validation reports"],"zh":["验证JSON数据与命令模式","调试决策模式不匹配","自动JSON固定数据验证报告"],"ja":["コマンドスキーマに対するJSONデータの検証","決定スキーマの不一致のデバッグ","JSON固定データの検証レポートの自動化"],"ko":["명령 스키마에 대한 JSON 데이터 검증","의사 결정 스키마 불일치 디버깅","JSON 고정 데이터 검증 보고서 자동화"],"es":["Validar datos JSON contra esquemas de comando","Depurar discrepancias en los esquemas de decisión","Automatizar informes de validación de fijaciones JSON"],"fr":["Valider les données JSON contre les schémas de commande","Déboguer les discordances dans les schémas de décision","Automatiser les rapports de validation des fixtures JSON"],"de":["JSON-Daten gegen Befehlsschemata validieren","Entscheidungsschemadiskrepanzen debuggen","JSON-Fixture-Validierungsberichte automatisieren"],"pt":["Validar dados JSON contra esquemas de comando","Depurar discordâncias de esquema de decisão","Automatizar relatórios de validação de fixtures JSON"],"ru":["Проверка данных JSON против командных схем","Отладка несоответствий схемы решения","Автоматизация отчетов о проверке фикстур JSON"],"ar":["التحقق من بيانات JSON ضد مخططات الأمر","تصحيح أخطاء مخططات القرار","تأتمتة تقارير التحقق من إصلاحات JSON"]},"limitations":{"en":["Requires JSON fixtures and schema files","Limited to JSON schema validation","Exits with non-zero status for validation failures"],"zh":["需要JSON固定数据和模式文件","仅限于JSON模式验证","验证失败时退出状态为非零"],"ja":["JSON 固定データとスキーマファイルが必要","JSON スキーマ検証のみに限定される","検証失敗時に終了ステータスはゼロ以外"],"ko":["JSON 고정 데이터 및 스키마 파일이 필요","JSON 스키마 검증만으로 제한","검증 실패 시 종료 상태는 0이 아님"],"es":["Requiere fijaciones y archivos de esquema JSON","Limitado a la validación de esquema JSON","Sale con un estado de salida distinto de cero en caso de fallas de validación"],"fr":["Nécessite des fixtures et des fichiers de schéma JSON","Limité à la validation de schéma JSON","Sortie avec un statut de sortie non nul en cas d''échecs de validation"],"de":["Benötigt JSON-Fixture und Schema-Dateien","Begrenzt auf JSON-Schema-Validierung","Beendet mit einem Nicht-Null-Ausgangsstatus bei Validierungsf